package com.gearforge;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(GearForgeConfig.GROUP)
public interface GearForgeConfig extends Config
{
	String GROUP = "gearforge";

	@ConfigItem(
		keyName = "groupVariants",
		name = "Group item variants",
		description = "Show one entry per item instead of listing every charged, imbued and degraded version separately. The best version is the one shown.",
		position = 1
	)
	default boolean groupVariants()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideZeroBonus",
		name = "Hide items with no bonus",
		description = "Hide items that give zero or a negative bonus in the stat you are looking at.",
		position = 2
	)
	default boolean hideZeroBonus()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightBank",
		name = "Highlight setup items",
		description = "Outline the active setup's items in your bank and inventory.",
		position = 3
	)
	default boolean highlightBank()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "highlightColour",
		name = "Highlight colour",
		description = "Colour of the outline drawn around the active setup's items.",
		position = 4
	)
	default Color highlightColour()
	{
		return new Color(255, 152, 31, 200);
	}
}

package com.gearforge;

import com.gearforge.bank.BankFilterService;
import com.gearforge.bank.BankHighlighter;
import com.gearforge.data.BankModel;
import com.gearforge.setups.Setup;
import com.gearforge.setups.SetupStore;
import com.gearforge.ui.GearForgePanel;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "GearForge",
	description = "Rank everything you own by equipment stat, per slot. Pairs well with Auto Bank Sorter and Bank Tags.",
	tags = {"gear", "equipment", "bank", "stats", "bis", "loadout", "combat"}
)
public class GearForgePlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private BankModel bankModel;

	@Inject
	private SetupStore setupStore;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BankHighlighter bankHighlighter;

	@Inject
	private BankFilterService bankFilterService;

	@Inject
	private GearForgePanel panel;

	private NavigationButton navButton;

	@Override
	protected void startUp()
	{
		bankModel.load();
		setupStore.load();
		overlayManager.add(bankHighlighter);
		bankFilterService.register();
		readLiveContainers();

		BufferedImage icon = ImageUtil.loadImageResource(GearForgePlugin.class, "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("GearForge")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		panel.refresh();

		log.debug("GearForge started");
	}

	@Override
	protected void shutDown()
	{
		panel.shutDown();
		bankFilterService.unregister();
		overlayManager.remove(bankHighlighter);
		clientToolbar.removeNavigation(navButton);
		navButton = null;

		log.debug("GearForge stopped");
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		switch (event.getContainerId())
		{
			case InventoryID.BANK:
				bankModel.updateBank(event.getItemContainer());
				break;
			case InventoryID.INV:
				bankModel.updateInventory(event.getItemContainer());
				break;
			case InventoryID.WORN:
				bankModel.updateEquipment(event.getItemContainer());
				break;
			default:
				return;
		}

		panel.refresh();
	}

	/**
	 * Reads the inventory and worn equipment straight from the client.
	 * <p>
	 * Container events only fire when a container <em>changes</em>, and the ones at login happen before
	 * this plugin starts if it is enabled mid-session or started late. Relying on them alone left worn
	 * gear empty until the player changed something, which made "Save what I'm wearing" claim nothing
	 * was equipped.
	 */
	private void readLiveContainers()
	{
		clientThread.invoke(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				return;
			}

			bankModel.updateInventory(client.getItemContainer(InventoryID.INV));
			bankModel.updateEquipment(client.getItemContainer(InventoryID.WORN));
			panel.refresh();
		});
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		// Bank Tags applies a filter to the open bank, so re-apply whenever the bank is opened rather
		// than only at the moment the user activates a setup.
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankFilterService.reapply();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (GearForgeConfig.GROUP.equals(event.getGroup()))
		{
			panel.refresh();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// The RS profile is only known once logged in, and it changes when hopping accounts, so
		// reload rather than letting one account's gear leak into another's panel.
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			bankModel.load();
			setupStore.load();

			// Restore whatever was last shown in the bank for this account.
			Setup active = setupStore.active();
			if (active != null)
			{
				bankFilterService.applySetup(active);
			}

			readLiveContainers();
			panel.refresh();
		}
	}

	@Provides
	GearForgeConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GearForgeConfig.class);
	}
}

package com.gearforge.bank;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.data.BankModel;
import com.gearforge.data.ItemCanonicalizer;
import com.gearforge.setups.ItemRequirement;
import com.gearforge.setups.Setup;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.banktags.BankTag;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;

/**
 * Filters the bank down to the active setup's items and arranges them like the equipment screen.
 * <p>
 * This works through RuneLite's own Bank Tags plugin rather than reimplementing bank filtering: we
 * register a virtual tag whose membership is "is this item in the active setup", save a layout for
 * it, then ask Bank Tags to open it. Nothing is written to the user's own tags and no item is moved —
 * the bank shows a filtered, arranged view, and every click remains theirs.
 * <p>
 * <b>Why these are looked up rather than injected.</b> Every RuneLite plugin gets its own Guice child
 * injector. {@code BankTagsService} is bound inside Bank Tags' injector and {@code LayoutManager}
 * depends on {@code BankTagsConfig}, which lives there too — injecting either makes Guice fail to
 * construct this plugin, which removes GearForge from the plugin list with no visible error. Both are
 * reached instead through the running plugin's own injector. {@link TagManager} needs only root-level
 * dependencies, so it injects normally.
 */
@Slf4j
@Singleton
public class BankFilterService
{
	/**
	 * Namespaced so it cannot collide with a tag the player created.
	 */
	private static final String TAG = "gearforge";

	/** The third-party Bank Tag Layouts plugin, which renders tag layouts itself. */
	private static final String BANK_TAG_LAYOUTS_GROUP = "banktaglayouts";
	private static final String BANK_TAG_LAYOUTS_LAYOUT_PREFIX = "layout_";

	private static final int EMPTY = -1;

	/** Five rows for the equipment doll, a blank row, then seven rows of inventory. */
	private static final int DOLL_ROWS = 5;
	private static final int INVENTORY_START_ROW = 6;
	private static final int INVENTORY_COLUMNS = 4;
	private static final int INVENTORY_ROWS = 7;
	private static final int ROWS = INVENTORY_START_ROW + INVENTORY_ROWS;
	private static final int LAYOUT_SIZE = ROWS * BankTagsPlugin.BANK_ITEMS_PER_ROW;

	/**
	 * Where each slot sits in the bank grid, mirroring the in-game equipment screen:
	 *
	 * <pre>
	 *        head
	 *  cape  neck  ammo
	 * weapon body shield
	 *        legs
	 * hands  feet  ring
	 * </pre>
	 */
	private static final Map<EquipmentSlot, Integer> DOLL_POSITIONS = new EnumMap<>(EquipmentSlot.class);

	static
	{
		int perRow = BankTagsPlugin.BANK_ITEMS_PER_ROW;
		DOLL_POSITIONS.put(EquipmentSlot.HEAD, 1);
		DOLL_POSITIONS.put(EquipmentSlot.CAPE, perRow);
		DOLL_POSITIONS.put(EquipmentSlot.AMULET, perRow + 1);
		DOLL_POSITIONS.put(EquipmentSlot.AMMO, perRow + 2);
		DOLL_POSITIONS.put(EquipmentSlot.WEAPON, 2 * perRow);
		DOLL_POSITIONS.put(EquipmentSlot.BODY, 2 * perRow + 1);
		DOLL_POSITIONS.put(EquipmentSlot.SHIELD, 2 * perRow + 2);
		DOLL_POSITIONS.put(EquipmentSlot.LEGS, 3 * perRow + 1);
		DOLL_POSITIONS.put(EquipmentSlot.GLOVES, 4 * perRow);
		DOLL_POSITIONS.put(EquipmentSlot.BOOTS, 4 * perRow + 1);
		DOLL_POSITIONS.put(EquipmentSlot.RING, 4 * perRow + 2);
	}

	private final ClientThread clientThread;
	private final TagManager tagManager;
	private final PluginManager pluginManager;
	private final ConfigManager configManager;
	private final ItemCanonicalizer canonicalizer;
	private final BankModel bankModel;

	private boolean registered;

	/** The setup currently shown, which may be an unsaved preview from the BiS tab. */
	@Nullable
	private Setup shownSetup;

	/** Accepted ids for {@link #shownSetup}, variant families already expanded. */
	private Set<Integer> shownIds = Collections.emptySet();

	@Inject
	private BankFilterService(
		ClientThread clientThread,
		TagManager tagManager,
		PluginManager pluginManager,
		ConfigManager configManager,
		ItemCanonicalizer canonicalizer,
		BankModel bankModel)
	{
		this.clientThread = clientThread;
		this.tagManager = tagManager;
		this.pluginManager = pluginManager;
		this.configManager = configManager;
		this.canonicalizer = canonicalizer;
		this.bankModel = bankModel;
	}

	/**
	 * Item ids to filter and highlight. Precomputed rather than derived per rendered item, because the
	 * highlight overlay runs for every visible item every frame.
	 */
	public Set<Integer> shownIds()
	{
		return shownIds;
	}

	/**
	 * @return true if this exact setup is the one currently shown
	 */
	public boolean isShowing(Setup setup)
	{
		return shownSetup != null && shownSetup.getId().equals(setup.getId());
	}

	public boolean isShowingAnything()
	{
		return shownSetup != null;
	}

	/**
	 * The running Bank Tags plugin, which implements the service.
	 *
	 * @return null if Bank Tags is not loaded, in which case filtering is unavailable
	 */
	@Nullable
	private Plugin bankTagsPlugin()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (plugin instanceof BankTagsService)
			{
				return plugin;
			}
		}

		return null;
	}

	/**
	 * Resolves a class from Bank Tags' own injector, where its plugin-private bindings exist.
	 *
	 * @return the instance, or null if Bank Tags is not loaded or the binding is unavailable
	 */
	@Nullable
	private <T> T fromBankTags(Class<T> type)
	{
		Plugin plugin = bankTagsPlugin();
		if (plugin == null || plugin.getInjector() == null)
		{
			return null;
		}

		try
		{
			return plugin.getInjector().getInstance(type);
		}
		catch (RuntimeException e)
		{
			log.debug("Could not resolve {} from Bank Tags", type.getSimpleName(), e);
			return null;
		}
	}

	/**
	 * Registers the virtual tag. Membership is resolved live from the store, so the tag automatically
	 * follows whichever setup is active without needing re-registration.
	 */
	public void register()
	{
		if (registered)
		{
			return;
		}

		BankTag tag = itemId -> shownIds.contains(itemId);
		tagManager.registerTag(TAG, tag);
		registered = true;
	}

	public void unregister()
	{
		if (!registered)
		{
			return;
		}

		clearFilter();

		// Leave no layout entry behind in the user's Bank Tags config.
		LayoutManager layoutManager = fromBankTags(LayoutManager.class);
		if (layoutManager != null)
		{
			layoutManager.removeLayout(TAG);
		}

		configManager.unsetConfiguration(BANK_TAG_LAYOUTS_GROUP, BANK_TAG_LAYOUTS_LAYOUT_PREFIX + TAG);

		tagManager.unregisterTag(TAG);
		registered = false;
	}

	/**
	 * Shows only this setup's items in the bank, arranged as an equipment doll.
	 * <p>
	 * The setup need not be saved — the BiS tab previews its result this way.
	 */
	public void applySetup(Setup setup)
	{
		shownSetup = setup;
		shownIds = acceptedIds(setup);

		Plugin plugin = bankTagsPlugin();
		if (plugin == null)
		{
			log.debug("Bank Tags is not available; cannot filter the bank");
			return;
		}

		BankTagsService service = (BankTagsService) plugin;

		clientThread.invoke(() ->
		{
			// The layout must be saved first: openBankTag reads it back via loadLayout.
			saveLayoutFor(setup);

			// Hide the tag name — this is GearForge's view, not a tag the player made and can rename.
			// OPTION_NO_LAYOUT is deliberately absent, otherwise the arrangement is discarded.
			service.openBankTag(TAG, BankTagsService.OPTION_HIDE_TAG_NAME);
		});
	}

	public void clearFilter()
	{
		shownSetup = null;
		shownIds = Collections.emptySet();

		Plugin plugin = bankTagsPlugin();
		if (plugin != null)
		{
			clientThread.invoke(((BankTagsService) plugin)::closeBankTag);
		}
	}

	/**
	 * Re-applies whatever is currently shown, e.g. when the bank is reopened.
	 */
	public void reapply()
	{
		if (shownSetup != null)
		{
			applySetup(shownSetup);
		}
	}

	/**
	 * Every id that satisfies the setup, expanding variant families so a degraded or imbued version
	 * still shows up.
	 */
	private Set<Integer> acceptedIds(Setup setup)
	{
		Set<Integer> ids = new HashSet<>();
		Map<Integer, BankModel.OwnedQuantity> owned = bankModel.ownedItems();

		List<ItemRequirement> all = new ArrayList<>(setup.getEquipment().values());
		all.addAll(setup.getInventory());

		for (ItemRequirement requirement : all)
		{
			if (requirement == null)
			{
				continue;
			}

			ids.add(requirement.getItemId());

			// Variants are a fallback, not an addition. Tagging the whole family put all six charge
			// states of a skills necklace in the tag, and Bank Tags then appended every tagged item the
			// layout had no place for — which is how they ended up baked into the saved layout.
			//
			// So: only look for a stand-in when the exact item is not owned, and only accept one that
			// actually is. A degraded Barrows piece still stands in for the undegraded one; a necklace
			// you are holding brings nothing else with it.
			if (requirement.isFuzzy() && !owned.containsKey(requirement.getItemId()))
			{
				for (int variant : canonicalizer.variantsOf(requirement.getItemId()))
				{
					if (owned.containsKey(variant))
					{
						ids.add(variant);
					}
				}
			}
		}

		return ids;
	}

	/**
	 * Writes the equipment-doll arrangement for this setup. Best effort — if Bank Tags cannot be
	 * reached the filter still works, just in bank order.
	 */
	private void saveLayoutFor(Setup setup)
	{
		LayoutManager layoutManager = fromBankTags(LayoutManager.class);
		if (layoutManager == null)
		{
			return;
		}

		// Drop the previous layout first. Bank Tags appends tagged items a layout has no place for, so
		// an older, wider tag leaves its extras behind permanently unless the layout is replaced
		// outright.
		layoutManager.removeLayout(TAG);

		int[] positions = new int[LAYOUT_SIZE];
		Arrays.fill(positions, EMPTY);

		for (Map.Entry<EquipmentSlot, ItemRequirement> entry : setup.getEquipment().entrySet())
		{
			Integer position = DOLL_POSITIONS.get(entry.getKey());
			if (position != null)
			{
				positions[position] = entry.getValue().getItemId();
			}
		}

		// The inventory sits below the doll, four wide, mirroring the in-game grid.
		List<ItemRequirement> inventory = setup.getInventory();
		int perRow = BankTagsPlugin.BANK_ITEMS_PER_ROW;

		for (int slot = 0; slot < inventory.size() && slot < INVENTORY_COLUMNS * INVENTORY_ROWS; slot++)
		{
			ItemRequirement requirement = inventory.get(slot);
			if (requirement == null)
			{
				continue;
			}

			int row = INVENTORY_START_ROW + (slot / INVENTORY_COLUMNS);
			int column = slot % INVENTORY_COLUMNS;
			int position = row * perRow + column;

			// A duplicate stack would overwrite the earlier one; leave the first placement standing.
			if (positions[position] == EMPTY)
			{
				positions[position] = requirement.getItemId();
			}
		}

		layoutManager.saveLayout(new Layout(TAG, positions));
		writeBankTagLayoutsCompatibility(positions);
	}

	/**
	 * @return whether bank filtering can work at all, so the UI can say so rather than doing nothing
	 */
	public boolean isAvailable()
	{
		return bankTagsPlugin() != null;
	}

	/**
	 * Whether the third-party Bank Tag Layouts plugin is installed and switched on.
	 * <p>
	 * Detected through config rather than by inspecting plugin classes, since that plugin is not on
	 * our classpath and RuneLite forbids reflection.
	 */
	public boolean isBankTagLayoutsEnabled()
	{
		return "true".equals(configManager.getConfiguration("runelite", "banktaglayoutsplugin"));
	}

	/**
	 * Also writes the arrangement in Bank Tag Layouts' own format.
	 * <p>
	 * That plugin renders bank layouts itself and overrides the native one, which previously left
	 * GearForge's equipment doll flattened into a single packed row. Writing the same arrangement in
	 * its format means it renders ours instead of generating its own. Only our private tag's key is
	 * touched — the player's own tags are never written to — and the key is removed on shutdown.
	 * <p>
	 * Best effort: if that plugin regenerates the layout anyway, the panel warns the player instead.
	 */
	private void writeBankTagLayoutsCompatibility(int[] positions)
	{
		if (!isBankTagLayoutsEnabled())
		{
			return;
		}

		StringBuilder layout = new StringBuilder();
		for (int position = 0; position < positions.length; position++)
		{
			if (positions[position] == EMPTY)
			{
				continue;
			}

			if (layout.length() > 0)
			{
				layout.append(',');
			}

			layout.append(positions[position]).append(':').append(position);
		}

		configManager.setConfiguration(
			BANK_TAG_LAYOUTS_GROUP, BANK_TAG_LAYOUTS_LAYOUT_PREFIX + TAG, layout.toString());
	}
}

package com.gearforge.bank;

import com.gearforge.GearForgeConfig;
import java.awt.BasicStroke;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Stroke;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/**
 * Outlines the active setup's items in the bank, inventory and equipment.
 * <p>
 * Drawing only — this never withdraws, deposits or clicks. It shows you where the items are and you
 * move them yourself.
 * <p>
 * This runs for every visible item every frame, so it does no work beyond a set lookup: the ids to
 * highlight, variant families already expanded, are precomputed by {@link SetupStore} whenever the
 * active setup changes.
 */
@Singleton
public class BankHighlighter extends WidgetItemOverlay
{
	private static final Stroke OUTLINE = new BasicStroke(2f);

	private final BankFilterService bankFilterService;
	private final GearForgeConfig config;

	@Inject
	private BankHighlighter(BankFilterService bankFilterService, GearForgeConfig config)
	{
		this.bankFilterService = bankFilterService;
		this.config = config;

		showOnBank();
		showOnInventory();
		showOnEquipment();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem itemWidget)
	{
		if (!config.highlightBank())
		{
			return;
		}

		Set<Integer> highlighted = bankFilterService.shownIds();
		if (highlighted.isEmpty() || !highlighted.contains(itemId))
		{
			return;
		}

		Rectangle bounds = itemWidget.getCanvasBounds();
		if (bounds == null)
		{
			return;
		}

		graphics.setColor(config.highlightColour());
		graphics.setStroke(OUTLINE);
		graphics.draw(bounds);
	}
}

package com.gearforge.data;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.config.ConfigManager;

/**
 * What the player owns, and how long ago we last saw it.
 * <p>
 * The bank can only be read while it is open, so it is snapshotted with a timestamp and persisted per
 * RS profile. Inventory and worn equipment are live and are not persisted.
 */
@Slf4j
@Singleton
public class BankModel
{
	private static final String CONFIG_GROUP = "gearforge";
	private static final String SNAPSHOT_KEY = "gearSnapshot";

	/** Marks an empty inventory slot. */
	public static final int EMPTY_SLOT = -1;
	public static final int INVENTORY_SIZE = 28;

	private final ConfigManager configManager;
	private final Gson gson;
	private final ItemCanonicalizer canonicalizer;

	private final Map<Integer, Integer> bank = new HashMap<>();
	private final Map<Integer, Integer> inventory = new HashMap<>();
	private final Map<Integer, Integer> equipment = new HashMap<>();
	private final int[] inventoryOrder = new int[INVENTORY_SIZE];

	private long bankCapturedAt;

	@Inject
	private BankModel(ConfigManager configManager, Gson gson, ItemCanonicalizer canonicalizer)
	{
		this.configManager = configManager;
		this.gson = gson;
		this.canonicalizer = canonicalizer;
	}

	/**
	 * Replaces the bank snapshot from an open bank container and persists it.
	 */
	public void updateBank(ItemContainer container)
	{
		bank.clear();
		collect(container, bank);
		bankCapturedAt = System.currentTimeMillis();
		save();
		log.debug("Bank snapshot updated: {} unique items", bank.size());
	}

	public void updateInventory(ItemContainer container)
	{
		inventory.clear();
		collect(container, inventory);
		captureInventoryOrder(container);
	}

	/**
	 * Records the inventory slot by slot, which the aggregate map cannot express.
	 * <p>
	 * Setups store an ordered inventory, so position matters — an empty slot in the middle is real
	 * information, not something to compact away.
	 */
	private void captureInventoryOrder(@Nullable ItemContainer container)
	{
		Arrays.fill(inventoryOrder, EMPTY_SLOT);

		if (container == null)
		{
			return;
		}

		Item[] items = container.getItems();
		for (int slot = 0; slot < Math.min(items.length, INVENTORY_SIZE); slot++)
		{
			Item item = items[slot];
			if (item != null && item.getQuantity() > 0 && item.getId() >= 0)
			{
				inventoryOrder[slot] = canonicalizer.canonicalize(item.getId());
			}
		}
	}

	/**
	 * @return the inventory by slot, {@value #EMPTY_SLOT} where empty. A copy; safe to keep.
	 */
	public int[] getInventoryOrder()
	{
		return Arrays.copyOf(inventoryOrder, inventoryOrder.length);
	}

	public void updateEquipment(ItemContainer container)
	{
		equipment.clear();
		collect(container, equipment);
	}

	/**
	 * Reads a container into a canonical id to quantity map, discarding empty slots and bank
	 * placeholders (which are always quantity 0).
	 */
	private void collect(@Nullable ItemContainer container, Map<Integer, Integer> into)
	{
		if (container == null)
		{
			return;
		}

		for (Item item : container.getItems())
		{
			int quantity = item.getQuantity();
			if (quantity <= 0 || item.getId() < 0)
			{
				continue;
			}

			int id = canonicalizer.canonicalize(item.getId());
			into.merge(id, quantity, Integer::sum);
		}
	}

	/**
	 * Everything the player owns: bank, inventory and worn gear merged, with quantities summed and the
	 * storages each item was found in.
	 */
	public Map<Integer, OwnedQuantity> ownedItems()
	{
		Map<Integer, OwnedQuantity> owned = new LinkedHashMap<>();
		mergeInto(owned, bank, Storage.BANK);
		mergeInto(owned, inventory, Storage.INVENTORY);
		mergeInto(owned, equipment, Storage.EQUIPMENT);
		return owned;
	}

	private static void mergeInto(Map<Integer, OwnedQuantity> owned, Map<Integer, Integer> source, Storage storage)
	{
		for (Map.Entry<Integer, Integer> entry : source.entrySet())
		{
			owned.compute(entry.getKey(), (id, existing) -> existing == null
				? new OwnedQuantity(entry.getValue(), EnumSet.of(storage))
				: existing.plus(entry.getValue(), storage));
		}
	}

	/**
	 * @return epoch millis of the last bank read, or 0 if the bank has never been seen.
	 */
	public long getBankCapturedAt()
	{
		return bankCapturedAt;
	}

	public boolean hasBankData()
	{
		return bankCapturedAt > 0;
	}

	/**
	 * Loads the persisted snapshot for the currently active RS profile. Safe to call repeatedly; it
	 * clears live state so switching accounts cannot leak one account's gear into another's.
	 */
	public void load()
	{
		bank.clear();
		inventory.clear();
		equipment.clear();
		bankCapturedAt = 0;

		if (configManager.getRSProfileKey() == null)
		{
			return;
		}

		String json = configManager.getRSProfileConfiguration(CONFIG_GROUP, SNAPSHOT_KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}

		try
		{
			GearSnapshot snapshot = gson.fromJson(json, GearSnapshot.class);
			if (snapshot == null || snapshot.getVersion() != GearSnapshot.CURRENT_VERSION)
			{
				log.debug("Discarding gear snapshot from an incompatible version");
				return;
			}

			if (snapshot.getBank() != null)
			{
				bank.putAll(snapshot.getBank());
			}
			bankCapturedAt = snapshot.getCapturedAt();
			log.debug("Loaded bank snapshot: {} unique items", bank.size());
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Could not read the stored gear snapshot, starting fresh", e);
		}
	}

	private void save()
	{
		if (configManager.getRSProfileKey() == null)
		{
			return;
		}

		GearSnapshot snapshot = new GearSnapshot();
		snapshot.setBank(new HashMap<>(bank));
		snapshot.setCapturedAt(bankCapturedAt);
		configManager.setRSProfileConfiguration(CONFIG_GROUP, SNAPSHOT_KEY, gson.toJson(snapshot));
	}

	/**
	 * A quantity owned plus the storages it was found in.
	 */
	public static final class OwnedQuantity
	{
		private final int quantity;
		private final Set<Storage> locations;

		OwnedQuantity(int quantity, Set<Storage> locations)
		{
			this.quantity = quantity;
			this.locations = locations;
		}

		OwnedQuantity plus(int extra, Storage storage)
		{
			Set<Storage> merged = EnumSet.copyOf(locations);
			merged.add(storage);
			return new OwnedQuantity(quantity + extra, merged);
		}

		public int getQuantity()
		{
			return quantity;
		}

		public Set<Storage> getLocations()
		{
			return Collections.unmodifiableSet(locations);
		}
	}
}

package com.gearforge.data;

import com.google.gson.annotations.SerializedName;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * The equipment slots that real items actually occupy.
 * <p>
 * {@code slotIndex} matches {@link net.runelite.api.EquipmentInventorySlot#getSlotIdx()} and the
 * {@code slot} field returned by {@link net.runelite.client.game.ItemEquipmentStats#getSlot()}.
 * The purely cosmetic slots (arms, hair, jaw) are deliberately absent — no equippable item uses them.
 * <p>
 * Every constant carries a {@link SerializedName} equal to its display name, and it has to. A saved
 * setup keys its equipment map by this enum, and Gson writes map keys with {@code String.valueOf} —
 * that is {@link #toString()}, the display name — while reading them through the enum adapter, which
 * matches on {@link #name()}. Without the annotation the two disagree, so "Hands" and "Feet" both
 * read back as null, Gson throws {@code duplicate key: null}, and the whole file is discarded. That
 * silently emptied every saved setup on restart. {@code SetupStoreTest} pins the round trip; the
 * enum name is kept as an alternate so nothing already on disk is lost.
 */
@Getter
@RequiredArgsConstructor
public enum EquipmentSlot
{
	@SerializedName(value = "Head", alternate = "HEAD")
	HEAD(0, "Head"),

	@SerializedName(value = "Cape", alternate = "CAPE")
	CAPE(1, "Cape"),

	@SerializedName(value = "Neck", alternate = "AMULET")
	AMULET(2, "Neck"),

	@SerializedName(value = "Weapon", alternate = "WEAPON")
	WEAPON(3, "Weapon"),

	@SerializedName(value = "Body", alternate = "BODY")
	BODY(4, "Body"),

	@SerializedName(value = "Shield", alternate = "SHIELD")
	SHIELD(5, "Shield"),

	@SerializedName(value = "Legs", alternate = "LEGS")
	LEGS(7, "Legs"),

	@SerializedName(value = "Hands", alternate = "GLOVES")
	GLOVES(9, "Hands"),

	@SerializedName(value = "Feet", alternate = "BOOTS")
	BOOTS(10, "Feet"),

	@SerializedName(value = "Ring", alternate = "RING")
	RING(12, "Ring"),

	@SerializedName(value = "Ammo", alternate = "AMMO")
	AMMO(13, "Ammo");

	private final int slotIndex;
	private final String displayName;

	/**
	 * @return the slot with this index, or null if the index is a cosmetic slot or out of range.
	 */
	public static EquipmentSlot fromSlotIndex(int slotIndex)
	{
		for (EquipmentSlot slot : values())
		{
			if (slot.slotIndex == slotIndex)
			{
				return slot;
			}
		}

		return null;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.gearforge.data;

import lombok.Builder;
import lombok.Value;

/**
 * A plain, immutable copy of an item's equipment bonuses.
 * <p>
 * This deliberately mirrors {@link net.runelite.client.game.ItemEquipmentStats} rather than using it
 * directly: that class has a package-private constructor, so it cannot be built in unit tests. Copying
 * into our own type keeps the ranking and (later) DPS code testable without a running client.
 * <p>
 * Note {@code magicDamage} is a percentage in whole units — an Occult necklace is {@code 5.0f}, meaning
 * +5%. Fractional values exist, which is why it is a float.
 */
@Value
@Builder
public class EquipmentStats
{
	int astab;
	int aslash;
	int acrush;
	int amagic;
	int arange;

	int dstab;
	int dslash;
	int dcrush;
	int dmagic;
	int drange;

	int strength;
	int rangedStrength;
	float magicDamage;
	int prayer;

	/** Matches {@link EquipmentSlot#getSlotIndex()}. */
	int slot;
	boolean twoHanded;
	/** Attack speed in game ticks. 0 for non-weapons. */
	int speed;

	/**
	 * Adds up a whole setup's bonuses, which is what the DPS engine scores against.
	 * <p>
	 * Slot, two-handedness and speed are not summable, so they are taken from the weapon: the sum's
	 * {@code speed} is the fastest non-zero speed present, which for a valid setup is the weapon's.
	 */
	public static EquipmentStats sum(Iterable<EquipmentStats> pieces)
	{
		EquipmentStatsBuilder total = EquipmentStats.builder();

		int astab = 0, aslash = 0, acrush = 0, amagic = 0, arange = 0;
		int dstab = 0, dslash = 0, dcrush = 0, dmagic = 0, drange = 0;
		int strength = 0, rangedStrength = 0, prayer = 0, speed = 0;
		float magicDamage = 0f;

		for (EquipmentStats piece : pieces)
		{
			if (piece == null)
			{
				continue;
			}

			astab += piece.astab;
			aslash += piece.aslash;
			acrush += piece.acrush;
			amagic += piece.amagic;
			arange += piece.arange;
			dstab += piece.dstab;
			dslash += piece.dslash;
			dcrush += piece.dcrush;
			dmagic += piece.dmagic;
			drange += piece.drange;
			strength += piece.strength;
			rangedStrength += piece.rangedStrength;
			magicDamage += piece.magicDamage;
			prayer += piece.prayer;

			if (piece.speed > 0 && (speed == 0 || piece.speed < speed))
			{
				speed = piece.speed;
			}
		}

		return total
			.astab(astab).aslash(aslash).acrush(acrush).amagic(amagic).arange(arange)
			.dstab(dstab).dslash(dslash).dcrush(dcrush).dmagic(dmagic).drange(drange)
			.strength(strength).rangedStrength(rangedStrength)
			.magicDamage(magicDamage).prayer(prayer)
			.speed(speed)
			.build();
	}
}

