	private long capturedAt;
}

package com.gearforge.data;

import java.util.function.ToDoubleFunction;
import lombok.Getter;

/**
 * A single rankable bonus. Names match what the in-game equipment stats screen calls them.
 */
@Getter
public enum GearStat
{
	STAB_ATTACK("Stab attack", EquipmentStats::getAstab),
	SLASH_ATTACK("Slash attack", EquipmentStats::getAslash),
	CRUSH_ATTACK("Crush attack", EquipmentStats::getAcrush),
	MAGIC_ATTACK("Magic attack", EquipmentStats::getAmagic),
	RANGED_ATTACK("Ranged attack", EquipmentStats::getArange),

	STAB_DEFENCE("Stab defence", EquipmentStats::getDstab),
	SLASH_DEFENCE("Slash defence", EquipmentStats::getDslash),
	CRUSH_DEFENCE("Crush defence", EquipmentStats::getDcrush),
	MAGIC_DEFENCE("Magic defence", EquipmentStats::getDmagic),
	RANGED_DEFENCE("Ranged defence", EquipmentStats::getDrange),

	STRENGTH("Melee strength", EquipmentStats::getStrength),
	RANGED_STRENGTH("Ranged strength", EquipmentStats::getRangedStrength),
	MAGIC_DAMAGE("Magic damage", EquipmentStats::getMagicDamage, true),
	PRAYER("Prayer", EquipmentStats::getPrayer);

	private final String displayName;
	private final ToDoubleFunction<EquipmentStats> extractor;
	private final boolean percentage;

	GearStat(String displayName, ToDoubleFunction<EquipmentStats> extractor)
	{
		this(displayName, extractor, false);
	}

	GearStat(String displayName, ToDoubleFunction<EquipmentStats> extractor, boolean percentage)
	{
		this.displayName = displayName;
		this.extractor = extractor;
		this.percentage = percentage;
	}

	public double valueOf(EquipmentStats stats)
	{
		return extractor.applyAsDouble(stats);
	}

	/**
	 * Formats a value the way the game does — always signed, percentages suffixed.
	 */
	public String format(double value)
	{
		String number;
		if (percentage)
		{
			// Fractional magic damage exists (e.g. 0.2%), so only show a decimal when there is one.
			number = value == Math.rint(value)
				? String.valueOf((long) value)
				: String.valueOf(Math.round(value * 10.0) / 10.0);
			number += "%";
		}
		else
		{
			number = String.valueOf((long) value);
		}

		return value >= 0 ? "+" + number : number;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.gearforge.data;

import java.util.Collection;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;

/**
 * Resolves the several ids a single "thing you own" can appear under.
 * <p>
 * Two different notions of sameness are kept separate on purpose:
 * <ul>
 *   <li>{@link #canonicalize(int)} collapses notes and bank placeholders onto the real item. This is
 *       always correct and always applied.</li>
 *   <li>{@link #variantGroup(int)} collapses a family of related items (charged/uncharged, imbued,
 *       degraded) onto one representative. These genuinely differ in stats, so it is only used for
 *       display grouping and is user-toggleable.</li>
 * </ul>
 */
@Singleton
public class ItemCanonicalizer
{
	private final ItemManager itemManager;

	@Inject
	private ItemCanonicalizer(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	/**
	 * Maps a noted or placeholder id onto the real, unnoted item id.
	 */
	public int canonicalize(int itemId)
	{
		return itemManager.canonicalize(itemId);
	}

	/**
	 * Maps an item onto the base id of its variant family, e.g. every degradation state of a Barrows
	 * piece onto the undegraded one. Items with no known variants map to themselves.
	 */
	public int variantGroup(int itemId)
	{
		return ItemVariationMapping.map(itemId);
	}

	/**
	 * Every id in this item's variant family, including the item itself.
	 * <p>
	 * Resolved live rather than persisted, so saved setups pick up variants added after they were
	 * created instead of going stale.
	 */
	public Collection<Integer> variantsOf(int itemId)
	{
		Set<Integer> variants = new HashSet<>();
		variants.add(itemId);

		Collection<Integer> known = ItemVariationMapping.getVariations(variantGroup(itemId));
		if (known != null)
		{
			variants.addAll(known);
		}

		return variants;
	}
}

package com.gearforge.data;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import com.gearforge.dps.CombatStyle;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Set;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ItemVariationMapping;

/**
 * What kind of weapon or ammunition an item is.
 * <p>
 * RuneLite's item stats say an item is a weapon but not what type, so nothing there prevents pairing
 * a crossbow with arrows. Ships as a generated resource — see
 * {@code scripts/generate-item-categories.mjs}.
 */
@Slf4j
@Singleton
public class ItemCategories
{
	private static final String RESOURCE = "/com/gearforge/item-categories.json";

	public static final String BOW = "BOW";
	public static final String OGRE_BOW = "OGRE_BOW";
	public static final String CROSSBOW = "CROSSBOW";
	public static final String BALLISTA = "BALLISTA";
	public static final String THROWN = "THROWN";
	public static final String POWERED_STAFF = "POWERED_STAFF";
	public static final String STAFF = "STAFF";

	/** Reaches two tiles, unlike every other melee weapon. */
	public static final String POLEARM = "POLEARM";

	public static final String ARROW = "ARROW";
	public static final String BRUTAL = "BRUTAL";
	public static final String BOLT = "BOLT";
	public static final String JAVELIN = "JAVELIN";

	/**
	 * Ranged weapons that make their own ammunition, listed by the family every variant maps to.
	 * <p>
	 * A bow of faerdhinen is category "Bow", and every bow was taken to need arrows in the ammo slot —
	 * so a setup holding one scored zero and was thrown away before it could be compared with
	 * anything. It was not that the bow lost to a blowpipe; it was never in the running. The same went
	 * for every crystal bow, the corrupted bows from the Gauntlet, Craw's bow and the webweaver.
	 * <p>
	 * Families rather than ids: this one entry covers the seven Prifddinas colours of the corrupted
	 * bow, both charge states, and the deadman copy.
	 */
	private static final Set<Integer> SUPPLY_OWN_AMMO = Collections.unmodifiableSet(
		new java.util.HashSet<>(java.util.Arrays.asList(
			25862,  // Bow of faerdhinen, every colour and charge state
			4212,   // Crystal bow, including the Gauntlet's basic, attuned and perfected
			23855,  // Corrupted bow
			22547,  // Craw's bow
			27652,  // Webweaver bow
			12924,  // Toxic blowpipe
			28687,  // Blazing blowpipe
			30373   // Rosewood blowpipe
		)));

	private final Map<Integer, String> categories;

	@Inject
	public ItemCategories(Gson gson)
	{
		this.categories = load(gson);
	}

	private static Map<Integer, String> load(Gson gson)
	{
		try (InputStream stream = ItemCategories.class.getResourceAsStream(RESOURCE))
		{
			if (stream == null)
			{
				log.warn("Item category resource missing; ammo pairing will not be checked");
				return Collections.emptyMap();
			}

			CategoryFile file = gson.fromJson(
				new InputStreamReader(stream, StandardCharsets.UTF_8), CategoryFile.class);

			if (file == null || file.categories == null)
			{
				return Collections.emptyMap();
			}

			log.debug("Loaded {} item categories", file.categories.size());
			return file.categories;
		}
		catch (IOException | JsonSyntaxException e)
		{
			log.warn("Could not read item categories; ammo pairing will not be checked", e);
			return Collections.emptyMap();
		}
	}

	/**
	 * @return the item's category, or null if it is unclassified — melee weapons, staves, and every
	 *     non-weapon fall here, and none of them constrain ammo.
	 */
	@Nullable
	public String categoryOf(int itemId)
	{
		return categories.get(itemId);
	}

	/**
	 * Whether this item is a ranged weapon of any kind.
	 */
	public boolean isRangedWeapon(int itemId)
	{
		String category = categoryOf(itemId);
		return BOW.equals(category)
			|| OGRE_BOW.equals(category)
			|| CROSSBOW.equals(category)
			|| BALLISTA.equals(category)
			|| THROWN.equals(category);
	}

	/**
	 * Whether a weapon can sensibly be used with a combat style.
	 * <p>
	 * Without this the optimizer will happily recommend a longsword as a ranged setup when the player
	 * owns no bow: a melee weapon contributes zero ranged attack and zero ranged strength, so it
	 * scores badly rather than being rejected, and "badly" still wins if nothing else is available.
	 * A wrong-but-confident answer is worse than saying you own nothing suitable.
	 *
	 * @param style the combat style being optimised, as {@code CombatStyle#name()}
	 */
	/**
	 * The attack styles a weapon category actually offers.
	 * <p>
	 * A whip has three options and every one of them is slash — it cannot crush at all. Recommending
	 * "melee — crush, abyssal tentacle" is not a slightly wrong answer, it is an impossible one, and the
	 * optimizer was producing exactly that because it read the crush bonus off the item and never asked
	 * whether the weapon could swing that way.
	 * <p>
	 * Transcribed from the reference calculator's style table.
	 */
	private static final Map<String, Set<CombatStyle>> STYLES_BY_CATEGORY = buildStyles();

	private static Map<String, Set<CombatStyle>> buildStyles()
	{
		Map<String, Set<CombatStyle>> styles = new HashMap<>();

		styles.put("WHIP", EnumSet.of(CombatStyle.SLASH));
		styles.put("FLAIL", EnumSet.of(CombatStyle.SLASH));
		styles.put("SLASH_SWORD", EnumSet.of(CombatStyle.SLASH, CombatStyle.STAB));
		styles.put("STAB_SWORD", EnumSet.of(CombatStyle.SLASH, CombatStyle.STAB));
		styles.put("CLAW", EnumSet.of(CombatStyle.SLASH, CombatStyle.STAB));
		styles.put("POLEARM", EnumSet.of(CombatStyle.SLASH, CombatStyle.STAB));
		styles.put("TWO_HANDED_SWORD", EnumSet.of(CombatStyle.SLASH, CombatStyle.CRUSH));
		styles.put("2H_SWORD", EnumSet.of(CombatStyle.SLASH, CombatStyle.CRUSH));
		styles.put("AXE", EnumSet.of(CombatStyle.SLASH, CombatStyle.CRUSH));
		styles.put("SCYTHE", EnumSet.of(CombatStyle.SLASH, CombatStyle.CRUSH));
		styles.put("BLUNT", EnumSet.of(CombatStyle.CRUSH));
		styles.put("BLUDGEON", EnumSet.of(CombatStyle.CRUSH));
		styles.put("POLESTAFF", EnumSet.of(CombatStyle.CRUSH));
		styles.put("BULWARK", EnumSet.of(CombatStyle.CRUSH));
		styles.put("GUN", EnumSet.of(CombatStyle.CRUSH));
		styles.put("UNARMED", EnumSet.of(CombatStyle.CRUSH));
		styles.put("PICKAXE", EnumSet.of(CombatStyle.CRUSH, CombatStyle.STAB));
		styles.put("PARTISAN", EnumSet.of(CombatStyle.CRUSH, CombatStyle.STAB));
		styles.put("SPIKED", EnumSet.of(CombatStyle.CRUSH, CombatStyle.STAB));
		styles.put("SPEAR", EnumSet.of(CombatStyle.CRUSH, CombatStyle.SLASH, CombatStyle.STAB));
		styles.put("BANNER", EnumSet.of(CombatStyle.CRUSH, CombatStyle.SLASH, CombatStyle.STAB));
		styles.put("STAFF", EnumSet.of(CombatStyle.CRUSH, CombatStyle.MAGIC));
		styles.put("BLADED_STAFF",
			EnumSet.of(CombatStyle.CRUSH, CombatStyle.SLASH, CombatStyle.STAB, CombatStyle.MAGIC));
		styles.put("POWERED_STAFF", EnumSet.of(CombatStyle.MAGIC));
		styles.put("SALAMANDER", EnumSet.of(CombatStyle.MAGIC, CombatStyle.RANGED, CombatStyle.SLASH));

		for (String ranged : new String[]{"BOW", "CROSSBOW", "THROWN", "CHINCHOMPA", "BALLISTA", "OGRE_BOW"})
		{
			styles.put(ranged, EnumSet.of(CombatStyle.RANGED));
		}

		return styles;
	}

	/**
	 * Whether this weapon can actually attack with this style.
	 * <p>
	 * An unknown category is allowed everything: refusing what we cannot classify would silently delete
	 * valid answers, which is the worse failure.
	 */
	public boolean canUseStyle(int weaponId, CombatStyle style)
	{
		Set<CombatStyle> allowed = STYLES_BY_CATEGORY.get(categoryOf(weaponId));
		return allowed == null || allowed.contains(style);
	}

	/**
	 * Whether this weapon reaches two tiles. Polearms do; everything else stops at one, which is the
	 * difference between being able to melee Zulrah and not.
	 */
	public boolean hasReach(int weaponId)
	{
		return POLEARM.equals(categoryOf(weaponId));
	}

	public boolean suitsStyle(int weaponId, String style)
	{
		String category = categoryOf(weaponId);
		boolean ranged = isRangedWeapon(weaponId);
		boolean magic = STAFF.equals(category) || POWERED_STAFF.equals(category);

		if ("RANGED".equals(style))
		{
			return ranged;
		}

		// A spell can technically be cast holding anything, but "best in slot for magic" holding a
		// melee weapon is nonsense to a player — and because spell damage does not depend on the
		// weapon, the search would otherwise pick whatever had the best incidental bonuses.
		if ("MAGIC".equals(style))
		{
			return magic;
		}

		// Melee: anything that is not a bow, crossbow or staff.
		return !ranged && !magic;
	}

	/**
	 * Whether this weapon needs ammunition to attack at all. A bow with no arrows does nothing.
	 */
	public boolean requiresAmmo(int weaponId)
	{
		if (suppliesOwnAmmo(weaponId))
		{
			return false;
		}

		String category = categoryOf(weaponId);
		return BOW.equals(category)
			|| OGRE_BOW.equals(category)
			|| CROSSBOW.equals(category)
			|| BALLISTA.equals(category);
	}

	/**
	 * Whether this weapon brings its own ammunition, so nothing in the ammo slot is needed — or
	 * counted, since a quiver of arrows worn beside a crystal bow does nothing in game.
	 */
	public boolean suppliesOwnAmmo(int weaponId)
	{
		return SUPPLY_OWN_AMMO.contains(weaponId)
			|| SUPPLY_OWN_AMMO.contains(ItemVariationMapping.map(weaponId));
	}

	/**
	 * Whether this ammunition can be fired from this weapon.
	 * <p>
	 * Unclassified weapons accept anything: melee weapons, staves and thrown weapons do not draw from
	 * the ammo slot, so constraining them would reject valid setups for no gain.
	 */
	public boolean ammoFits(int weaponId, int ammoId)
	{
		String weapon = categoryOf(weaponId);
		if (weapon == null)
		{
			return true;
		}

		String ammo = categoryOf(ammoId);

		switch (weapon)
		{
			case BOW:
				return ARROW.equals(ammo);
			// Ogre bows fire brutal arrows, and the composite also takes ordinary ones.
			case OGRE_BOW:
				return BRUTAL.equals(ammo) || ARROW.equals(ammo);
			case CROSSBOW:
				return BOLT.equals(ammo);
			// Ballistas are categorised as crossbows upstream but fire javelins.
			case BALLISTA:
				return JAVELIN.equals(ammo);
			default:
				return true;
		}
	}

	private static final class CategoryFile
	{
		int dataVersion;
		String source;
		String generatedAt;
		Map<Integer, String> categories = new HashMap<>();
	}
}

package com.gearforge.data;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.game.ItemVariationMapping;

/**
 * Level requirements for equipping items.
 * <p>
 * RuneLite's item data has no requirements and the OSRS Wiki only states them in prose, so this ships
 * as a generated resource — see {@code scripts/generate-requirements.mjs}.
 * <p>
 * Coverage is incomplete: the source dataset stopped being updated, so items released after that are
 * absent. Absent is treated as <em>unknown</em>, not as <em>unrestricted</em>, and unknown items are
 * still offered to the player with a caveat. Hiding a player's best weapon because a dataset is stale
 * would be a worse failure than mentioning one they cannot yet wield.
 */
@Slf4j
@Singleton
public class ItemRequirements
{
	private static final String RESOURCE = "/com/gearforge/equipment-requirements.json";

	private final Map<Integer, Map<String, Integer>> requirements;

	@Inject
	public ItemRequirements(Gson gson)
	{
		this.requirements = load(gson);
	}

	private static Map<Integer, Map<String, Integer>> load(Gson gson)
	{
		try (InputStream stream = ItemRequirements.class.getResourceAsStream(RESOURCE))
		{
			if (stream == null)
			{
				log.warn("Equipment requirements resource missing; requirement filtering disabled");
				return Collections.emptyMap();
			}

			// A concrete class rather than a TypeToken: Gson resolves the field's generics directly,
			// and it keeps java.lang.reflect out of the plugin entirely.
			RequirementsFile file = gson.fromJson(
				new InputStreamReader(stream, StandardCharsets.UTF_8), RequirementsFile.class);

			if (file == null || file.requirements == null)
			{
				return Collections.emptyMap();
			}

			log.debug("Loaded {} equipment requirement entries", file.requirements.size());
			return file.requirements;
		}
		catch (IOException | JsonSyntaxException e)
		{
			log.warn("Could not read equipment requirements; requirement filtering disabled", e);
			return Collections.emptyMap();
		}
	}

	/**
	 * @return true if we have requirement data for this item at all
	 */
	public boolean isKnown(int itemId)
	{
		return requirements.containsKey(itemId) || requirements.containsKey(family(itemId));
	}

	/**
	 * @return skill name to required level; empty if the item has no requirements or is unknown
	 */
	public Map<String, Integer> requirementsFor(int itemId)
	{
		Map<String, Integer> exact = requirements.get(itemId);
		if (exact != null && !exact.isEmpty())
		{
			return exact;
		}

		// An ornament kit does not lower a requirement, and an ornamented item's page rarely restates
		// one — so an empty entry is not the last word, only the absence of a statement on that page.
		// The family is: dragon claws (or) needs the same 60 Attack the claws do.
		Map<String, Integer> family = requirements.get(family(itemId));
		if (family != null)
		{
			return family;
		}

		return exact == null ? Collections.emptyMap() : exact;
	}

	private static int family(int itemId)
	{
		return ItemVariationMapping.map(itemId);
	}

	/**
	 * @return true if the player meets every known requirement. Items with no data return true, since
	 *     unknown is not the same as unmet.
	 */
	public boolean canEquip(int itemId, PlayerLevels levels)
	{
		for (Map.Entry<String, Integer> requirement : requirementsFor(itemId).entrySet())
		{
			if (levels.levelOf(requirement.getKey()) < requirement.getValue())
			{
				return false;
			}
		}

		return true;
	}

	/**
	 * A short, game-native description of what is missing, e.g. "Needs 70 Attack".
	 *
	 * @return the description, or null if the player can already equip it
	 */
	public String describeShortfall(int itemId, PlayerLevels levels)
	{
		for (Map.Entry<String, Integer> requirement : requirementsFor(itemId).entrySet())
		{
			if (levels.levelOf(requirement.getKey()) < requirement.getValue())
			{
				return "Needs " + requirement.getValue() + " " + capitalise(requirement.getKey());
			}
		}

		return null;
	}

	private static String capitalise(String skill)
	{
		return skill.substring(0, 1).toUpperCase() + skill.substring(1);
	}

	/**
	 * Mirrors the generated JSON. Only {@code requirements} is read; the rest is provenance.
	 */
	private static final class RequirementsFile
	{
		int dataVersion;
		String source;
		String generatedAt;
		Map<Integer, Map<String, Integer>> requirements = new HashMap<>();
	}
}

package com.gearforge.data;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

/**
 * Turns owned item ids into items with resolved bonuses.
 * <p>
 * RuneLite loads its equipment stat table asynchronously after startup, so {@link #statsFor(int)}
 * returns null both for items that have no bonuses and for every item before that load completes.
 * Callers must treat an empty result as "not ready yet" rather than "you own nothing".
 */
@Singleton
public class ItemStatEngine
{
	private final ItemManager itemManager;

	@Inject
	private ItemStatEngine(ItemManager itemManager)
	{
		this.itemManager = itemManager;
	}

	/**
	 * @return the item's equipment bonuses, or null if it is not equippable or stats have not loaded.
	 */
	@Nullable
	public EquipmentStats statsFor(int itemId)
	{
		ItemStats stats = itemManager.getItemStats(itemId);
		if (stats == null || !stats.isEquipable())
		{
			return null;
		}

		ItemEquipmentStats equipment = stats.getEquipment();
		if (equipment == null)
		{
			return null;
		}

		return EquipmentStats.builder()
			.astab(equipment.getAstab())
			.aslash(equipment.getAslash())
			.acrush(equipment.getAcrush())
			.amagic(equipment.getAmagic())
			.arange(equipment.getArange())
			.dstab(equipment.getDstab())
			.dslash(equipment.getDslash())
			.dcrush(equipment.getDcrush())
			.dmagic(equipment.getDmagic())
			.drange(equipment.getDrange())
			.strength(equipment.getStr())
			.rangedStrength(equipment.getRstr())
			.magicDamage(equipment.getMdmg())
			.prayer(equipment.getPrayer())
			.slot(equipment.getSlot())
			.twoHanded(equipment.isTwoHanded())
			.speed(equipment.getAspeed())
			.build();
	}

	/**
	 * Resolves everything the player owns into equippable items with bonuses and names.
	 * <p>
	 * Must be called on the client thread — item names come from {@link ItemComposition}.
	 *
	 * @return every owned item that is equippable; non-equippable items are dropped.
	 */
	public List<GearItem> resolveOwnedGear(BankModel bankModel)
	{
		Map<Integer, BankModel.OwnedQuantity> owned = bankModel.ownedItems();
		List<GearItem> gear = new ArrayList<>();

		for (Map.Entry<Integer, BankModel.OwnedQuantity> entry : owned.entrySet())
		{
			int itemId = entry.getKey();
			EquipmentStats stats = statsFor(itemId);
			if (stats == null)
			{
				continue;
			}

			if (EquipmentSlot.fromSlotIndex(stats.getSlot()) == null)
			{
				// A cosmetic-only slot. Nothing to rank it against.
				continue;
			}

			ItemComposition composition = itemManager.getItemComposition(itemId);
			BankModel.OwnedQuantity quantity = entry.getValue();
			gear.add(new GearItem(
				itemId,
				composition.getName(),
				quantity.getQuantity(),
				stats,
				quantity.getLocations()));
		}

		return gear;
	}
}

package com.gearforge.data;

import com.gearforge.dps.MonsterAttribute;
import com.gearforge.dps.Spell;
import com.gearforge.dps.Target;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * One boss, as shipped in the generated dataset.
 * <p>
 * A plain class with a no-arg constructor because this is read with Gson.
 */
@Data
@NoArgsConstructor
public class Monster
{
	private int id;
	private String name = "";

	/** Distinguishes forms of the same boss, e.g. Zulrah's colours. Often empty. */
	private String version = "";

	private int combatLevel;
	private int size = 1;
	private int defenceLevel;
	private int magicLevel;

	/** Magic attack bonus, used by the twisted bow's scaling. */
	private int magicAttack;

	private int hitpoints;
	private Defensive defensive = new Defensive();
	private List<String> attributes = new ArrayList<>();
	private boolean slayerMonster;

	/** Elemental weakness, if any. A matching spell gains the severity in accuracy and damage. */
	private String weaknessElement;
	private int weaknessSeverity;

	/** Whether this is a curated boss. Bosses keep their forms when the list is collapsed. */
	private boolean boss;

	/**
	 * Name plus form, e.g. "Zulrah (Tanzanite)". Used everywhere the boss is shown.
	 */
	public String displayName()
	{
		return version == null || version.isEmpty() ? name : name + " (" + version + ")";
	}

	/**
	 * Used directly by combo boxes, so it must read as the boss name rather than a field dump.
	 */
	@Override
	public String toString()
	{
		return displayName();
	}

	/**
	 * Converts to what the DPS engine scores against.
	 */
	public Target toTarget()
	{
		EquipmentStats bonuses = EquipmentStats.builder()
			.dstab(defensive.stab)
			.dslash(defensive.slash)
			.dcrush(defensive.crush)
			.dmagic(defensive.magic)
			.drange(defensive.ranged)
			.build();

		return Target.builder()
			.name(displayName())
			.defenceLevel(defenceLevel)
			.magicLevel(magicLevel)
			.magicAttack(magicAttack)
			.defensiveBonuses(bonuses)
			.size(size)
			.attributes(parseAttributes())
			.weaknessElement(Spell.Element.parse(weaknessElement))
			.weaknessSeverity(weaknessSeverity)
			.build();
	}

	/**
	 * Maps the dataset's attribute strings onto the ones item effects key off. Unknown attributes are
	 * ignored rather than failing — the source carries more of them than we model.
	 */
	private Set<MonsterAttribute> parseAttributes()
	{
		Set<MonsterAttribute> parsed = EnumSet.noneOf(MonsterAttribute.class);

		for (String attribute : attributes)
		{
			for (MonsterAttribute known : MonsterAttribute.values())
			{
				if (known.name().equalsIgnoreCase(attribute))
				{
					parsed.add(known);
					break;
				}
			}
		}

		return parsed;
	}

	@Data
	@NoArgsConstructor
	public static class Defensive
	{
		private int stab;
		private int slash;
		private int crush;
		private int magic;
		private int ranged;
	}
}

package com.gearforge.data;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * The bosses GearForge knows about.
 * <p>
 * Ships as a generated resource — see {@code scripts/generate-monsters.mjs}. Sourced from the OSRS
 * Wiki, which is CC BY-NC-SA: attribution is required and the licence is non-commercial, so the
 * credit line must stay on the BiS tab and in the README, and the plugin must remain free.
 */
@Slf4j
@Singleton
public class MonsterRepository
{
	private static final String RESOURCE = "/com/gearforge/monsters.json";

	/** What a fight is called, against what its monsters are called. */
	private static final Map<String, String[]> ALIASES = buildAliases();

	private static Map<String, String[]> buildAliases()
	{
		Map<String, String[]> aliases = new LinkedHashMap<>();
		aliases.put("royal titans", new String[]{"branda", "eldric"});
		aliases.put("dagannoth kings", new String[]{"dagannoth rex", "dagannoth prime", "dagannoth supreme"});
		aliases.put("dks", new String[]{"dagannoth rex", "dagannoth prime", "dagannoth supreme"});
		aliases.put("desert treasure", new String[]{"vardorvis", "duke sucellus", "leviathan", "whisperer"});
		aliases.put("gauntlet", new String[]{"crystalline hunllef", "corrupted hunllef"});
		return aliases;
	}

	private final List<Monster> monsters;
	private final String attribution;

	@Inject
	public MonsterRepository(Gson gson)
	{
		MonsterFile file = load(gson);
		this.monsters = collapseDuplicates(
			file.monsters == null ? Collections.emptyList() : file.monsters);
		this.attribution = file.attribution == null ? "" : file.attribution;
	}

	/**
	 * Removes entries the DPS engine cannot tell apart.
	 * <p>
	 * The wiki data lists a row per NPC id, so one monster arrives many times over: "Armoured zombie
	 * (Zemouregal's Fort) (Melee)" appears four times, and the ranged form beside it has the same
	 * defence, the same bonuses and the same attributes. Scrolling past twenty rows that all score
	 * identically is just noise.
	 * <p>
	 * Two entries collapse when they share a name and every stat the engine reads — defence, magic,
	 * bonuses, size, hitpoints and attributes. Combat level is deliberately not part of that: the
	 * Ankou variants differ by level but not by anything that changes DPS, so they fold into one.
	 * <p>
	 * A form is only worth showing when it distinguishes something. Once a name has collapsed to a
	 * single entry, its version suffix is dropped, so "Zulrah (Tanzanite)" keeps its form — the colours
	 * really do defend differently — while "Ankou (Level 75)" becomes plain "Ankou".
	 */
	private static List<Monster> collapseDuplicates(List<Monster> loaded)
	{
		Map<String, Monster> bossForms = new LinkedHashMap<>();
		Map<String, Integer> formsPerBoss = new HashMap<>();
		Map<String, Monster> ordinary = new LinkedHashMap<>();

		for (Monster monster : loaded)
		{
			// Ordinary monsters collapse to one row per name, full stop. Twenty armoured zombies that
			// differ only in which room they stand in is not a choice anyone wants to scroll past.
			if (!monster.isBoss())
			{
				ordinary.merge(baseName(monster.getName()), monster, MonsterRepository::toughest);
				continue;
			}

			if (bossForms.putIfAbsent(monster.getName() + '|' + combatSignature(monster), monster) == null)
			{
				formsPerBoss.merge(monster.getName(), 1, Integer::sum);
			}
		}

		List<Monster> collapsed = new ArrayList<>(bossForms.values());
		for (Monster monster : collapsed)
		{
			if (formsPerBoss.getOrDefault(monster.getName(), 0) == 1)
			{
				monster.setVersion("");
			}
		}

		for (Map.Entry<String, Monster> entry : ordinary.entrySet())
		{
			Monster monster = entry.getValue();
			monster.setName(entry.getKey());
			monster.setVersion("");
			collapsed.add(monster);
		}

		collapsed = disambiguate(collapsed);
		collapsed.sort(Comparator.comparing(Monster::displayName, String.CASE_INSENSITIVE_ORDER));

		log.debug("Collapsed {} monster entries to {}", loaded.size(), collapsed.size());
		return Collections.unmodifiableList(collapsed);
	}

	/**
	 * An ordinary monster's name with any trailing qualifier removed.
	 * <p>
	 * The source bakes the location into the name rather than the form, so the armoured zombie arrives
	 * as four separate monsters — "(Defender of Varrock)", "(The Curse of Arrav)", "(Zemouregal's Base)"
	 * and "(Zemouregal's Fort)" — each with its own set of forms underneath. Which quest a zombie
	 * belongs to does not change how you kill it, so the qualifier goes and the four become one.
	 * <p>
	 * Bosses never reach here: their qualifiers are the whole point.
	 */
	private static String baseName(String name)
	{
		int qualifier = name.lastIndexOf(" (");
		if (qualifier <= 0 || !name.endsWith(")"))
		{
			return name;
		}

		return name.substring(0, qualifier);
	}

	/**
	 * Which of two forms of the same ordinary monster to keep.
	 * <p>
	 * The tougher one, so the DPS estimate reads low rather than high. Being told you kill something
	 * slower than you really do is the harmless direction to be wrong in.
	 */
	private static Monster toughest(Monster left, Monster right)
	{
		if (left.getDefenceLevel() != right.getDefenceLevel())
		{
			return left.getDefenceLevel() > right.getDefenceLevel() ? left : right;
		}

		return left.getHitpoints() >= right.getHitpoints() ? left : right;
	}

	/**
	 * Settles rows that still read identically.
	 * <p>
	 * A handful of monsters defend differently but carry no form to say so — Jhallan is one, listed
	 * twice with nothing between the two rows. Two entries a player cannot choose between are worse
	 * than one, so combat level is borrowed as the label where it separates them, and where even that
	 * matches the row really is a duplicate and only the first is kept.
	 */
	private static List<Monster> disambiguate(List<Monster> collapsed)
	{
		Map<String, List<Monster>> byDisplayName = new LinkedHashMap<>();
		for (Monster monster : collapsed)
		{
			byDisplayName.computeIfAbsent(monster.displayName(), name -> new ArrayList<>()).add(monster);
		}

		List<Monster> settled = new ArrayList<>();
		for (List<Monster> sharing : byDisplayName.values())
		{
			if (sharing.size() == 1)
			{
				settled.add(sharing.get(0));
				continue;
			}

			Set<Integer> levels = new HashSet<>();
			for (Monster monster : sharing)
			{
				levels.add(monster.getCombatLevel());
			}

			if (levels.size() != sharing.size())
			{
				settled.add(sharing.get(0));
				continue;
			}

			for (Monster monster : sharing)
			{
				monster.setVersion("Level " + monster.getCombatLevel());
				settled.add(monster);
			}
		}

		return settled;
	}

	/**
	 * Everything {@link Monster#toTarget()} reads. Two monsters with the same signature score the same,
	 * so listing both only makes the picker longer.
	 */
	private static String combatSignature(Monster monster)
	{
		List<String> attributes = new ArrayList<>(
			monster.getAttributes() == null ? Collections.emptyList() : monster.getAttributes());
		attributes.sort(String.CASE_INSENSITIVE_ORDER);

		Monster.Defensive defensive = monster.getDefensive();

		return monster.getDefenceLevel() + ":" + monster.getMagicLevel() + ":" + monster.getMagicAttack()
			+ ":" + monster.getHitpoints() + ":" + monster.getSize() + ":" + monster.isSlayerMonster()
			+ ":" + defensive.getStab() + ":" + defensive.getSlash() + ":" + defensive.getCrush()
			+ ":" + defensive.getMagic() + ":" + defensive.getRanged()
			+ ":" + String.join(",", attributes);
	}

	private static MonsterFile load(Gson gson)
	{
		try (InputStream stream = MonsterRepository.class.getResourceAsStream(RESOURCE))
		{
			if (stream == null)
			{
				log.warn("Monster data resource missing; no targets will be selectable");
				return new MonsterFile();
			}

			MonsterFile file = gson.fromJson(
				new InputStreamReader(stream, StandardCharsets.UTF_8), MonsterFile.class);

			if (file == null)
			{
				return new MonsterFile();
			}

			log.debug("Loaded {} monsters", file.monsters == null ? 0 : file.monsters.size());
			return file;
		}
		catch (IOException | JsonSyntaxException e)
		{
			log.warn("Could not read monster data; no targets will be selectable", e);
			return new MonsterFile();
		}
	}

	public List<Monster> all()
	{
		return Collections.unmodifiableList(monsters);
	}

	/**
	 * Only the curated bosses, for the Bosses tab. The full set stays searchable elsewhere so DPS can
	 * be checked against whatever is actually being fought.
	 */
	public List<Monster> bosses()
	{
		List<Monster> bosses = new ArrayList<>();
		for (Monster monster : monsters)
		{
			if (monster.isBoss())
			{
				bosses.add(monster);
			}
		}

		return bosses;
	}

	/**
	 * @return the first monster with this exact name, or null. Used for the default target.
	 */
	@Nullable
	public Monster byName(String name)
	{
		for (Monster monster : monsters)
		{
			if (monster.getName().equalsIgnoreCase(name))
			{
				return monster;
			}
		}

		return null;
	}

	public boolean isEmpty()
	{
		return monsters.isEmpty();
	}

	/**
	 * Required credit for the wiki data.
	 */
	public String getAttribution()
	{
		return attribution;
	}

	/**
	 * Case-insensitive substring search over name and form. An empty query returns everything, so the
	 * tab shows the full list before the player types.
	 * <p>
	 * Deliberately uncapped: capping here once truncated the list at "E" with nothing on screen to say
	 * so. Any display limit belongs in the UI, where it can be shown to the player.
	 */
	public List<Monster> search(String query)
	{
		return search(query, monsters);
	}

	/**
	 * Same search, restricted to a supplied set — the Bosses tab passes {@link #bosses()}.
	 */
	public List<Monster> search(String query, List<Monster> within)
	{
		String needle = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
		List<Monster> matches = new ArrayList<>();

		for (Monster monster : within)
		{
			String name = monster.displayName().toLowerCase(Locale.ROOT);

			if (needle.isEmpty() || name.contains(needle) || matchesAlias(needle, name))
			{
				matches.add(monster);
			}
		}

		return matches;
	}

	/**
	 * Names people search by that no monster is actually called.
	 * <p>
	 * The Royal Titans are two separate NPCs, Branda and Eldric, so searching what the fight is called
	 * found nothing at all.
	 */
	private static boolean matchesAlias(String needle, String name)
	{
		for (Map.Entry<String, String[]> alias : ALIASES.entrySet())
		{
			if (!alias.getKey().startsWith(needle))
			{
				continue;
			}

			for (String member : alias.getValue())
			{
				if (name.contains(member))
				{
					return true;
				}
			}
		}

		return false;
	}

	/**
	 * Mirrors the generated JSON.
	 */
	private static final class MonsterFile
	{
		int dataVersion;
		String attribution;
		String source;
		String generatedAt;
		List<Monster> monsters = new ArrayList<>();
	}
}

package com.gearforge.data;

import lombok.Builder;
import lombok.Value;

/**
 * A snapshot of the levels that gate equipment, taken on the client thread so the rest of the code
 * can use it from anywhere.
 */
@Value
@Builder
public class PlayerLevels
{
	int attack;
	int strength;
	int defence;
	int ranged;
	int magic;
	int prayer;
	int hitpoints;
	int slayer;

	/** Only the Moonlight potion needs this — its boost scales with Herblore. */
	int herblore;

	/** Whether the player currently has a slayer task assigned. */
	boolean onSlayerTask;

	/**
	 * @param skill lowercase skill name as it appears in the requirements dataset
	 * @return the player's level in that skill, or 0 for a skill we do not track
	 */
	public int levelOf(String skill)
	{
		switch (skill)
		{
			case "attack":
				return attack;
			case "strength":
				return strength;
			case "defence":
				return defence;
			case "ranged":
				return ranged;
			case "magic":
				return magic;
			case "prayer":
				return prayer;
			case "hitpoints":
				return hitpoints;
			case "slayer":
				return slayer;
			default:
				return 0;
		}
	}

	/**
	 * A maxed account — used when no requirement filtering is wanted.
	 */
	public static PlayerLevels maxed()
	{
		return PlayerLevels.builder()
			.attack(99).strength(99).defence(99).ranged(99).magic(99)
			.prayer(99).hitpoints(99).slayer(99).herblore(99)
			.build();
	}
}

package com.gearforge.data;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarPlayerID;

/**
 * The player's levels.
 * <p>
 * Real levels rather than boosted ones: best-in-slot should answer "what should I wear", not "what
 * looks good while a potion happens to be active". Reads must happen on the client thread, which is
 * why {@link #snapshot()} exists — take one there, use it anywhere.
 */
@Singleton
public class PlayerModel
{
	private final Client client;

	@Inject
	private PlayerModel(Client client)
	{
		this.client = client;
	}

	public boolean isLoggedIn()
	{
		return client.getGameState() == GameState.LOGGED_IN;
	}

	/**
	 * Whether the player currently has a slayer task, read from the amount remaining.
	 * <p>
	 * This answers "do I have a task at all", not "is this specific monster my task" — matching a task
	 * creature to a boss needs a mapping we do not ship. Callers combine it with whether the target is
	 * a slayer monster, which is a much better guess than assuming either way.
	 * <p>
	 * Must be called on the client thread.
	 */
	public boolean hasSlayerTask()
	{
		return isLoggedIn() && client.getVarpValue(VarPlayerID.SLAYER_COUNT) > 0;
	}

	/**
	 * Must be called on the client thread.
	 */
	public PlayerLevels snapshot()
	{
		return PlayerLevels.builder()
			.attack(level(Skill.ATTACK))
			.strength(level(Skill.STRENGTH))
			.defence(level(Skill.DEFENCE))
			.ranged(level(Skill.RANGED))
			.magic(level(Skill.MAGIC))
			.prayer(level(Skill.PRAYER))
			.hitpoints(level(Skill.HITPOINTS))
			.slayer(level(Skill.SLAYER))
			.herblore(level(Skill.HERBLORE))
			.onSlayerTask(hasSlayerTask())
			.build();
	}

	private int level(Skill skill)
	{
		return isLoggedIn() ? client.getRealSkillLevel(skill) : 1;
	}
}

package com.gearforge.data;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

/**
 * Monsters that melee can only reach with a long weapon.
 * <p>
 * Zulrah is the example: it sits a tile beyond an ordinary weapon's reach, so a whip cannot touch it
 * — but a halberd can, and people do melee it that way. Banning melee outright is as wrong as
 * allowing it, because it deletes a correct answer instead of a wrong one.
 * <p>
 * So this is a reach question, not a style question. Polearms reach two tiles; everything else reaches
 * one. The category comes from the equipment data at build time rather than being guessed at here.
 * <p>
 * The list is hand-kept because no dataset carries it. The wiki's monster export records what a
 * monster attacks <em>with</em>, not what reaches it, and the wiki's own calculator does not model
 * this at all — there the player picks a style and takes responsibility for it. GearForge picks the
 * style itself, so it has to be right.
 */
public final class Reachability
{
	/**
	 * Monsters an ordinary melee weapon cannot reach, matched on the base name so every form counts.
	 */
	private static final Set<String> NEEDS_REACH = new HashSet<>(Arrays.asList(
		"zulrah"
	));

	/**
	 * Monsters melee cannot touch at any reach, because there is nothing standing on the ground to hit.
	 */
	private static final Set<String> NO_MELEE = new HashSet<>(Arrays.asList(
		// In the water, and out of reach of anything.
		"kraken",
		"cave kraken",

		// Airborne for the whole fight. Kree'arra's bodyguards are aviansies and are equally unreachable.
		"kree'arra",
		"aviansie",
		"wingman skree",
		"flockleader geerin",
		"flight kilisa",

		// Suspended above the arena and only damaged indirectly.
		"zalcano"
	));

	private Reachability()
	{
	}

	/**
	 * @param polearm whether the melee weapon in question reaches two tiles
	 * @return whether a melee weapon of this reach can attack this monster
	 */
	public static boolean meleeCanReach(Monster monster, boolean polearm)
	{
		if (monster == null)
		{
			return true;
		}

		String name = monster.getName().toLowerCase(Locale.ROOT);

		if (NO_MELEE.contains(name))
		{
			return false;
		}

		return polearm || !NEEDS_REACH.contains(name);
	}

	/**
	 * Whether melee is possible at all here, with the right weapon.
	 */
	public static boolean meleeIsPossible(Monster monster)
	{
		return monster == null || !NO_MELEE.contains(monster.getName().toLowerCase(Locale.ROOT));
	}

	/**
	 * Whether reaching this monster in melee requires a long weapon.
	 */
	public static boolean requiresReach(Monster monster)
	{
		return monster != null && NEEDS_REACH.contains(monster.getName().toLowerCase(Locale.ROOT));
	}

	/**
	 * Said plainly in the panel rather than a style silently disappearing.
	 */
	public static String reason(Monster monster)
	{
		if (requiresReach(monster))
		{
			return monster.getName() + " can only be meleed with a halberd or another weapon that "
				+ "reaches two tiles.";
		}

		return monster.getName() + " cannot be attacked with melee.";
	}
}

package com.gearforge.data;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.annotation.Nullable;

/**
 * Gear a slayer monster obliges you to bring.
 * <p>
 * These are not preferences. An aberrant spectre cannot be fought without a nose peg — the game will
 * not let you — so a best-in-slot answer that puts a helm of neitiznot in that slot is not merely
 * suboptimal, it is unusable. The optimizer had no idea these existed and confidently recommended
 * setups nobody could equip.
 * <p>
 * Two kinds of requirement, and they are handled differently:
 * <ul>
 *     <li><b>Worn</b> — a nose peg, earmuffs, a mirror shield. The slot is forced to one of the
 *     accepted items, best first, so a slayer helmet is preferred over a bare nose peg when both are
 *     owned: it satisfies the requirement and carries stats.</li>
 *     <li><b>Carried</b> — a rock hammer, a bag of salt, an ice cooler. These finish the kill rather
 *     than occupying a slot, so they are said in the reasoning instead of being equipped.</li>
 * </ul>
 * Hand-kept, because no dataset carries it. Deliberately confined to monsters where the item is
 * genuinely required rather than merely useful.
 */
public final class SlayerGear
{
	/** Any slayer helmet satisfies the nose peg, earmuffs, facemask and spiny helmet requirements. */
	private static final int[] SLAYER_HELMETS = {11864, 11865, 26674, 19639, 19641, 19643, 21264, 21266,
		21888, 21890, 23073, 23075, 24370, 24372, 25177, 25179, 25898, 25900, 27615, 27617};

	private static final Map<String, Requirement> REQUIREMENTS = build();

	/**
	 * What a monster demands, or null if it demands nothing.
	 */
	public static final class Requirement
	{
		private final EquipmentSlot slot;
		private final List<Integer> accepted;
		private final String note;

		Requirement(@Nullable EquipmentSlot slot, List<Integer> accepted, String note)
		{
			this.slot = slot;
			this.accepted = Collections.unmodifiableList(accepted);
			this.note = note;
		}

		/** The slot that must hold one of the accepted items, or null for a carried item. */
		@Nullable
		public EquipmentSlot getSlot()
		{
			return slot;
		}

		/** Acceptable items, best first. Empty for a carried requirement. */
		public List<Integer> getAccepted()
		{
			return accepted;
		}

		/** Said in the reasoning either way, so the player knows why the slot is fixed. */
		public String getNote()
		{
			return note;
		}

		public boolean isWorn()
		{
			return slot != null;
		}
	}

	private SlayerGear()
	{
	}

	@Nullable
	public static Requirement forMonster(@Nullable Monster monster)
	{
		return monster == null
			? null
			: REQUIREMENTS.get(monster.getName().toLowerCase(Locale.ROOT));
	}

	private static Map<String, Requirement> build()
	{
		Map<String, Requirement> requirements = new LinkedHashMap<>();

		// A slayer helmet covers all four of the head-slot protections, and is worth wearing over the
		// bare item because it carries stats the bare item does not.
		worn(requirements, EquipmentSlot.HEAD, withHelmets(4168),
			"Needs a nose peg or a slayer helmet — without one you cannot fight it at all.",
			"aberrant spectre", "deviant spectre", "abhorrent spectre", "repugnant spectre");

		worn(requirements, EquipmentSlot.HEAD, withHelmets(4166),
			"Needs earmuffs or a slayer helmet — without one you cannot fight it at all.",
			"banshee", "twisted banshee");

		worn(requirements, EquipmentSlot.HEAD, withHelmets(4164),
			"Needs a facemask or a slayer helmet — without one you cannot fight it at all.",
			"dust devil", "choke devil");

		worn(requirements, EquipmentSlot.HEAD, withHelmets(4551),
			"Needs a spiny helmet or a slayer helmet.",
			"wall beast");

		// A slayer helmet does not help here: the shield is what stops the gaze.
		worn(requirements, EquipmentSlot.SHIELD, Arrays.asList(24266, 4156),
			"Needs a mirror shield or V's shield to block its gaze.",
			"basilisk", "basilisk knight", "monstrous basilisk", "basilisk sentinel");

		worn(requirements, EquipmentSlot.AMULET, Collections.singletonList(8923),
			"Needs a witchwood icon against its screech.",
			"cave horror");

		worn(requirements, EquipmentSlot.BOOTS, Collections.singletonList(7159),
			"Needs insulated boots.",
			"killerwatt");

		worn(requirements, EquipmentSlot.GLOVES, Collections.singletonList(6720),
			"Needs slayer gloves.",
			"fever spider");

		// Carried rather than worn: these finish the kill and take no slot.
		carried(requirements, "Bring a rock hammer — it will not die without one.",
			"gargoyle", "marble gargoyle");

		carried(requirements, "Bring a bag of salt — it will not die without one.",
			"rockslug");

		carried(requirements, "Bring fungicide spray — it will not die without it.",
			"zygomite");

		carried(requirements, "Bring an ice cooler to finish it.",
			"desert lizard", "lizard", "small lizard");

		carried(requirements, "Only a leaf-bladed weapon or Magic Dart will hurt it.",
			"kurask", "turoth");

		return requirements;
	}

	/**
	 * The bare protective item, then every slayer helmet. Helmets come first once sorted by the
	 * optimizer, but the bare item is kept so someone without a helmet still gets an answer.
	 */
	private static List<Integer> withHelmets(int bareItem)
	{
		java.util.List<Integer> accepted = new java.util.ArrayList<>();
		for (int helmet : SLAYER_HELMETS)
		{
			accepted.add(helmet);
		}

		accepted.add(bareItem);
		return accepted;
	}

	private static void worn(
		Map<String, Requirement> into, EquipmentSlot slot, List<Integer> accepted, String note,
		String... monsters)
	{
		for (String monster : monsters)
		{
			into.put(monster, new Requirement(slot, accepted, note));
		}
	}

	private static void carried(Map<String, Requirement> into, String note, String... monsters)
	{
		for (String monster : monsters)
		{
			into.put(monster, new Requirement(null, Collections.emptyList(), note));
		}
	}
}

package com.gearforge.data;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import java.util.stream.Collectors;

/**
 * Ranks owned items for one slot by one bonus.
 * <p>
 * Deliberately pure and free of RuneLite types so it can be unit tested without a client. The variant
 * grouping function is passed in for the same reason.
 */
public final class SlotRanker
{
	private SlotRanker()
	{
	}

	/**
	 * @param owned            every equippable item the player owns
	 * @param slot             the slot to rank
	 * @param stat             the bonus to rank by
	 * @param groupVariants    collapse variant families to their single best member
	 * @param hideNonPositive  drop items whose value in this stat is zero or negative
	 * @param variantGrouper   maps an item id to its variant family id
	 * @return items for that slot, best first
	 */
	public static List<GearItem> rank(
		Collection<GearItem> owned,
		EquipmentSlot slot,
		GearStat stat,
		boolean groupVariants,
		boolean hideNonPositive,
		IntUnaryOperator variantGrouper)
	{
		List<GearItem> candidates = new ArrayList<>();
		for (GearItem item : owned)
		{
			if (item.getStats().getSlot() != slot.getSlotIndex())
			{
				continue;
			}

			if (hideNonPositive && item.statValue(stat) <= 0)
			{
				continue;
			}

			candidates.add(item);
		}

		if (groupVariants)
		{
			candidates = keepBestPerVariantFamily(candidates, stat, variantGrouper);
		}

		candidates.sort(rankingOrder(stat));
		return candidates;
	}

	/**
	 * Counts, for one slot, how many owned items give a positive value in each bonus.
	 * <p>
	 * Used to turn a dead end into a signpost: an empty ranking can then say which bonus is actually
	 * worth looking at for that slot rather than just showing nothing.
	 */
	public static Map<GearStat, Integer> positiveCounts(Collection<GearItem> owned, EquipmentSlot slot)
	{
		Map<GearStat, Integer> counts = new EnumMap<>(GearStat.class);

		for (GearItem item : owned)
		{
			if (item.getStats().getSlot() != slot.getSlotIndex())
			{
				continue;
			}

			for (GearStat stat : GearStat.values())
			{
				if (item.statValue(stat) > 0)
				{
					counts.merge(stat, 1, Integer::sum);
				}
			}
		}

		return counts;
	}

	/**
	 * The bonuses with the most owned items for a slot, best first, excluding one already being viewed.
	 */
	public static List<GearStat> suggestStats(Map<GearStat, Integer> counts, GearStat exclude, int limit)
	{
		return counts.entrySet().stream()
			.filter(e -> e.getKey() != exclude && e.getValue() > 0)
			.sorted(Map.Entry.<GearStat, Integer>comparingByValue().reversed())
			.limit(limit)
			.map(Map.Entry::getKey)
			.collect(Collectors.toList());
	}

	/**
	 * Keeps only the highest-scoring member of each variant family. Picking the best member rather than
	 * an arbitrary one means grouping can never hide a genuinely better item.
	 */
	private static List<GearItem> keepBestPerVariantFamily(
		List<GearItem> candidates,
		GearStat stat,
		IntUnaryOperator variantGrouper)
	{
		Map<Integer, GearItem> best = new LinkedHashMap<>();
		Comparator<GearItem> order = rankingOrder(stat);

		for (GearItem item : candidates)
		{
			int family = variantGrouper.applyAsInt(item.getItemId());
			GearItem incumbent = best.get(family);
			if (incumbent == null || order.compare(item, incumbent) < 0)
			{
				best.put(family, item);
			}
		}

		return new ArrayList<>(best.values());
	}

	/**
	 * Best first. Ties break on name then id so the list is stable between rebuilds.
	 */
	private static Comparator<GearItem> rankingOrder(GearStat stat)
	{
		return Comparator
			.comparingDouble((GearItem item) -> item.statValue(stat)).reversed()
			.thenComparing(GearItem::getName)
			.thenComparingInt(GearItem::getItemId);
	}
}

