	 * hits considerably harder than this says.
	 */
	ABYSSAL_BLUDGEON("Abyssal bludgeon", 50, Shape.SINGLE_HIT, ItemID.ABYSSAL_BLUDGEON, 1.0, 1.0),

	/**
	 * These three cannot miss, but their damage comes from the arrow alone and ignores the rest of your
	 * gear. Only the guaranteed hit is modelled, so against a target you already hit reliably they read
	 * high.
	 */
	MAGIC_LONGBOW("Magic longbow", 35, Shape.GUARANTEED_HIT, ItemID.MAGIC_LONGBOW),

	SEERCULL("Seercull", 100, Shape.GUARANTEED_HIT, ItemID.DAGANOTH_CAVE_MAGIC_SHORTBOW);

	/**
	 * How the spec's damage is shaped. Each needs its own distribution; none of them is a multiplier
	 * on the ordinary attack.
	 */
	public enum Shape
	{
		SINGLE_HIT,
		TWO_HITS,
		CASCADE,
		GUARANTEED_HALF_TO_ONE_AND_A_HALF,
		DEFENCE_REDUCTION,

		/** A second hit lands only if the target is bigger than one tile. */
		SWEEP,

		/** Costs no attack turn, so it is a free hit rather than a replacement for one. */
		INSTANT,

		/** Four hits, as the webweaver fires. */
		FOUR_HITS,

		/**
		 * The maximum comes from the Magic level and a per-weapon cap rather than from the spell, so
		 * spell damage and magic damage bonuses play no part at all.
		 */
		MAGIC_LEVEL_MAX,

		/** Cannot miss, and rolls between fixed bounds that ignore your gear entirely. */
		GUARANTEED_RANGE,

		/** Cannot miss; damage rolls as usual. */
		GUARANTEED_HIT
	}

	private final String displayName;
	private final int energyCost;
	private final Shape shape;
	private final int itemId;
	private final double accuracyMultiplier;
	private final double damageMultiplier;
	private final double defenceReduction;

	/** Damage ceiling for a Magic special, reached at 99 Magic. Zero for everything else. */
	private int magicLevelCap;

	SpecialAttack(String displayName, int energyCost, Shape shape, int itemId)
	{
		this(displayName, energyCost, shape, itemId, 1.0, 1.0, 0.0);
	}

	/** For the Magic specials, whose damage is capped rather than multiplied. */
	SpecialAttack(String displayName, int energyCost, Shape shape, int itemId, int magicLevelCap)
	{
		this(displayName, energyCost, shape, itemId, 1.0, 1.0, 0.0);
		this.magicLevelCap = magicLevelCap;
	}

	SpecialAttack(
		String displayName, int energyCost, Shape shape, int itemId,
		double accuracyMultiplier, double damageMultiplier)
	{
		this(displayName, energyCost, shape, itemId, accuracyMultiplier, damageMultiplier, 0.0);
	}

	SpecialAttack(
		String displayName, int energyCost, Shape shape, int itemId,
		double accuracyMultiplier, double damageMultiplier, double defenceReduction)
	{
		this.displayName = displayName;
		this.energyCost = energyCost;
		this.shape = shape;
		this.itemId = itemId;
		this.accuracyMultiplier = accuracyMultiplier;
		this.damageMultiplier = damageMultiplier;
		this.defenceReduction = defenceReduction;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	/** Percentage of the special attack bar consumed. */
	public int getEnergyCost()
	{
		return energyCost;
	}

	public Shape getShape()
	{
		return shape;
	}

	public int getItemId()
	{
		return itemId;
	}

	public double getAccuracyMultiplier()
	{
		return accuracyMultiplier;
	}

	public double getDamageMultiplier()
	{
		return damageMultiplier;
	}

	/** Fraction of the target's Defence removed, 0 for specs that do not reduce it. */
	public double getDefenceReduction()
	{
		return defenceReduction;
	}

	public int getMagicLevelCap()
	{
		return magicLevelCap;
	}

	public boolean reducesDefence()
	{
		return shape == Shape.DEFENCE_REDUCTION;
	}

	/**
	 * Whether the special costs no attack turn. Such a spec adds a whole hit rather than replacing the
	 * one you would have thrown anyway, so it is scored without deducting the ordinary attack.
	 */
	public boolean isInstant()
	{
		return shape == Shape.INSTANT;
	}

	/**
	 * Arclight and Darklight drain twice as hard against demons, which is the only reason to bring
	 * them. Everything else ignores what it is hitting.
	 */
	public double defenceReductionAgainst(boolean demon)
	{
		boolean demonbane = this == ARCLIGHT || this == DARKLIGHT;
		return demon && demonbane ? defenceReduction * 2 : defenceReduction;
	}

	/**
	 * A short plain-language note for the panel, so a recommendation always says why.
	 */
	public String describe()
	{
		switch (shape)
		{
			case CASCADE:
				return energyCost + "% energy · 4 hits";
			case GUARANTEED_HALF_TO_ONE_AND_A_HALF:
				return energyCost + "% energy · always hits";
			case TWO_HITS:
				return energyCost + "% energy · 2 hits";
			case FOUR_HITS:
				return energyCost + "% energy · 4 hits";
			case GUARANTEED_RANGE:
				return energyCost + "% energy · always hits 75-150";
			case GUARANTEED_HIT:
				return energyCost + "% energy · always hits";
			case MAGIC_LEVEL_MAX:
				return energyCost + "% energy · up to " + magicLevelCap + " damage";
			case SWEEP:
				return energyCost + "% energy · 2 hits on large targets";
			case INSTANT:
				return energyCost + "% energy · instant, costs no turn";
			case DEFENCE_REDUCTION:
				return energyCost + "% energy · -"
					+ Math.round(defenceReduction * 100) + "% defence";
			default:
				return energyCost + "% energy";
		}
	}

	/**
	 * Matches on the whole variant family, not just the exact id. A crystal halberd has a charge state
	 * per hundred, an ornate granite maul is its own item, and every one of them specs the same — so
	 * listing ids one by one would go stale the moment a new charge tier appeared.
	 */
	@Nullable
	public static SpecialAttack forItem(int itemId)
	{
		for (SpecialAttack special : values())
		{
			if (special.itemId == itemId)
			{
				return special;
			}
		}

		int family = ItemVariationMapping.map(itemId);
		for (SpecialAttack special : values())
		{
			if (ItemVariationMapping.map(special.itemId) == family)
			{
				return special;
			}
		}

		return null;
	}

	/**
	 * The item ids that carry a scoreable special attack.
	 */
	public static List<Integer> itemIds()
	{
		List<Integer> ids = new ArrayList<>();
		for (SpecialAttack special : values())
		{
			ids.add(special.itemId);
		}

		return Collections.unmodifiableList(ids);
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.gearforge.dps;

import java.util.ArrayList;
import java.util.List;
import javax.annotation.Nullable;

/**
 * The combat spells worth casting, with the level they need and the element they carry.
 * <p>
 * GearForge assumed Ice Barrage for every magic setup. That is the strongest spell in the game and
 * the right guess against something with no elemental weakness — but over a thousand monsters have
 * one, and a matching spell gains that weakness as a percentage of <em>both</em> accuracy and max
 * hit. Against a fire-weak target a Fire Surge beats Ice Barrage outright despite hitting for six
 * less on paper.
 * <p>
 * Assuming a single spell also made the elemental tomes useless, since a tome only raises a spell of
 * its own element.
 * <p>
 * Max hits come from the reference calculator's spell data. Level requirements are the game's own.
 */
public enum Spell
{
	// Standard spellbook, four elements through five tiers.

	WIND_STRIKE("Wind strike", 1, 2, Element.AIR),
	WATER_STRIKE("Water strike", 5, 4, Element.WATER),
	EARTH_STRIKE("Earth strike", 9, 6, Element.EARTH),
	FIRE_STRIKE("Fire strike", 13, 8, Element.FIRE),

	WIND_BOLT("Wind bolt", 17, 9, Element.AIR),
	WATER_BOLT("Water bolt", 23, 10, Element.WATER),
	EARTH_BOLT("Earth bolt", 29, 11, Element.EARTH),
	FIRE_BOLT("Fire bolt", 35, 12, Element.FIRE),

	WIND_BLAST("Wind blast", 41, 13, Element.AIR),
	WATER_BLAST("Water blast", 47, 14, Element.WATER),
	EARTH_BLAST("Earth blast", 53, 15, Element.EARTH),
	FIRE_BLAST("Fire blast", 59, 16, Element.FIRE),

	WIND_WAVE("Wind wave", 62, 17, Element.AIR),
	WATER_WAVE("Water wave", 65, 18, Element.WATER),
	EARTH_WAVE("Earth wave", 70, 19, Element.EARTH),
	FIRE_WAVE("Fire wave", 75, 20, Element.FIRE),

	WIND_SURGE("Wind surge", 81, 21, Element.AIR),
	WATER_SURGE("Water surge", 85, 22, Element.WATER),
	EARTH_SURGE("Earth surge", 90, 23, Element.EARTH),
	FIRE_SURGE("Fire surge", 95, 24, Element.FIRE),

	// Ancient spellbook. No element, but the strongest damage in the game.

	SMOKE_RUSH("Smoke rush", 50, 13, null),
	SHADOW_RUSH("Shadow rush", 52, 14, null),
	BLOOD_RUSH("Blood rush", 56, 15, null),
	ICE_RUSH("Ice rush", 58, 16, null),

	SMOKE_BURST("Smoke burst", 62, 17, null),
	SHADOW_BURST("Shadow burst", 64, 18, null),
	BLOOD_BURST("Blood burst", 68, 21, null),
	ICE_BURST("Ice burst", 70, 22, null),

	SMOKE_BLITZ("Smoke blitz", 74, 23, null),
	SHADOW_BLITZ("Shadow blitz", 76, 24, null),
	BLOOD_BLITZ("Blood blitz", 80, 25, null),
	ICE_BLITZ("Ice blitz", 82, 26, null),

	SMOKE_BARRAGE("Smoke barrage", 86, 27, null),
	SHADOW_BARRAGE("Shadow barrage", 88, 28, null),
	BLOOD_BARRAGE("Blood barrage", 92, 29, null),
	ICE_BARRAGE("Ice barrage", 94, 30, null);

	/** The four elements a monster can be weak to. */
	public enum Element
	{
		AIR,
		WATER,
		EARTH,
		FIRE;

		@Nullable
		public static Element parse(@Nullable String name)
		{
			if (name == null)
			{
				return null;
			}

			for (Element element : values())
			{
				if (element.name().equalsIgnoreCase(name))
				{
					return element;
				}
			}

			return null;
		}
	}

	private final String displayName;
	private final int magicLevel;
	private final int maxHit;
	private final Element element;

	Spell(String displayName, int magicLevel, int maxHit, @Nullable Element element)
	{
		this.displayName = displayName;
		this.magicLevel = magicLevel;
		this.maxHit = maxHit;
		this.element = element;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public int getMagicLevel()
	{
		return magicLevel;
	}

	public int getMaxHit()
	{
		return maxHit;
	}

	@Nullable
	public Element getElement()
	{
		return element;
	}

	/**
	 * What this spell would hit for against a given target, before gear.
	 * <p>
	 * A matching element adds the target's weakness severity to the base maximum, which is what lets a
	 * Fire Surge beat an Ice Barrage against something fire-weak.
	 */
	public int maxHitAgainst(Target target)
	{
		if (element == null || target == null || element != target.getWeaknessElement())
		{
			return maxHit;
		}

		return maxHit + maxHit * target.getWeaknessSeverity() / 100;
	}

	/**
	 * The best spell for this target at this level.
	 * <p>
	 * Ranked by what each would actually hit for rather than by raw max hit, so an elemental spell wins
	 * where the weakness makes it win and Ice Barrage wins everywhere else.
	 *
	 * @param magicLevel the caster's Magic level
	 * @param ancients   whether the ancient spellbook is available
	 */
	public static Spell bestFor(Target target, int magicLevel, boolean ancients)
	{
		Spell best = null;
		int bestDamage = -1;

		for (Spell spell : values())
		{
			if (spell.magicLevel > magicLevel || (!ancients && spell.element == null))
			{
				continue;
			}

			int damage = spell.maxHitAgainst(target);
			if (damage > bestDamage)
			{
				bestDamage = damage;
				best = spell;
			}
		}

		return best;
	}

	/**
	 * Whether the twinflame staff doubles up on this spell: the standard book's bolt, blast and wave
	 * spells only, never a strike, a surge, or anything ancient.
	 */
	public boolean firesTwice()
	{
		if (element == null)
		{
			return false;
		}

		String name = displayName.toLowerCase();
		return name.contains("bolt") || name.contains("blast") || name.contains("wave");
	}

	/**
	 * The best spell to cast holding a twinflame staff.
	 * <p>
	 * The staff fires a second hit for two fifths on bolt, blast and wave spells — so a Fire Wave with
	 * the staff can beat a Fire Surge without it, and the plain "strongest spell" answer is wrong while
	 * it is held. Choosing the spell without knowing the weapon meant the staff's effect could never
	 * apply to the spell that got chosen, and so never applied at all.
	 */
	public static Spell bestForTwinflame(Target target, int magicLevel, boolean ancients)
	{
		Spell best = bestFor(target, magicLevel, ancients);
		double bestDamage = best == null ? 0 : best.maxHitAgainst(target);

		for (Spell spell : values())
		{
			if (spell.magicLevel > magicLevel || !spell.firesTwice())
			{
				continue;
			}

			double doubled = spell.maxHitAgainst(target) * 1.4;
			if (doubled > bestDamage)
			{
				bestDamage = doubled;
				best = spell;
			}
		}

		return best;
	}

	/**
	 * Every spell castable at this level, best first, for showing the alternatives.
	 */
	public static List<Spell> castableAt(int magicLevel, boolean ancients)
	{
		List<Spell> castable = new ArrayList<>();
		for (Spell spell : values())
		{
			if (spell.magicLevel <= magicLevel && (ancients || spell.element != null))
			{
				castable.add(spell);
			}
		}

		return castable;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.gearforge.dps;

import com.gearforge.data.EquipmentStats;
import java.util.EnumSet;
import java.util.Set;
import lombok.Builder;
import lombok.Value;

/**
 * What is being hit.
 * <p>
 * Magic uses the target's <em>Magic</em> level in its defence roll rather than its Defence level,
 * which is why both are tracked separately.
 */
@Value
@Builder(toBuilder = true)
public class Target
{
	@Builder.Default
	String name = "Dummy";

	int defenceLevel;
	int magicLevel;

	/**
	 * The target's magic <em>attack</em> bonus. Only the twisted bow uses it, and it scales off
	 * whichever of this and the magic level is higher.
	 */
	int magicAttack;

	/** Defensive bonuses. Only the defence fields and slot are meaningful here. */
	EquipmentStats defensiveBonuses;

	/** Number of tiles across. Drives scythe and colossal blade multi-hit behaviour later. */
	@Builder.Default
	int size = 1;

	@Builder.Default
	Set<MonsterAttribute> attributes = EnumSet.noneOf(MonsterAttribute.class);

	/**
	 * The element this target is weak to, or null. A spell of that element gains the severity below as
	 * a percentage of both its accuracy and its maximum, which is large enough to change which spell
	 * is worth casting.
	 */
	Spell.Element weaknessElement;

	int weaknessSeverity;

	/**
	 * A target that rolls zero defence — the neutral baseline the BiS tab uses when no boss is
	 * selected, matching a combat dummy.
	 */
	public static Target dummy()
	{
		return Target.builder()
			.name("Dummy")
			.defenceLevel(0)
			.magicLevel(0)
			.defensiveBonuses(EquipmentStats.builder().build())
			.build();
	}

	public boolean hasAttribute(MonsterAttribute attribute)
	{
		return attributes.contains(attribute);
	}
}

package com.gearforge.dps;

/**
 * Void multipliers. Only applies when the full set is worn, which the caller is responsible for
 * establishing — {@code SetEffectRegistry} will do that once it exists.
 * <p>
 * Elite void is identical to regular void for melee and for ranged accuracy; it differs only in
 * ranged strength (1.125) and in magic damage, which is handled as a damage-side set effect rather
 * than here.
 */
public enum VoidSet
{
	NONE(1.0, 1.0),
	MELEE(1.1, 1.1),
	RANGED(1.1, 1.1),
	ELITE_RANGED(1.1, 1.125),
	MAGIC(1.45, 1.0);

	private final double accuracy;
	private final double strength;

	VoidSet(double accuracy, double strength)
	{
		this.accuracy = accuracy;
		this.strength = strength;
	}

	public double accuracyMultiplier()
	{
		return accuracy;
	}

	public double strengthMultiplier()
	{
		return strength;
	}
}

package com.gearforge.optimizer;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.data.GearItem;
import java.util.Map;

/**
 * Structural rules about what can be worn together.
 * <p>
 * Only rules that can be decided from data we actually have are implemented. Equipment level and
 * quest requirements are deliberately absent: RuneLite's item data carries no requirements, so
 * enforcing them needs a generated dataset. Until that exists the optimizer can suggest an item the
 * player owns but cannot yet equip — see the README for the caveat rather than guessing at limits.
 */
public final class Constraints
{
	private Constraints()
	{
	}

	public static boolean isTwoHanded(GearItem item)
	{
		return item != null && item.getStats().isTwoHanded();
	}

	/**
	 * Whether an item can actually be attacked with.
	 * <p>
	 * Some weapon-slot items carry a nonsensical attack speed — a monkey greegree is {@code -1}, and
	 * around 29 novelty items are {@code 0}. Left unchecked those become one-tick weapons and score as
	 * wildly best-in-slot. Anything without a positive speed is not a weapon.
	 */
	public static boolean isUsableWeapon(GearItem item)
	{
		return item != null && item.getStats().getSpeed() > 0;
	}

	/**
	 * A two-handed weapon occupies the shield slot as well, so the two can never coexist.
	 */
	public static boolean isValid(Map<EquipmentSlot, GearItem> setup)
	{
		GearItem weapon = setup.get(EquipmentSlot.WEAPON);
		GearItem shield = setup.get(EquipmentSlot.SHIELD);

		return !(isTwoHanded(weapon) && shield != null);
	}

	/**
	 * Whether an item can occupy the slot it claims. Guards against a caller putting a helmet in the
	 * boots slot when assembling setups by hand.
	 */
	public static boolean fitsSlot(GearItem item, EquipmentSlot slot)
	{
		return item != null && item.getStats().getSlot() == slot.getSlotIndex();
	}
}

package com.gearforge.optimizer;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.data.EquipmentStats;
import com.gearforge.data.GearItem;
import com.gearforge.data.ItemCategories;
import com.gearforge.dps.CombatContext;
import com.gearforge.dps.BoltEffect;
import com.gearforge.dps.CombatStyle;
import com.gearforge.dps.DpsEngine;
import com.gearforge.dps.PoweredStaff;
import com.gearforge.dps.SetEffectRegistry;
import com.gearforge.dps.SetEffects;
import com.gearforge.dps.SetupScore;
import com.gearforge.dps.Spell;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.gameval.ItemID;

/**
 * Finds the highest-DPS setup from what the player owns.
 * <p>
 * DPS is not slot-independent — a two-handed weapon costs you the shield, void is worthless until the
 * whole set is on, and a salve amulet changes what the helmet slot is worth. So this scores whole
 * setups rather than picking per slot, using a beam search ordered weapon-first because the weapon
 * dominates everything downstream.
 * <p>
 * The candidate pool per slot is the top few items by raw offensive bonus <em>plus</em> every item the
 * set effect registry cares about. Without that second part a void piece would be pruned for having
 * poor stats, and the set bonus would never be discovered.
 */
@Singleton
public class DpsOptimizer
{
	/**
	 * How many items per slot survive the raw-stat pre-filter.
	 * <p>
	 * Measured, not guessed. At five, the search fell short of an exhaustive one in every one of
	 * fifteen deep banks, by up to 4.16%. At ten it was still short in thirteen; at fifteen, six. At
	 * twenty it matched exhaustive every time, and stayed there at thirty and forty.
	 * <p>
	 * The failure the low number caused is invisible from outside: an item that is second best at both
	 * accuracy and strength beats items that are first at one, but never enters the search, and the
	 * wrong answer is presented with the same confidence as the right one.
	 * <p>
	 * {@code OptimizerBreadthTest} holds the measurement and fails if the shipped breadth stops
	 * matching an exhaustive search, or stops being fast enough to run on a gear change.
	 */
	private static final int CANDIDATES_PER_SLOT = 20;

	/** How many partial setups survive each beam step. */
	private static final int BEAM_WIDTH = 50;

	/** Rerolls a magic miss, but only alongside a one-handed weapon. */
	private static final int CONFLICTION_GAUNTLETS = 31106;

	/**
	 * The blowpipes, which are loaded with darts rather than fed from the ammo slot.
	 * <p>
	 * Both the pipe and the dart are weapon-slot items, so nothing ever put them together: a toxic
	 * blowpipe was scored on its own 20 ranged strength while rune knives scored 26, and the knives
	 * won. In game the dart's strength adds to the pipe's, which is the whole point of the weapon.
	 */
	private static final Set<Integer> BLOWPIPES = new HashSet<>(Arrays.asList(
		12926, 12924, 28688, 28687, 30374, 30373, 31575, 31577, 31579, 31581, 31583, 31585));

	/** Fires a second hit on bolt, blast and wave spells, which changes which spell is worth casting. */
	private static final int TWINFLAME_STAFF = 30634;

	/** Thrown with the arm rather than drawn, so it reads Strength instead of Ranged. */
	private static final int ECLIPSE_ATLATL = 29000;

	/**
	 * Adjustable so the breadth can be measured rather than assumed. The pre-filter keeps the best few
	 * items per slot by raw offensive stat, which is a guess at what might win — an item that is second
	 * best at both accuracy and strength can beat items that are first at one, and would never enter
	 * the search.
	 */
	private final int candidatesPerSlot;

	/**
	 * Weapon first because it dominates; shield straight after so the two-handed decision resolves
	 * early rather than polluting the beam.
	 */
	private static final List<EquipmentSlot> SLOT_ORDER = Arrays.asList(
		EquipmentSlot.WEAPON,
		EquipmentSlot.SHIELD,
		EquipmentSlot.HEAD,
		EquipmentSlot.BODY,
		EquipmentSlot.LEGS,
		EquipmentSlot.GLOVES,
		EquipmentSlot.BOOTS,
		EquipmentSlot.AMULET,
		EquipmentSlot.CAPE,
		EquipmentSlot.RING,
		EquipmentSlot.AMMO);

	private final DpsEngine engine;
	private final SetEffectRegistry setEffects;
	private final ItemCategories itemCategories;

	@Inject
	public DpsOptimizer(DpsEngine engine, SetEffectRegistry setEffects, ItemCategories itemCategories)
	{
		this(engine, setEffects, itemCategories, CANDIDATES_PER_SLOT);
	}

	static int candidatesPerSlotDefault()
	{
		return CANDIDATES_PER_SLOT;
	}

	/** For measuring how much the pre-filter costs in accuracy. */
	DpsOptimizer(
		DpsEngine engine, SetEffectRegistry setEffects, ItemCategories itemCategories,
		int candidatesPerSlot)
	{
		this.candidatesPerSlot = candidatesPerSlot;
		this.engine = engine;
		this.setEffects = setEffects;
		this.itemCategories = itemCategories;
	}

	/**
	 * @param owned        every equippable item the player has
	 * @param template     levels, prayer, style and target; equipment and speed are filled in per candidate
	 * @param onSlayerTask whether slayer-task effects should count
	 * @param topN         how many results to return
	 * @return the best setups, highest DPS first, or empty if the player owns no usable weapon
	 */
	public List<ScoredSetup> best(
		Collection<GearItem> owned,
		CombatContext template,
		boolean onSlayerTask,
		int topN)
	{
		Map<EquipmentSlot, List<GearItem>> candidates = buildCandidates(owned, template.getStyle());

		// Worked out once: a blowpipe is only as good as the best dart in the bank.
		int dartStrength = bestDartStrength(owned);

		List<GearItem> weapons = candidates.get(EquipmentSlot.WEAPON);
		if (weapons == null || weapons.isEmpty())
		{
			return new ArrayList<>();
		}

		List<Map<EquipmentSlot, GearItem>> beam = new ArrayList<>();
		beam.add(new EnumMap<>(EquipmentSlot.class));

		for (EquipmentSlot slot : SLOT_ORDER)
		{
			beam = extend(beam, slot, candidates.get(slot), template, onSlayerTask, dartStrength);
		}

		return rank(beam, template, onSlayerTask, topN, dartStrength);
	}

	/**
	 * Grows every partial setup by each candidate for this slot (plus leaving it empty), then keeps
	 * only the best {@value #BEAM_WIDTH}.
	 */
	private List<Map<EquipmentSlot, GearItem>> extend(
		List<Map<EquipmentSlot, GearItem>> beam,
		EquipmentSlot slot,
		@Nullable List<GearItem> slotCandidates,
		CombatContext template,
		boolean onSlayerTask,
		int dartStrength)
	{
		List<Map<EquipmentSlot, GearItem>> grown = new ArrayList<>();

		for (Map<EquipmentSlot, GearItem> partial : beam)
		{
			// Leaving a slot empty is always allowed, and for the shield it is mandatory behind a
			// two-hander.
			grown.add(partial);

			if (slotCandidates == null)
			{
				continue;
			}

			boolean shieldBlocked = slot == EquipmentSlot.SHIELD
				&& Constraints.isTwoHanded(partial.get(EquipmentSlot.WEAPON));

			if (shieldBlocked)
			{
				continue;
			}

			GearItem weapon = partial.get(EquipmentSlot.WEAPON);

			for (GearItem candidate : slotCandidates)
			{
				// Ammo has to actually fit the weapon — otherwise the search happily pairs a crossbow
				// with arrows, which reads as a confident recommendation and is simply wrong.
				//
				// A weapon that fires nothing is worse than that. Knives and darts are thrown from the
				// hand, so a quiver of bolts worn beside them adds nothing in game — but its ranged
				// strength was being summed into the setup all the same, which is how rune knives came
				// to out-score a bow of faerdhinen.
				if (slot == EquipmentSlot.AMMO
					&& weapon != null
					&& (!itemCategories.requiresAmmo(weapon.getItemId())
						|| !itemCategories.ammoFits(weapon.getItemId(), candidate.getItemId())))
				{
					continue;
				}

				Map<EquipmentSlot, GearItem> extended = new EnumMap<>(partial);
				extended.put(slot, candidate);
				grown.add(extended);
			}
		}

		// A setup with no weapon cannot be scored, so keep those alive unscored until one is chosen.
		if (slot == EquipmentSlot.WEAPON)
		{
			grown.removeIf(setup -> setup.get(EquipmentSlot.WEAPON) == null);
		}

		grown.sort(Comparator.comparingDouble(
			(Map<EquipmentSlot, GearItem> setup) -> score(setup, template, onSlayerTask, dartStrength).getDps()).reversed());

		return grown.subList(0, Math.min(BEAM_WIDTH, grown.size()));
	}

	/**
	 * The spell this weapon would be cast with.
	 * <p>
	 * Chosen before the weapon is known, so a twinflame staff never got a spell it could double. Now
	 * that the weapon is in hand, reconsider: a Fire Wave fired twice beats a Fire Surge fired once.
	 */
	private static CombatContext withSpellFor(GearItem weapon, CombatContext template)
	{
		if (!template.getStyle().isMagic() || weapon.getItemId() != TWINFLAME_STAFF)
		{
			return template;
		}

		return template.toBuilder()
			.spell(Spell.bestForTwinflame(template.getTarget(), template.getMagicLevel(), true))
			.build();
	}

	private List<ScoredSetup> rank(
		List<Map<EquipmentSlot, GearItem>> beam,
		CombatContext template,
		boolean onSlayerTask,
		int topN,
		int dartStrength)
	{
		List<ScoredSetup> scored = new ArrayList<>();
		Set<String> seen = new HashSet<>();

		for (Map<EquipmentSlot, GearItem> setup : beam)
		{
			SetEffects effects = setEffects.evaluate(
				setup.values(), template.getStyle(), template.getTarget(), onSlayerTask);

			GearItem weapon = setup.get(EquipmentSlot.WEAPON);
			// The spell goes on the result so the panel can say which one it assumed, rather than
			// claiming Ice Barrage for a setup that is casting a Fire Surge.
			Spell spell = weapon == null ? template.getSpell() : withSpellFor(weapon, template).getSpell();

			ScoredSetup candidate = new ScoredSetup(
				setup, score(setup, template, onSlayerTask, dartStrength), template.getStyle(),
				effects.getNotes(), spell);
			if (seen.add(candidate.signature()))
			{
				scored.add(candidate);
			}
		}

		scored.sort(ScoredSetup.BY_DPS_DESC);
		return scored.subList(0, Math.min(topN, scored.size()));
	}

	/**
	 * The strongest dart in the bank, which is what a blowpipe would be loaded with.
	 */
	private static int bestDartStrength(Collection<GearItem> owned)
	{
		int best = 0;
		for (GearItem item : owned)
		{
			if (item.getName().toLowerCase().endsWith("dart")
				&& item.getStats().getRangedStrength() > best)
			{
				best = item.getStats().getRangedStrength();
			}
		}

		return best;
	}

	/**
	 * Scores a complete or partial setup. Empty slots simply contribute nothing.
	 */
	private SetupScore score(
		Map<EquipmentSlot, GearItem> setup, CombatContext template, boolean onSlayerTask,
		int dartStrength)
	{
		GearItem weapon = setup.get(EquipmentSlot.WEAPON);
		if (weapon == null)
		{
			return SetupScore.builder().dps(0).build();
		}

		// A bow with no arrows cannot attack, so it must not be scored as though it can.
		if (itemCategories.requiresAmmo(weapon.getItemId()))
		{
			GearItem ammo = setup.get(EquipmentSlot.AMMO);
			if (ammo == null || !itemCategories.ammoFits(weapon.getItemId(), ammo.getItemId()))
			{
				return SetupScore.builder().dps(0).build();
			}
		}

		List<EquipmentStats> pieces = new ArrayList<>();
		for (GearItem item : setup.values())
		{
			pieces.add(item.getStats());
		}

		// A blowpipe fires the darts loaded into it, and both are weapon-slot items, so the two never
		// met in the search. Without the dart the pipe is scored on a fraction of its real strength.
		if (BLOWPIPES.contains(weapon.getItemId()) && dartStrength > 0)
		{
			pieces.add(EquipmentStats.builder().rangedStrength(dartStrength).build());
		}

		CombatContext scored = withSpellFor(weapon, template);

		// This call dropped the spell entirely, so the elemental tomes and the twinflame staff could
		// never fire however the spell was chosen — the effects were modelled and then never reached.
		SetEffects effects = setEffects.evaluate(
			setup.values(), scored.getStyle(), scored.getTarget(), onSlayerTask, scored.getSpell());

		PoweredStaff staff = scored.getStyle().isMagic()
			? PoweredStaff.forItem(weapon.getItemId())
			: null;

		// A spellbook cast keeps its own 5-tick speed regardless of what is held. A powered staff does
		// not cast — it attacks at its own speed, and takes the attack style's magic bonus.
		boolean spellbookCast = scored.getStyle().isMagic() && staff == null;
		int speed = spellbookCast ? scored.getWeaponSpeedTicks() : weapon.getStats().getSpeed();

		CombatContext context = scored.toBuilder()
			.equipment(EquipmentStats.sum(pieces))
			.weaponSpeedTicks(speed)
			.voidSet(effects.getVoidSet())
			.accuracyMultiplier(effects.getAccuracyMultiplier())
			.damageMultiplier(effects.getDamageMultiplier())
			.flatMaxHit(effects.getFlatMaxHit())
			.brimstoneRing(effects.isBrimstoneRing())
			.poweredStaffType(staff)
			.poweredStaff(staff != null)
			// Confliction gauntlets reroll a magic miss, but only with a one-handed weapon.
			.rerollsMisses(effects.isRerollsMisses()
				|| (template.getStyle().isMagic()
					&& setup.containsKey(EquipmentSlot.GLOVES)
					&& setup.get(EquipmentSlot.GLOVES).getItemId() == CONFLICTION_GAUNTLETS
					&& !weapon.getStats().isTwoHanded()))
			.build();

		return engine.score(context);
	}

	/**
	 * Top few per slot by offensive relevance, unioned with everything the set effect registry needs.
	 */
	private Map<EquipmentSlot, List<GearItem>> buildCandidates(Collection<GearItem> owned, CombatStyle style)
	{
		Map<EquipmentSlot, List<GearItem>> bySlot = new EnumMap<>(EquipmentSlot.class);
		for (GearItem item : owned)
		{
			EquipmentSlot slot = EquipmentSlot.fromSlotIndex(item.getStats().getSlot());

			// A weapon that cannot swing this way is not a candidate. A whip's three attack options are
			// all slash, so offering one for a crush setup was recommending something impossible.
			if (slot == EquipmentSlot.WEAPON && !itemCategories.canUseStyle(item.getItemId(), style))
			{
				continue;
			}
			if (slot != null)
			{
				bySlot.computeIfAbsent(slot, key -> new ArrayList<>()).add(item);
			}
		}

		Set<Integer> effectItems = setEffects.relevantItemIds();
		Map<EquipmentSlot, List<GearItem>> candidates = new EnumMap<>(EquipmentSlot.class);

		for (Map.Entry<EquipmentSlot, List<GearItem>> entry : bySlot.entrySet())
		{
			List<GearItem> items = entry.getValue();

			if (entry.getKey() == EquipmentSlot.WEAPON)
			{
				// A weapon has to match the style. Otherwise, with no bow owned, a longsword wins the
				// ranged slot simply by being the least bad of the wrong options.
				List<GearItem> suitable = new ArrayList<>();
				for (GearItem item : items)
				{
					if (Constraints.isUsableWeapon(item)
						&& itemCategories.suitsStyle(item.getItemId(), style.name()))
					{
						suitable.add(item);
					}
				}

				items = suitable;
			}

			if (entry.getKey() == EquipmentSlot.WEAPON)
			{
				items = new ArrayList<>(items);
				items.removeIf(item -> !Constraints.isUsableWeapon(item));
			}

			// LinkedHashSet keeps the pool deterministic and free of duplicates across the two passes.
			Set<GearItem> pool = new LinkedHashSet<>();
			pool.addAll(topBy(items, accuracyRelevance(style)));
			pool.addAll(topBy(items, damageRelevance(style)));

			for (GearItem item : items)
			{
				if (effectItems.contains(item.getItemId()))
				{
					pool.add(item);
				}
			}

			candidates.put(entry.getKey(), new ArrayList<>(pool));
		}

		return candidates;
	}

	private List<GearItem> topBy(List<GearItem> items, Comparator<GearItem> order)
	{
		List<GearItem> sorted = new ArrayList<>(items);
		sorted.sort(order);
		return sorted.subList(0, Math.min(candidatesPerSlot, sorted.size()));
	}

	private static Comparator<GearItem> accuracyRelevance(CombatStyle style)
	{
		return Comparator
			.comparingInt((GearItem item) -> style.attackBonusOf(item.getStats())).reversed()
			.thenComparing(tieBreak(style));
	}

	private static Comparator<GearItem> damageRelevance(CombatStyle style)
	{
		if (style.isMagic())
		{
			return Comparator
				.comparingDouble((GearItem item) -> item.getStats().getMagicDamage()).reversed()
				.thenComparing(tieBreak(style));
		}

		if (style.isRanged())
		{
			return Comparator
				.comparingInt((GearItem item) -> item.getStats().getRangedStrength()).reversed()
				.thenComparing(tieBreak(style));
		}

		return Comparator
			.comparingInt((GearItem item) -> item.getStats().getStrength()).reversed()
			.thenComparing(tieBreak(style));
	}

	/**
	 * The tie-break, once offence is equal.
	 * <p>
	 * Offensive ties are common and exact. The oathplate chest is +16 slash and nothing else; the
	 * fighter torso is +0 across the board. Both give +4 strength, so for stab and crush the two are
	 * identical to the DPS engine and nothing is left to separate them. This used to fall through to
	 * the item name, which meant the alphabet decided — and "Fighter torso" beat "Oathplate chest"
	 * every time.
	 * <p>
	 * Defence is the right decider: at equal damage a player wants the piece that survives better.
	 * Prayer bonus follows, then the name, so a run is still reproducible.
	 */
	static final Comparator<GearItem> BY_DEFENSIVE_VALUE = Comparator
		.comparingInt((GearItem item) -> defensiveValue(item.getStats())).reversed()
		.thenComparing(Comparator.comparingInt((GearItem item) -> item.getStats().getPrayer()).reversed())
		.thenComparing(GearItem::getName);

	/**
	 * Ranks the pieces that are level on the stat being sorted by. Strength before defence: Dharok's
	 * platelegs are tankier than oathplate legs and worse in every way that matters, and defence alone
	 * put them first.
	 */
	private static Comparator<GearItem> tieBreak(CombatStyle style)
	{
		return Comparator
			.comparingInt((GearItem item) -> strengthFor(style, item)).reversed()
			.thenComparing(BY_DEFENSIVE_VALUE);
	}

	private static int strengthFor(CombatStyle style, GearItem item)
	{
		EquipmentStats stats = item.getStats();

		if (style.isRanged())
		{
			return stats.getRangedStrength();
		}

		return style.isMagic() ? (int) (stats.getMagicDamage() * 10) : stats.getStrength();
	}

	static int defensiveValue(EquipmentStats stats)
	{
		return stats.getDstab() + stats.getDslash() + stats.getDcrush()
			+ stats.getDmagic() + stats.getDrange();
	}
}

package com.gearforge.optimizer;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.data.GearItem;
import com.gearforge.data.GearStat;
import java.util.ArrayList;
import java.util.Collection;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Singleton;

/**
 * Best setup for a single slot-independent bonus — defence against one style, or prayer.
 * <p>
 * For these stats each slot really is independent, so picking the best item per slot is not a
 * heuristic, it is optimal. The one exception is the weapon and shield pair: a two-handed weapon
 * blocks the shield, so both arrangements are costed and the better one wins. Picking the highest
 * weapon first and discovering the shield is now unavailable is exactly the bug this avoids.
 * <p>
 * Offensive DPS is <em>not</em> slot-independent and must not use this — that is what
 * {@code DpsOptimizer} is for.
 */
@Singleton
public class GreedyOptimizer
{
	public OptimizerResult best(Collection<GearItem> owned, GearStat stat)
	{
		Map<EquipmentSlot, List<GearItem>> bySlot = groupBySlot(owned);
		Map<EquipmentSlot, GearItem> chosen = new EnumMap<>(EquipmentSlot.class);
		List<String> reasons = new ArrayList<>();
		double total = 0.0;

		for (EquipmentSlot slot : EquipmentSlot.values())
		{
			if (slot == EquipmentSlot.WEAPON || slot == EquipmentSlot.SHIELD)
			{
				continue;
			}

			GearItem best = bestIn(bySlot.get(slot), stat, null);
			if (best != null)
			{
				chosen.put(slot, best);
				total += best.statValue(stat);
			}
		}

		total += chooseWeaponAndShield(bySlot, stat, chosen, reasons);

		return new OptimizerResult(chosen, total, reasons);
	}

	/**
	 * Costs "best one-hander plus best shield" against "best two-hander" and takes the winner.
	 *
	 * @return the combined value contributed by the weapon and shield slots
	 */
	private double chooseWeaponAndShield(
		Map<EquipmentSlot, List<GearItem>> bySlot,
		GearStat stat,
		Map<EquipmentSlot, GearItem> chosen,
		List<String> reasons)
	{
		List<GearItem> weapons = bySlot.get(EquipmentSlot.WEAPON);

		GearItem oneHanded = bestIn(weapons, stat, item -> !Constraints.isTwoHanded(item));
		GearItem twoHanded = bestIn(weapons, stat, Constraints::isTwoHanded);
		GearItem shield = bestIn(bySlot.get(EquipmentSlot.SHIELD), stat, null);

		double withShield = valueOf(oneHanded, stat) + valueOf(shield, stat);
		double withTwoHander = valueOf(twoHanded, stat);

		if (withTwoHander > withShield)
		{
			chosen.put(EquipmentSlot.WEAPON, twoHanded);
			if (shield != null)
			{
				reasons.add(twoHanded.getName() + " beats " + oneHanded(oneHanded)
					+ " with " + shield.getName() + ", even losing the shield slot");
			}

			return withTwoHander;
		}

		if (oneHanded != null)
		{
			chosen.put(EquipmentSlot.WEAPON, oneHanded);
		}

		if (shield != null)
		{
			chosen.put(EquipmentSlot.SHIELD, shield);
			if (twoHanded != null)
			{
				reasons.add("Kept the shield slot — " + shield.getName()
					+ " is worth more than upgrading to " + twoHanded.getName());
			}
		}

		return withShield;
	}

	private static String oneHanded(@Nullable GearItem item)
	{
		return item == null ? "an empty weapon slot" : item.getName();
	}

	/**
	 * The highest-scoring candidate, or null if none is worth wearing. Items scoring zero or less are
	 * rejected: an empty slot contributes nothing, so a negative item is strictly worse than nothing.
	 */
	@Nullable
	private static GearItem bestIn(
		@Nullable Collection<GearItem> candidates,
		GearStat stat,
		@Nullable java.util.function.Predicate<GearItem> filter)
	{
		if (candidates == null)
		{
			return null;
		}

		GearItem best = null;
		for (GearItem candidate : candidates)
		{
			if (filter != null && !filter.test(candidate))
			{
				continue;
			}

			if (candidate.statValue(stat) <= 0)
			{
				continue;
			}

			if (best == null || isBetter(candidate, best, stat))
			{
				best = candidate;
			}
		}

		return best;
	}

	/**
	 * Ties break on name then id, so repeated runs return the same setup.
	 */
	private static boolean isBetter(GearItem candidate, GearItem incumbent, GearStat stat)
	{
		int byValue = Double.compare(candidate.statValue(stat), incumbent.statValue(stat));
		if (byValue != 0)
		{
			return byValue > 0;
		}

		int byName = candidate.getName().compareTo(incumbent.getName());
		return byName != 0 ? byName < 0 : candidate.getItemId() < incumbent.getItemId();
	}

	private static double valueOf(@Nullable GearItem item, GearStat stat)
	{
		return item == null ? 0.0 : item.statValue(stat);
	}

	private static Map<EquipmentSlot, List<GearItem>> groupBySlot(Collection<GearItem> owned)
	{
		Map<EquipmentSlot, List<GearItem>> bySlot = new EnumMap<>(EquipmentSlot.class);

		for (GearItem item : owned)
		{
			EquipmentSlot slot = EquipmentSlot.fromSlotIndex(item.getStats().getSlot());
			if (slot != null)
			{
				bySlot.computeIfAbsent(slot, key -> new ArrayList<>()).add(item);
			}
		}

		return bySlot;
	}
}

package com.gearforge.optimizer;

import com.gearforge.data.ItemCategories;
import com.gearforge.dps.DpsEngine;
import com.gearforge.dps.SetEffectRegistry;

/**
 * Exposes the optimizer's search breadth so it can be measured.
 * <p>
 * The pre-filter keeps only the best few items per slot before searching, which is a guess at what
 * might win. A wrong guess is invisible — the item simply never enters the search — so the cost of
 * that guess has to be measured rather than assumed. This is the seam that lets a test do it.
 */
public final class OptimizerBreadth
{
	/** The shipped breadth. */
	public static final int CANDIDATES_PER_SLOT = DpsOptimizer.candidatesPerSlotDefault();

	private OptimizerBreadth()
	{
	}

	public static DpsOptimizer withBreadth(
		DpsEngine engine, SetEffectRegistry setEffects, ItemCategories itemCategories, int candidatesPerSlot)
	{
		return new DpsOptimizer(engine, setEffects, itemCategories, candidatesPerSlot);
	}
}

package com.gearforge.optimizer;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.data.EquipmentStats;
import com.gearforge.data.GearItem;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/**
 * A chosen setup and why it was chosen.
 * <p>
 * The reasons are not diagnostics — the spec requires the BiS tab to always show its reasoning, so
 * they are part of what gets rendered.
 */
public final class OptimizerResult
{
	private final Map<EquipmentSlot, GearItem> setup;
	private final double total;
	private final List<String> reasons;

	public OptimizerResult(Map<EquipmentSlot, GearItem> setup, double total, List<String> reasons)
	{
		this.setup = new EnumMap<>(setup);
		this.total = total;
		this.reasons = new ArrayList<>(reasons);
	}

	/**
	 * The chosen item per slot. Slots the player has nothing useful for are absent rather than null.
	 */
	public Map<EquipmentSlot, GearItem> getSetup()
	{
		return Collections.unmodifiableMap(setup);
	}

	public double getTotal()
	{
		return total;
	}

	public List<String> getReasons()
	{
		return Collections.unmodifiableList(reasons);
	}

	public boolean isEmpty()
	{
		return setup.isEmpty();
	}

	/**
	 * The combined bonuses of everything chosen, for scoring or display.
	 */
	public EquipmentStats totalStats()
	{
		List<EquipmentStats> pieces = new ArrayList<>();
		for (GearItem item : setup.values())
		{
			pieces.add(item.getStats());
		}

		return EquipmentStats.sum(pieces);
	}
}

package com.gearforge.optimizer;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.data.GearItem;
import com.gearforge.data.EquipmentStats;
import com.gearforge.dps.CombatStyle;
import com.gearforge.dps.SetupScore;
import com.gearforge.dps.Spell;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;

/**
 * A candidate setup with its score and the effects that applied to it.
 */
public final class ScoredSetup
{
	/**
	 * Highest DPS first, then the better offensive stats, then the setup that survives better.
	 * <p>
	 * Whole setups tie on DPS constantly, because max hit is an integer: two more strength usually
	 * changes nothing after truncation. Breaking those ties on defence alone was wrong — it handed the
	 * legs slot to Dharok's over oathplate, when oathplate is +2 strength and +12 slash and simply
	 * better. Offence has to come first, because a stat that does not move the maximum today still
	 * moves it with a different boost or a different weapon.
	 * <p>
	 * Defence remains the decider when offence is genuinely identical, which is the fighter torso and
	 * oathplate chest case that started all this.
	 */
	public static final Comparator<ScoredSetup> BY_DPS_DESC =
		Comparator.comparingDouble((ScoredSetup setup) -> setup.getScore().getDps()).reversed()
			.thenComparing(Comparator.comparingInt(ScoredSetup::offensiveValue).reversed())
			.thenComparing(Comparator.comparingInt(ScoredSetup::defensiveValue).reversed());

	private final Map<EquipmentSlot, GearItem> setup;
	private final SetupScore score;
	private final CombatStyle style;
	private final List<String> notes;
	private final Spell spell;

	ScoredSetup(
		Map<EquipmentSlot, GearItem> setup, SetupScore score, CombatStyle style, List<String> notes)
	{
		this(setup, score, style, notes, null);
	}

	ScoredSetup(
		Map<EquipmentSlot, GearItem> setup, SetupScore score, CombatStyle style, List<String> notes,
		@Nullable Spell spell)
	{
		this.setup = new EnumMap<>(setup);
		this.score = score;
		this.style = style;
		this.notes = notes;
		this.spell = spell;
	}

	/**
	 * The spell this setup was scored casting, or null for anything that is not magic.
	 */
	@Nullable
	public Spell getSpell()
	{
		return spell;
	}

	public Map<EquipmentSlot, GearItem> getSetup()
	{
		return Collections.unmodifiableMap(setup);
	}

	public SetupScore getScore()
	{
		return score;
	}

	/**
	 * Why this setup scores what it does, e.g. "Salve (ei): target is undead".
	 */
	public List<String> getNotes()
	{
		return Collections.unmodifiableList(notes);
	}

	/**
	 * The offensive stats that matter for the style this setup was scored with. Used only to settle DPS
	 * ties, where the integer maximum has swallowed a real difference.
	 */
	private int offensiveValue()
	{
		int total = 0;
		for (GearItem item : setup.values())
		{
			EquipmentStats stats = item.getStats();
			total += style.attackBonusOf(stats);

			if (style.isRanged())
			{
				total += stats.getRangedStrength();
			}
			else if (style.isMagic())
			{
				total += (int) (stats.getMagicDamage() * 10);
			}
			else
			{
				total += stats.getStrength();
			}
		}

		return total;
	}

	/**
	 * Total defence across every worn piece, used only to settle DPS ties.
	 */
	private int defensiveValue()
	{
		int total = 0;
		for (GearItem item : setup.values())
		{
			total += DpsOptimizer.defensiveValue(item.getStats());
		}

		return total;
	}

	/**
	 * Identifies the combination of items, so near-identical setups can be de-duplicated.
	 */
	String signature()
	{
		StringBuilder builder = new StringBuilder();
		for (Map.Entry<EquipmentSlot, GearItem> entry : setup.entrySet())
		{
			builder.append(entry.getKey().name()).append(':').append(entry.getValue().getItemId()).append('|');
		}

		return builder.toString();
	}
}

package com.gearforge.optimizer;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.data.EquipmentStats;
import com.gearforge.data.GearItem;
import com.gearforge.data.ItemCategories;
import com.gearforge.data.Monster;
import com.gearforge.data.Reachability;
import com.gearforge.dps.CombatContext;
import com.gearforge.dps.CombatStyle;
import com.gearforge.dps.DamageDistribution;
import com.gearforge.dps.DpsEngine;
import com.gearforge.dps.MonsterAttribute;
import com.gearforge.dps.SpecDamage;
import com.gearforge.dps.SpecialAttack;
import com.gearforge.dps.SetupScore;
import com.gearforge.dps.Target;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Which special attack weapon to bring, given the setup you are already wearing.
 * <p>
 * The hard part is that specs are not comparable in their own terms. Claws are burst damage, the
 * voidwaker is guaranteed damage, and the dragon warhammer is almost no damage at all — its worth is
 * that everything afterwards lands more often. Ranking those against each other needs one currency.
 * <p>
 * The currency here is <b>damage added to the kill</b>. For a damage spec that is simply what it hits
 * for, less the ordinary attack it replaced. For a defence-reduction spec it is the time the lower
 * defence saves you, valued at the damage you would have dealt in that time — which is why a warhammer
 * scores well on a long boss and near zero on a crab, exactly as it should.
 * <p>
 * The setup matters, and that is the point: the spec weapon is swapped into the gear the BiS tab just
 * recommended, so your body slot's strength bonus raises what the claws and the voidwaker hit for. A
 * two-handed spec weapon correctly costs you the shield.
 */
@Singleton
public class SpecFinder
{
	private final DpsEngine engine;
	private final ItemCategories itemCategories;

	@Inject
	public SpecFinder(DpsEngine engine, ItemCategories itemCategories)
	{
		this.engine = engine;
		this.itemCategories = itemCategories;
	}

	/**
	 * @param setup    the gear being worn, whose weapon the spec weapon replaces
	 * @param owned    everything the player has, searched for spec weapons
	 * @param template the context the setup was scored with — target, levels, prayer, boost
	 * @return the worthwhile specs, best first
	 */
	public List<SpecSuggestion> find(
		Map<EquipmentSlot, GearItem> setup, List<GearItem> owned, CombatContext template)
	{
		return find(setup, owned, template, null);
	}

	/**
	 * @param monster the target, so a special that cannot physically reach it is not suggested — a
	 *                dragon warhammer is useless at Zulrah however good its numbers look
	 */
	public List<SpecSuggestion> find(
		Map<EquipmentSlot, GearItem> setup, List<GearItem> owned, CombatContext template,
		@Nullable Monster monster)
	{
		SetupScore baseline = engine.score(template);
		if (baseline.getDps() <= 0)
		{
			return Collections.emptyList();
		}

		double normalHit = averageOrdinaryHit(baseline);
		List<SpecSuggestion> suggestions = new ArrayList<>();

		for (GearItem candidate : owned)
		{
			SpecialAttack special = SpecialAttack.forItem(candidate.getItemId());
			if (special == null)
			{
				continue;
			}

			// A special that cannot reach the target is not a weaker suggestion, it is an impossible one.
			if (!canReach(candidate, monster))
			{
				continue;
			}

			// Everything else owned is returned, including specials that are not worth using here.
			// Filtering those out made owning a weapon look identical to not owning one.
			suggestions.add(evaluate(special, candidate, setup, template, baseline, normalHit));
		}

		suggestions.sort(SpecSuggestion.BEST_FIRST);
		return suggestions;
	}

	/**
	 * Whether this special could physically be used on the target. Melee needs the reach; a bow does
	 * not care.
	 */
	private boolean canReach(GearItem weapon, @Nullable Monster monster)
	{
		if (monster == null || styleFor(weapon) == CombatStyle.RANGED
			|| styleFor(weapon) == CombatStyle.MAGIC)
		{
			return true;
		}

		return Reachability.meleeCanReach(monster, itemCategories.hasReach(weapon.getItemId()));
	}

	private SpecSuggestion evaluate(
		SpecialAttack special,
		GearItem weapon,
		Map<EquipmentSlot, GearItem> setup,
		CombatContext template,
		SetupScore baseline,
		double normalHit)
	{
		CombatStyle style = styleFor(weapon);
		CombatContext specContext = template.toBuilder()
			.style(style)
			.poweredStaff(style.isMagic())
			.equipment(withWeapon(setup, weapon))
			.weaponSpeedTicks(Math.max(1, weapon.getStats().getSpeed()))
			.accuracyMultiplier(template.getAccuracyMultiplier() * special.getAccuracyMultiplier())
			.damageMultiplier(template.getDamageMultiplier() * special.getDamageMultiplier())
			.build();

		SetupScore specScore = engine.score(specContext);
		int targetSize = template.getTarget() == null ? 1 : template.getTarget().getSize();

		// A Magic special ignores spell damage entirely: its ceiling comes from the Magic level.
		int maxHit = special.getShape() == SpecialAttack.Shape.MAGIC_LEVEL_MAX
			? magicLevelMaxHit(special, template.getMagicLevel() + template.getMagicBoost())
			: specScore.getMaxHit();

		DamageDistribution damage =
			SpecDamage.of(special, specScore.getHitChance(), maxHit, targetSize);

		// An instant special costs no attack turn, so it is a hit gained rather than a hit swapped.
		double added = special.isInstant() ? damage.mean() : damage.mean() - normalHit;
		String note = null;

		if (special.reducesDefence())
		{
			double uplift = defenceReductionValue(special, template, baseline, specScore.getHitChance());
			added += uplift;

			if (uplift > 0)
			{
				note = String.format("worth %.0f damage over the rest of the kill", uplift);
			}
		}

		return new SpecSuggestion(special, weapon, added, damage.mean(), note);
	}

	/**
	 * What a landed defence reduction is worth, as damage.
	 * <p>
	 * Lower defence means every remaining attack lands more often, so the kill finishes sooner. That
	 * saved time is valued at the damage the setup would have dealt during it. A target with no
	 * hitpoints recorded cannot be valued this way, and scores zero rather than a guess.
	 */
	private double defenceReductionValue(
		SpecialAttack special, CombatContext template, SetupScore baseline, double landChance)
	{
		Target target = template.getTarget();
		if (target == null || template.getTargetHitpoints() <= 0 || target.getDefenceLevel() <= 0)
		{
			return 0;
		}

		boolean demon = target.getAttributes() != null
			&& target.getAttributes().contains(MonsterAttribute.DEMON);
		double fraction = special.defenceReductionAgainst(demon);
		int reducedDefence = (int) Math.floor(target.getDefenceLevel() * (1 - fraction));
		CombatContext reduced = template.toBuilder()
			.target(target.toBuilder().defenceLevel(reducedDefence).build())
			.build();

		double after = engine.score(reduced).getDps();
		if (after <= baseline.getDps())
		{
			return 0;
		}

		double hitpoints = template.getTargetHitpoints();
		double timeSaved = hitpoints / baseline.getDps() - hitpoints / after;
		return landChance * timeSaved * baseline.getDps();
	}

	/**
	 * The Magic specials scale their ceiling with Magic level and stop at a per-weapon cap.
	 */
	private static int magicLevelMaxHit(SpecialAttack special, int magicLevel)
	{
		int cap = special.getMagicLevelCap();
		return Math.max(1, Math.min(cap, (99 + cap * magicLevel) / 99));
	}

	/**
	 * The damage an ordinary attack of the current setup deals, which is what the spec replaces.
	 */
	private static double averageOrdinaryHit(SetupScore baseline)
	{
		return DamageDistribution.roll(baseline.getHitChance(), baseline.getMaxHit()).mean();
	}

	/**
	 * The setup's bonuses with the spec weapon in place of its own. A two-hander drops the shield,
	 * because you cannot hold both.
	 */
	private static EquipmentStats withWeapon(Map<EquipmentSlot, GearItem> setup, GearItem weapon)
	{
		Map<EquipmentSlot, GearItem> swapped = new EnumMap<>(EquipmentSlot.class);
		swapped.putAll(setup);
		swapped.put(EquipmentSlot.WEAPON, weapon);

		if (weapon.getStats().isTwoHanded())
		{
			swapped.remove(EquipmentSlot.SHIELD);
		}

		List<EquipmentStats> pieces = new ArrayList<>();
		for (GearItem item : swapped.values())
		{
			pieces.add(item.getStats());
		}

		return EquipmentStats.sum(pieces);
	}

	/**
	 * Which attack style the spec rolls with.
	 * <p>
	 * The weapon decides, not the style you were already using — you spec on the weapon's own strength.
	 * A bow rolls ranged, a staff rolls magic, and only then does the melee question of stab against
	 * slash against crush arise.
	 * <p>
	 * Getting this wrong is not a small error: a dark bow scored as a sword would read its strength
	 * bonus instead of its ranged strength and roll against the wrong defence, producing a number that
	 * looks perfectly reasonable and is nonsense.
	 */
	private CombatStyle styleFor(GearItem weapon)
	{
		if (itemCategories.suitsStyle(weapon.getItemId(), "RANGED"))
		{
			return CombatStyle.RANGED;
		}

		if (itemCategories.suitsStyle(weapon.getItemId(), "MAGIC"))
		{
			return CombatStyle.MAGIC;
		}

		EquipmentStats stats = weapon.getStats();
		CombatStyle best = CombatStyle.SLASH;
		int bonus = Integer.MIN_VALUE;

		for (CombatStyle style : new CombatStyle[]{CombatStyle.STAB, CombatStyle.SLASH, CombatStyle.CRUSH})
		{
			if (style.attackBonusOf(stats) > bonus)
			{
				bonus = style.attackBonusOf(stats);
				best = style;
			}
		}

		return best;
	}
}

package com.gearforge.optimizer;

import com.gearforge.data.GearItem;
import com.gearforge.dps.SpecialAttack;
import java.util.Comparator;
import javax.annotation.Nullable;

/**
 * One spec weapon worth bringing, and what it is worth.
 */
public final class SpecSuggestion
{
	static final Comparator<SpecSuggestion> BEST_FIRST =
		Comparator.comparingDouble(SpecSuggestion::getDamageAdded).reversed();

	private final SpecialAttack special;
	private final GearItem weapon;
	private final double damageAdded;
	private final double specDamage;
	private final String note;

	SpecSuggestion(
		SpecialAttack special, GearItem weapon, double damageAdded, double specDamage,
		@Nullable String note)
	{
		this.special = special;
		this.weapon = weapon;
		this.damageAdded = damageAdded;
		this.specDamage = specDamage;
		this.note = note;
	}

	/**
	 * Whether the weapon is actually in the player's bank. Unowned weapons are scored too, so the
	 * panel can answer "would this be worth buying" — but it has to say which is which.
	 */
	public boolean isOwned()
	{
		return weapon.getLocations() != null && !weapon.getLocations().isEmpty();
	}

	public SpecialAttack getSpecial()
	{
		return special;
	}

	public GearItem getWeapon()
	{
		return weapon;
	}

	/**
	 * Damage the spec adds to the kill over just attacking normally. The one number the ranking uses,
	 * and the only one that lets a warhammer be compared with a set of claws.
	 */
	public double getDamageAdded()
	{
		return damageAdded;
	}

	/** What the special attack itself hits for, on average. */
	public double getSpecDamage()
	{
		return specDamage;
	}

	/**
	 * Why it scores what it does, for specs whose value is not the damage you can see.
	 */
	@Nullable
	public String getNote()
	{
		return note;
	}
}

package com.gearforge.optimizer;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.data.EquipmentStats;
import com.gearforge.data.GearItem;
import com.gearforge.data.ItemCategories;
import com.gearforge.dps.CombatContext;
import com.gearforge.dps.CombatStyle;
import com.gearforge.dps.DpsEngine;
import com.gearforge.dps.SetEffectRegistry;
import com.gearforge.dps.SetEffects;
import com.gearforge.dps.Target;
import com.gearforge.setups.ItemRequirement;
import com.gearforge.setups.Setup;
import java.util.ArrayList;
import java.util.Collection;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Finds items already in the player's bank that would improve a saved setup.
 * <p>
 * Deliberately a <em>single-slot</em> search rather than a re-optimisation. Re-running the optimizer
 * would just return the best-in-slot setup, which the BiS tab already does; the value of a nudge is
 * that it is small and actionable — one item you own and forgot about.
 * <p>
 * A setup carries no target, so upgrades are judged against a fixed benchmark rather than a boss.
 * That benchmark deliberately <em>has</em> defence: against a zero-defence dummy accuracy is already
 * near 100%, so an accuracy upgrade would score as worthless and only strength upgrades would ever
 * surface. Judging against something that can actually be missed makes both count.
 */
@Singleton
public class UpgradeFinder
{
	/**
	 * Below this, a suggestion is noise rather than an upgrade.
	 * <p>
	 * Not lower: near the accuracy crossover a single point of attack bonus is already worth ~0.7%, so
	 * a tighter threshold would fill the panel with "swap for a helm with +1 slash".
	 */
	private static final double MIN_GAIN = 0.01;

	/**
	 * A mid-tier target — roughly a mid-level boss. Not a real monster, and not meant to be: it is a
	 * fixed yardstick for comparing two items, not a DPS figure to quote.
	 */
	private static final Target BENCHMARK = Target.builder()
		.name("Benchmark")
		.defenceLevel(100)
		.magicLevel(100)
		.defensiveBonuses(EquipmentStats.builder()
			.dstab(100).dslash(100).dcrush(100).dmagic(100).drange(100)
			.build())
		.build();

	private final DpsEngine engine;
	private final SetEffectRegistry setEffects;
	private final ItemCategories itemCategories;

	@Inject
	public UpgradeFinder(DpsEngine engine, SetEffectRegistry setEffects, ItemCategories itemCategories)
	{
		this.engine = engine;
		this.setEffects = setEffects;
		this.itemCategories = itemCategories;
	}

	/**
	 * @param setup    the saved setup to improve
	 * @param owned    every equippable item the player has
	 * @param template levels and target; equipment and speed are filled in per candidate
	 * @return suggestions worth showing, biggest gain first
	 */
	public List<UpgradeSuggestion> find(Setup setup, Collection<GearItem> owned, CombatContext template)
	{
		Map<EquipmentSlot, GearItem> baseline = resolve(setup, owned);

		GearItem weapon = baseline.get(EquipmentSlot.WEAPON);
		if (weapon == null)
		{
			// Without a weapon there is no DPS to compare against.
			return new ArrayList<>();
		}

		CombatStyle style = inferStyle(weapon);
		double baselineDps = score(baseline, template, style);
		if (baselineDps <= 0)
		{
			return new ArrayList<>();
		}

		List<UpgradeSuggestion> suggestions = new ArrayList<>();

		for (EquipmentSlot slot : EquipmentSlot.values())
		{
			UpgradeSuggestion best = bestSwapFor(slot, baseline, owned, template, style, baselineDps, setup);
			if (best != null)
			{
				suggestions.add(best);
			}
		}

		suggestions.sort((a, b) -> Double.compare(b.getGain(), a.getGain()));
		return suggestions;
	}

	@Nullable
	private UpgradeSuggestion bestSwapFor(
		EquipmentSlot slot,
		Map<EquipmentSlot, GearItem> baseline,
		Collection<GearItem> owned,
		CombatContext template,
		CombatStyle style,
		double baselineDps,
		Setup setup)
	{
		GearItem current = baseline.get(slot);
		UpgradeSuggestion best = null;

		for (GearItem candidate : owned)
		{
			if (candidate.getStats().getSlot() != slot.getSlotIndex())
			{
				continue;
			}

			if (current != null && candidate.getItemId() == current.getItemId())
			{
				continue;
			}

			if (setup.getDismissedUpgrades().contains(candidate.getItemId()))
			{
				continue;
			}

			if (slot == EquipmentSlot.WEAPON
				&& (!Constraints.isUsableWeapon(candidate)
				|| !itemCategories.suitsStyle(candidate.getItemId(), style.name())))
			{
				continue;
			}

			// Never suggest ammo the setup's weapon cannot fire.
			GearItem weapon = baseline.get(EquipmentSlot.WEAPON);
			if (slot == EquipmentSlot.AMMO
				&& weapon != null
				&& !itemCategories.ammoFits(weapon.getItemId(), candidate.getItemId()))
			{
				continue;
			}

			Map<EquipmentSlot, GearItem> swapped = new EnumMap<>(baseline);
			swapped.put(slot, candidate);

			// A two-hander cannot coexist with a shield; dropping the shield is part of the trade.
			if (slot == EquipmentSlot.WEAPON && Constraints.isTwoHanded(candidate))
			{
				swapped.remove(EquipmentSlot.SHIELD);
			}
			else if (slot == EquipmentSlot.SHIELD && Constraints.isTwoHanded(swapped.get(EquipmentSlot.WEAPON)))
			{
				continue;
			}

			double gain = (score(swapped, template, style) - baselineDps) / baselineDps;
			if (gain >= MIN_GAIN && (best == null || gain > best.getGain()))
			{
				best = new UpgradeSuggestion(slot, candidate, gain);
			}
		}

		return best;
	}

	/**
	 * A setup records no combat style, so it is taken from whichever bonus the weapon leans on.
	 */
	private static CombatStyle inferStyle(GearItem weapon)
	{
		EquipmentStats stats = weapon.getStats();

		CombatStyle best = CombatStyle.SLASH;
		int bestBonus = Integer.MIN_VALUE;

		for (CombatStyle style : CombatStyle.values())
		{
			int bonus = style.attackBonusOf(stats);
			if (bonus > bestBonus)
			{
				bestBonus = bonus;
				best = style;
			}
		}

		return best;
	}

	/**
	 * Maps the setup's item ids onto the items the player actually owns. Items no longer owned leave
	 * the slot empty rather than failing.
	 */
	private static Map<EquipmentSlot, GearItem> resolve(Setup setup, Collection<GearItem> owned)
	{
		Map<EquipmentSlot, GearItem> resolved = new EnumMap<>(EquipmentSlot.class);

		for (Map.Entry<EquipmentSlot, ItemRequirement> entry : setup.getEquipment().entrySet())
		{
			for (GearItem item : owned)
			{
				if (item.getItemId() == entry.getValue().getItemId())
				{
					resolved.put(entry.getKey(), item);
					break;
				}
			}
		}

		return resolved;
	}

	private double score(Map<EquipmentSlot, GearItem> setup, CombatContext template, CombatStyle style)
	{
		GearItem weapon = setup.get(EquipmentSlot.WEAPON);
		if (weapon == null)
		{
			return 0.0;
		}

		List<EquipmentStats> pieces = new ArrayList<>();
		for (GearItem item : setup.values())
		{
			pieces.add(item.getStats());
		}

		SetEffects effects = setEffects.evaluate(setup.values(), style, BENCHMARK, false);

		CombatContext context = template.toBuilder()
			.style(style)
			.target(BENCHMARK)
			.equipment(EquipmentStats.sum(pieces))
			.weaponSpeedTicks(weapon.getStats().getSpeed())
			.voidSet(effects.getVoidSet())
			.accuracyMultiplier(effects.getAccuracyMultiplier())
			.damageMultiplier(effects.getDamageMultiplier())
			.build();

		return engine.score(context).getDps();
	}
}

