import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * One item a setup asks for.
 * <p>
 * The accepted variant ids are deliberately <em>not</em> stored: they are resolved at match time from
 * the item variation mapping. Persisting them would freeze today's answer into saved data and go
 * stale the moment a new variant is released.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class ItemRequirement
{
	private int itemId;
	private int quantity;

	/**
	 * Whether a different member of the same variant family satisfies this — a degraded Barrows piece
	 * standing in for the undegraded one, say.
	 */
	private boolean fuzzy;

	public static ItemRequirement of(int itemId)
	{
		return new ItemRequirement(itemId, 1, true);
	}
}

package com.gearforge.setups;

import com.gearforge.data.EquipmentSlot;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * A saved loadout.
 * <p>
 * Equipment only for now — the inventory grid, rune pouch and quiver from the design are not built
 * yet. A plain class with a no-arg constructor because this is persisted with Gson.
 */
@Data
@NoArgsConstructor
public class Setup
{
	/** String rather than UUID so the persisted JSON stays readable and trivially portable. */
	private String id = UUID.randomUUID().toString();

	private String name = "New setup";
	private SetupSource source = SetupSource.MANUAL;
	private Map<EquipmentSlot, ItemRequirement> equipment = new LinkedHashMap<>();

	/**
	 * The inventory, slot by slot. Up to 28 entries with nulls for empty slots — position is preserved
	 * because where something sits in your inventory is part of the setup.
	 */
	private List<ItemRequirement> inventory = new ArrayList<>();

	private long lastUsedMillis;

	/**
	 * Item ids whose upgrade suggestion has been dismissed, so a deliberately suboptimal setup stops
	 * nagging. Permanent per setup.
	 */
	private Set<Integer> dismissedUpgrades = new HashSet<>();

	public static Setup named(String name, SetupSource source)
	{
		Setup setup = new Setup();
		setup.setName(name);
		setup.setSource(source);
		return setup;
	}

	public void put(EquipmentSlot slot, int itemId)
	{
		equipment.put(slot, ItemRequirement.of(itemId));
	}

	/**
	 * Replaces the inventory from a slot-indexed array, where {@code -1} means empty.
	 */
	public void setInventoryFrom(int[] slots)
	{
		inventory = new ArrayList<>();
		for (int itemId : slots)
		{
			inventory.add(itemId < 0 ? null : ItemRequirement.of(itemId));
		}

		trimTrailingEmptySlots();
	}

	/**
	 * Trailing empties carry no information and only bloat the saved JSON.
	 */
	private void trimTrailingEmptySlots()
	{
		int last = inventory.size() - 1;
		while (last >= 0 && inventory.get(last) == null)
		{
			inventory.remove(last);
			last--;
		}
	}

	/**
	 * @return how many inventory slots actually hold something
	 */
	public int inventoryCount()
	{
		int count = 0;
		for (ItemRequirement requirement : inventory)
		{
			if (requirement != null)
			{
				count++;
			}
		}

		return count;
	}

	/**
	 * Total items the setup asks for, across equipment and inventory.
	 */
	public int size()
	{
		return equipment.size() + inventoryCount();
	}
}

package com.gearforge.setups;

import com.gearforge.data.BankModel;
import com.gearforge.data.EquipmentSlot;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.Map;
import javax.annotation.Nullable;

/**
 * Turns a setup into a shareable code and back.
 * <p>
 * Self-contained by design — no server, no lookup, nothing to go offline. The code carries everything
 * needed to rebuild the setup.
 * <p>
 * Format: {@code GF1|<base64 name>|<slot:itemId,...>|<inventory ids,...>}. Deliberately not raw JSON
 * in base64: this stays short enough to paste into a chat message, and stays readable enough that a
 * malformed code can be diagnosed by eye. The name is base64'd so a pipe or comma in it cannot break
 * parsing.
 */
public final class SetupCodec
{
	private static final String PREFIX = "GF1";
	private static final String SECTION = "\\|";
	private static final int SECTIONS = 4;

	private SetupCodec()
	{
	}

	public static String encode(Setup setup)
	{
		StringBuilder code = new StringBuilder(PREFIX).append('|');

		code.append(Base64.getUrlEncoder().withoutPadding()
			.encodeToString(setup.getName().getBytes(StandardCharsets.UTF_8)));
		code.append('|');

		boolean first = true;
		for (Map.Entry<EquipmentSlot, ItemRequirement> entry : setup.getEquipment().entrySet())
		{
			if (!first)
			{
				code.append(',');
			}

			code.append(entry.getKey().getSlotIndex()).append(':').append(entry.getValue().getItemId());
			first = false;
		}

		code.append('|');

		for (int slot = 0; slot < setup.getInventory().size(); slot++)
		{
			if (slot > 0)
			{
				code.append(',');
			}

			ItemRequirement requirement = setup.getInventory().get(slot);
			code.append(requirement == null ? BankModel.EMPTY_SLOT : requirement.getItemId());
		}

		return code.toString();
	}

	/**
	 * @return the decoded setup, or null if the code is not a GearForge code or is malformed. Never
	 *     throws — a mistyped code is a normal thing for a user to do, not an error condition.
	 */
	@Nullable
	public static Setup decode(String code)
	{
		if (code == null)
		{
			return null;
		}

		String[] sections = code.trim().split(SECTION, -1);
		if (sections.length != SECTIONS || !PREFIX.equals(sections[0]))
		{
			return null;
		}

		try
		{
			String name = new String(
				Base64.getUrlDecoder().decode(sections[1]), StandardCharsets.UTF_8);

			Setup setup = Setup.named(name.isEmpty() ? "Shared setup" : name, SetupSource.SHARED);

			if (!sections[2].isEmpty())
			{
				for (String pair : sections[2].split(","))
				{
					String[] parts = pair.split(":");
					if (parts.length != 2)
					{
						return null;
					}

					EquipmentSlot slot = EquipmentSlot.fromSlotIndex(Integer.parseInt(parts[0]));
					if (slot != null)
					{
						setup.put(slot, Integer.parseInt(parts[1]));
					}
				}
			}

			if (!sections[3].isEmpty())
			{
				String[] ids = sections[3].split(",");
				int[] inventory = new int[Math.min(ids.length, BankModel.INVENTORY_SIZE)];
				for (int slot = 0; slot < inventory.length; slot++)
				{
					inventory[slot] = Integer.parseInt(ids[slot]);
				}

				setup.setInventoryFrom(inventory);
			}

			return setup.size() == 0 ? null : setup;
		}
		catch (IllegalArgumentException e)
		{
			// Covers both malformed base64 and unparseable numbers.
			return null;
		}
	}
}

