	private final String displayName;

	SetupSource(String displayName)
	{
		this.displayName = displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.gearforge.setups;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Saved setups, persisted per RuneScape account.
 * <p>
 * Remembers which setup was last shown in the bank so it can be restored after a relog. What is
 * <em>currently</em> shown is owned by {@code BankFilterService}, because that can also be an unsaved
 * preview from the BiS tab.
 */
@Slf4j
@Singleton
public class SetupStore
{
	private static final String CONFIG_GROUP = "gearforge";
	private static final String SETUPS_KEY = "setups";
	private static final String ACTIVE_KEY = "activeSetup";

	private final ConfigManager configManager;
	private final Gson gson;

	private final List<Setup> setups = new ArrayList<>();
	private String activeSetupId;

	@Inject
	private SetupStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public List<Setup> all()
	{
		return Collections.unmodifiableList(setups);
	}

	public boolean isEmpty()
	{
		return setups.isEmpty();
	}

	public void add(Setup setup)
	{
		setups.add(setup);
		save();
	}

	/**
	 * Persists an in-place edit to a setup, such as dismissing an upgrade suggestion.
	 */
	public void persist()
	{
		save();
	}

	public void remove(String id)
	{
		setups.removeIf(setup -> id.equals(setup.getId()));

		if (id.equals(activeSetupId))
		{
			activeSetupId = null;
		}

		save();
	}

	@Nullable
	public Setup active()
	{
		if (activeSetupId == null)
		{
			return null;
		}

		for (Setup setup : setups)
		{
			if (activeSetupId.equals(setup.getId()))
			{
				return setup;
			}
		}

		return null;
	}

	public boolean isActive(Setup setup)
	{
		return setup.getId().equals(activeSetupId);
	}

	/**
	 * Makes a setup the one the bank highlights. Activating never withdraws or moves anything.
	 */
	public void activate(Setup setup)
	{
		activeSetupId = setup.getId();
		setup.setLastUsedMillis(System.currentTimeMillis());
		save();
	}

	public void deactivate()
	{
		activeSetupId = null;
		save();
	}

	/**
	 * Loads setups for the active RS profile. Clears first so one account's setups cannot leak into
	 * another's after a hop.
	 */
	public void load()
	{
		setups.clear();
		activeSetupId = null;

		if (configManager.getRSProfileKey() == null)
		{
			return;
		}

		String json = configManager.getRSProfileConfiguration(CONFIG_GROUP, SETUPS_KEY);
		if (json != null && !json.isEmpty())
		{
			try
			{
				SetupsFile file = gson.fromJson(json, SetupsFile.class);
				if (file != null && file.setups != null)
				{
					setups.addAll(file.setups);
				}
			}
			catch (JsonSyntaxException e)
			{
				log.warn("Could not read saved setups, starting fresh", e);
			}
		}

		activeSetupId = configManager.getRSProfileConfiguration(CONFIG_GROUP, ACTIVE_KEY);
		log.debug("Loaded {} setups", setups.size());
	}

	private void save()
	{
		if (configManager.getRSProfileKey() == null)
		{
			return;
		}

		SetupsFile file = new SetupsFile();
		file.setups = new ArrayList<>(setups);
		configManager.setRSProfileConfiguration(CONFIG_GROUP, SETUPS_KEY, gson.toJson(file));

		if (activeSetupId == null)
		{
			configManager.unsetRSProfileConfiguration(CONFIG_GROUP, ACTIVE_KEY);
		}
		else
		{
			configManager.setRSProfileConfiguration(CONFIG_GROUP, ACTIVE_KEY, activeSetupId);
		}
	}

	/**
	 * A concrete wrapper so Gson can resolve the list's element type without a TypeToken.
	 */
	private static final class SetupsFile
	{
		List<Setup> setups = new ArrayList<>();
	}
}

package com.gearforge.setups;

import com.gearforge.data.EquipmentSlot;
import java.util.Collection;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntUnaryOperator;

/**
 * Checks a setup against what the player owns.
 * <p>
 * Pure and RuneLite-free so it can be tested without a client. Charges and doses are not checked:
 * the spec is explicit that unknown charges must read as neutral rather than as a warning, and we
 * have no charge data at all yet, so claiming to check them would be worse than not checking.
 */
public final class SetupValidator
{
	private SetupValidator()
	{
	}

	public enum Status
	{
		/** Exactly the item asked for. */
		HAVE("Have it"),
		/** A different member of the same family — a degraded or imbued version. */
		VARIANT("Different version"),
		/** Not in the bank, inventory or worn. */
		MISSING("Missing");

		private final String displayName;

		Status(String displayName)
		{
			this.displayName = displayName;
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}

	/**
	 * @param owned          canonical item id to quantity owned
	 * @param variantGrouper maps an item id to its variant family id
	 */
	public static Map<EquipmentSlot, Status> validate(
		Setup setup,
		Map<Integer, Integer> owned,
		IntUnaryOperator variantGrouper)
	{
		Map<EquipmentSlot, Status> statuses = new EnumMap<>(EquipmentSlot.class);

		for (Map.Entry<EquipmentSlot, ItemRequirement> entry : setup.getEquipment().entrySet())
		{
			statuses.put(entry.getKey(), check(entry.getValue(), owned, variantGrouper));
		}

		return statuses;
	}

	public static Status check(
		ItemRequirement requirement,
		Map<Integer, Integer> owned,
		IntUnaryOperator variantGrouper)
	{
		int needed = Math.max(1, requirement.getQuantity());

		if (owned.getOrDefault(requirement.getItemId(), 0) >= needed)
		{
			return Status.HAVE;
		}

		if (requirement.isFuzzy())
		{
			int wantedFamily = variantGrouper.applyAsInt(requirement.getItemId());

			for (Map.Entry<Integer, Integer> entry : owned.entrySet())
			{
				if (entry.getValue() >= needed
					&& variantGrouper.applyAsInt(entry.getKey()) == wantedFamily)
				{
					return Status.VARIANT;
				}
			}
		}

		return Status.MISSING;
	}

	/**
	 * Validates the inventory, accounting for duplicates.
	 * <p>
	 * A setup asking for four sharks is only satisfied if four are owned, so requirements are totalled
	 * per item before being compared — checking each slot independently would call one shark enough.
	 *
	 * @return a status per occupied inventory slot, indexed as the setup stores them
	 */
	public static Map<Integer, Status> validateInventory(
		Setup setup,
		Map<Integer, Integer> owned,
		IntUnaryOperator variantGrouper)
	{
		Map<Integer, Integer> needed = new HashMap<>();
		List<ItemRequirement> inventory = setup.getInventory();

		for (ItemRequirement requirement : inventory)
		{
			if (requirement != null)
			{
				needed.merge(requirement.getItemId(), Math.max(1, requirement.getQuantity()), Integer::sum);
			}
		}

		Map<Integer, Status> statuses = new LinkedHashMap<>();

		for (int slot = 0; slot < inventory.size(); slot++)
		{
			ItemRequirement requirement = inventory.get(slot);
			if (requirement == null)
			{
				continue;
			}

			ItemRequirement total = new ItemRequirement(
				requirement.getItemId(), needed.get(requirement.getItemId()), requirement.isFuzzy());

			statuses.put(slot, check(total, owned, variantGrouper));
		}

		return statuses;
	}

	/**
	 * @return how many of the setup's items the player has in some form
	 */
	public static int satisfiedCount(Map<EquipmentSlot, Status> statuses)
	{
		return countSatisfied(statuses.values());
	}

	public static int countSatisfied(Collection<Status> statuses)
	{
		int count = 0;
		for (Status status : statuses)
		{
			if (status != Status.MISSING)
			{
				count++;
			}
		}

		return count;
	}
}

