/**
 * Best-in-slot from what you own.
 * <p>
 * Offensive profiles score whole setups through the DPS optimizer; defensive and prayer profiles are
 * genuinely slot-independent and use the greedy optimizer, which is exact and instant.
 */
@Singleton
class BisTab extends JPanel
{
	/** Ice Barrage. Magic best-in-slot is meaningless without fixing a spell, so one is assumed. */
	private static final int ASSUMED_SPELL_DAMAGE = 30;
	private static final int SPELL_SPEED_TICKS = 5;

	private final ClientThread clientThread;
	private final ScheduledExecutorService executor;
	private final BankModel bankModel;
	private final ItemStatEngine statEngine;
	private final PlayerModel playerModel;
	private final ItemRequirements itemRequirements;
	private final DpsOptimizer dpsOptimizer;
	private final GreedyOptimizer greedyOptimizer;
	private final SetupStore setupStore;
	private final BankFilterService bankFilterService;
	private final MonsterRepository monsters;
	private final ItemManager itemManager;
	private final SpriteManager spriteManager;
	private final SpecFinder specFinder;
	private final ItemCategories itemCategories;
	private final Scoring scoring;

	/** Matches the wiki calculator's habit of scoring against a low-defence crab by default. */
	private static final String DEFAULT_TARGET = "Ammonite Crab";

	/**
	 * How many rows the dropdown shows before scrolling. Not a cap on its contents.
	 * <p>
	 * Deliberately tall. Twelve rows was a keyhole to scroll a few thousand monsters through, and while
	 * the list is open the setup underneath is not what you are reading anyway.
	 */
	private static final int TARGET_POPUP_ROWS = 26;

	/** Raced against each other for the overview. */
	private static final List<CombatStyle> OFFENSIVE_STYLES = Arrays.asList(
		CombatStyle.STAB, CombatStyle.SLASH, CombatStyle.CRUSH, CombatStyle.RANGED, CombatStyle.MAGIC);

	private final JComboBox<Profile> profilePicker = Cards.comboBox(Profile.values());
	private final JTextField targetSearch = new JTextField();
	private final JComboBox<Monster> targetPicker = Cards.comboBox(new Monster[0]);
	private final JPanel results = new JPanel();

	/**
	 * Refilled on every render. The spec section sits with Prayers and Boosts rather than at the foot
	 * of the results, so the three things you can open are in one place.
	 */
	private final JPanel specContent = new JPanel();

	/**
	 * How many ranked setups a style offers. The best one is not always the one you want — it may hinge
	 * on an item you would rather not risk — so the runners-up are worth being able to look at.
	 */
	private static final int SETUPS_OFFERED = 5;

	/** Which of them is on screen. Reset whenever the style or target changes. */
	private int shownSetupIndex;

	/** How many spec weapons the recommendation shows before it stops being a recommendation. */
	private static final int SPECS_SHOWN = 3;

	/** Below this a special adds nothing worth swapping weapons for. */
	private static final double SPEC_WORTH_USING = 1.0;

	/** Narrows the picker below it. Fifty-five weapons is far too many to scroll through. */
	private final JTextField specSearch = new JTextField();

	/** Picks one spec weapon to look at, owned or not. */
	private final JComboBox<SpecialAttack> specPicker = Cards.comboBox(new SpecialAttack[0]);

	/** The weapon currently being looked at, or null for none. */
	private SpecialAttack inspectedSpec;

	/** The last scored specs, kept so typing in the search can refilter without recomputing. */
	private List<SpecSuggestion> shownSpecs = Collections.emptyList();

	private GearPool pool = GearPool.USABLE;

	/**
	 * Whether to count slayer helmet bonuses. Detected from the player's task, with a manual override
	 * for planning a task you have not been assigned yet.
	 */
	private SlayerChoice slayerChoice = SlayerChoice.AUTO;

	/**
	 * Selected prayers and boosts. Several may be chosen at once — two that raise the same stat do not
	 * stack in game, so the engine takes the strongest of each rather than adding them.
	 */
	private final Set<CombatPrayer> prayers = EnumSet.noneOf(CombatPrayer.class);
	private final Set<Potion> potions = EnumSet.noneOf(Potion.class);

	/**
	 * Plain buttons rather than toggles: RuneLite's sprite and item image helpers only accept
	 * {@link JButton}, and selection is drawn here anyway so the two pickers match.
	 */
	private final Map<CombatPrayer, JButton> prayerButtons = new EnumMap<>(CombatPrayer.class);
	private final Map<Potion, JButton> potionButtons = new EnumMap<>(Potion.class);

	/** The setup currently on screen, so it can be saved without recomputing. */
	private Map<EquipmentSlot, GearItem> shownSetup = Collections.emptyMap();
	private String shownName = "Setup";
	private Runnable onSetupSaved = () ->
	{
	};

	@Inject
	private BisTab(
		ClientThread clientThread,
		ScheduledExecutorService executor,
		BankModel bankModel,
		ItemStatEngine statEngine,
		PlayerModel playerModel,
		ItemRequirements itemRequirements,
		DpsOptimizer dpsOptimizer,
		GreedyOptimizer greedyOptimizer,
		SetupStore setupStore,
		BankFilterService bankFilterService,
		MonsterRepository monsters,
		ItemManager itemManager,
		SpriteManager spriteManager,
		SpecFinder specFinder,
		ItemCategories itemCategories,
		Scoring scoring)
	{
		this.clientThread = clientThread;
		this.executor = executor;
		this.bankModel = bankModel;
		this.statEngine = statEngine;
		this.playerModel = playerModel;
		this.itemRequirements = itemRequirements;
		this.dpsOptimizer = dpsOptimizer;
		this.greedyOptimizer = greedyOptimizer;
		this.setupStore = setupStore;
		this.bankFilterService = bankFilterService;
		this.monsters = monsters;
		this.itemManager = itemManager;
		this.spriteManager = spriteManager;
		this.specFinder = specFinder;
		this.itemCategories = itemCategories;
		this.scoring = scoring;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		add(buildControls(), BorderLayout.NORTH);

		results.setLayout(new BoxLayout(results, BoxLayout.Y_AXIS));
		results.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel holder = new JPanel(new BorderLayout());
		holder.setBackground(ColorScheme.DARK_GRAY_COLOR);
		holder.add(results, BorderLayout.NORTH);

		JScrollPane scroll = new JScrollPane(
			holder, JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(scroll, BorderLayout.CENTER);

		profilePicker.addActionListener(event ->
		{
			shownSetupIndex = 0;
			rebuild();
		});
	}

	/**
	 * The prayers as a grid of their in-game icons, four across, matching the prayer book.
	 * <p>
	 * Single-select: clicking the active prayer turns it off. GearForge scores one prayer at a time,
	 * and the strong prayers each already cover their whole style.
	 */
	private JPanel buildPrayerGrid()
	{
		// Five across rather than four: seventeen prayers is four rows instead of five, which is a row
		// of the panel handed back to the results below when the section is open.
		JPanel grid = new JPanel(new GridLayout(0, 5, 2, 2));
		grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
		grid.setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));

		for (CombatPrayer candidate : CombatPrayer.values())
		{
			int sprite = PrayerIcon.spriteFor(candidate);
			if (sprite < 0)
			{
				// NONE has no icon; it is expressed by deselecting instead.
				continue;
			}

			JButton button = new JButton();
			button.setToolTipText(PrayerIcon.nameOf(candidate));
			button.setPreferredSize(new Dimension(34, 34));
			button.setFocusPainted(false);
			button.setBorderPainted(false);
			button.setOpaque(true);
			spriteManager.addSpriteTo(button, sprite, 0);

			button.addActionListener(event ->
			{
				if (!prayers.remove(candidate))
				{
					prayers.add(candidate);
				}
				paintPrayerButtons();
				rebuild();
			});

			prayerButtons.put(candidate, button);
			grid.add(button);
		}

		paintPrayerButtons();
		return grid;
	}

	private void paintPrayerButtons()
	{
		prayerButtons.forEach((candidate, button) ->
		{
			boolean on = prayers.contains(candidate);
			button.setBackground(on ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR);
		});
	}

	/**
	 * The potions as a scrollable list of item icons and names.
	 */
	private JPanel buildBoostList()
	{
		JPanel list = new JPanel();
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARK_GRAY_COLOR);

		for (Potion candidate : Potion.values())
		{
			if (candidate == Potion.NONE)
			{
				continue;
			}

			JButton button = new JButton(candidate.toString());
			button.setHorizontalAlignment(SwingConstants.LEFT);
			button.setFont(FontManager.getRunescapeSmallFont());
			button.setFocusPainted(false);
			button.setBorderPainted(false);
			button.setOpaque(true);
			button.setIconTextGap(6);
			button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
			button.setAlignmentX(Component.LEFT_ALIGNMENT);
			itemManager.getImage(candidate.getItemId()).addTo(button);

			button.addActionListener(event ->
			{
				if (!potions.remove(candidate))
				{
					potions.add(candidate);
				}
				paintPotionButtons();
				rebuild();
			});

			potionButtons.put(candidate, button);
			list.add(button);
		}

		paintPotionButtons();

		JPanel holder = new JPanel(new BorderLayout());
		holder.setBackground(ColorScheme.DARK_GRAY_COLOR);
		holder.add(list, BorderLayout.NORTH);

		JScrollPane scroll = new JScrollPane(
			holder, JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		// Capped so the list scrolls rather than pushing the results off screen, and clamped so its
		// contents cannot widen it past the panel.
		scroll.setPreferredSize(new Dimension(0, 150));
		scroll.setMaximumSize(new Dimension(Integer.MAX_VALUE, 150));
		scroll.setMinimumSize(new Dimension(0, 60));

		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrapper.setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));
		wrapper.add(scroll, BorderLayout.CENTER);
		return wrapper;
	}

	private void paintPotionButtons()
	{
		potionButtons.forEach((candidate, button) ->
		{
			boolean on = potions.contains(candidate);
			button.setBackground(on ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR);
			button.setForeground(on ? ColorScheme.DARKER_GRAY_COLOR : ColorScheme.LIGHT_GRAY_COLOR);
		});
	}

	private JPanel buildControls()
	{
		JPanel controls = new JPanel();
		controls.setLayout(new BoxLayout(controls, BoxLayout.Y_AXIS));
		controls.setBackground(ColorScheme.DARK_GRAY_COLOR);
		controls.setBorder(BorderFactory.createEmptyBorder(0, 0, 10, 0));

		controls.add(Cards.field("Optimise for", profilePicker));
		controls.add(Cards.gap(8));

		GearPool[] pools = GearPool.values();
		String[] labels = new String[pools.length];
		for (int i = 0; i < pools.length; i++)
		{
			labels[i] = pools[i].toString();
		}

		controls.add(Cards.segmented(labels, pool.ordinal(), index ->
		{
			pool = pools[index];
			rebuild();
		}));
		controls.add(Cards.gap(8));

		SlayerChoice[] choices = SlayerChoice.values();
		String[] slayerLabels = new String[choices.length];
		for (int i = 0; i < choices.length; i++)
		{
			slayerLabels[i] = choices[i].toString();
		}

		controls.add(Cards.field("Slayer helmet", Cards.segmented(
			slayerLabels, slayerChoice.ordinal(), index ->
			{
				slayerChoice = choices[index];
				rebuild();
			})));
		controls.add(Cards.gap(8));

		controls.add(Cards.expandable("Prayers", buildPrayerGrid(),
			header -> spriteManager.addSpriteTo(header, SpriteID.Staticons.PRAYER, 0)));
		controls.add(Cards.gap(6));
		controls.add(Cards.expandable("Boosts", buildBoostList(),
			header -> spriteManager.addSpriteTo(header, SpriteID.Staticons.HERBLORE, 0)));
		specContent.setLayout(new BoxLayout(specContent, BoxLayout.Y_AXIS));
		specContent.setBackground(ColorScheme.DARK_GRAY_COLOR);
		specContent.setAlignmentX(Component.LEFT_ALIGNMENT);
		// This section sits inside the results scroll pane. Once the pane is long enough to scroll, the
		// scrollbar takes width off the right, and anything sized to fill ran underneath it — which is
		// what clipped the dropdown once the prayer grid was open.
		specContent.setBorder(
			BorderFactory.createEmptyBorder(0, 0, 0, Cards.SCROLLBAR_ALLOWANCE));
		specSearch.addKeyListener(new java.awt.event.KeyAdapter()
		{
			@Override
			public void keyReleased(java.awt.event.KeyEvent event)
			{
				refillSpecPicker();
			}
		});

		specSearch.setAlignmentX(Component.LEFT_ALIGNMENT);
		specSearch.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));

		specPicker.setMaximumRowCount(12);
		specPicker.addActionListener(event ->
		{
			SpecialAttack picked = (SpecialAttack) specPicker.getSelectedItem();
			if (picked != inspectedSpec)
			{
				inspectedSpec = picked;
				showSpecs(shownSpecs);
			}
		});
		// Populate the picker up front; it was previously only filled on a keystroke, so it started empty.
		refillSpecPicker();
		controls.add(Cards.gap(8));

		targetSearch.setFont(FontManager.getRunescapeSmallFont());
		targetSearch.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		targetSearch.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		targetSearch.setCaretColor(ColorScheme.LIGHT_GRAY_COLOR);
		targetSearch.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
		targetSearch.setToolTipText("Type to narrow the list of targets");
		targetSearch.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent event)
			{
				repopulateTargets();
			}

			@Override
			public void removeUpdate(DocumentEvent event)
			{
				repopulateTargets();
			}

			@Override
			public void changedUpdate(DocumentEvent event)
			{
				repopulateTargets();
			}
		});

		controls.add(Cards.field("Score against", targetSearch));
		controls.add(Cards.gap(4));
		targetPicker.setMaximumRowCount(TARGET_POPUP_ROWS);
		controls.add(targetPicker);

		repopulateTargets();
		targetPicker.addActionListener(event ->
		{
			// A new target reranks everything, so holding position three from the last boss is meaningless.
			shownSetupIndex = 0;
			rebuild();
		});

		return controls;
	}

	/**
	 * Refills the target dropdown from the search box, keeping the current pick if it still matches so
	 * typing does not silently change what you are scoring against.
	 */
	private void repopulateTargets()
	{
		Monster previous = (Monster) targetPicker.getSelectedItem();

		// Uncapped on purpose. Trimming the list made it stop partway through the alphabet with
		// nothing on screen to say why, which reads as a broken scrollbar rather than a limit.
		List<Monster> matches = monsters.search(targetSearch.getText());

		DefaultComboBoxModel<Monster> model = new DefaultComboBoxModel<>();
		for (Monster monster : matches)
		{
			model.addElement(monster);
		}

		targetPicker.setModel(model);

		if (previous != null && matches.contains(previous))
		{
			targetPicker.setSelectedItem(previous);
		}
		else if (model.getSize() > 0)
		{
			Monster fallback = monsters.byName(DEFAULT_TARGET);
			targetPicker.setSelectedItem(
				fallback != null && matches.contains(fallback) ? fallback : model.getElementAt(0));
		}
	}

	void rebuild()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::rebuild);
			return;
		}

		if (!bankModel.hasBankData())
		{
			showMessage("Open your bank once to get started.");
			return;
		}

		Profile profile = (Profile) profilePicker.getSelectedItem();
		if (profile == null)
		{
			return;
		}

		GearPool pool = this.pool;
		SlayerChoice slayer = this.slayerChoice;
		Monster target = (Monster) targetPicker.getSelectedItem();

		// Read on the EDT and carried through, because the search runs on another thread and must not
		// touch Swing state.
		Set<CombatPrayer> chosenPrayers = EnumSet.copyOf(prayers.isEmpty()
			? EnumSet.noneOf(CombatPrayer.class) : prayers);
		Set<Potion> chosenPotions = EnumSet.copyOf(potions.isEmpty()
			? EnumSet.noneOf(Potion.class) : potions);

		clientThread.invoke(() ->
		{
			if (pool == GearPool.USABLE && !playerModel.isLoggedIn())
			{
				SwingUtilities.invokeLater(() ->
					showMessage("Log in so GearForge can read your levels, or switch to "
						+ GearPool.EVERYTHING + "."));
				return;
			}

			PlayerLevels levels = playerModel.snapshot();
			List<GearItem> owned = statEngine.resolveOwnedGear(bankModel);
			List<GearItem> everySpecWeapon = allSpecWeapons();

			// Only the two lookups above need the client: item names come from the item cache and
			// levels from the client. The search itself is pure computation and moves off the game
			// thread — running a beam search there froze the client on every gear swap.
			executor.execute(() ->
				optimise(owned, everySpecWeapon, levels, profile, pool, slayer, target,
					chosenPrayers, chosenPotions));
		});
	}

	/**
	 * The expensive half. Runs on a background thread, never on the client thread or the EDT.
	 */
	private void optimise(
		List<GearItem> owned,
		List<GearItem> everySpecWeapon,
		PlayerLevels levels,
		Profile profile,
		GearPool pool,
		SlayerChoice slayer,
		@Nullable Monster target,
		Set<CombatPrayer> prayers,
		Set<Potion> potions)
	{
		boolean slayerTask = slayer.resolve(levels.isOnSlayerTask());
		List<GearItem> pooled = pool == GearPool.USABLE ? onlyEquippable(owned, levels) : owned;

		if (profile == Profile.ALL_STYLES)
		{
			Map<CombatStyle, ScoredSetup> byStyle = new LinkedHashMap<>();
			for (CombatStyle style : OFFENSIVE_STYLES)
			{
				// Melee against something nothing can reach is not a worse answer, it is not an answer.
				if (style.isMelee() && !Reachability.meleeIsPossible(target))
				{
					continue;
				}

				List<ScoredSetup> best = dpsOptimizer.best(
					wearingRequiredGear(reaching(pooled, style, target), target),
					contextFor(Profile.forStyle(style), levels, target, prayers, potions), slayerTask, 1);

				if (!best.isEmpty())
				{
					byStyle.put(style, best.get(0));
				}
			}

			SwingUtilities.invokeLater(() -> renderAllStyles(byStyle, target));
		}
		else if (profile.isOffensive())
		{
			if (profile.getStyle().isMelee() && !Reachability.meleeIsPossible(target))
			{
				SwingUtilities.invokeLater(() -> showMessage(Reachability.reason(target)));
				return;
			}

			CombatContext context = contextFor(profile, levels, target, prayers, potions);
			List<ScoredSetup> best =
				dpsOptimizer.best(wearingRequiredGear(reaching(pooled, profile.getStyle(), target), target), context, slayerTask, SETUPS_OFFERED);
			List<SpecSuggestion> specs = specsFor(best, everySpecWeapon, context, target);
			SwingUtilities.invokeLater(() -> renderOffensive(best, specs, profile, pool, target));
		}
		else
		{
			OptimizerResult best = greedyOptimizer.best(pooled, profile.getStat());
			SwingUtilities.invokeLater(() -> renderDefensive(best, profile, pool));
		}
	}

	private List<GearItem> onlyEquippable(List<GearItem> owned, PlayerLevels levels)
	{
		List<GearItem> usable = new ArrayList<>();
		for (GearItem item : owned)
		{
			if (itemRequirements.canEquip(item.getItemId(), levels))
			{
				usable.add(item);
			}
		}

		return usable;
	}

	/**
	 * Must run on the client thread — player levels come from the client.
	 */
	/**
	 * Delegates to the shared builder. This method used to assemble the context by hand, as did the
	 * Bosses and Setups tabs, and the three drifted apart — a fix landing in one of them was not a fix.
	 */
	private CombatContext contextFor(
		Profile profile,
		PlayerLevels levels,
		@Nullable Monster target,
		Set<CombatPrayer> prayers,
		Set<Potion> potions)
	{
		return scoring.contextFor(profile.getStyle(), levels, target, prayers, potions);
	}


	/**
	 * The overview: one row per attack style, best first, each opening the full setup.
	 * <p>
	 * Deliberately shows the gear and lets DPS be the ranking, rather than presenting a single number
	 * the player has to configure their way towards.
	 */
	private void renderAllStyles(Map<CombatStyle, ScoredSetup> byStyle, @Nullable Monster target)
	{
		results.removeAll();

		if (byStyle.isEmpty())
		{
			showMessage("Nothing in this gear pool can attack yet. Open your bank with a weapon in it.");
			return;
		}

		List<Map.Entry<CombatStyle, ScoredSetup>> ranked = new ArrayList<>(byStyle.entrySet());
		ranked.sort((a, b) -> Double.compare(b.getValue().getScore().getDps(), a.getValue().getScore().getDps()));

		Map.Entry<CombatStyle, ScoredSetup> winner = ranked.get(0);
		shownSetup = winner.getValue().getSetup();
		shownName = Profile.forStyle(winner.getKey()).toString();

		results.add(Cards.sectionLabel("Best of every style"));
		results.add(Cards.gap(4));

		for (Map.Entry<CombatStyle, ScoredSetup> entry : ranked)
		{
			results.add(styleRow(entry.getKey(), entry.getValue()));
			results.add(Cards.gap(3));
		}

		results.add(Cards.gap(8));
		results.add(Cards.muted("Scored against "
			+ (target == null ? "a dummy target" : target.displayName())
			+ ". Pick a style above to see its full setup."));

		finish();
	}

	/**
	 * One clickable style result. Selecting it switches the picker to that style, which shows the setup.
	 */
	private JPanel styleRow(CombatStyle style, ScoredSetup setup)
	{
		Profile profile = Profile.forStyle(style);

		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 6));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 44));

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(row.getBackground());
		// A weapon name is as long as it is; the row must not grow to fit it.
		Cards.fitToPanel(text);

		JLabel dps = new JLabel(String.format("%.2f DPS", setup.getScore().getDps()));
		dps.setFont(FontManager.getRunescapeBoldFont());
		dps.setForeground(ColorScheme.BRAND_ORANGE);
		dps.setAlignmentX(Component.LEFT_ALIGNMENT);
		text.add(dps);

		GearItem weapon = setup.getSetup().get(EquipmentSlot.WEAPON);
		JLabel detail = new JLabel(profile + (weapon == null ? "" : " · " + weapon.getName()));
		detail.setFont(FontManager.getRunescapeSmallFont());
		detail.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		detail.setAlignmentX(Component.LEFT_ALIGNMENT);
		text.add(detail);

		row.add(text, BorderLayout.CENTER);

		JButton open = Cards.button("Open");
		open.setToolTipText("Show the full setup for " + profile);
		open.addActionListener(event -> profilePicker.setSelectedItem(profile));
		row.add(open, BorderLayout.EAST);

		return Cards.fitRow(row);
	}

	/**
	 * Drops melee weapons that cannot physically reach the target.
	 * <p>
	 * Zulrah sits a tile beyond an ordinary weapon, so only a polearm gets there. Filtering the weapons
	 * rather than banning melee outright keeps the halberd answer — which is the one people actually
	 * use, and which an earlier blanket rule of mine deleted.
	 */
	/**
	 * Says what a slayer monster obliges you to bring, whether it is worn or carried.
	 * <p>
	 * A carried item takes no slot, so the setup cannot show it and the reasoning is the only place it
	 * can appear — an ice cooler is the difference between killing a desert lizard and not.
	 */
	private void addSlayerRequirement(
		@Nullable Monster target, Map<EquipmentSlot, GearItem> setup, List<String> reasons)
	{
		SlayerGear.Requirement requirement = SlayerGear.forMonster(target);
		if (requirement == null)
		{
			return;
		}

		reasons.add(requirement.getNote());

		if (!requirement.isWorn())
		{
			return;
		}

		// Only claim the slot is handled when it actually is: without the item the search was left
		// alone, and saying nothing would let someone walk out with an unusable setup.
		GearItem worn = setup.get(requirement.getSlot());
		if (worn == null || !requirement.getAccepted().contains(worn.getItemId()))
		{
			reasons.add("You do not own one, so this setup cannot be used here as it stands.");
		}
	}

	/**
	 * Restricts a slot to the gear a slayer monster obliges you to wear.
	 * <p>
	 * An aberrant spectre cannot be fought without a nose peg, so a setup with anything else in that
	 * slot is not a worse answer — it is one the game will not let you equip. If none of the accepted
	 * items is owned the pool is left alone, and the reasoning says what is missing rather than
	 * returning nothing.
	 */
	private List<GearItem> wearingRequiredGear(List<GearItem> pool, @Nullable Monster target)
	{
		SlayerGear.Requirement requirement = SlayerGear.forMonster(target);
		if (requirement == null || !requirement.isWorn())
		{
			return pool;
		}

		boolean ownsOne = false;
		for (GearItem item : pool)
		{
			if (requirement.getAccepted().contains(item.getItemId()))
			{
				ownsOne = true;
				break;
			}
		}

		if (!ownsOne)
		{
			return pool;
		}

		int slotIndex = requirement.getSlot().getSlotIndex();
		List<GearItem> allowed = new ArrayList<>();
		for (GearItem item : pool)
		{
			if (item.getStats().getSlot() != slotIndex
				|| requirement.getAccepted().contains(item.getItemId()))
			{
				allowed.add(item);
			}
		}

		return allowed;
	}

	private List<GearItem> reaching(List<GearItem> pool, CombatStyle style, @Nullable Monster target)
	{
		if (!style.isMelee() || !Reachability.requiresReach(target))
		{
			return pool;
		}

		List<GearItem> usable = new ArrayList<>();
		for (GearItem item : pool)
		{
			// Only the weapon slot is constrained; the rest of the setup is unaffected.
			if (item.getStats().getSlot() != EquipmentSlot.WEAPON.getSlotIndex()
				|| itemCategories.hasReach(item.getItemId()))
			{
				usable.add(item);
			}
		}

		return usable;
	}

	/**
	 * Every special attack weapon in the game, with its stats, whether or not it is owned.
	 * <p>
	 * Must run on the client thread. Scoring the ones you do not have is the point of the search: the
	 * question "would claws actually beat my voidwaker here" is worth answering before spending the
	 * money, not after.
	 * <p>
	 * Ownership is matched across the whole variant family, not on the one canonical id. Nobody's bank
	 * holds a plain dragon dagger — it holds a dagger(p++) — and matching on the canonical id alone
	 * told those players they owned no special attack weapon at all, which is exactly what the empty
	 * recommendation was reporting.
	 */
	private List<GearItem> allSpecWeapons()
	{
		List<GearItem> weapons = new ArrayList<>();
		Map<SpecialAttack, Integer> ownedVariants = ownedSpecVariants();

		for (SpecialAttack special : SpecialAttack.values())
		{
			Integer ownedId = ownedVariants.get(special);
			// The variant actually in the bank is the one to score: a charged blowpipe and an empty one
			// are the same family and nothing like the same weapon.
			int itemId = ownedId == null ? special.getItemId() : ownedId;

			EquipmentStats stats = statEngine.statsFor(itemId);
			if (stats == null)
			{
				continue;
			}

			weapons.add(new GearItem(
				itemId,
				special.getDisplayName(),
				1,
				stats,
				ownedId == null ? EnumSet.noneOf(Storage.class) : EnumSet.of(Storage.BANK)));
		}

		return weapons;
	}

	/**
	 * Which special attack weapon each bank item is, keeping the strongest variant where several are
	 * held — an inactive crystal halberd sits in the same family as a perfected one.
	 */
	private Map<SpecialAttack, Integer> ownedSpecVariants()
	{
		Map<SpecialAttack, Integer> owned = new EnumMap<>(SpecialAttack.class);

		for (Integer itemId : bankModel.ownedItems().keySet())
		{
			SpecialAttack special = SpecialAttack.forItem(itemId);
			if (special == null)
			{
				continue;
			}

			Integer held = owned.get(special);
			if (held == null || offenceOf(itemId) > offenceOf(held))
			{
				owned.put(special, itemId);
			}
		}

		return owned;
	}

	/**
	 * A rough ranking of two variants of the same weapon, only ever used to choose between them.
	 */
	private int offenceOf(int itemId)
	{
		EquipmentStats stats = statEngine.statsFor(itemId);
		if (stats == null)
		{
			return -1;
		}

		return Math.max(Math.max(stats.getAstab(), stats.getAslash()),
			Math.max(stats.getAcrush(), Math.max(stats.getArange(), stats.getAmagic())))
			+ stats.getStrength() + stats.getRangedStrength();
	}

	/**
	 * Scores the spec weapons against the setup that just won, rather than against bare stats — the
	 * whole point being that your body slot's strength bonus changes what the claws hit for.
	 */
	private List<SpecSuggestion> specsFor(
		List<ScoredSetup> best, List<GearItem> pooled, CombatContext context, @Nullable Monster target)
	{
		// The target decides which specials are even usable — a warhammer cannot reach Zulrah.
		if (best.isEmpty())
		{
			return Collections.emptyList();
		}

		Map<EquipmentSlot, GearItem> winner = best.get(0).getSetup();
		List<EquipmentStats> pieces = new ArrayList<>();
		int speed = SPELL_SPEED_TICKS;

		for (Map.Entry<EquipmentSlot, GearItem> entry : winner.entrySet())
		{
			pieces.add(entry.getValue().getStats());
			if (entry.getKey() == EquipmentSlot.WEAPON)
			{
				speed = Math.max(1, entry.getValue().getStats().getSpeed());
			}
		}

		return specFinder.find(winner, pooled, context.toBuilder()
			.equipment(EquipmentStats.sum(pieces))
			.weaponSpeedTicks(speed)
			.build(), target);
	}

	/**
	 * The spec weapons as rows, best first. Collapsed by default: it is a secondary question, and the
	 * panel is already dense.
	 */
	private void showSpecs(List<SpecSuggestion> specs)
	{
		shownSpecs = specs;

		specContent.removeAll();
		specContent.add(specList(recommended(specs), bestOwned(specs)));

		specContent.add(Cards.gap(8));
		specContent.add(Cards.sectionLabel("Compare any spec weapon"));
		specContent.add(specSearch);
		specContent.add(Cards.gap(4));
		specContent.add(specPicker);

		if (inspectedSpec != null)
		{
			SpecSuggestion picked = suggestionFor(specs, inspectedSpec);
			if (picked != null)
			{
				specContent.add(Cards.gap(4));
				specContent.add(specRow(picked));
			}
		}

		specContent.revalidate();
		specContent.repaint();
	}

	/**
	 * What to actually bring: the spec weapons you own that beat attacking normally against this
	 * target, best first.
	 * <p>
	 * Owning a weapon is not a reason to list it. A bank with every special in the game would fill the
	 * panel with weapons that do nothing here, and a recommendation that recommends everything
	 * recommends nothing.
	 */
	private static List<SpecSuggestion> recommended(List<SpecSuggestion> specs)
	{
		List<SpecSuggestion> worthUsing = new ArrayList<>();
		for (SpecSuggestion suggestion : specs)
		{
			if (suggestion.isOwned() && suggestion.getDamageAdded() >= SPEC_WORTH_USING)
			{
				worthUsing.add(suggestion);
			}
		}

		return worthUsing.size() > SPECS_SHOWN ? worthUsing.subList(0, SPECS_SHOWN) : worthUsing;
	}

	/** The best owned special, worth using or not, so an empty recommendation can still say why. */
	private static SpecSuggestion bestOwned(List<SpecSuggestion> specs)
	{
		for (SpecSuggestion suggestion : specs)
		{
			if (suggestion.isOwned())
			{
				return suggestion;
			}
		}

		return null;
	}

	private static SpecSuggestion suggestionFor(List<SpecSuggestion> specs, SpecialAttack special)
	{
		for (SpecSuggestion suggestion : specs)
		{
			if (suggestion.getSpecial() == special)
			{
				return suggestion;
			}
		}

		return null;
	}

	/**
	 * Rebuilds the picker to whatever the search matches, keeping the current selection if it survives.
	 */
	private void refillSpecPicker()
	{
		String needle = specSearch.getText().trim().toLowerCase();

		DefaultComboBoxModel<SpecialAttack> model = new DefaultComboBoxModel<>();
		for (SpecialAttack special : SpecialAttack.values())
		{
			if (needle.isEmpty() || special.getDisplayName().toLowerCase().contains(needle))
			{
				model.addElement(special);
			}
		}

		specPicker.setModel(model);

		if (inspectedSpec != null && model.getIndexOf(inspectedSpec) >= 0)
		{
			specPicker.setSelectedItem(inspectedSpec);
		}
		else if (model.getSize() > 0)
		{
			specPicker.setSelectedIndex(0);
		}
	}

	/**
	 * The recommendation: the spec weapons you actually own, best first.
	 */
	private JPanel specList(List<SpecSuggestion> specs, SpecSuggestion bestOwned)
	{
		JPanel list = new JPanel();
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARK_GRAY_COLOR);
		list.setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));

		list.add(Cards.sectionLabel("Spec weapon"));

		if (specs.isEmpty())
		{
			// One line rather than a column of weapons marked as useless, and the reason has to come
			// from the numbers: the old wording blamed accuracy every time, and told people they rarely
			// miss a boss they were missing half their swings on.
			list.add(Cards.muted(bestOwned == null
				? "You have no special attack weapon GearForge can score."
				: String.format(
					"Nothing you own is worth speccing with here. The best is %s: it hits %.1f on "
						+ "average, which is %s an ordinary attack with the setup above.",
					bestOwned.getSpecial().getDisplayName(),
					bestOwned.getSpecDamage(),
					bestOwned.getDamageAdded() < 0 ? "less than" : "no better than")));
			return list;
		}

		for (SpecSuggestion suggestion : specs)
		{
			list.add(specRow(suggestion));
			list.add(Cards.gap(3));
		}

		list.add(Cards.muted("Damage each adds to the kill, using the setup above."));
		return list;
	}

	/**
	 * One spec weapon as a row. Shared by the recommendation and the picker below it.
	 */
	private JPanel specRow(SpecSuggestion suggestion)
	{
		JPanel row = new JPanel(new BorderLayout(Cards.ROW_GAP, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(5, Cards.ROW_PADDING, 5, Cards.ROW_PADDING));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel icon = new JLabel();
		itemManager.getImage(suggestion.getWeapon().getItemId()).addTo(icon);
		row.add(icon, BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(row.getBackground());
		// BorderLayout gives the centre whatever the sides do not take, but it will not shrink a centre
		// below its minimum — it squeezes the east side to nothing instead. A label's minimum is the
		// width of its text, so the damage figure was being pushed off the panel entirely. Padding could
		// never fix that, which is why it kept coming back.
		Cards.fitToPanel(text);

		JLabel name = new JLabel(suggestion.getSpecial().getDisplayName());
		name.setFont(FontManager.getRunescapeBoldFont());
		name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		name.setAlignmentX(Component.LEFT_ALIGNMENT);
		text.add(name);

		text.add(Cards.bodyInRow(suggestion.getSpecial().describe()));
		// What it actually hits for. Without it the row showed a single net figure, so a spec that hits
		// hard but only a little harder than the weapon it replaces read as if nothing were computed.
		text.add(Cards.mutedInRow(String.format("average hit %.1f", suggestion.getSpecDamage())));

		if (suggestion.getNote() != null)
		{
			text.add(Cards.mutedInRow(suggestion.getNote()));
		}

		if (!suggestion.isOwned())
		{
			text.add(Cards.mutedInRow("Not in your bank"));
		}

		row.add(text, BorderLayout.CENTER);

		// A spec that is not worth using here is still shown, just not dressed up as a recommendation.
		boolean worthwhile = suggestion.getDamageAdded() >= SPEC_WORTH_USING;
		// A decimal, because rounding turned a real +1.4 into a bare "+1" that people read as a number
		// with its end cut off. The tooltip carries the unit the column has no room for.
		JLabel added = new JLabel(specValue(suggestion.getDamageAdded()));
		added.setFont(FontManager.getRunescapeBoldFont());
		added.setForeground(worthwhile ? ColorScheme.BRAND_ORANGE : Cards.mutedColor());
		added.setHorizontalAlignment(SwingConstants.RIGHT);
		added.setToolTipText("Damage this spec adds to the kill over an ordinary attack");
		// Reserved outright, so it cannot be negotiated away by a long weapon name.
		added.setPreferredSize(new Dimension(Cards.ROW_VALUE_WIDTH, added.getPreferredSize().height));
		added.setMinimumSize(new Dimension(Cards.ROW_VALUE_WIDTH, added.getPreferredSize().height));
		row.add(added, BorderLayout.EAST);

		return Cards.fitRow(row);
	}

	/**
	 * The damage figure as it is shown: a decimal until three figures, where the decimal would no
	 * longer fit the column it is given.
	 */
	private static String specValue(double damageAdded)
	{
		if (damageAdded < 0.05)
		{
			return "—";
		}

		return damageAdded >= 100
			? String.format("+%.0f", damageAdded)
			: String.format("+%.1f", damageAdded);
	}

	/**
	 * Gets back to the overview from a single style's setup.
	 * <p>
	 * The only route back used to be reopening "Optimise for" and reselecting "Best of every style",
	 * which is not somewhere you would think to look after clicking Open on a row.
	 */
	private JPanel backToAllStyles()
	{
		JButton back = Cards.button("← All styles");
		back.setToolTipText("Back to the best setup for every style");
		back.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		back.addActionListener(event -> profilePicker.setSelectedItem(Profile.ALL_STYLES));

		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
		row.add(back, BorderLayout.CENTER);
		return row;
	}

	private void renderOffensive(
		List<ScoredSetup> best, List<SpecSuggestion> specs, Profile profile, GearPool pool,
		@Nullable Monster target)
	{
		results.removeAll();
		if (best.isEmpty())
		{
			showMessage("Nothing in this gear pool can attack with " + profile.toString().toLowerCase()
				+ ".");
			return;
		}

		// Five setups that all score 2.48 are not five answers, they are one answer and four ties on a
		// slot that changes nothing — an emerald ring against a ring of dueling(1) against a ring of
		// dueling(5). Only setups that actually score differently are worth offering.
		best = distinctlyScored(best);

		int index = Math.min(shownSetupIndex, best.size() - 1);
		ScoredSetup top = best.get(index);
		remember(top.getSetup(), profile.toString());

		results.add(backToAllStyles());

		// Ranked alternatives, switchable in place. The strongest setup often hinges on one expensive
		// or risky item, and seeing what second place costs you is the whole question.
		if (best.size() > 1)
		{
			String[] labels = new String[best.size()];
			for (int i = 0; i < best.size(); i++)
			{
				labels[i] = String.valueOf(i + 1);
			}

			results.add(Cards.sectionLabel("Ranked setups"));
			results.add(Cards.segmented(labels, index, chosen ->
			{
				shownSetupIndex = chosen;
				rebuild();
			}));
			results.add(Cards.gap(6));
		}

		results.add(summaryCard(
			String.format("%.2f DPS", top.getScore().getDps()),
			String.format("%.1f%% accuracy  ·  max hit %d",
				top.getScore().accuracyPercent(), top.getScore().getMaxHit())));

		List<String> reasons = new ArrayList<>(top.getNotes());
		String against = target == null ? "a dummy target" : target.displayName();
		// The spell follows the target's elemental weakness now, so the panel has to say which one it
		// settled on. It claimed Ice Barrage whatever it had actually scored.
		reasons.add(profile.getStyle().isMagic() && top.getSpell() != null
			? "Casting " + top.getSpell().getDisplayName() + ", scored against " + against + "."
			: "Scored against " + against + ".");
		addSlayerRequirement(target, top.getSetup(), reasons);
		addUncheckedWarning(top.getSetup(), pool, reasons);
		addSection("Why", reasons);

		addSetup(top.getSetup());

		// Shown outright rather than behind a header. It is a recommendation like the setup above it,
		// and a recommendation you have to click to see is one most people never read.
		showSpecs(specs);
		results.add(Cards.gap(8));
		results.add(specContent);


		if (best.size() > 1)
		{
			List<String> alternatives = new ArrayList<>();
			for (int i = 0; i < best.size(); i++)
			{
				if (i == index)
				{
					continue;
				}

				ScoredSetup alternative = best.get(i);
				double delta = alternative.getScore().getDps() - top.getScore().getDps();
				alternatives.add(String.format("%d. %.2f DPS (%.2f) — %s",
					i + 1, alternative.getScore().getDps(), delta,
					describeDifference(top, alternative)));
			}

			addSection("The others", alternatives);
		}

		finish();
	}

	/**
	 * One setup per distinct DPS, keeping the best-ranked of each.
	 * <p>
	 * Rounded to what the panel prints: if two setups display the same number, offering both as
	 * alternatives tells the reader nothing they can act on.
	 */
	static List<ScoredSetup> distinctlyScored(List<ScoredSetup> best)
	{
		List<ScoredSetup> distinct = new ArrayList<>();
		Set<Long> seen = new HashSet<>();

		for (ScoredSetup setup : best)
		{
			if (seen.add(Math.round(setup.getScore().getDps() * 100)))
			{
				distinct.add(setup);
			}
		}

		return distinct;
	}

	private void renderDefensive(OptimizerResult best, Profile profile, GearPool pool)
	{
		results.removeAll();

		if (best.isEmpty())
		{
			showMessage("Nothing in this gear pool gives "
				+ profile.getStat().getDisplayName().toLowerCase() + ".");
			return;
		}

		remember(best.getSetup(), profile.toString());

		results.add(backToAllStyles());

		results.add(summaryCard(
			profile.getStat().format(best.getTotal()),
			profile.getStat().getDisplayName() + " total"));

		List<String> reasons = new ArrayList<>(best.getReasons());
		addUncheckedWarning(best.getSetup(), pool, reasons);
		addSection("Why", reasons);

		addSetup(best.getSetup());
		finish();
	}

	/**
	 * The requirements dataset is incomplete, so say plainly when a recommended item could not be
	 * checked rather than implying it is definitely wearable.
	 */
	private void addUncheckedWarning(Map<EquipmentSlot, GearItem> setup, GearPool pool, List<String> reasons)
	{
		if (pool != GearPool.USABLE)
		{
			return;
		}

		List<String> unchecked = new ArrayList<>();
		for (GearItem item : setup.values())
		{
			if (!itemRequirements.isKnown(item.getItemId()))
			{
				unchecked.add(item.getName());
			}
		}

		if (!unchecked.isEmpty())
		{
			reasons.add("Could not check requirements for " + String.join(", ", unchecked)
				+ " — check you can wear " + (unchecked.size() == 1 ? "it" : "them") + ".");
		}
	}

	private JPanel summaryCard(String headline, String detail)
	{
		JPanel inner = Cards.card();
		inner.add(Cards.headline(headline));
		inner.add(Cards.gap(2));
		inner.add(Cards.body(detail));

		JPanel card = Cards.accentCard(ColorScheme.BRAND_ORANGE);
		card.add(inner, BorderLayout.CENTER);
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	private void addSection(String title, List<String> lines)
	{
		if (lines.isEmpty())
		{
			return;
		}

		results.add(Cards.gap(10));
		results.add(Cards.sectionLabel(title));

		for (String line : lines)
		{
			results.add(Cards.muted(line));
			results.add(Cards.gap(2));
		}
	}

	private void addSetup(Map<EquipmentSlot, GearItem> setup)
	{
		results.add(Cards.gap(10));
		results.add(Cards.sectionLabel("Setup"));

		for (EquipmentSlot slot : EquipmentSlot.values())
		{
			GearItem item = setup.get(slot);
			if (item != null)
			{
				results.add(setupRow(slot, item));
				results.add(Cards.gap(2));
			}
		}

		results.add(Cards.gap(8));

		// Both sit in a strip that reserves the scrollbar's width, so they line up with the setup rows
		// above rather than running under the scrollbar and reading as off-centre.
		JPanel actions = new JPanel();
		actions.setLayout(new BoxLayout(actions, BoxLayout.Y_AXIS));
		actions.setBackground(ColorScheme.DARK_GRAY_COLOR);
		actions.setAlignmentX(Component.LEFT_ALIGNMENT);
		actions.setBorder(
			BorderFactory.createEmptyBorder(0, 0, 0, Cards.SCROLLBAR_ALLOWANCE));

		JButton save = Cards.button("Save as setup");
		save.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		save.setToolTipText("Save this as a setup you can come back to");
		save.addActionListener(event -> saveShownSetup());
		actions.add(save);

		actions.add(Cards.gap(4));

		// Filtering without saving: most of the time you just want to go and grab the gear. It has to
		// toggle — the filter stays on the bank until something turns it off, and this tab offered no
		// way to do that at all, so the only escape was the Setups tab or logging out.
		JButton show = Cards.button("Show in bank");
		show.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		labelBankFilterButton(show);
		show.addActionListener(event ->
		{
			if (bankFilterService.isShowingAnything())
			{
				clearBankFilter();
			}
			else
			{
				showShownSetupInBank();
			}

			labelBankFilterButton(show);
		});
		actions.add(show);

		actions.setMaximumSize(new Dimension(Integer.MAX_VALUE, actions.getPreferredSize().height));
		results.add(actions);
	}

	private void labelBankFilterButton(JButton button)
	{
		boolean showing = bankFilterService.isShowingAnything();
		button.setText(showing ? "Clear bank filter" : "Show in bank");
		button.setToolTipText(showing
			? "Stop filtering the bank"
			: "Filter your bank to these items without saving a setup");
	}

	/**
	 * Clears whatever the bank is filtered to, wherever it was set from.
	 * <p>
	 * The active setup is cleared as well, otherwise the filter comes back by itself on the next
	 * login — the plugin re-applies whatever is active.
	 */
	private void clearBankFilter()
	{
		setupStore.deactivate();
		bankFilterService.clearFilter();
		onSetupSaved.run();
	}

	/**
	 * Filters the bank to the displayed result directly, with no saved setup involved.
	 */
	private void showShownSetupInBank()
	{
		if (shownSetup.isEmpty())
		{
			return;
		}

		bankFilterService.applySetup(asSetup(shownName));
		onSetupSaved.run();
	}

	private Setup asSetup(String name)
	{
		Setup setup = Setup.named(name, SetupSource.BIS);
		shownSetup.forEach((slot, item) -> setup.put(slot, item.getItemId()));
		return setup;
	}

	private void remember(Map<EquipmentSlot, GearItem> setup, String name)
	{
		this.shownSetup = setup;
		this.shownName = name;
	}

	/**
	 * Turns the displayed result into a saved setup — the design's "BiS output is a setup" step.
	 */
	private void saveShownSetup()
	{
		if (shownSetup.isEmpty())
		{
			return;
		}

		String name = JOptionPane.showInputDialog(this, "Name this setup", shownName);
		if (name == null || name.trim().isEmpty())
		{
			return;
		}

		setupStore.add(asSetup(name.trim()));
		onSetupSaved.run();
	}

	/**
	 * Lets the panel refresh the Setups tab when a setup is saved from here.
	 */
	void setOnSetupSaved(Runnable callback)
	{
		this.onSetupSaved = callback;
	}

	/**
	 * Names the slots where the alternative differs, so a near-tie is explained rather than just listed.
	 */
	private static String describeDifference(ScoredSetup top, ScoredSetup alternative)
	{
		List<String> changes = new ArrayList<>();

		for (EquipmentSlot slot : EquipmentSlot.values())
		{
			GearItem chosen = top.getSetup().get(slot);
			GearItem other = alternative.getSetup().get(slot);

			if (other != null && (chosen == null || chosen.getItemId() != other.getItemId()))
			{
				changes.add(other.getName());
			}
		}

		return changes.isEmpty() ? "fewer items" : String.join(", ", changes);
	}

	private JPanel setupRow(EquipmentSlot slot, GearItem item)
	{
		JPanel row = new JPanel(new BorderLayout(8, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(30, 30));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		itemManager.getImage(item.getItemId()).addTo(icon);
		row.add(icon, BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(row.getBackground());
		Cards.fitToPanel(text);

		JLabel name = new JLabel(item.getName());
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		name.setAlignmentX(Component.LEFT_ALIGNMENT);
		text.add(name);

		JLabel slotLabel = new JLabel(slot.getDisplayName());
		slotLabel.setFont(FontManager.getRunescapeSmallFont());
		slotLabel.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		slotLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		text.add(slotLabel);

		row.add(text, BorderLayout.CENTER);
		row.setToolTipText(item.getName());
		return Cards.fitRow(row);
	}

	private void showMessage(String message)
	{
		results.removeAll();
		results.add(Cards.muted(message));
		finish();
	}

	private void finish()
	{
		// The monster data is CC BY-NC-SA, which requires attribution wherever it is used. This used to
		// live only on the Bosses tab; with that tab gone it has to be here, or the licence is breached.
		results.add(Cards.gap(10));
		results.add(Cards.muted(monsters.getAttribution()));

		results.revalidate();
		results.repaint();
	}

	/**
	 * Whether slayer helmet bonuses count. Defaults to reading the player's actual task, with manual
	 * overrides for planning ahead.
	 */
	private enum SlayerChoice
	{
		AUTO("Auto"),
		ON("On task"),
		OFF("Off task");

		private final String displayName;

		SlayerChoice(String displayName)
		{
			this.displayName = displayName;
		}

		boolean resolve(boolean detected)
		{
			switch (this)
			{
				case ON:
					return true;
				case OFF:
					return false;
				default:
					return detected;
			}
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}

	/**
	 * Which items the optimizer is allowed to choose from.
	 */
	private enum GearPool
	{
		USABLE("BiS for Level"),
		EVERYTHING("BiS Overall");

		private final String displayName;

		GearPool(String displayName)
		{
			this.displayName = displayName;
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}

	/**
	 * What the user is optimising for. Offensive profiles carry a combat style, defensive ones carry a
	 * single stat.
	 */
	private enum Profile
	{
		/**
		 * The default. Leads with the gear rather than making the player pick a style first — this is a
		 * best-in-slot tool that happens to rank by DPS, not a DPS calculator.
		 */
		ALL_STYLES("Best of every style", null, null),

		STAB("Melee — stab", CombatStyle.STAB, null),
		SLASH("Melee — slash", CombatStyle.SLASH, null),
		CRUSH("Melee — crush", CombatStyle.CRUSH, null),
		RANGED("Ranged", CombatStyle.RANGED, null),
		MAGIC("Magic", CombatStyle.MAGIC, null),

		DEF_STAB("Defence — stab", null, GearStat.STAB_DEFENCE),
		DEF_SLASH("Defence — slash", null, GearStat.SLASH_DEFENCE),
		DEF_CRUSH("Defence — crush", null, GearStat.CRUSH_DEFENCE),
		DEF_MAGIC("Defence — magic", null, GearStat.MAGIC_DEFENCE),
		DEF_RANGED("Defence — ranged", null, GearStat.RANGED_DEFENCE),
		PRAYER("Max prayer", null, GearStat.PRAYER);

		private final String displayName;
		@Nullable
		private final CombatStyle style;
		@Nullable
		private final GearStat stat;

		Profile(String displayName, @Nullable CombatStyle style, @Nullable GearStat stat)
		{
			this.displayName = displayName;
			this.style = style;
			this.stat = stat;
		}

		boolean isOffensive()
		{
			return style != null;
		}

		/**
		 * @return the single-style profile for this combat style, so a row in the overview can jump to it
		 */
		static Profile forStyle(CombatStyle style)
		{
			for (Profile profile : values())
			{
				if (profile.style == style)
				{
					return profile;
				}
			}

			return ALL_STYLES;
		}

		CombatStyle getStyle()
		{
			return style;
		}

		GearStat getStat()
		{
			return stat;
		}

		@Override
		public String toString()
		{
			return displayName;
		}
	}
}

package com.gearforge.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.util.function.Consumer;
import java.util.function.IntConsumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ButtonGroup;
import javax.swing.DefaultListCellRenderer;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JToggleButton;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Shared building blocks so the two tabs look like one plugin rather than two.
 */
final class Cards
{
	/** Left accent strip width on a card, in pixels. */
	private static final int ACCENT = 3;

	/** Red rather than the brand orange, so a warning does not read as ordinary highlighting. */
	private static final Color WARNING_COLOR = new Color(220, 90, 70);

	/**
	 * Secondary text. RuneLite's MEDIUM_GRAY_COLOR on the panel background is grey-on-grey and was
	 * reported as hard to read; this keeps the hierarchy while staying legible.
	 */
	private static final Color MUTED_TEXT = new Color(170, 170, 170);

	/**
	 * Rows sit inside a scroll pane, and a trailing value would otherwise be clipped by the scrollbar.
	 */
	static final int SCROLLBAR_ALLOWANCE = 12;

	/** Padding inside a card, per side. */
	static final int CARD_PADDING = 8;

	/** The panel's own border, per side, set in GearForgePanel. */
	private static final int PANEL_BORDER = 8;

	/**
	 * How wide anything in the panel may actually be.
	 * <p>
	 * RuneLite gives a plugin panel {@link PluginPanel#PANEL_WIDTH} pixels. The panel's own border
	 * takes eight from each side, and once a tab is long enough to scroll — which every one of them
	 * is — the scrollbar takes more off the right. Everything else here is derived from this rather
	 * than guessed at, because guessing is what produced a panel that kept not fitting.
	 */
	static final int CONTENT_WIDTH =
		PluginPanel.PANEL_WIDTH - 2 * PANEL_BORDER - SCROLLBAR_ALLOWANCE;

	/**
	 * How wide wrapped text may be. Card padding on both sides, the accent strip a card may carry, and
	 * two pixels of slack for a border this arithmetic has not accounted for.
	 */
	static final int TEXT_WIDTH = CONTENT_WIDTH - 2 * CARD_PADDING - ACCENT - 2;

	/** The icon on the left of a row, and the gap after it. */
	static final int ROW_ICON_WIDTH = 36;

	/** Horizontal padding inside a row, per side. */
	static final int ROW_PADDING = 6;

	/** The gap a row's BorderLayout puts between its icon, its text and its value. */
	static final int ROW_GAP = 6;

	/** Reserved for the figure at the right of a row, wide enough for any of them. */
	static final int ROW_VALUE_WIDTH = 44;

	/**
	 * How wide text may be inside a row that also carries an icon on one side and a value on the
	 * other. What is left after everything fixed has taken its share.
	 */
	static final int IN_ROW_TEXT_WIDTH = CONTENT_WIDTH - 2 * ROW_PADDING - ROW_ICON_WIDTH
		- 2 * ROW_GAP - ROW_VALUE_WIDTH;

	private Cards()
	{
	}

	/**
	 * How many real pixels Swing gives one CSS pixel.
	 * <p>
	 * Swing's HTML renderer does not treat {@code width:140px} as 140 pixels — it scales it, by about a
	 * third on a standard display. Every wrapped label in this panel was therefore a third wider than
	 * the number written next to it, which is why the widths kept looking right in the source and
	 * wrong on screen. Measured once rather than assumed, since the factor follows the display.
	 */
	private static final double CSS_PIXEL = measureCssPixel();

	private static double measureCssPixel()
	{
		JLabel probe = new JLabel("<html><body style='width:100px'>x</body></html>");
		probe.setFont(FontManager.getRunescapeSmallFont());

		int measured = probe.getPreferredSize().width;
		return measured > 0 ? measured / 100.0 : 1.0;
	}

	/**
	 * Text that wraps within a given number of real pixels.
	 */
	private static String wrapped(String text, int pixels)
	{
		int css = Math.max(1, (int) Math.floor(pixels / CSS_PIXEL));
		return "<html><body style='width:" + css + "px'>" + escape(text) + "</body></html>";
	}

	/**
	 * Wrapped text at the panel's text width, for callers that need their own font or colour on it.
	 */
	static String wrappedText(String text)
	{
		return wrapped(text, TEXT_WIDTH);
	}

	/**
	 * Stops a component insisting on more width than the panel has.
	 * <p>
	 * A BoxLayout hands each child the container's width, but never less than the child's own minimum
	 * — and a minimum comes from the text inside, so one long item name lays its row out wider than
	 * the panel and everything to the right of it goes off the edge. The scroll pane has no horizontal
	 * bar, so there is no way to reach it. Every row, dropdown and button strip is clamped through
	 * here, which is what makes "it does not fit" a thing that cannot happen rather than a thing to
	 * keep noticing.
	 */
	static <T extends JComponent> T fitToPanel(T component)
	{
		component.setMinimumSize(new Dimension(0, component.getMinimumSize().height));
		return component;
	}

	/**
	 * The same, for a component whose height should also be pinned to what it needs — a row in a
	 * vertical list, which BoxLayout would otherwise stretch to fill the viewport.
	 */
	static <T extends JComponent> T fitRow(T row)
	{
		int height = row.getPreferredSize().height;
		row.setMinimumSize(new Dimension(0, height));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		return row;
	}

	/**
	 * A padded block with a subtle darker background — the unit the panel is composed from.
	 */
	static JPanel card()
	{
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		return card;
	}

	/**
	 * A card with a coloured strip down the left, used for the headline result.
	 */
	static JPanel accentCard(Color accent)
	{
		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		wrapper.setBorder(BorderFactory.createMatteBorder(0, ACCENT, 0, 0, accent));
		wrapper.setAlignmentX(Component.LEFT_ALIGNMENT);
		return wrapper;
	}

	/**
	 * Section label — small, uppercase, muted. Used to break the panel into scannable groups.
	 */
	static JLabel sectionLabel(String text)
	{
		JLabel label = new JLabel(text.toUpperCase());
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(MUTED_TEXT);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
		// Clipped rather than allowed to widen the panel: a label's minimum is the width of its text,
		// and a BoxLayout honours that minimum even when the container is narrower.
		return fitToPanel(label);
	}

	/**
	 * The one number that matters, rendered large.
	 */
	static JLabel headline(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 16f));
		label.setForeground(ColorScheme.BRAND_ORANGE);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return fitToPanel(label);
	}

	/**
	 * A setup or section title — larger than body text so a list of setups scans by name.
	 */
	static JLabel title(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 13f));
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return fitToPanel(label);
	}

	/**
	 * A prominent warning block — a coloured strip and bold text, for things the player needs to act
	 * on rather than merely notice.
	 */
	static JPanel warning(String text)
	{
		JPanel inner = new JPanel();
		inner.setLayout(new BoxLayout(inner, BoxLayout.Y_AXIS));
		inner.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		inner.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		JLabel label = new JLabel(wrapped(text, TEXT_WIDTH));
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(WARNING_COLOR);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		inner.add(label);

		JPanel card = new JPanel(new BorderLayout());
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createMatteBorder(0, ACCENT, 0, 0, WARNING_COLOR));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.add(inner, BorderLayout.CENTER);
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	/**
	 * The secondary text colour, for callers that need it on a component this class does not build.
	 */
	static Color mutedColor()
	{
		return MUTED_TEXT;
	}

	static JLabel body(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return fitToPanel(label);
	}

	/**
	 * Body text sized to sit inside a row that already has an icon on one side and a value on the
	 * other.
	 */
	static JLabel bodyInRow(String text)
	{
		JLabel label = new JLabel(wrapped(text, IN_ROW_TEXT_WIDTH));
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/**
	 * Muted text sized to sit inside a row that already has an icon on one side and a value on the
	 * other. The full-width version forces the row wider than the panel, which pushes the value off the
	 * edge entirely.
	 */
	static JLabel mutedInRow(String text)
	{
		JLabel label = new JLabel(wrapped(text, IN_ROW_TEXT_WIDTH));
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(MUTED_TEXT);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	static JLabel muted(String text)
	{
		JLabel label = new JLabel(wrapped(text, TEXT_WIDTH));
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(MUTED_TEXT);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/**
	 * A labelled form field stacked vertically, which reads better than side-by-side at this width.
	 */
	static JPanel field(String label, JComponent input)
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel caption = sectionLabel(label);
		panel.add(caption);

		input.setAlignmentX(Component.LEFT_ALIGNMENT);
		input.setMaximumSize(new Dimension(Integer.MAX_VALUE, input.getPreferredSize().height));
		panel.add(input);

		return panel;
	}

	/**
	 * A vertical spacer that is left-aligned like everything else.
	 * <p>
	 * {@link Box#createVerticalStrut} defaults to centre alignment, and a Y_AXIS BoxLayout containing
	 * a mix of alignments indents its children instead of filling the panel — which is what made the
	 * whole sidebar look squashed toward one side.
	 */
	static Component gap(int height)
	{
		Component strut = Box.createVerticalStrut(height);
		((JComponent) strut).setAlignmentX(Component.LEFT_ALIGNMENT);
		return strut;
	}

	/**
	 * A compact button that matches the sidebar rather than the platform look-and-feel.
	 */
	static JButton button(String text)
	{
		JButton button = new JButton(text);
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		button.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		// Tight horizontal padding: at 225px, three buttons in a row have barely 60px each, and
		// generous padding is what truncated "Off task" into "Off...".
		button.setBorder(BorderFactory.createEmptyBorder(4, 3, 4, 3));
		button.setFocusPainted(false);
		button.setAlignmentX(Component.LEFT_ALIGNMENT);
		return fitToPanel(button);
	}

	/**
	 * A titled section that expands when clicked, like the panels in the wiki's DPS calculator.
	 * <p>
	 * Used instead of a dropdown where the options benefit from being seen at once — prayers as a grid
	 * of icons, potions as a scrollable list — rather than hidden one-at-a-time behind a combo box.
	 *
	 * @param content shown when expanded; starts hidden
	 * @param decorate given the header button, so callers can hang an icon on it — the sprite and item
	 *                 image loaders are asynchronous, so the icon cannot simply be passed in
	 */
	static JPanel expandable(String title, JComponent content, Consumer<JButton> decorate)
	{
		JPanel section = new JPanel();
		section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
		section.setBackground(ColorScheme.DARK_GRAY_COLOR);
		section.setAlignmentX(Component.LEFT_ALIGNMENT);

		JButton header = button(title + "   +");
		header.setHorizontalAlignment(SwingConstants.LEFT);
		header.setIconTextGap(8);
		// Tall enough that a skill icon sits in the row rather than being clipped by it.
		header.setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 6));
		header.setPreferredSize(new Dimension(0, 30));
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
		header.setMinimumSize(new Dimension(0, 30));
		decorate.accept(header);

		content.setVisible(false);
		content.setAlignmentX(Component.LEFT_ALIGNMENT);

		header.addActionListener(event ->
		{
			boolean opening = !content.isVisible();
			content.setVisible(opening);
			header.setText(title + (opening ? "   −" : "   +"));
			section.revalidate();
			section.repaint();
		});

		section.add(header);
		section.add(content);
		return section;
	}

	/**
	 * A dropdown styled to match the sidebar. The default Swing combo renders light-on-light here and
	 * stands out badly against RuneLite's dark panels.
	 */
	static <T> JComboBox<T> comboBox(T[] items)
	{
		JComboBox<T> combo = new JComboBox<>(items);
		combo.setFont(FontManager.getRunescapeSmallFont());
		combo.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		combo.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		combo.setFocusable(false);
		combo.setBorder(BorderFactory.createEmptyBorder(2, 4, 2, 4));
		combo.setRenderer(new DarkListRenderer());
		combo.setAlignmentX(Component.LEFT_ALIGNMENT);

		// A combo sizes itself to its longest entry. With a thousand monsters in the list that is far
		// wider than the panel, and the box was laid out past the edge of it.
		int height = combo.getPreferredSize().height;
		combo.setPreferredSize(new Dimension(CONTENT_WIDTH, height));
		combo.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		combo.setMinimumSize(new Dimension(0, height));
		return combo;
	}

	/**
	 * Two or more mutually exclusive options as side-by-side buttons — clearer than a dropdown when
	 * there are only a couple of choices, and it shows the alternative without a click.
	 */
	static JPanel segmented(String[] labels, int selectedIndex, IntConsumer onSelect)
	{
		JPanel row = new JPanel(new GridLayout(1, labels.length, 4, 0));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		row.setMinimumSize(new Dimension(0, 26));

		ButtonGroup group = new ButtonGroup();

		for (int i = 0; i < labels.length; i++)
		{
			final int index = i;
			JToggleButton option = new JToggleButton(labels[i]);
			option.setFont(FontManager.getRunescapeSmallFont());
			option.setFocusPainted(false);
			option.setBorder(BorderFactory.createEmptyBorder(4, 2, 4, 2));
			option.setSelected(i == selectedIndex);
			// A grid divides the width evenly, but only down to the widest label's minimum, so two long
			// options together were enough to push the strip past the panel.
			fitToPanel(option);
			paintToggle(option);

			option.addItemListener(event ->
			{
				paintToggle(option);
				if (option.isSelected())
				{
					onSelect.accept(index);
				}
			});

			group.add(option);
			row.add(option);
		}

		return row;
	}

	private static void paintToggle(JToggleButton option)
	{
		option.setBackground(option.isSelected()
			? ColorScheme.BRAND_ORANGE
			: ColorScheme.DARKER_GRAY_COLOR);
		option.setForeground(option.isSelected()
			? ColorScheme.DARKER_GRAY_COLOR
			: ColorScheme.LIGHT_GRAY_COLOR);
	}

	/**
	 * Keeps the dropdown popup dark instead of the default white list.
	 */
	private static final class DarkListRenderer extends DefaultListCellRenderer
	{
		@Override
		public Component getListCellRendererComponent(
			JList<?> list, Object value, int index, boolean isSelected, boolean cellHasFocus)
		{
			super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);

			setFont(FontManager.getRunescapeSmallFont());
			setBackground(isSelected ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR);
			setForeground(isSelected ? ColorScheme.DARKER_GRAY_COLOR : ColorScheme.LIGHT_GRAY_COLOR);
			setBorder(BorderFactory.createEmptyBorder(3, 5, 3, 5));
			return this;
		}
	}

	/**
	 * Item names come from the game and can contain characters that would break the HTML wrapper.
	 */
	static String escape(String text)
	{
		return text
			.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;");
	}
}

package com.gearforge.ui;

import com.gearforge.data.BankModel;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.materialtabs.MaterialTab;
import net.runelite.client.ui.components.materialtabs.MaterialTabGroup;

/**
 * The GearForge sidebar: Setups, Search, BiS and Raids.
 */
@Singleton
public class GearForgePanel extends PluginPanel
{
	/**
	 * Gear changes arrive in bursts — swapping a set fires an event per item. Coalescing them stops
	 * each one kicking off its own recomputation.
	 */
	private static final long REFRESH_DELAY_MS = 400;

	private final BankModel bankModel;
	private final ScheduledExecutorService executor;
	private final SetupsTab setupsTab;
	private final SlotsTab slotsTab;
	private final BisTab bisTab;
	private final RaidsTab raidsTab = new RaidsTab();
	private final JLabel staleness = new JLabel();

	/** The tab currently on screen. Only this one is ever recomputed. */
	private Runnable activeRebuild;

	/** Whether the sidebar is actually open. Nothing is computed while it is closed. */
	private volatile boolean visible;

	private ScheduledFuture<?> pendingRefresh;

	@Inject
	private GearForgePanel(
		BankModel bankModel,
		ScheduledExecutorService executor,
		SetupsTab setupsTab,
		SlotsTab slotsTab,
		BisTab bisTab)
	{
		super(false);
		this.bankModel = bankModel;
		this.executor = executor;
		this.setupsTab = setupsTab;
		this.slotsTab = slotsTab;
		this.bisTab = bisTab;

		// Saving or filtering from another tab has to show up in the Setups tab straight away.
		bisTab.setOnSetupSaved(setupsTab::rebuild);

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		JPanel display = new JPanel(new BorderLayout());
		display.setBackground(ColorScheme.DARK_GRAY_COLOR);

		MaterialTabGroup tabGroup = new MaterialTabGroup(display);
		// Two rows, because four will not fit on one. A grid divides the width evenly, so at 225 pixels
		// each of four tabs gets 47 — and "Raids (TBD)" needs 86, "Setups" 60. Measured rather than
		// guessed at: a label wider than its cell is what made an earlier fourth tab vanish.
		tabGroup.setLayout(new GridLayout(2, 2, 2, 2));
		tabGroup.setAlignmentX(LEFT_ALIGNMENT);
		tabGroup.setMaximumSize(new Dimension(Integer.MAX_VALUE, 58));

		MaterialTab setups = new MaterialTab("Setups", tabGroup, setupsTab);
		MaterialTab slots = new MaterialTab("Search", tabGroup, slotsTab);
		MaterialTab bis = new MaterialTab("BiS", tabGroup, bisTab);
		MaterialTab raids = new MaterialTab(RaidsTab.TITLE, tabGroup, raidsTab);
		raids.setToolTipText("Raid gear — not built yet");
		// Recompute only the tab being looked at, and only when it is switched to. Rebuilding every one
		// on every gear change is what made the client stutter.
		trackSelection(setups, setupsTab::rebuild);
		trackSelection(slots, slotsTab::rebuild);
		trackSelection(bis, bisTab::rebuild);
		// Nothing to recompute: the tab is a notice, not a result.
		trackSelection(raids, () -> { });

		tabGroup.addTab(setups);
		tabGroup.addTab(slots);
		tabGroup.addTab(bis);
		tabGroup.addTab(raids);

		activeRebuild = setupsTab::rebuild;
		tabGroup.select(setups);

		JPanel top = new JPanel();
		top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));
		top.setBackground(ColorScheme.DARK_GRAY_COLOR);
		top.add(buildHeader());
		top.add(tabGroup);
		// Breathing room between the tab row and whatever the tab puts at its top.
		top.add(Box.createVerticalStrut(10));

		add(top, BorderLayout.NORTH);
		add(display, BorderLayout.CENTER);
	}

	private JPanel buildHeader()
	{
		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setBorder(BorderFactory.createEmptyBorder(0, 0, 8, 0));

		JLabel title = new JLabel("GearForge");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(ColorScheme.BRAND_ORANGE);
		title.setAlignmentX(LEFT_ALIGNMENT);
		header.add(title);

		staleness.setFont(FontManager.getRunescapeSmallFont());
		staleness.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		staleness.setAlignmentX(LEFT_ALIGNMENT);
		header.add(staleness);

		return header;
	}

	/**
	 * Notes which tab is on screen so only that one is recomputed.
	 */
	private void trackSelection(MaterialTab tab, Runnable rebuild)
	{
		tab.setOnSelectEvent(() ->
		{
			activeRebuild = rebuild;
			rebuild.run();
			return true;
		});
	}

	@Override
	public void onActivate()
	{
		visible = true;
		refresh();
	}

	@Override
	public void onDeactivate()
	{
		visible = false;
		cancelPendingRefresh();
	}

	/**
	 * Asks for a recomputation of the visible tab.
	 * <p>
	 * Debounced and dropped entirely while the sidebar is closed. Callers include equipment and
	 * inventory container events, which fire on the game thread several times per gear swap, so this
	 * must stay cheap — the actual work happens later and off that thread.
	 */
	public void refresh()
	{
		if (!visible)
		{
			return;
		}

		SwingUtilities.invokeLater(this::updateStaleness);

		synchronized (this)
		{
			cancelPendingRefresh();
			Runnable rebuild = activeRebuild;
			pendingRefresh = executor.schedule(
				() -> SwingUtilities.invokeLater(rebuild), REFRESH_DELAY_MS, TimeUnit.MILLISECONDS);
		}
	}

	/**
	 * Rebuilds immediately, for user actions where waiting would feel broken.
	 */
	public void refreshNow()
	{
		SwingUtilities.invokeLater(this::updateStaleness);
		SwingUtilities.invokeLater(activeRebuild);
	}

	private synchronized void cancelPendingRefresh()
	{
		if (pendingRefresh != null)
		{
			pendingRefresh.cancel(false);
			pendingRefresh = null;
		}
	}

	/**
	 * Cancels outstanding work so a shut-down plugin leaves nothing scheduled.
	 */
	public void shutDown()
	{
		visible = false;
		cancelPendingRefresh();
	}

	private void updateStaleness()
	{
		staleness.setText(bankModel.hasBankData()
			? "Bank data from " + describeAge(System.currentTimeMillis() - bankModel.getBankCapturedAt())
			: "No bank data yet");
	}

	/**
	 * Plain-language age, e.g. "2 hours ago". Never dresses stale data up as current.
	 */
	private static String describeAge(long millis)
	{
		long minutes = TimeUnit.MILLISECONDS.toMinutes(millis);
		if (minutes < 1)
		{
			return "just now";
		}

		if (minutes < 60)
		{
			return plural(minutes, "minute") + " ago";
		}

		long hours = TimeUnit.MILLISECONDS.toHours(millis);
		if (hours < 24)
		{
			return plural(hours, "hour") + " ago";
		}

		return plural(TimeUnit.MILLISECONDS.toDays(millis), "day") + " ago";
	}

	private static String plural(long count, String unit)
	{
		return count + " " + (count == 1 ? unit : unit + "s");
	}
}

package com.gearforge.ui;

import com.gearforge.data.GearItem;
import com.gearforge.data.GearStat;
import com.gearforge.data.Storage;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.Font;
import java.util.StringJoiner;
import javax.annotation.Nullable;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * One row in the ranked list: icon, name, where it is, and how it compares to what you have on.
 */
class ItemRow extends JPanel
{
	private static final Dimension ICON_SIZE = new Dimension(32, 32);

	/**
	 * @param wornValue the value of this stat on the item currently in that slot, or null if the slot
	 *                  is empty or the player is not logged in
	 */
	ItemRow(GearItem item, GearStat stat, ItemManager itemManager, @Nullable Double wornValue)
	{
		boolean isWorn = item.getLocations().contains(Storage.EQUIPMENT);

		setLayout(new BorderLayout(8, 0));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		// Extra room on the right so the value is not clipped by the scroll pane's scrollbar.
		setBorder(BorderFactory.createEmptyBorder(4, 6, 4, 6 + Cards.SCROLLBAR_ALLOWANCE));
		setAlignmentX(LEFT_ALIGNMENT);
		// Without a ceiling, BoxLayout stretches the last row to fill the viewport.
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 42));

		JLabel icon = new JLabel();
		icon.setPreferredSize(ICON_SIZE);
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		itemManager.getImage(item.getItemId()).addTo(icon);
		add(icon, BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(getBackground());
		// An item name is as long as it is. Without this the row's own minimum grows with it and the
		// row is laid out wider than the panel, taking the value on the right off the edge with it.
		Cards.fitToPanel(text);

		JLabel name = new JLabel(item.getName());
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(isWorn ? ColorScheme.BRAND_ORANGE : ColorScheme.LIGHT_GRAY_COLOR);
		name.setAlignmentX(LEFT_ALIGNMENT);
		text.add(name);

		text.add(buildSubtitle(item, stat, wornValue, isWorn));
		add(text, BorderLayout.CENTER);

		JLabel value = new JLabel(stat.format(item.statValue(stat)));
		value.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD));
		value.setForeground(ColorScheme.BRAND_ORANGE);
		value.setHorizontalAlignment(SwingConstants.RIGHT);
		add(value, BorderLayout.EAST);

		setMinimumSize(new Dimension(0, 42));
		setToolTipText(item.getName() + " — " + stat.getDisplayName() + " " + stat.format(item.statValue(stat)));
	}

	/**
	 * "Bank" plus, when something is worn in this slot, how much better or worse this item is.
	 */
	private JPanel buildSubtitle(GearItem item, GearStat stat, @Nullable Double wornValue, boolean isWorn)
	{
		JPanel subtitle = new JPanel();
		subtitle.setLayout(new BoxLayout(subtitle, BoxLayout.X_AXIS));
		subtitle.setBackground(getBackground());
		subtitle.setAlignmentX(LEFT_ALIGNMENT);

		JLabel where = new JLabel(isWorn ? "Worn" : describeLocations(item));
		where.setFont(FontManager.getRunescapeSmallFont());
		where.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		subtitle.add(where);

		if (!isWorn && wornValue != null)
		{
			double delta = item.statValue(stat) - wornValue;
			if (delta != 0)
			{
				subtitle.add(Box.createHorizontalStrut(4));

				JLabel comparison = new JLabel(stat.format(delta) + " vs worn");
				comparison.setFont(FontManager.getRunescapeSmallFont());
				comparison.setForeground(delta > 0
					? ColorScheme.PROGRESS_COMPLETE_COLOR
					: ColorScheme.PROGRESS_ERROR_COLOR);
				subtitle.add(comparison);
			}
		}

		subtitle.add(Box.createHorizontalGlue());
		return subtitle;
	}

	private static String describeLocations(GearItem item)
	{
		StringJoiner joiner = new StringJoiner(", ");
		for (Storage storage : item.getLocations())
		{
			joiner.add(storage.toString());
		}

		String places = joiner.toString();
		return item.getQuantity() > 1
			? places + " (" + item.getQuantity() + ")"
			: places;
	}
}

