	static final String TITLE = "Raids (TBD)";

	RaidsTab()
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder(4, 0, 4, Cards.SCROLLBAR_ALLOWANCE));
