/**
 * Saved loadouts.
 * <p>
 * Showing a setup in the bank filters it there — it never withdraws, deposits or equips anything.
 * Editing is per slot: take what you are wearing, or accept an upgrade the plugin found in your bank.
 */
@Singleton
class SetupsTab extends JPanel
{
	private final ClientThread clientThread;
	private final ScheduledExecutorService executor;
	private final BankModel bankModel;
	private final ItemStatEngine statEngine;
	private final ItemCanonicalizer canonicalizer;
	private final SetupStore setupStore;
	private final BankFilterService bankFilterService;
	private final PlayerModel playerModel;
	private final UpgradeFinder upgradeFinder;
	private final Scoring scoring;
	private final InventorySetupsImporter importer;
	private final ItemManager itemManager;

	private final JPanel list = new JPanel();

	private static final int INVENTORY_COLUMNS = 4;
	private static final int INVENTORY_ROWS = 7;

	/** Which setups are expanded for editing. */
	private final Set<String> expanded = new HashSet<>();

	@Inject
	private SetupsTab(
		ClientThread clientThread,
		ScheduledExecutorService executor,
		BankModel bankModel,
		ItemStatEngine statEngine,
		ItemCanonicalizer canonicalizer,
		SetupStore setupStore,
		BankFilterService bankFilterService,
		PlayerModel playerModel,
		UpgradeFinder upgradeFinder,
		Scoring scoring,
		InventorySetupsImporter importer,
		ItemManager itemManager)
	{
		this.clientThread = clientThread;
		this.executor = executor;
		this.bankModel = bankModel;
		this.statEngine = statEngine;
		this.canonicalizer = canonicalizer;
		this.setupStore = setupStore;
		this.bankFilterService = bankFilterService;
		this.playerModel = playerModel;
		this.upgradeFinder = upgradeFinder;
		this.scoring = scoring;
		this.importer = importer;
		this.itemManager = itemManager;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		add(buildControls(), BorderLayout.NORTH);

		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel holder = new JPanel(new BorderLayout());
		holder.setBackground(ColorScheme.DARK_GRAY_COLOR);
		holder.add(list, BorderLayout.NORTH);

		JScrollPane scroll = new JScrollPane(
			holder, JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(scroll, BorderLayout.CENTER);
	}

	private JPanel buildControls()
	{
		JPanel controls = new JPanel();
		controls.setLayout(new BoxLayout(controls, BoxLayout.Y_AXIS));
		controls.setBackground(ColorScheme.DARK_GRAY_COLOR);
		controls.setBorder(BorderFactory.createEmptyBorder(4, 0, 12, 0));

		JButton fromCurrent = Cards.button("Save what I'm wearing");
		fromCurrent.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		fromCurrent.addActionListener(event -> saveCurrentGear());
		controls.add(fromCurrent);

		controls.add(Cards.gap(4));

		JButton paste = Cards.button("Paste a share code");
		paste.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		paste.setToolTipText("Rebuild a setup someone shared with you");
		paste.addActionListener(event -> pasteShareCode());
		controls.add(paste);

		controls.add(Cards.gap(4));

		// Shown unconditionally. This panel is built once, so gating it on a check made at construction
		// hid the button from anyone who installed Inventory Setups or made their first loadout later —
		// the feature simply looked absent. Checking when it is clicked always reflects reality.
		JButton importSetups = Cards.button("Import from Inventory Setups");
		importSetups.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
		importSetups.setToolTipText("Copy your Inventory Setups loadouts across. Nothing there is changed.");
		importSetups.addActionListener(event -> importFromInventorySetups());
		controls.add(importSetups);

		return controls;
	}

	/**
	 * The primary creation path from the design: capture what you have on rather than build a setup
	 * piece by piece.
	 */
	private void saveCurrentGear()
	{
		clientThread.invoke(() ->
		{
			Map<EquipmentSlot, GearItem> worn = wornGear();

			Setup setup = Setup.named("New setup", SetupSource.CURRENT_GEAR);
			worn.forEach((slot, item) -> setup.put(slot, item.getItemId()));
			setup.setInventoryFrom(bankModel.getInventoryOrder());

			SwingUtilities.invokeLater(() -> promptAndSave(setup, "Worn gear"));
		});
	}

	/**
	 * Saves a setup after asking for a name. Shared by this tab and the BiS tab's save button.
	 */
	void promptAndSave(Setup setup, String suggestedName)
	{
		if (setup.getEquipment().isEmpty())
		{
			JOptionPane.showMessageDialog(this,
				"Couldn't read your worn equipment. Log in and make sure you're wearing something, "
					+ "then try again.",
				"GearForge", JOptionPane.INFORMATION_MESSAGE);
			return;
		}

		String name = JOptionPane.showInputDialog(this, "Name this setup", suggestedName);
		if (name == null || name.trim().isEmpty())
		{
			return;
		}

		setup.setName(name.trim());
		setupStore.add(setup);
		rebuild();
	}

	/**
	 * Copies loadouts across from Inventory Setups. Nothing there is modified or removed, so both
	 * plugins keep working.
	 */
	private void importFromInventorySetups()
	{
		List<Setup> found = importer.readAll();

		if (found.isEmpty())
		{
			JOptionPane.showMessageDialog(this,
				"No Inventory Setups loadouts found.\n\nThis reads the setups that plugin has already "
					+ "saved, so it needs Inventory Setups installed with at least one setup in it.",
				"GearForge", JOptionPane.INFORMATION_MESSAGE);
			return;
		}

		int choice = JOptionPane.showConfirmDialog(this,
			"Import " + found.size() + (found.size() == 1 ? " setup" : " setups")
				+ " from Inventory Setups?\nYour Inventory Setups data won't be changed.",
			"GearForge", JOptionPane.YES_NO_OPTION);

		if (choice != JOptionPane.YES_OPTION)
		{
			return;
		}

		for (Setup setup : found)
		{
			setupStore.add(setup);
		}

		rebuild();
	}

	private void copyShareCode(Setup setup)
	{
		String code = SetupCodec.encode(setup);
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(code), null);

		JOptionPane.showMessageDialog(this,
			"Share code copied to your clipboard.", "GearForge", JOptionPane.INFORMATION_MESSAGE);
	}

	private void pasteShareCode()
	{
		String code = JOptionPane.showInputDialog(this, "Paste a GearForge share code");
		if (code == null || code.trim().isEmpty())
		{
			return;
		}

		Setup shared = SetupCodec.decode(code);
		if (shared == null)
		{
			JOptionPane.showMessageDialog(this,
				"That doesn't look like a GearForge share code.", "GearForge",
				JOptionPane.INFORMATION_MESSAGE);
			return;
		}

		setupStore.add(shared);
		rebuild();
	}

	void rebuild()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::rebuild);
			return;
		}

		// Item names and levels need the client thread; the upgrade search does not. Running it there
		// for every saved setup is part of what made gear swaps stutter.
		clientThread.invoke(() ->
		{
			List<GearItem> ownedGear = bankModel.hasBankData()
				? statEngine.resolveOwnedGear(bankModel)
				: Collections.emptyList();
			PlayerLevels levels = playerModel.snapshot();
			Map<Integer, String> inventoryNames = resolveInventoryNames();

			executor.execute(() ->
			{
				SetupsView view = buildView(ownedGear, levels, inventoryNames);
				SwingUtilities.invokeLater(() -> render(view));
			});
		});
	}

	/**
	 * Names for every item a saved setup carries in its inventory.
	 * <p>
	 * Must run on the client thread. An inventory holds things that are not equipment — logs, seeds,
	 * runes — so their names cannot come from the resolved gear list and have to be looked up here,
	 * before the rest of the view is built off-thread.
	 */
	private Map<Integer, String> resolveInventoryNames()
	{
		Map<Integer, String> names = new HashMap<>();

		for (Setup setup : setupStore.all())
		{
			for (ItemRequirement requirement : setup.getInventory())
			{
				if (requirement != null)
				{
					names.computeIfAbsent(requirement.getItemId(),
						id -> itemManager.getItemComposition(id).getName());
				}
			}
		}

		return names;
	}

	/**
	 * Everything the panel needs. Pure computation, so it is safe off the client thread.
	 */
	private SetupsView buildView(
		List<GearItem> ownedGear, PlayerLevels levels, Map<Integer, String> inventoryNames)
	{
		SetupsView view = new SetupsView();

		bankModel.ownedItems().forEach((id, owned) -> view.quantities.put(id, owned.getQuantity()));

		// Before the early return: a setup's inventory should still read as item names when there is no
		// bank data to resolve gear from.
		view.names.putAll(inventoryNames);

		if (ownedGear.isEmpty())
		{
			return view;
		}

		view.worn.putAll(wornGear(ownedGear));

		for (GearItem item : ownedGear)
		{
			view.names.put(item.getItemId(), item.getName());
		}

		// The shared builder, so an upgrade suggestion is measured the same way the BiS tab measures a
		// setup. This was assembled by hand here — slash, Ice Barrage, no target — so every fix to the
		// model since has been missing from the upgrade nudges entirely.
		CombatContext template = scoring.contextFor(
			CombatStyle.SLASH, levels, null, Scoring.noPrayers(), Scoring.noPotions());

		for (Setup setup : setupStore.all())
		{
			view.inventoryStatuses.put(setup.getId(),
				SetupValidator.validateInventory(setup, view.quantities, canonicalizer::variantGroup));

			Map<EquipmentSlot, UpgradeSuggestion> bySlot = new EnumMap<>(EquipmentSlot.class);
			for (UpgradeSuggestion suggestion : upgradeFinder.find(setup, ownedGear, template))
			{
				bySlot.putIfAbsent(suggestion.getSlot(), suggestion);
				view.names.put(suggestion.getReplacement().getItemId(), suggestion.getReplacement().getName());
			}

			view.upgrades.put(setup.getId(), bySlot);
		}

		return view;
	}

	private Map<EquipmentSlot, GearItem> wornGear()
	{
		return wornGear(statEngine.resolveOwnedGear(bankModel));
	}

	private static Map<EquipmentSlot, GearItem> wornGear(List<GearItem> ownedGear)
	{
		Map<EquipmentSlot, GearItem> worn = new EnumMap<>(EquipmentSlot.class);

		for (GearItem item : ownedGear)
		{
			if (!item.getLocations().contains(Storage.EQUIPMENT))
			{
				continue;
			}

			EquipmentSlot slot = EquipmentSlot.fromSlotIndex(item.getStats().getSlot());
			if (slot != null)
			{
				worn.put(slot, item);
			}
		}

		return worn;
	}

	private void render(SetupsView view)
	{
		list.removeAll();

		// Rendered here rather than in the fixed controls: the controls are built once, so a plugin
		// toggled after GearForge started would never have been noticed.
		if (bankFilterService.isBankTagLayoutsEnabled())
		{
			list.add(Cards.warning("Turn off the Bank Tag Layouts plugin. It overrides GearForge's "
				+ "bank arrangement, so your filtered bank won't be laid out as an equipment doll."));
			list.add(Cards.gap(8));
		}

		if (setupStore.isEmpty())
		{
			list.add(Cards.muted("No setups yet. Save what you're wearing, or build one on the BiS tab "
				+ "and save it from there."));
			finish();
			return;
		}

		for (Setup setup : new ArrayList<>(setupStore.all()))
		{
			list.add(setupCard(setup, view));
			list.add(Cards.gap(6));
		}

		finish();
	}

	private JPanel setupCard(Setup setup, SetupsView view)
	{
		Map<EquipmentSlot, SetupValidator.Status> statuses =
			SetupValidator.validate(setup, view.quantities, canonicalizer::variantGroup);

		Map<Integer, SetupValidator.Status> inventoryStatuses = view.inventoryStatuses
			.getOrDefault(setup.getId(), Collections.emptyMap());

		// Both halves have to be counted: the total includes inventory, so counting only equipment
		// reported a healthy setup as "6 of 20 — missing".
		int satisfied = SetupValidator.satisfiedCount(statuses)
			+ SetupValidator.countSatisfied(inventoryStatuses.values());

		boolean active = bankFilterService.isShowing(setup);
		boolean open = expanded.contains(setup.getId());

		Map<EquipmentSlot, UpgradeSuggestion> upgrades =
			view.upgrades.getOrDefault(setup.getId(), new EnumMap<>(EquipmentSlot.class));

		JPanel inner = Cards.card();
		inner.add(Cards.title(setup.getName()));
		inner.add(Cards.gap(4));

		// Only mention what is actually missing. A running tally like "6 of 20" reads as an alarm even
		// when nothing is wrong.
		int missing = setup.size() - satisfied;
		if (missing <= 0)
		{
			inner.add(Cards.muted("Everything's in your bank"));
		}
		else
		{
			JLabel shortfall = new JLabel(Cards.wrappedText("Missing " + missing + ": "
				+ describeMissing(setup, statuses, inventoryStatuses, view)));
			shortfall.setFont(FontManager.getRunescapeSmallFont());
			shortfall.setForeground(ColorScheme.BRAND_ORANGE);
			shortfall.setAlignmentX(Component.LEFT_ALIGNMENT);
			inner.add(shortfall);
		}

		if (!upgrades.isEmpty() && !open)
		{
			inner.add(Cards.gap(4));
			JLabel hint = new JLabel(Cards.wrappedText(upgrades.size()
				+ (upgrades.size() == 1 ? " upgrade" : " upgrades") + " available — open to apply"));
			hint.setFont(FontManager.getRunescapeSmallFont());
			hint.setForeground(ColorScheme.BRAND_ORANGE);
			hint.setAlignmentX(Component.LEFT_ALIGNMENT);
			inner.add(hint);
		}

		if (open)
		{
			inner.add(Cards.gap(8));
			inner.add(Cards.sectionLabel("Slots"));

			// Every slot, including empty ones — an empty slot is something you may want to fill.
			for (EquipmentSlot slot : EquipmentSlot.values())
			{
				inner.add(slotRow(setup, slot, setup.getEquipment().get(slot),
					upgrades.get(slot), view.worn.get(slot), view));
				inner.add(Cards.gap(2));
			}

			inner.add(Cards.gap(8));
			inner.add(Cards.sectionLabel("Inventory (" + setup.inventoryCount() + ")"));
			inner.add(Cards.gap(2));
			inner.add(inventoryGrid(setup, view));

			inner.add(Cards.gap(6));

			JButton updateAll = Cards.button("Update to what I'm wearing");
			updateAll.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
			updateAll.setToolTipText("Replace this setup's gear and inventory with what you have now");
			updateAll.addActionListener(event -> updateFromWorn(setup));
			inner.add(updateAll);

			inner.add(Cards.gap(3));

			JButton updateInventory = Cards.button("Update inventory only");
			updateInventory.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
			updateInventory.setToolTipText("Replace just the inventory with what you're carrying");
			updateInventory.addActionListener(event -> updateInventoryFromCarried(setup));
			inner.add(updateInventory);

			inner.add(Cards.gap(3));

			JButton share = Cards.button("Copy share code");
			share.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
			share.setToolTipText("Copy a code someone else can paste to rebuild this setup");
			share.addActionListener(event -> copyShareCode(setup));
			inner.add(share);
		}

		inner.add(Cards.gap(6));
		inner.add(buttons(setup, active, open));

		JPanel card = Cards.accentCard(active ? ColorScheme.BRAND_ORANGE : ColorScheme.DARK_GRAY_COLOR);
		card.add(inner, BorderLayout.CENTER);
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	/**
	 * One slot: what the setup asks for, plus the two ways to change it — accept the upgrade found in
	 * your bank, or take whatever you have on right now.
	 */
	private JPanel slotRow(
		Setup setup,
		EquipmentSlot slot,
		@Nullable ItemRequirement requirement,
		@Nullable UpgradeSuggestion upgrade,
		@Nullable GearItem worn,
		SetupsView view)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(3, 4, 3, 4));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(28, 28));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		if (requirement != null)
		{
			itemManager.getImage(requirement.getItemId()).addTo(icon);
		}
		row.add(icon, BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(row.getBackground());
		// An item name is as long as it is; the row must not grow past the panel to fit it.
		Cards.fitToPanel(text);

		String itemName = requirement == null
			? "(empty)"
			: view.names.getOrDefault(requirement.getItemId(), "Item " + requirement.getItemId());

		JLabel name = new JLabel(itemName);
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		name.setAlignmentX(Component.LEFT_ALIGNMENT);
		text.add(name);

		JLabel detail = new JLabel(upgrade == null
			? slot.getDisplayName()
			: String.format("%s · +%.1f%%", slot.getDisplayName(), upgrade.getGain() * 100.0));
		detail.setFont(FontManager.getRunescapeSmallFont());
		detail.setForeground(upgrade == null ? ColorScheme.MEDIUM_GRAY_COLOR : ColorScheme.BRAND_ORANGE);
		detail.setAlignmentX(Component.LEFT_ALIGNMENT);
		text.add(detail);

		row.add(text, BorderLayout.CENTER);
		row.add(slotButtons(setup, slot, upgrade, worn), BorderLayout.EAST);
		return Cards.fitRow(row);
	}

	private JPanel slotButtons(
		Setup setup, EquipmentSlot slot, @Nullable UpgradeSuggestion upgrade, @Nullable GearItem worn)
	{
		JPanel buttons = new JPanel(new GridLayout(1, 0, 2, 0));
		buttons.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		if (upgrade != null)
		{
			JButton apply = Cards.button("▲");
			apply.setToolTipText("Use " + upgrade.getReplacement().getName()
				+ String.format(" instead (+%.1f%% DPS)", upgrade.getGain() * 100.0));
			apply.addActionListener(event ->
			{
				setup.put(slot, upgrade.getReplacement().getItemId());
				setupStore.persist();
				rebuild();
			});
			buttons.add(apply);
		}

		if (worn != null)
		{
			JButton takeWorn = Cards.button("⤓");
			takeWorn.setToolTipText("Set this slot to what you're wearing: " + worn.getName());
			takeWorn.addActionListener(event ->
			{
				setup.put(slot, worn.getItemId());
				setupStore.persist();
				rebuild();
			});
			buttons.add(takeWorn);
		}

		return buttons;
	}

	/**
	 * The inventory as a 4x7 grid of icons, mirroring the in-game layout so it reads at a glance
	 * rather than as 28 rows of text.
	 */
	private JPanel inventoryGrid(Setup setup, SetupsView view)
	{
		JPanel grid = new JPanel(new GridLayout(INVENTORY_ROWS, INVENTORY_COLUMNS, 1, 1));
		grid.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		grid.setBorder(BorderFactory.createEmptyBorder(2, 2, 2, 2));
		grid.setAlignmentX(Component.LEFT_ALIGNMENT);

		List<ItemRequirement> inventory = setup.getInventory();
		Map<Integer, SetupValidator.Status> statuses = view.inventoryStatuses
			.getOrDefault(setup.getId(), new LinkedHashMap<>());

		for (int slot = 0; slot < INVENTORY_ROWS * INVENTORY_COLUMNS; slot++)
		{
			ItemRequirement requirement = slot < inventory.size() ? inventory.get(slot) : null;

			JLabel cell = new JLabel();
			cell.setHorizontalAlignment(SwingConstants.CENTER);
			cell.setPreferredSize(new Dimension(26, 26));
			cell.setOpaque(true);
			cell.setBackground(ColorScheme.DARK_GRAY_COLOR);

			if (requirement != null)
			{
				itemManager.getImage(requirement.getItemId()).addTo(cell);

				String name = view.names.getOrDefault(requirement.getItemId(),
					"Item " + requirement.getItemId());

				SetupValidator.Status status = statuses.get(slot);
				cell.setToolTipText(status == SetupValidator.Status.MISSING
					? name + " — missing"
					: name);

				if (status == SetupValidator.Status.MISSING)
				{
					cell.setBorder(BorderFactory.createLineBorder(ColorScheme.PROGRESS_ERROR_COLOR));
				}
			}

			grid.add(cell);
		}

		grid.setMaximumSize(new Dimension(Integer.MAX_VALUE, grid.getPreferredSize().height));
		return grid;
	}

	private void updateInventoryFromCarried(Setup setup)
	{
		clientThread.invoke(() ->
		{
			int[] carried = bankModel.getInventoryOrder();

			SwingUtilities.invokeLater(() ->
			{
				setup.setInventoryFrom(carried);
				setupStore.persist();
				rebuild();
			});
		});
	}

	private void updateFromWorn(Setup setup)
	{
		clientThread.invoke(() ->
		{
			Map<EquipmentSlot, GearItem> worn = wornGear();
			int[] carried = bankModel.getInventoryOrder();

			SwingUtilities.invokeLater(() ->
			{
				if (worn.isEmpty())
				{
					JOptionPane.showMessageDialog(this,
						"Couldn't read your worn equipment. Log in and make sure you're wearing something, "
							+ "then try again.",
						"GearForge", JOptionPane.INFORMATION_MESSAGE);
					return;
				}

				setup.getEquipment().clear();
				worn.forEach((slot, item) -> setup.put(slot, item.getItemId()));
				setup.setInventoryFrom(carried);
				setupStore.persist();
				rebuild();
			});
		});
	}

	private JPanel buttons(Setup setup, boolean active, boolean open)
	{
		JPanel row = new JPanel(new GridLayout(1, 3, 3, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));

		JButton edit = Cards.button(open ? "Close" : "Edit");
		edit.setToolTipText("Show each slot, with upgrades you can apply");
		edit.addActionListener(event ->
		{
			if (!expanded.remove(setup.getId()))
			{
				expanded.add(setup.getId());
			}

			rebuild();
		});
		row.add(edit);

		JButton activate = Cards.button(active ? "Clear" : "Show");
		activate.setToolTipText(active
			? "Stop filtering the bank"
			: "Filter your bank to just this setup's items");
		activate.addActionListener(event ->
		{
			if (active)
			{
				setupStore.deactivate();
				bankFilterService.clearFilter();
			}
			else
			{
				setupStore.activate(setup);
				bankFilterService.applySetup(setup);
			}

			rebuild();
		});
		row.add(activate);

		JButton delete = Cards.button("Delete");
		delete.addActionListener(event ->
		{
			int choice = JOptionPane.showConfirmDialog(this,
				"Delete \"" + setup.getName() + "\"?", "GearForge", JOptionPane.YES_NO_OPTION);

			if (choice == JOptionPane.YES_OPTION)
			{
				setupStore.remove(setup.getId());
				expanded.remove(setup.getId());
				rebuild();
			}
		});
		row.add(delete);

		return row;
	}

	/**
	 * Names what is missing across both gear and inventory. Inventory items are named rather than
	 * numbered, because "slot 14" means nothing to anyone.
	 */
	private static String describeMissing(
		Setup setup,
		Map<EquipmentSlot, SetupValidator.Status> equipment,
		Map<Integer, SetupValidator.Status> inventory,
		SetupsView view)
	{
		List<String> missing = new ArrayList<>();

		for (Map.Entry<EquipmentSlot, SetupValidator.Status> entry : equipment.entrySet())
		{
			if (entry.getValue() == SetupValidator.Status.MISSING)
			{
				missing.add(entry.getKey().getDisplayName().toLowerCase());
			}
		}

		for (Map.Entry<Integer, SetupValidator.Status> entry : inventory.entrySet())
		{
			if (entry.getValue() != SetupValidator.Status.MISSING)
			{
				continue;
			}

			ItemRequirement requirement = setup.getInventory().get(entry.getKey());
			String name = view.names.get(requirement.getItemId());

			// The same item in several slots only needs saying once.
			if (name != null && !missing.contains(name))
			{
				missing.add(name);
			}
		}

		return String.join(", ", missing);
	}

	private static String describeLastUsed(Setup setup)
	{
		if (setup.getLastUsedMillis() <= 0)
		{
			return "";
		}

		long days = TimeUnit.MILLISECONDS.toDays(System.currentTimeMillis() - setup.getLastUsedMillis());
		if (days < 1)
		{
			return " · used today";
		}

		return " · used " + days + (days == 1 ? " day ago" : " days ago");
	}

	private void finish()
	{
		list.revalidate();
		list.repaint();
	}

	/**
	 * A snapshot of everything the panel renders from, so the client thread is touched once per rebuild.
	 */
	private static final class SetupsView
	{
		private final Map<Integer, Integer> quantities = new HashMap<>();
		private final Map<Integer, String> names = new HashMap<>();
		private final Map<EquipmentSlot, GearItem> worn = new EnumMap<>(EquipmentSlot.class);
		private final Map<String, Map<EquipmentSlot, UpgradeSuggestion>> upgrades = new HashMap<>();
		private final Map<String, Map<Integer, SetupValidator.Status>> inventoryStatuses = new HashMap<>();
	}
}

package com.gearforge.ui;

import com.gearforge.GearForgeConfig;
import com.gearforge.data.BankModel;
import com.gearforge.data.EquipmentSlot;
import com.gearforge.data.GearItem;
import com.gearforge.data.GearStat;
import com.gearforge.data.ItemCanonicalizer;
import com.gearforge.data.ItemStatEngine;
import com.gearforge.data.SlotRanker;
import com.gearforge.data.Storage;
import java.awt.BorderLayout;
import java.awt.Component;
import java.util.Collections;
import java.util.List;
import java.util.StringJoiner;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.SwingUtilities;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Pick a slot and a bonus, see everything you own for it, best first.
 */
@Singleton
class SlotsTab extends JPanel
{
	/**
	 * Long lists are slow to build in Swing and nobody scrolls past the top few anyway.
	 */
	private static final int MAX_ROWS = 100;

	private final ClientThread clientThread;
	private final BankModel bankModel;
	private final ItemStatEngine statEngine;
	private final ItemCanonicalizer canonicalizer;
	private final ItemManager itemManager;
	private final GearForgeConfig config;

	private final JComboBox<EquipmentSlot> slotPicker = Cards.comboBox(EquipmentSlot.values());
	private final JComboBox<GearStat> statPicker = Cards.comboBox(GearStat.values());
	private final JPanel results = new JPanel();
	private final JLabel status = new JLabel();

	@Inject
	private SlotsTab(
		ClientThread clientThread,
		BankModel bankModel,
		ItemStatEngine statEngine,
		ItemCanonicalizer canonicalizer,
		ItemManager itemManager,
		GearForgeConfig config)
	{
		this.clientThread = clientThread;
		this.bankModel = bankModel;
		this.statEngine = statEngine;
		this.canonicalizer = canonicalizer;
		this.itemManager = itemManager;
		this.config = config;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		add(buildPickers(), BorderLayout.NORTH);

		results.setLayout(new BoxLayout(results, BoxLayout.Y_AXIS));
		results.setBackground(ColorScheme.DARK_GRAY_COLOR);

		// NORTH inside a plain panel stops BoxLayout rows stretching to fill the viewport.
		JPanel resultsHolder = new JPanel(new BorderLayout());
		resultsHolder.setBackground(ColorScheme.DARK_GRAY_COLOR);
		resultsHolder.add(results, BorderLayout.NORTH);

		JScrollPane scroll = new JScrollPane(
			resultsHolder,
			JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED,
			JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(scroll, BorderLayout.CENTER);

		slotPicker.setSelectedItem(EquipmentSlot.WEAPON);
		statPicker.setSelectedItem(GearStat.SLASH_ATTACK);
		slotPicker.addActionListener(e -> rebuild());
		statPicker.addActionListener(e -> rebuild());
	}

	private JPanel buildPickers()
	{
		JPanel pickers = new JPanel();
		pickers.setLayout(new BoxLayout(pickers, BoxLayout.Y_AXIS));
		pickers.setBackground(ColorScheme.DARK_GRAY_COLOR);
		pickers.setBorder(BorderFactory.createEmptyBorder(0, 0, 10, 0));

		pickers.add(Cards.field("Gear slot", slotPicker));
		pickers.add(Cards.gap(8));
		pickers.add(Cards.field("Rank by", statPicker));
		pickers.add(Cards.gap(8));

		status.setFont(FontManager.getRunescapeSmallFont());
		status.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		status.setAlignmentX(Component.LEFT_ALIGNMENT);
		pickers.add(status);

		return pickers;
	}

	/**
	 * Recomputes the ranking. Safe to call from either thread; the read happens on the client thread
	 * because item names come from the item cache, and the render happens on the EDT.
	 */
	void rebuild()
	{
		// Callers include the client thread (container events), so hop to the EDT before touching
		// any Swing state.
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::rebuild);
			return;
		}

		if (!bankModel.hasBankData())
		{
			showMessage("Open your bank once to get started.");
			return;
		}

		EquipmentSlot slot = (EquipmentSlot) slotPicker.getSelectedItem();
		GearStat stat = (GearStat) statPicker.getSelectedItem();
		if (slot == null || stat == null)
		{
			return;
		}

		boolean groupVariants = config.groupVariants();
		boolean hideZeroBonus = config.hideZeroBonus();

		clientThread.invoke(() ->
		{
			List<GearItem> owned = statEngine.resolveOwnedGear(bankModel);
			List<GearItem> ranked = SlotRanker.rank(
				owned, slot, stat, groupVariants, hideZeroBonus, canonicalizer::variantGroup);

			SlotView view = new SlotView(
				ranked,
				owned.isEmpty(),
				wornValue(owned, slot, stat),
				ranked.isEmpty()
					? SlotRanker.suggestStats(SlotRanker.positiveCounts(owned, slot), stat, 2)
					: Collections.emptyList());

			SwingUtilities.invokeLater(() -> render(view, slot, stat));
		});
	}

	/**
	 * The value of this stat on whatever is currently equipped in the slot, or null if the slot is
	 * empty. This is what every row is compared against.
	 */
	@Nullable
	private static Double wornValue(List<GearItem> owned, EquipmentSlot slot, GearStat stat)
	{
		for (GearItem item : owned)
		{
			if (item.getStats().getSlot() == slot.getSlotIndex()
				&& item.getLocations().contains(Storage.EQUIPMENT))
			{
				return item.statValue(stat);
			}
		}

		return null;
	}

	private void render(SlotView view, EquipmentSlot slot, GearStat stat)
	{
		results.removeAll();

		if (view.nothingResolved)
		{
			// Distinguish "stats have not downloaded yet" from "you own nothing for this slot" —
			// RuneLite fetches its equipment stat table after startup.
			showMessage("No equippable items found yet. Item stats may still be loading.");
			return;
		}

		if (view.ranked.isEmpty())
		{
			showMessage(describeEmptyResult(slot, stat, view.suggestions));
			return;
		}

		int shown = Math.min(view.ranked.size(), MAX_ROWS);
		for (int i = 0; i < shown; i++)
		{
			results.add(new ItemRow(view.ranked.get(i), stat, itemManager, view.wornValue));
			results.add(Box.createVerticalStrut(2));
		}

		List<GearItem> ranked = view.ranked;

		status.setText(shown < ranked.size()
			? "Top " + shown + " of " + ranked.size() + " items"
			: ranked.size() + (ranked.size() == 1 ? " item" : " items"));

		results.revalidate();
		results.repaint();
	}

	private void showMessage(String message)
	{
		results.removeAll();
		status.setText("");

		results.add(Cards.muted(message));

		results.revalidate();
		results.repaint();
	}

	/**
	 * An empty ranking is usually the wrong question rather than an empty bank — arrows carry ranged
	 * strength, not ranged attack, for instance. Point at what this slot actually has.
	 */
	private static String describeEmptyResult(EquipmentSlot slot, GearStat stat, List<GearStat> suggestions)
	{
		String message = "Nothing you own gives " + stat.getDisplayName().toLowerCase()
			+ " in the " + slot.getDisplayName().toLowerCase() + " slot.";

		if (suggestions.isEmpty())
		{
			return message;
		}

		StringJoiner joiner = new StringJoiner(" or ");
		for (GearStat suggestion : suggestions)
		{
			joiner.add(suggestion.getDisplayName().toLowerCase());
		}

		return message + " Try " + joiner + ".";
	}

	/**
	 * Everything one rebuild produced, so it can cross the thread boundary in one piece.
	 */
	private static final class SlotView
	{
		private final List<GearItem> ranked;
		private final boolean nothingResolved;
		@Nullable
		private final Double wornValue;
		private final List<GearStat> suggestions;

		private SlotView(List<GearItem> ranked, boolean nothingResolved, @Nullable Double wornValue,
			List<GearStat> suggestions)
		{
			this.ranked = ranked;
			this.nothingResolved = nothingResolved;
			this.wornValue = wornValue;
			this.suggestions = suggestions;
		}
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentStats;
import com.gearforge.dps.BoltEffect;
import com.gearforge.dps.DamageDistribution;
import com.gearforge.dps.MonsterAttribute;
import com.gearforge.dps.Target;
import java.util.EnumSet;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Enchanted bolts were the largest single gap in the gear model, and the one a damage multiplier
 * cannot paper over: a ruby bolt does not make your hits bigger, it replaces six percent of them with
 * a fifth of the target's health.
 */
public class BoltEffectTest
{
	private static final double TOLERANCE = 1e-9;

	/** A shot that always lands for exactly 10, so the effect is the only thing moving the average. */
	private static final DamageDistribution SHOT = DamageDistribution.certain(10);

	@Test
	public void bothTheOrdinaryAndDragonBoltsAreRecognised()
	{
		assertEquals(BoltEffect.RUBY,
			BoltEffect.forItem(ItemID.XBOWS_CROSSBOW_BOLTS_ADAMANTITE_TIPPED_RUBY_ENCHANTED));
		assertEquals(BoltEffect.RUBY, BoltEffect.forItem(ItemID.DRAGON_BOLTS_ENCHANTED_RUBY));
		assertEquals(BoltEffect.ONYX, BoltEffect.forItem(ItemID.DRAGON_BOLTS_ENCHANTED_ONYX));

		assertNull("An ordinary bolt has no effect", BoltEffect.forItem(ItemID.ABYSSAL_WHIP));
	}

	/**
	 * Ruby bolts deal a fifth of the target's health six percent of the time, so their worth rises with
	 * the size of what you are shooting. That is the whole reason they are used at bosses.
	 */
	@Test
	public void rubyBoltsScaleWithTheTargetsHealth()
	{
		double small = mean(BoltEffect.RUBY, 99, 40, plain(), 100);
		double large = mean(BoltEffect.RUBY, 99, 40, plain(), 1000);

		assertTrue("A bigger target should make rubies worth more", large > small);

		// 6% of a fifth of 500 health, plus the 94% of shots that were unaffected.
		assertEquals(0.94 * 10 + 0.06 * 100, mean(BoltEffect.RUBY, 99, 40, plain(), 500), TOLERANCE);
	}

	@Test
	public void rubyDamageIsCapped()
	{
		// A fifth of 5000 is 1000, but the effect stops at 100.
		assertEquals(0.94 * 10 + 0.06 * 100, mean(BoltEffect.RUBY, 99, 40, plain(), 5000), TOLERANCE);
	}

	@Test
	public void opalBoltsAddAFlatBonusFromTheRangedLevel()
	{
		// 99 / 10 truncates to 9, landing 5% of the time on top of the shot.
		assertEquals(0.95 * 10 + 0.05 * 19, mean(BoltEffect.OPAL, 99, 40, plain(), 500), TOLERANCE);
	}

	@Test
	public void dragonstoneBoltsDoNothingToSomethingAlreadyMadeOfFire()
	{
		double versusPlain = mean(BoltEffect.DRAGONSTONE, 99, 40, plain(), 500);
		double versusDragon = mean(BoltEffect.DRAGONSTONE, 99, 40, withAttribute(MonsterAttribute.DRAGON), 500);

		assertTrue(versusPlain > 10);
		assertEquals("Dragonfire cannot burn a dragon", 10, versusDragon, TOLERANCE);
	}

	@Test
	public void onyxBoltsDoNothingToTheUndead()
	{
		double versusPlain = mean(BoltEffect.ONYX, 99, 40, plain(), 500);
		double versusUndead = mean(BoltEffect.ONYX, 99, 40, withAttribute(MonsterAttribute.UNDEAD), 500);

		assertTrue(versusPlain > 10);
		assertEquals("There is no life in the undead to leech", 10, versusUndead, TOLERANCE);
	}

	@Test
	public void pearlBoltsHitFierySomethingHarder()
	{
		double versusPlain = mean(BoltEffect.PEARL, 99, 40, plain(), 500);
		double versusFiery = mean(BoltEffect.PEARL, 99, 40, withAttribute(MonsterAttribute.FIERY), 500);

		assertTrue("Pearls are stronger against something fiery", versusFiery > versusPlain);
	}

	/**
	 * A zaryte crossbow strengthens every effect, which is most of what makes it worth its price.
	 */
	@Test
	public void aZaryteCrossbowStrengthensTheEffect()
	{
		double ordinary = mean(BoltEffect.RUBY, 99, 40, plain(), 500, false);
		double zaryte = mean(BoltEffect.RUBY, 99, 40, plain(), 500, true);

		assertTrue(zaryte > ordinary);
	}

	@Test
	public void everyBoltEffectIsReachableFromAnItemId()
	{
		for (BoltEffect bolt : BoltEffect.values())
		{
			assertNotNull(bolt + " has no item mapping", bolt.toString());
			assertTrue(bolt.getProcChance() > 0 && bolt.getProcChance() < 1);
		}
	}

	private static double mean(
		BoltEffect bolt, int rangedLevel, int maxHit, Target target, int hitpoints)
	{
		return mean(bolt, rangedLevel, maxHit, target, hitpoints, false);
	}

	private static double mean(
		BoltEffect bolt, int rangedLevel, int maxHit, Target target, int hitpoints, boolean zaryte)
	{
		return bolt.apply(SHOT, rangedLevel, maxHit, target, hitpoints, zaryte).mean();
	}

	private static Target plain()
	{
		return Target.builder()
			.name("Plain")
			.defenceLevel(100)
			.defensiveBonuses(EquipmentStats.builder().build())
			.build();
	}

	private static Target withAttribute(MonsterAttribute attribute)
	{
		return Target.builder()
			.name("Special")
			.defenceLevel(100)
			.defensiveBonuses(EquipmentStats.builder().build())
			.attributes(EnumSet.of(attribute))
			.build();
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentStats;
import com.gearforge.data.ItemCategories;
import com.gearforge.data.Monster;
import com.gearforge.data.MonsterRepository;
import com.gearforge.data.Reachability;
import com.gearforge.dps.CombatStyle;
import com.gearforge.dps.SetEffectRegistry;
import com.gearforge.dps.SetEffects;
import com.gearforge.dps.Target;
import com.google.gson.Gson;
import com.gearforge.data.GearItem;
import com.gearforge.data.Storage;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Two gaps that between them produced a visibly wrong answer at Zulrah: a melee setup recommended for
 * something melee cannot reach, and a bow of faerdhinen losing to rune knives because the armour that
 * makes the bow worth using was not modelled.
 */
public class CrystalArmourTest
{
	private static final double EXACT = 1e-9;

	private final SetEffectRegistry registry = new SetEffectRegistry();

	@Test
	public void theFullSetIsWorthThirtyPercentAccuracyAndFifteenDamage()
	{
		SetEffects effects = apply(ItemID.BOW_OF_FAERDHINEN,
			ItemID.CRYSTAL_HELMET, ItemID.CRYSTAL_CHESTPLATE, ItemID.CRYSTAL_PLATELEGS);

		assertEquals(1.30, effects.getAccuracyMultiplier(), EXACT);
		assertEquals(1.15, effects.getDamageMultiplier(), EXACT);
	}

	@Test
	public void piecesCountIndividually()
	{
		SetEffects bodyOnly = apply(ItemID.BOW_OF_FAERDHINEN, ItemID.CRYSTAL_CHESTPLATE);

		assertEquals(1.15, bodyOnly.getAccuracyMultiplier(), EXACT);
		assertEquals(1.075, bodyOnly.getDamageMultiplier(), EXACT);
	}

	/**
	 * The armour is dead weight without the bow, which is exactly why it must not be applied to a setup
	 * that happens to be wearing it with something else.
	 */
	@Test
	public void theArmourDoesNothingWithoutACrystalBow()
	{
		SetEffects effects = apply(ItemID.MAGIC_SHORTBOW,
			ItemID.CRYSTAL_HELMET, ItemID.CRYSTAL_CHESTPLATE, ItemID.CRYSTAL_PLATELEGS);

		assertEquals(1.0, effects.getAccuracyMultiplier(), EXACT);
		assertEquals(1.0, effects.getDamageMultiplier(), EXACT);
	}

	@Test
	public void chargeVariantsCountAsTheSameArmour()
	{
		SetEffects effects = apply(ItemID.BOW_OF_FAERDHINEN_INACTIVE,
			ItemID.CRYSTAL_HELMET_INACTIVE, ItemID.CRYSTAL_CHESTPLATE_INACTIVE,
			ItemID.CRYSTAL_PLATELEGS_INACTIVE);

		assertEquals(1.30, effects.getAccuracyMultiplier(), EXACT);
	}

	/**
	 * Zulrah is a reach problem, not a style problem. An ordinary weapon cannot get there; a halberd
	 * can, and people melee it that way. Banning melee outright deleted a correct answer.
	 */
	@Test
	public void zulrahNeedsAHalberdRatherThanNoMeleeAtAll()
	{
		Monster zulrah = named("Zulrah");

		assertTrue("Melee is possible at Zulrah with the right weapon",
			Reachability.meleeIsPossible(zulrah));
		assertTrue(Reachability.requiresReach(zulrah));

		assertFalse("A whip cannot reach Zulrah", Reachability.meleeCanReach(zulrah, false));
		assertTrue("A halberd can", Reachability.meleeCanReach(zulrah, true));
	}

	/**
	 * A kraken is in the water — no reach helps.
	 */
	@Test
	public void somethingUnreachableStaysUnreachableWhateverTheWeapon()
	{
		Monster kraken = new Monster();
		kraken.setName("Kraken");

		assertFalse(Reachability.meleeIsPossible(kraken));
		assertFalse(Reachability.meleeCanReach(kraken, true));
	}

	@Test
	public void anOrdinaryMonsterIsReachableByAnything()
	{
		Monster crab = new Monster();
		crab.setName("Ammonite Crab");

		assertTrue(Reachability.meleeIsPossible(crab));
		assertFalse(Reachability.requiresReach(crab));
		assertTrue(Reachability.meleeCanReach(crab, false));
	}

	/**
	 * The polearms are what makes the reach rule work, so the classification has to actually find them.
	 */
	@Test
	public void halberdsAreClassifiedAsHavingReach()
	{
		ItemCategories categories = new ItemCategories(new Gson());

		assertTrue(categories.hasReach(ItemID.DRAGON_HALBERD));
		assertTrue(categories.hasReach(ItemID.CRYSTAL_HALBERD));
		assertFalse(categories.hasReach(ItemID.ABYSSAL_WHIP));
	}

	private static Monster named(String name)
	{
		return new MonsterRepository(new Gson()).all().stream()
			.filter(monster -> monster.getName().equalsIgnoreCase(name))
			.findFirst()
			.orElseThrow(() -> new AssertionError(name + " missing from the monster data"));
	}

	private SetEffects apply(int... itemIds)
	{
		List<GearItem> equipped = new ArrayList<>();
		for (int id : itemIds)
		{
			equipped.add(new GearItem(id, "Item " + id, 1,
				EquipmentStats.builder().build(), EnumSet.of(Storage.BANK)));
		}

		return registry.evaluate(equipped, CombatStyle.RANGED, target(), false);
	}

	private static Target target()
	{
		return Target.builder()
			.name("Zulrah")
			.defenceLevel(300)
			.magicLevel(300)
			.defensiveBonuses(EquipmentStats.builder().build())
			.build();
	}
}

package com.gearforge;

import com.gearforge.dps.DamageDistribution;
import com.gearforge.dps.DpsEngine;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * The distribution has to agree with the closed-form average the engine already uses, or introducing
 * it would quietly move every DPS number in the plugin.
 */
public class DamageDistributionTest
{
	private static final double EXACT = 1e-9;

	private final DpsEngine engine = new DpsEngine();

	@Test
	public void aSingleRollMatchesTheClosedFormAverage()
	{
		for (int maxHit = 1; maxHit <= 60; maxHit++)
		{
			for (double hitChance = 0.05; hitChance < 1.0; hitChance += 0.05)
			{
				assertEquals("max hit " + maxHit + " at " + hitChance,
					engine.averageDamage(hitChance, maxHit),
					DamageDistribution.roll(hitChance, maxHit).mean(),
					EXACT);
			}
		}
	}

	@Test
	public void probabilitiesSumToOne()
	{
		DamageDistribution triple = DamageDistribution.roll(0.6, 40)
			.plus(DamageDistribution.roll(0.6, 20))
			.plus(DamageDistribution.roll(0.6, 10));

		// Every outcome is covered exactly once, which is the property convolution can silently break.
		double total = 0;
		for (int damage = 0; damage <= triple.maximum(); damage++)
		{
			total += triple.probabilityOf(damage);
		}

		assertEquals(1.0, total, EXACT);
	}

	@Test
	public void independentHitsAddTheirAverages()
	{
		DamageDistribution first = DamageDistribution.roll(0.75, 30);
		DamageDistribution second = DamageDistribution.roll(0.75, 15);

		assertEquals(first.mean() + second.mean(), first.plus(second).mean(), EXACT);
		assertEquals(45, first.plus(second).maximum());
	}

	@Test
	public void bothHitsMustMissForTheAttackToDoNothing()
	{
		DamageDistribution first = DamageDistribution.roll(0.5, 20);
		DamageDistribution second = DamageDistribution.roll(0.5, 20);

		// A three-swing weapon connects far more often than a one-swing weapon of the same accuracy;
		// that is most of why the scythe cannot be modelled as a single roll.
		assertEquals(0.25, first.plus(second).missChance(), EXACT);
	}

	@Test
	public void aGuaranteedHitNeverMisses()
	{
		DamageDistribution voidwaker = DamageDistribution.uniform(25, 75);

		assertEquals(0.0, voidwaker.missChance(), EXACT);
		assertEquals(50.0, voidwaker.mean(), EXACT);
		assertEquals(75, voidwaker.maximum());
	}

	@Test
	public void weightedOutcomesMixInProportion()
	{
		DamageDistribution big = DamageDistribution.certain(100);
		DamageDistribution small = DamageDistribution.certain(0);

		assertEquals(30.0, big.or(0.3, small).mean(), EXACT);
	}

	@Test
	public void aZeroMaxHitCannotDealDamage()
	{
		assertEquals(0.0, DamageDistribution.roll(1.0, 0).mean(), EXACT);
		assertTrue(DamageDistribution.roll(1.0, 0).missChance() > 0.99);
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentStats;
import com.gearforge.dps.AttackStyle;
import com.gearforge.dps.CombatContext;
import com.gearforge.dps.CombatPrayer;
import com.gearforge.dps.CombatStyle;
import com.gearforge.dps.DpsEngine;
import com.gearforge.dps.SetupScore;
import com.gearforge.dps.Target;
import com.gearforge.dps.VoidSet;
import java.util.Arrays;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Reference tests for the combat maths.
 * <p>
 * Two kinds of assertion here, kept distinct on purpose:
 * <ul>
 *   <li><b>External anchors</b> — max hits that are independently known and checkable in game
 *       (unarmed 11, whip 25, dragon scimitar 22 at 99 Strength). If the formula chain is wrong
 *       anywhere, these break.</li>
 *   <li><b>Conformance</b> — each step matches the wiki formula, with the arithmetic worked out in
 *       the comment so a future reader can re-derive it without trusting the implementation.</li>
 * </ul>
 * See {@code docs/combat-formulas.md} for sources.
 */
public class DpsEngineTest
{
	private static final double TOLERANCE = 1e-4;

	private final DpsEngine engine = new DpsEngine();

	private static final EquipmentStats WHIP = EquipmentStats.builder()
		.aslash(82).strength(82).speed(4).slot(3).build();

	private static final EquipmentStats DRAGON_SCIMITAR = EquipmentStats.builder()
		.astab(8).aslash(67).acrush(-2).strength(66).speed(4).slot(3).build();

	private static final EquipmentStats UNARMED = EquipmentStats.builder().speed(4).slot(3).build();

	// ---------------------------------------------------------------- external anchors

	@Test
	public void unarmedMaxHitAt99Strength()
	{
		// effStr = 99 + 3 (aggressive) + 8 = 110
		// max    = floor((110 * (0 + 64) + 320) / 640) = floor(7360 / 640) = 11
		assertEquals(11, melee(UNARMED, AttackStyle.AGGRESSIVE, CombatPrayer.NONE).getMaxHit());
	}

	@Test
	public void whipMaxHitAt99Strength()
	{
		// The whip has no aggressive style; lash is controlled, so +1 rather than +3.
		// effStr = 99 + 1 + 8 = 108
		// max    = floor((108 * (82 + 64) + 320) / 640) = floor(16088 / 640) = 25
		assertEquals(25, melee(WHIP, AttackStyle.CONTROLLED, CombatPrayer.NONE).getMaxHit());
	}

	@Test
	public void dragonScimitarMaxHitAt99Strength()
	{
		// effStr = 99 + 3 + 8 = 110
		// max    = floor((110 * (66 + 64) + 320) / 640) = floor(14620 / 640) = 22
		assertEquals(22, melee(DRAGON_SCIMITAR, AttackStyle.AGGRESSIVE, CombatPrayer.NONE).getMaxHit());
	}

	// ---------------------------------------------------------------- effective levels

	@Test
	public void prayerAppliesToTheLevelBeforeStyleAndPlusEight()
	{
		// This is the spec's error and the Maximum-melee-hit page's error, pinned.
		// Correct:   floor(99 * 1.23) = 121, then +3 +8 = 132
		// Incorrect: (99 + 3 + 8) * 1.23 = floor(135.3) = 135
		CombatContext context = meleeContext(WHIP, AttackStyle.AGGRESSIVE, CombatPrayer.PIETY);
		assertEquals(132, engine.effectiveStrengthLevel(context));
	}

	@Test
	public void styleBonusIsAdditiveNotMultiplicative()
	{
		CombatContext aggressive = meleeContext(WHIP, AttackStyle.AGGRESSIVE, CombatPrayer.NONE);
		CombatContext defensive = meleeContext(WHIP, AttackStyle.DEFENSIVE, CombatPrayer.NONE);

		// Exactly 3 apart, not 3x apart.
		assertEquals(3, engine.effectiveStrengthLevel(aggressive) - engine.effectiveStrengthLevel(defensive));
	}

	@Test
	public void meleeVoidMultipliesAfterTheStyleAddAndPlusEight()
	{
		// floor((99 + 3 + 8) * 1.1) = floor(121.0) = 121
		CombatContext context = CombatContext.builder()
			.strengthLevel(99).attackLevel(99)
			.style(CombatStyle.SLASH)
			.attackStyle(AttackStyle.AGGRESSIVE)
			.voidSet(VoidSet.MELEE)
			.equipment(WHIP)
			.weaponSpeedTicks(4)
			.build();

		assertEquals(121, engine.effectiveStrengthLevel(context));
	}

	@Test
	public void rigourBoostsRangedStrengthMoreThanRangedAccuracy()
	{
		// Rigour is 1.20 on ranged attack but 1.23 on ranged strength — collapsing them is a classic
		// source of wrong numbers.
		CombatContext context = CombatContext.builder()
			.rangedLevel(99)
			.style(CombatStyle.RANGED)
			.attackStyle(AttackStyle.ACCURATE)
			.prayer(CombatPrayer.RIGOUR)
			.equipment(EquipmentStats.builder().arange(100).rangedStrength(50).speed(5).build())
			.weaponSpeedTicks(5)
			.build();

		assertEquals(129, engine.effectiveAttackLevel(context));    // floor(99*1.20)=118, +3+8
		assertEquals(132, engine.effectiveStrengthLevel(context));  // floor(99*1.23)=121, +3+8
	}

	@Test
	public void eliteRangedVoidOnlyImprovesStrength()
	{
		CombatContext context = CombatContext.builder()
			.rangedLevel(99)
			.style(CombatStyle.RANGED)
			.attackStyle(AttackStyle.ACCURATE)
			.voidSet(VoidSet.ELITE_RANGED)
			.equipment(EquipmentStats.builder().arange(100).rangedStrength(50).speed(5).build())
			.weaponSpeedTicks(5)
			.build();

		assertEquals(121, engine.effectiveAttackLevel(context));    // floor(110 * 1.10)
		assertEquals(123, engine.effectiveStrengthLevel(context));  // floor(110 * 1.125) = 123
	}

	@Test
	public void magicAppliesVoidBeforeTheStyleAddUnlikeMeleeAndRanged()
	{
		// floor(99 * 1.45 + 3 + 8) = floor(154.55) = 154
		// If void were applied last, as melee does, this would be floor(110 * 1.45) = 159.
		CombatContext context = magicContext(true, AttackStyle.ACCURATE, VoidSet.MAGIC);
		assertEquals(154, engine.effectiveAttackLevel(context));
	}

	@Test
	public void spellbookCastsGetNoStyleBonus()
	{
		// Only powered staves get the style add.
		CombatContext staff = magicContext(true, AttackStyle.ACCURATE, VoidSet.NONE);
		CombatContext spell = magicContext(false, AttackStyle.ACCURATE, VoidSet.NONE);

		assertEquals(110, engine.effectiveAttackLevel(staff));  // 99 + 3 + 8
		assertEquals(107, engine.effectiveAttackLevel(spell));  // 99 + 0 + 8
	}

	// ---------------------------------------------------------------- rolls and chance

	@Test
	public void magicDefenceRollUsesTheTargetsMagicLevelNotItsDefenceLevel()
	{
		Target target = Target.builder()
			.name("Test")
			.defenceLevel(50)
			.magicLevel(200)
			.defensiveBonuses(EquipmentStats.builder().dmagic(100).drange(999).build())
			.build();

		CombatContext context = CombatContext.builder()
			.magicLevel(99)
			.style(CombatStyle.MAGIC)
			.equipment(EquipmentStats.builder().amagic(100).build())
			.target(target)
			.weaponSpeedTicks(5)
			.baseSpellDamage(30)
			.build();

		// (200 + 9) * (100 + 64) = 34276. Using defence level would give (50+9)*164 = 9676.
		assertEquals(34276, engine.defenceRoll(context));
	}

	@Test
	public void hitChanceUsesTheHigherBranchWhenAttackExceedsDefence()
	{
		// 1 - (10000 + 2) / (2 * (20000 + 1)) = 1 - 10002/40002
		assertEquals(1.0 - 10002.0 / 40002.0, engine.hitChance(20000, 10000), TOLERANCE);
	}

	@Test
	public void hitChanceUsesTheLowerBranchWhenDefenceMeetsOrExceedsAttack()
	{
		// 5000 / (2 * (10000 + 1))
		assertEquals(5000.0 / 20002.0, engine.hitChance(5000, 10000), TOLERANCE);
		// Equal rolls take the else branch too.
		assertEquals(100.0 / 202.0, engine.hitChance(100, 100), TOLERANCE);
	}

	// ---------------------------------------------------------------- damage and speed

	@Test
	public void averageDamageIncludesTheZeroBecomesOneCorrection()
	{
		// maxHit/2 + 1/(maxHit+1) = 12.5 + 1/26
		assertEquals(12.5 + 1.0 / 26.0, engine.averageDamage(1.0, 25), TOLERANCE);
	}

	@Test
	public void averageDamageIsZeroWhenNothingCanBeHit()
	{
		assertEquals(0.0, engine.averageDamage(1.0, 0), TOLERANCE);
	}

	@Test
	public void rapidIsOneTickFasterAndOtherStylesAreNot()
	{
		assertEquals(4, engine.attackSpeedTicks(rangedContext(AttackStyle.RAPID)));
		assertEquals(5, engine.attackSpeedTicks(rangedContext(AttackStyle.ACCURATE)));
		assertEquals(5, engine.attackSpeedTicks(rangedContext(AttackStyle.LONGRANGE)));
	}

	@Test
	public void magicMaxHitAppliesMagicDamagePercent()
	{
		// Ice barrage base 30, with +15% magic damage: floor(30 * 1.15) = floor(34.5) = 34
		CombatContext context = CombatContext.builder()
			.magicLevel(99)
			.style(CombatStyle.MAGIC)
			.equipment(EquipmentStats.builder().amagic(100).magicDamage(15f).build())
			.baseSpellDamage(30)
			.weaponSpeedTicks(5)
			.build();

		assertEquals(34, engine.score(context).getMaxHit());
	}

	// ---------------------------------------------------------------- end to end

	@Test
	public void whipAgainstADummyProducesTheExpectedDpsChain()
	{
		SetupScore score = melee(WHIP, AttackStyle.CONTROLLED, CombatPrayer.NONE);

		// effAtk = 99 + 1 + 8 = 108; atkRoll = 108 * (82 + 64) = 15768
		assertEquals(15768, score.getAttackRoll());
		// dummy: (0 + 9) * (0 + 64) = 576
		assertEquals(576, score.getDefenceRoll());

		double expectedHitChance = 1.0 - 578.0 / (2.0 * 15769.0);
		assertEquals(expectedHitChance, score.getHitChance(), TOLERANCE);

		double expectedDps = expectedHitChance * (12.5 + 1.0 / 26.0) / (4 * 0.6);
		assertEquals(expectedDps, score.getDps(), TOLERANCE);
	}

	@Test
	public void higherDefenceTargetsLowerDpsWithoutChangingMaxHit()
	{
		SetupScore vsDummy = melee(WHIP, AttackStyle.CONTROLLED, CombatPrayer.NONE);

		Target armoured = Target.builder()
			.name("Armoured")
			.defenceLevel(200)
			.defensiveBonuses(EquipmentStats.builder().dslash(300).build())
			.build();

		SetupScore vsArmoured = engine.score(CombatContext.builder()
			.attackLevel(99).strengthLevel(99)
			.style(CombatStyle.SLASH)
			.attackStyle(AttackStyle.CONTROLLED)
			.equipment(WHIP)
			.weaponSpeedTicks(4)
			.target(armoured)
			.build());

		assertEquals(vsDummy.getMaxHit(), vsArmoured.getMaxHit());
		assertTrue(vsArmoured.getDps() < vsDummy.getDps());
		assertTrue(vsArmoured.getHitChance() > 0.0);
	}

	@Test
	public void equipmentStatsSumAddsBonusesAndTakesTheWeaponSpeed()
	{
		EquipmentStats helm = EquipmentStats.builder().aslash(0).dslash(30).strength(0).slot(0).build();
		EquipmentStats total = EquipmentStats.sum(Arrays.asList(WHIP, helm));

		assertEquals(82, total.getAslash());
		assertEquals(82, total.getStrength());
		assertEquals(30, total.getDslash());
		assertEquals(4, total.getSpeed());
	}

	// ---------------------------------------------------------------- helpers

	private SetupScore melee(EquipmentStats weapon, AttackStyle style, CombatPrayer prayer)
	{
		return engine.score(meleeContext(weapon, style, prayer));
	}

	private static CombatContext meleeContext(EquipmentStats weapon, AttackStyle style, CombatPrayer prayer)
	{
		return CombatContext.builder()
			.attackLevel(99)
			.strengthLevel(99)
			.style(CombatStyle.SLASH)
			.attackStyle(style)
			.prayer(prayer)
			.equipment(weapon)
			.weaponSpeedTicks(weapon.getSpeed())
			.build();
	}

	private static CombatContext magicContext(boolean poweredStaff, AttackStyle style, VoidSet voidSet)
	{
		return CombatContext.builder()
			.magicLevel(99)
			.style(CombatStyle.MAGIC)
			.attackStyle(style)
			.voidSet(voidSet)
			.poweredStaff(poweredStaff)
			.equipment(EquipmentStats.builder().amagic(100).build())
			.baseSpellDamage(30)
			.weaponSpeedTicks(4)
			.build();
	}

	private static CombatContext rangedContext(AttackStyle style)
	{
		return CombatContext.builder()
			.rangedLevel(99)
			.style(CombatStyle.RANGED)
			.attackStyle(style)
			.equipment(EquipmentStats.builder().arange(100).rangedStrength(50).speed(5).build())
			.weaponSpeedTicks(5)
			.build();
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.data.EquipmentStats;
import com.gearforge.data.GearItem;
import com.gearforge.data.ItemCategories;
import com.gearforge.data.Storage;
import com.google.gson.Gson;
import com.gearforge.dps.CombatContext;
import com.gearforge.dps.CombatStyle;
import com.gearforge.dps.DpsEngine;
import com.gearforge.dps.SetEffectRegistry;
import com.gearforge.dps.Target;
import com.gearforge.optimizer.Constraints;
import com.gearforge.optimizer.DpsOptimizer;
import com.gearforge.optimizer.ScoredSetup;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class DpsOptimizerTest
{
	private final DpsOptimizer optimizer =
		new DpsOptimizer(new DpsEngine(), new SetEffectRegistry(), new ItemCategories(new Gson()));

	private static CombatContext melee()
	{
		return CombatContext.builder()
			.attackLevel(99)
			.strengthLevel(99)
			.style(CombatStyle.SLASH)
			.equipment(EquipmentStats.builder().build())
			.target(Target.dummy())
			.weaponSpeedTicks(4)
			.build();
	}

	@Test
	public void picksTheHigherDpsWeapon()
	{
		List<GearItem> owned = Arrays.asList(
			weapon(1, "Bronze sword", 5, 5, 4, false),
			weapon(2, "Abyssal whip", 82, 82, 4, false));

		List<ScoredSetup> results = optimizer.best(owned, melee(), false, 3);

		assertFalse(results.isEmpty());
		assertEquals("Abyssal whip", results.get(0).getSetup().get(EquipmentSlot.WEAPON).getName());
	}

	@Test
	public void neverPairsATwoHanderWithAShield()
	{
		List<GearItem> owned = Arrays.asList(
			weapon(1, "Big two-hander", 120, 120, 5, true),
			weapon(2, "Small one-hander", 10, 10, 4, false),
			armour(3, "Strong shield", EquipmentSlot.SHIELD, 40, 20));

		for (ScoredSetup result : optimizer.best(owned, melee(), false, 3))
		{
			assertTrue(Constraints.isValid(result.getSetup()));
		}
	}

	@Test
	public void findsVoidEvenThoughVoidPiecesHaveWeakRawStats()
	{
		// This is the reason the candidate pool includes set effect items regardless of their stats.
		// Void's own bonuses are nil, so a pure top-N-by-stat filter would prune the whole set and
		// the 1.1x multiplier would never be found.
		List<GearItem> owned = new ArrayList<>(SetEffectRegistryTest.fullVoidMelee());
		owned.add(weapon(1, "Abyssal whip", 82, 82, 4, false));
		owned.add(armour(50, "Slightly better helm", EquipmentSlot.HEAD, 1, 1));
		owned.add(armour(51, "Slightly better body", EquipmentSlot.BODY, 1, 1));
		owned.add(armour(52, "Slightly better legs", EquipmentSlot.LEGS, 1, 1));
		owned.add(armour(53, "Slightly better gloves", EquipmentSlot.GLOVES, 1, 1));

		ScoredSetup best = optimizer.best(owned, melee(), false, 1).get(0);

		assertEquals(ItemID.GAME_PEST_MELEE_HELM, best.getSetup().get(EquipmentSlot.HEAD).getItemId());
		assertEquals(ItemID.PEST_VOID_KNIGHT_TOP, best.getSetup().get(EquipmentSlot.BODY).getItemId());
		assertTrue(best.getNotes().stream().anyMatch(note -> note.contains("Void melee")));
	}

	@Test
	public void resultsAreOrderedByDpsDescending()
	{
		List<GearItem> owned = Arrays.asList(
			weapon(1, "Bronze sword", 5, 5, 4, false),
			weapon(2, "Rune scimitar", 45, 44, 4, false),
			weapon(3, "Abyssal whip", 82, 82, 4, false));

		List<ScoredSetup> results = optimizer.best(owned, melee(), false, 3);

		assertEquals(3, results.size());
		for (int i = 1; i < results.size(); i++)
		{
			assertTrue(results.get(i - 1).getScore().getDps() >= results.get(i).getScore().getDps());
		}
	}

	@Test
	public void returnsNothingWhenNoWeaponIsOwned()
	{
		List<GearItem> noWeapons = Collections.singletonList(
			armour(1, "Rune platebody", EquipmentSlot.BODY, 0, 0));

		assertTrue(optimizer.best(noWeapons, melee(), false, 3).isEmpty());
	}

	@Test
	public void junkWeaponsWithNoAttackSpeedAreNeverChosen()
	{
		// A monkey greegree really is speed -1 in the item data, and 29 novelty items are speed 0.
		// Coerced to a one-tick weapon they score as overwhelmingly best-in-slot, which is exactly what
		// happened in the wild: "Ninja monkey greegree, +218% DPS".
		GearItem greegree = weapon(1, "Ninja monkey greegree", 0, 0, -1, false);
		GearItem crate = weapon(2, "Crate of fish", 0, 0, 0, false);
		GearItem whip = weapon(3, "Abyssal whip", 82, 82, 4, false);

		List<ScoredSetup> results = optimizer.best(Arrays.asList(greegree, crate, whip), melee(), false, 3);

		assertFalse(results.isEmpty());
		assertEquals("Abyssal whip", results.get(0).getSetup().get(EquipmentSlot.WEAPON).getName());

		for (ScoredSetup result : results)
		{
			String chosen = result.getSetup().get(EquipmentSlot.WEAPON).getName();
			assertTrue("junk weapon chosen: " + chosen, chosen.equals("Abyssal whip"));
		}
	}

	@Test
	public void aWeaponWithNoSpeedScoresZeroRatherThanInfiniteDps()
	{
		DpsEngine engine = new DpsEngine();
		double dps = engine.score(CombatContext.builder()
			.attackLevel(99).strengthLevel(99)
			.style(CombatStyle.SLASH)
			.equipment(EquipmentStats.builder().aslash(50).strength(50).slot(3).build())
			.weaponSpeedTicks(0)
			.target(Target.dummy())
			.build()).getDps();

		assertEquals(0.0, dps, 1e-9);
	}

	@Test
	public void emptyBankDegradesGracefully()
	{
		assertTrue(optimizer.best(Collections.emptyList(), melee(), false, 3).isEmpty());
	}

	@Test
	public void leavesASlotEmptyRatherThanWearingSomethingHarmful()
	{
		List<GearItem> owned = Arrays.asList(
			weapon(1, "Abyssal whip", 82, 82, 4, false),
			armour(2, "Cursed helm", EquipmentSlot.HEAD, -50, -50));

		ScoredSetup best = optimizer.best(owned, melee(), false, 1).get(0);
		assertNull(best.getSetup().get(EquipmentSlot.HEAD));
	}

	@Test
	public void slayerHelmOnlyChangesTheAnswerWhenOnTask()
	{
		List<GearItem> owned = Arrays.asList(
			weapon(1, "Abyssal whip", 82, 82, 4, false),
			SetEffectRegistryTest.piece(ItemID.SLAYER_HELM_I, EquipmentSlot.HEAD));

		double offTask = optimizer.best(owned, melee(), false, 1).get(0).getScore().getDps();
		double onTask = optimizer.best(owned, melee(), true, 1).get(0).getScore().getDps();

		assertTrue(onTask > offTask);
	}

	@Test
