	/**
	 * A bow of faerdhinen makes its own arrows. Every bow was taken to need something in the ammo
	 * slot, so a setup holding one scored zero and was discarded before it could be compared with
	 * anything — reported as the panel "ignoring bowfa if you have a blowpipe", though in truth the
	 * bow was never in the running at all.
	 */
	@Test
	public void aBowThatMakesItsOwnArrowsIsScoredWithoutThem()
	{
		GearItem bowfa = rangedStrengthWeapon(ItemID.BOW_OF_FAERDHINEN, "Bow of faerdhinen", 128, 106, 5);

		List<ScoredSetup> best = optimizer.best(
			Collections.singletonList(bowfa), rangedContext(), false, 1);

		assertFalse("A bow of faerdhinen needs no arrows", best.isEmpty());
		assertEquals(ItemID.BOW_OF_FAERDHINEN, best.get(0).getSetup().get(EquipmentSlot.WEAPON).getItemId());
		assertNull("and must not be given any", best.get(0).getSetup().get(EquipmentSlot.AMMO));
	}

	/**
	 * The comparison the report was really about. A blowpipe loaded with dragon darts is a fine
	 * weapon; it is not a bow of faerdhinen.
	 */
	@Test
	public void aBowOfFaerdhinenBeatsABlowpipe()
	{
		List<GearItem> owned = Arrays.asList(
			rangedStrengthWeapon(ItemID.BOW_OF_FAERDHINEN, "Bow of faerdhinen", 128, 106, 5),
			rangedStrengthWeapon(ItemID.TOXIC_BLOWPIPE, "Toxic blowpipe", 30, 20, 3),
			ammo(ItemID.DRAGON_DART, "Dragon dart", 20));

		ScoredSetup best = optimizer.best(owned, rangedContext(), false, 1).get(0);

		assertEquals(ItemID.BOW_OF_FAERDHINEN, best.getSetup().get(EquipmentSlot.WEAPON).getItemId());
	}

	/**
	 * The blowpipe still has to be scored with its darts, which is a separate fix that must not be
	 * undone by this one: on its own twenty ranged strength it loses to a rune knife.
	 */
	@Test
	public void aBlowpipeStillCountsItsDarts()
	{
		GearItem blowpipe = rangedStrengthWeapon(ItemID.TOXIC_BLOWPIPE, "Toxic blowpipe", 30, 20, 3);
		GearItem darts = ammo(ItemID.DRAGON_DART, "Dragon dart", 20);

		double withDarts = optimizer
			.best(Arrays.asList(blowpipe, darts), rangedContext(), false, 1).get(0).getScore().getDps();
		double without = optimizer
			.best(Collections.singletonList(blowpipe), rangedContext(), false, 1).get(0).getScore().getDps();

		assertTrue("Darts have to raise what the pipe hits for", withDarts > without);
	}

	private static CombatContext rangedContext()
	{
		return melee().toBuilder()
			.style(CombatStyle.RANGED)
			.rangedLevel(99)
			.target(Target.builder()
				.name("Boss")
				.defenceLevel(150)
				.defensiveBonuses(EquipmentStats.builder().drange(50).build())
				.build())
			.build();
	}

	private static GearItem rangedStrengthWeapon(
		int id, String name, int rangedAttack, int rangedStrength, int speed)
	{
		EquipmentStats stats = EquipmentStats.builder()
			.arange(rangedAttack)
			.rangedStrength(rangedStrength)
			.slot(EquipmentSlot.WEAPON.getSlotIndex())
			.twoHanded(true)
			.speed(speed)
			.build();

		return new GearItem(id, name, 1, stats, EnumSet.of(Storage.BANK));
	}

	private static GearItem rangedWeapon(int id, String name, int rangedAttack, int speed)
	{
		EquipmentStats stats = EquipmentStats.builder()
			.arange(rangedAttack)
			.slot(EquipmentSlot.WEAPON.getSlotIndex())
			.twoHanded(true)
			.speed(speed)
			.build();

		return new GearItem(id, name, 1, stats, EnumSet.of(Storage.BANK));
	}

	private static GearItem ammo(int id, String name, int rangedStrength)
	{
		EquipmentStats stats = EquipmentStats.builder()
			.rangedStrength(rangedStrength)
			.slot(EquipmentSlot.AMMO.getSlotIndex())
			.build();

		return new GearItem(id, name, 1000, stats, EnumSet.of(Storage.BANK));
	}

	private static GearItem weapon(int id, String name, int slash, int strength, int speed, boolean twoHanded)
	{
		EquipmentStats stats = EquipmentStats.builder()
			.aslash(slash)
			.strength(strength)
			.slot(EquipmentSlot.WEAPON.getSlotIndex())
			.twoHanded(twoHanded)
			.speed(speed)
			.build();

		return new GearItem(id, name, 1, stats, EnumSet.of(Storage.BANK));
	}

	/**
	 * The reported bug: for stab and crush, oathplate chest and the fighter torso are offensively
	 * identical — both +0 attack in the style, both +4 strength — so DPS ties exactly. The tie used to
	 * fall through to the item name, and "Fighter torso" wins the alphabet. Defence decides it now.
	 */
	@Test
	public void aDpsTieGoesToTheBetterDefensivePiece()
	{
		List<GearItem> owned = Arrays.asList(
			weapon(1, "Abyssal whip", 82, 82, 4, false),
			// Real numbers: the torso is +0 attack everywhere, the chest is +16 slash and nothing else.
			// Under a crush context neither contributes accuracy, and both give +4 strength.
			defensiveBody(2, "Fighter torso", 4, 61, 60, 62),
			defensiveBody(3, "Oathplate chest", 4, 105, 128, 100));

		CombatContext crush = melee().toBuilder().style(CombatStyle.CRUSH).build();
		List<ScoredSetup> results = optimizer.best(owned, crush, false, 3);

		assertFalse(results.isEmpty());
		assertEquals("Oathplate chest",
			results.get(0).getSetup().get(EquipmentSlot.BODY).getName());
	}

	private static GearItem defensiveBody(int id, String name, int strength, int dstab, int dslash, int dcrush)
	{
		EquipmentStats stats = EquipmentStats.builder()
			.strength(strength)
			.dstab(dstab)
			.dslash(dslash)
			.dcrush(dcrush)
			.slot(EquipmentSlot.BODY.getSlotIndex())
			.build();

		return new GearItem(id, name, 1, stats, EnumSet.of(Storage.BANK));
	}

	/**
	 * On task, the head slot is the slayer helmet's — a seventh more damage and a seventh more
	 * accuracy beats any raw stat a helm can carry. It was losing the slot because only one of its
	 * seventy-odd ids was recognised, so an ordinary or recoloured helmet counted for nothing.
	 */
	@Test
	public void aSlayerHelmetWinsTheHeadSlotOnTask()
	{
		List<GearItem> owned = Arrays.asList(
			weapon(1, "Abyssal whip", 82, 82, 4, false),
			armour(ItemID.TORVA_HELM, "Torva full helm", EquipmentSlot.HEAD, 12, 6),
			armour(ItemID.SLAYER_HELM_I_HYDRA, "Slayer helmet (i)", EquipmentSlot.HEAD, 0, 0));

		List<ScoredSetup> onTask = optimizer.best(owned, melee(), true, 1);
		List<ScoredSetup> offTask = optimizer.best(owned, melee(), false, 1);

		assertEquals("Slayer helmet (i)",
			onTask.get(0).getSetup().get(EquipmentSlot.HEAD).getName());
		assertEquals("Torva full helm",
			offTask.get(0).getSetup().get(EquipmentSlot.HEAD).getName());
	}

	/**
	 * The unimbued helmet carries the melee bonus in full, so it wins the slot the same way.
	 */
	@Test
	public void anUnimbuedSlayerHelmetWinsItToo()
	{
		List<GearItem> owned = Arrays.asList(
			weapon(1, "Abyssal whip", 82, 82, 4, false),
			armour(ItemID.TORVA_HELM, "Torva full helm", EquipmentSlot.HEAD, 12, 6),
			armour(ItemID.SLAYER_HELM, "Slayer helmet", EquipmentSlot.HEAD, 0, 0));

		assertEquals("Slayer helmet",
			optimizer.best(owned, melee(), true, 1).get(0).getSetup().get(EquipmentSlot.HEAD).getName());
	}

	private static GearItem armour(int id, String name, EquipmentSlot slot, int slash, int strength)
	{
		EquipmentStats stats = EquipmentStats.builder()
			.aslash(slash)
			.strength(strength)
			.slot(slot.getSlotIndex())
			.build();

		return new GearItem(id, name, 1, stats, EnumSet.of(Storage.BANK));
	}

	/**
	 * A thrown weapon is thrown from the hand. Bolts worn beside knives do nothing in game, but their
	 * ranged strength was being summed into the setup — which is how rune knives came to out-score a
	 * bow of faerdhinen in a real player's bank.
	 */
	@Test
	public void aThrownWeaponIsNotCreditedWithAmmoItCannotFire()
	{
		List<GearItem> owned = Arrays.asList(
			rangedWeapon(ItemID.RUNE_KNIFE, "Rune knife", 40, 3),
			ammo(ItemID.DRAGON_BOLTS_ENCHANTED_RUBY, "Ruby dragon bolts (e)", 122));

		CombatContext ranged = melee().toBuilder()
			.style(CombatStyle.RANGED)
			.rangedLevel(99)
			.build();

		List<ScoredSetup> results = optimizer.best(owned, ranged, false, 1);

		assertFalse(results.isEmpty());
		assertNull("Bolts cannot be worn to feed a thrown weapon",
			results.get(0).getSetup().get(EquipmentSlot.AMMO));
	}

	/**
	 * The rule has to stay narrow: a bow still needs its arrows.
	 */
	@Test
	public void aBowKeepsItsArrows()
	{
		List<GearItem> owned = Arrays.asList(
			rangedWeapon(ItemID.MAGIC_SHORTBOW, "Magic shortbow", 40, 4),
			ammo(ItemID.RUNE_ARROW, "Rune arrow", 49));

		CombatContext ranged = melee().toBuilder()
			.style(CombatStyle.RANGED)
			.rangedLevel(99)
			.build();

		List<ScoredSetup> results = optimizer.best(owned, ranged, false, 1);

		assertFalse(results.isEmpty());
		assertNotNull("A bow needs arrows to shoot",
			results.get(0).getSetup().get(EquipmentSlot.AMMO));
	}

	/**
	 * The reported bug: Dharok's platelegs recommended over oathplate legs. Dharok's are tankier and
	 * worse in every way that matters — no strength, no attack — but two strength rarely changes an
	 * integer max hit, so the DPS tied and defence alone handed it to the wrong pair.
	 */
	@Test
	public void aStrictlyBetterOffensivePieceBeatsATankierOne()
	{
		List<GearItem> owned = Arrays.asList(
			weapon(1, "Abyssal whip", 82, 82, 4, false),
			// Real numbers for the two legs.
			legs(2, "Dharok's platelegs", 0, 0, 85, 82, 83),
			legs(3, "Oathplate legs", 12, 2, 75, 100, 73));

		for (CombatStyle style : new CombatStyle[]{CombatStyle.SLASH, CombatStyle.STAB, CombatStyle.CRUSH})
		{
			CombatContext context = melee().toBuilder().style(style).build();
			List<ScoredSetup> results = optimizer.best(owned, context, false, 1);

			assertFalse(results.isEmpty());
			assertEquals("Wrong legs for " + style, "Oathplate legs",
				results.get(0).getSetup().get(EquipmentSlot.LEGS).getName());
		}
	}

	private static GearItem legs(
		int id, String name, int slash, int strength, int dstab, int dslash, int dcrush)
	{
		EquipmentStats stats = EquipmentStats.builder()
			.aslash(slash)
			.strength(strength)
			.dstab(dstab)
			.dslash(dslash)
			.dcrush(dcrush)
			.slot(EquipmentSlot.LEGS.getSlotIndex())
			.build();

		return new GearItem(id, name, 1, stats, EnumSet.of(Storage.BANK));
	}

	/**
	 * A whip's three attack options are all slash. Offering one for a crush setup is not a slightly
	 * wrong answer, it is an impossible one — and the optimizer produced exactly that, because it read
	 * the crush bonus off the item and never asked whether the weapon could swing that way.
	 */
	@Test
	public void aWhipIsNotOfferedForCrush()
	{
		List<GearItem> owned = Arrays.asList(
			weapon(ItemID.ABYSSAL_TENTACLE, "Abyssal tentacle", 90, 86, 4, false),
			weapon(ItemID.GRANITE_MAUL, "Granite maul", 81, 79, 7, false));

		CombatContext crush = melee().toBuilder().style(CombatStyle.CRUSH).build();
		List<ScoredSetup> results = optimizer.best(owned, crush, false, 1);

		assertFalse(results.isEmpty());
		assertEquals("A whip cannot crush", "Granite maul",
			results.get(0).getSetup().get(EquipmentSlot.WEAPON).getName());
	}

	/**
	 * A blowpipe fires the darts loaded into it. Both are weapon-slot items, so the two never met in
	 * the search and the pipe was scored on a fraction of its real strength.
	 */
	@Test
	public void aBlowpipeIsLoadedWithTheBestDart()
	{
		GearItem blowpipe = rangedWeapon(12926, "Toxic blowpipe", 30, 3);
		GearItem knife = rangedWeapon(ItemID.RUNE_KNIFE, "Rune knife", 30, 3);

		CombatContext ranged = melee().toBuilder().style(CombatStyle.RANGED).rangedLevel(99).build();

		// Without a dart in the bank the pipe is only its own strength, and the knife wins.
		List<ScoredSetup> withoutDarts = optimizer.best(
			Arrays.asList(blowpipe, knife), ranged, false, 1);
		assertEquals("Rune knife",
			withoutDarts.get(0).getSetup().get(EquipmentSlot.WEAPON).getName());

		// With dragon darts to load, the pipe should win.
		List<ScoredSetup> withDarts = optimizer.best(
			Arrays.asList(blowpipe, knife, dart(11230, "Dragon dart", 35)), ranged, false, 1);
		assertEquals("Toxic blowpipe",
			withDarts.get(0).getSetup().get(EquipmentSlot.WEAPON).getName());
	}

	private static GearItem dart(int id, String name, int rangedStrength)
	{
		EquipmentStats stats = EquipmentStats.builder()
			.rangedStrength(rangedStrength)
			.slot(EquipmentSlot.WEAPON.getSlotIndex())
			.speed(3)
			.build();

		return new GearItem(id, name, 1, stats, EnumSet.of(Storage.BANK));
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.data.EquipmentStats;
import com.gearforge.data.GearItem;
import com.gearforge.data.ItemCategories;
import com.gearforge.data.Storage;
import com.gearforge.dps.CombatContext;
import com.gearforge.dps.CombatStyle;
import com.gearforge.dps.DpsEngine;
import com.gearforge.dps.PoweredStaff;
import com.gearforge.dps.SetEffectRegistry;
import com.gearforge.dps.Spell;
import com.gearforge.dps.Target;
import com.gearforge.optimizer.DpsOptimizer;
import com.gearforge.optimizer.ScoredSetup;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.EnumSet;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Effects reaching the thing that scores them.
 * <p>
 * Several were modelled, tested in isolation, and then never applied, because the call that computes
 * DPS dropped the spell on the floor and because a scripted edit of mine quietly removed the powered
 * staff wiring. A unit test of an effect proves the arithmetic; it does not prove the effect is
 * plugged in. These check the plug.
 */
public class EffectsReachScoringTest
{
	private final DpsOptimizer optimizer =
		new DpsOptimizer(new DpsEngine(), new SetEffectRegistry(), new ItemCategories(new Gson()));

	/** Fires a second hit on bolt, blast and wave spells. */
	private static final int TWINFLAME_STAFF = 30634;

	/**
	 * The twinflame staff doubles bolt, blast and wave spells only — so while it is held, a Fire Wave
	 * beats the Fire Surge that would otherwise be chosen. Picking the spell before the weapon meant
	 * the staff could never be given a spell it was able to double, so its effect never applied.
	 */
	@Test
	public void theTwinflameStaffChangesWhichSpellIsWorthCasting()
	{
		// Against a fire-weak target a Fire Wave is worth 30 before the staff, and 42 with it doubled,
		// against Ice Barrage's flat 30. Weakness and the staff compound, which is where it matters.
		Target fireWeak = Target.builder()
			.name("Weak")
			.defenceLevel(100)
			.magicLevel(100)
			.defensiveBonuses(EquipmentStats.builder().build())
			.weaknessElement(Spell.Element.FIRE)
			.weaknessSeverity(50)
			.build();

		Spell chosen = Spell.bestForTwinflame(fireWeak, 99, true);

		assertTrue("A doubled spell should be chosen", chosen.firesTwice());
		assertEquals(Spell.FIRE_WAVE, chosen);
	}

	/**
	 * The staff does not change the answer everywhere, and must not pretend to. At 99 Magic against
	 * something with no weakness, a doubled Fire Wave is 28 and an Ice Barrage is 30.
	 */
	@Test
	public void theStaffDoesNotOverrideAStrongerSpell()
	{
		Target plain = Target.builder()
			.name("Plain")
			.defenceLevel(100)
			.magicLevel(100)
			.defensiveBonuses(EquipmentStats.builder().build())
			.build();

		assertEquals(Spell.ICE_BARRAGE, Spell.bestFor(plain, 99, true));
		assertEquals(Spell.ICE_BARRAGE, Spell.bestForTwinflame(plain, 99, true));
	}

	@Test
	public void onlyBoltBlastAndWaveAreDoubled()
	{
		assertTrue(Spell.FIRE_WAVE.firesTwice());
		assertTrue(Spell.FIRE_BLAST.firesTwice());
		assertTrue(Spell.FIRE_BOLT.firesTwice());

		assertFalse("A surge is not doubled", Spell.FIRE_SURGE.firesTwice());
		assertFalse("Nothing ancient is doubled", Spell.ICE_BARRAGE.firesTwice());
		assertFalse("A strike is not doubled", Spell.FIRE_STRIKE.firesTwice());
	}

	/**
	 * A staff held is a staff scored. This is the wiring that a scripted edit removed without failing
	 * a single test, because every powered staff test checked the formula rather than the plumbing.
	 */
	@Test
	public void aPoweredStaffIsScoredAsItsOwnWeapon()
	{
		GearItem trident = magicWeapon(ItemID.TOTS_CHARGED, "Trident of the seas");
		GearItem plainStaff = magicWeapon(ItemID.BATTLESTAFF, "Battlestaff");

		List<ScoredSetup> results = optimizer.best(
			Arrays.asList(trident, plainStaff), magicContext(), false, 1);

		assertFalse(results.isEmpty());

		// A trident attacks four times faster than a five-tick cast and hits for its own maximum, so
		// it must win. If the wiring is gone it is scored as an Ice Barrage cast and ties.
		assertEquals("Trident of the seas",
			results.get(0).getSetup().get(EquipmentSlot.WEAPON).getName());
		assertEquals(PoweredStaff.TRIDENT_OF_THE_SEAS, PoweredStaff.forItem(ItemID.TOTS_CHARGED));
	}

	/**
	 * Dragon javelins carry 150 ranged strength — more than any thrown weapon — so crediting them to a
	 * knife that cannot fire them dwarfed every honest setup.
	 */
	@Test
	public void aThrownWeaponIsNotGivenJavelins()
	{
		GearItem knife = new GearItem(ItemID.RUNE_KNIFE, "Rune knife", 1,
			EquipmentStats.builder()
				.arange(40).rangedStrength(24)
				.slot(EquipmentSlot.WEAPON.getSlotIndex()).speed(3).build(),
			EnumSet.of(Storage.BANK));

		GearItem javelin = new GearItem(19484, "Dragon javelin", 100,
			EquipmentStats.builder()
				.rangedStrength(150)
				.slot(EquipmentSlot.AMMO.getSlotIndex()).build(),
			EnumSet.of(Storage.BANK));

		CombatContext ranged = CombatContext.builder()
			.rangedLevel(99)
			.style(CombatStyle.RANGED)
			.equipment(EquipmentStats.builder().build())
			.target(Target.dummy())
			.weaponSpeedTicks(3)
			.build();

		List<ScoredSetup> results = optimizer.best(Arrays.asList(knife, javelin), ranged, false, 1);

		assertFalse(results.isEmpty());
		assertNull("A knife cannot fire a javelin",
			results.get(0).getSetup().get(EquipmentSlot.AMMO));
	}

	private static GearItem magicWeapon(int id, String name)
	{
		return new GearItem(id, name, 1,
			EquipmentStats.builder()
				.amagic(25)
				.slot(EquipmentSlot.WEAPON.getSlotIndex())
				.speed(4)
				.build(),
			EnumSet.of(Storage.BANK));
	}

	private static CombatContext magicContext()
	{
		return CombatContext.builder()
			.magicLevel(99)
			.style(CombatStyle.MAGIC)
			.equipment(EquipmentStats.builder().build())
			.target(Target.dummy())
			.baseSpellDamage(30)
			.weaponSpeedTicks(5)
			.build();
	}
}

