public class GreedyOptimizerTest
{
	private final GreedyOptimizer optimizer = new GreedyOptimizer();

	@Test
	public void picksTheBestItemInEachSlot()
	{
		List<GearItem> owned = Arrays.asList(
			defensive(1, "Iron full helm", EquipmentSlot.HEAD, 10),
			defensive(2, "Rune full helm", EquipmentSlot.HEAD, 30),
			defensive(3, "Rune platebody", EquipmentSlot.BODY, 70));

		OptimizerResult result = optimizer.best(owned, GearStat.STAB_DEFENCE);

		assertEquals("Rune full helm", result.getSetup().get(EquipmentSlot.HEAD).getName());
		assertEquals("Rune platebody", result.getSetup().get(EquipmentSlot.BODY).getName());
		assertEquals(100.0, result.getTotal(), 1e-9);
	}

	@Test
	public void takesTheTwoHanderWhenItBeatsAOneHanderPlusShield()
	{
		List<GearItem> owned = Arrays.asList(
			weapon(1, "Weak one-hander", 5, false),
			weapon(2, "Huge two-hander", 60, true),
			defensive(3, "Small shield", EquipmentSlot.SHIELD, 20));

		OptimizerResult result = optimizer.best(owned, GearStat.STAB_DEFENCE);

		// 60 beats 5 + 20.
		assertEquals("Huge two-hander", result.getSetup().get(EquipmentSlot.WEAPON).getName());
		assertNull(result.getSetup().get(EquipmentSlot.SHIELD));
		assertEquals(60.0, result.getTotal(), 1e-9);
		assertTrue(Constraints.isValid(result.getSetup()));
	}

	@Test
	public void keepsTheShieldWhenTheOneHandedPairWins()
	{
		List<GearItem> owned = Arrays.asList(
			weapon(1, "Decent one-hander", 25, false),
			weapon(2, "Modest two-hander", 30, true),
			defensive(3, "Big shield", EquipmentSlot.SHIELD, 50));

		OptimizerResult result = optimizer.best(owned, GearStat.STAB_DEFENCE);

		// 25 + 50 beats 30. A naive "best weapon first" pass would have taken the two-hander.
		assertEquals("Decent one-hander", result.getSetup().get(EquipmentSlot.WEAPON).getName());
		assertEquals("Big shield", result.getSetup().get(EquipmentSlot.SHIELD).getName());
		assertEquals(75.0, result.getTotal(), 1e-9);
		assertTrue(Constraints.isValid(result.getSetup()));
	}

	@Test
	public void explainsWhyTheShieldSlotWasKeptOrGivenUp()
	{
		OptimizerResult keptShield = optimizer.best(Arrays.asList(
			weapon(1, "Decent one-hander", 25, false),
			weapon(2, "Modest two-hander", 30, true),
			defensive(3, "Big shield", EquipmentSlot.SHIELD, 50)), GearStat.STAB_DEFENCE);

		assertFalse(keptShield.getReasons().isEmpty());
		assertTrue(keptShield.getReasons().get(0).contains("Big shield"));

		OptimizerResult tookTwoHander = optimizer.best(Arrays.asList(
			weapon(1, "Weak one-hander", 5, false),
			weapon(2, "Huge two-hander", 60, true),
			defensive(3, "Small shield", EquipmentSlot.SHIELD, 20)), GearStat.STAB_DEFENCE);

		assertFalse(tookTwoHander.getReasons().isEmpty());
		assertTrue(tookTwoHander.getReasons().get(0).contains("Huge two-hander"));
	}

	@Test
	public void leavesASlotEmptyRatherThanWearingANegativeItem()
	{
		List<GearItem> owned = Arrays.asList(
			defensive(1, "Cursed helm", EquipmentSlot.HEAD, -20),
			defensive(2, "Useless helm", EquipmentSlot.HEAD, 0),
			defensive(3, "Rune platebody", EquipmentSlot.BODY, 70));

		OptimizerResult result = optimizer.best(owned, GearStat.STAB_DEFENCE);

		assertNull(result.getSetup().get(EquipmentSlot.HEAD));
		assertEquals(70.0, result.getTotal(), 1e-9);
	}

	@Test
	public void neverProducesATwoHanderAndShieldTogether()
	{
		// A two-hander good enough to win, with a shield also present.
		List<GearItem> owned = Arrays.asList(
			weapon(1, "Huge two-hander", 100, true),
			defensive(2, "Big shield", EquipmentSlot.SHIELD, 50));

		OptimizerResult result = optimizer.best(owned, GearStat.STAB_DEFENCE);
		assertTrue(Constraints.isValid(result.getSetup()));
	}

	@Test
	public void sparseBankDegradesGracefullyInsteadOfFailing()
	{
		OptimizerResult empty = optimizer.best(Collections.emptyList(), GearStat.MAGIC_DEFENCE);
		assertTrue(empty.isEmpty());
		assertEquals(0.0, empty.getTotal(), 1e-9);

		OptimizerResult oneItem = optimizer.best(
			Collections.singletonList(defensive(1, "Leather boots", EquipmentSlot.BOOTS, 2)),
			GearStat.STAB_DEFENCE);
		assertEquals(1, oneItem.getSetup().size());

		// An item with no bonus in the requested stat is not worth a slot.
		OptimizerResult wrongStat = optimizer.best(
			Collections.singletonList(defensive(1, "Leather boots", EquipmentSlot.BOOTS, 2)),
			GearStat.MAGIC_DEFENCE);
		assertTrue(wrongStat.isEmpty());
	}

	@Test
	public void totalStatsMatchesTheChosenSetup()
	{
		List<GearItem> owned = Arrays.asList(
			defensive(1, "Rune full helm", EquipmentSlot.HEAD, 30),
			defensive(2, "Rune platebody", EquipmentSlot.BODY, 70));

		OptimizerResult result = optimizer.best(owned, GearStat.STAB_DEFENCE);
		assertEquals(100, result.totalStats().getDstab());
	}

	@Test
	public void resultIsDeterministicForTiedItems()
	{
		List<GearItem> owned = Arrays.asList(
			defensive(3, "Zebra helm", EquipmentSlot.HEAD, 30),
			defensive(1, "Apple helm", EquipmentSlot.HEAD, 30));

		String first = optimizer.best(owned, GearStat.STAB_DEFENCE).getSetup().get(EquipmentSlot.HEAD).getName();

		Collections.reverse(owned = new java.util.ArrayList<>(owned));
		String second = optimizer.best(owned, GearStat.STAB_DEFENCE).getSetup().get(EquipmentSlot.HEAD).getName();

		assertEquals(first, second);
		assertEquals("Apple helm", first);
	}

	private static GearItem defensive(int id, String name, EquipmentSlot slot, int stabDefence)
	{
		EquipmentStats stats = EquipmentStats.builder()
			.dstab(stabDefence)
			.slot(slot.getSlotIndex())
			.build();

		return new GearItem(id, name, 1, stats, EnumSet.of(Storage.BANK));
	}

	private static GearItem weapon(int id, String name, int stabDefence, boolean twoHanded)
	{
		EquipmentStats stats = EquipmentStats.builder()
			.dstab(stabDefence)
			.slot(EquipmentSlot.WEAPON.getSlotIndex())
			.twoHanded(twoHanded)
			.speed(4)
			.build();

		return new GearItem(id, name, 1, stats, EnumSet.of(Storage.BANK));
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.setups.InventorySetupsImporter;
import com.gearforge.setups.Setup;
import com.gearforge.setups.SetupSource;
import com.google.gson.Gson;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * The sample below is a real Inventory Setups record, taken verbatim from a live RuneLite config, so
 * the importer is tested against the format as it actually ships rather than an invented one.
 */
public class InventorySetupsImporterTest
{
	private final InventorySetupsImporter importer =
		new InventorySetupsImporter(null, new Gson());

	private static final String BIRDHOUSE = "{\"inv\":["
		+ "{\"id\":8792},{\"id\":8792},{\"id\":8792},{\"id\":6333},{\"id\":6333},{\"id\":6333},"
		+ "{\"id\":6333},{\"id\":6333},{\"id\":2347},{\"id\":8794},{\"id\":1755},"
		+ "{\"id\":557,\"q\":11312},{\"id\":556,\"q\":34523},{\"id\":563,\"q\":1962},"
		+ "null,null,null,null,null,null,null,null,null,null,null,null,null,null],"
		+ "\"eq\":[{\"id\":3751},null,{\"id\":1704},{\"id\":772},{\"id\":10551},{\"id\":33101},null,"
		+ "{\"id\":1079},null,{\"id\":11972},{\"id\":4131},null,{\"id\":2572},{\"id\":20232}],"
		+ "\"name\":\"Birdhouse\",\"hc\":\"#FFFF0000\",\"fb\":true}";

	@Test
	public void importsTheNameAndMarksItAsImported()
	{
		Setup setup = importer.parse(BIRDHOUSE);

		assertNotNull(setup);
		assertEquals("Birdhouse", setup.getName());
		assertEquals(SetupSource.IMPORTED, setup.getSource());
	}

	@Test
	public void equipmentArrayIsIndexedByEquipmentSlot()
	{
		Setup setup = importer.parse(BIRDHOUSE);
		assertNotNull(setup);

		// Index 0 is head, 3 is weapon, 13 is ammo — a mis-indexed import would silently put the
		// weapon on your head, so these are pinned explicitly.
		assertEquals(3751, setup.getEquipment().get(EquipmentSlot.HEAD).getItemId());
		assertEquals(1704, setup.getEquipment().get(EquipmentSlot.AMULET).getItemId());
		assertEquals(772, setup.getEquipment().get(EquipmentSlot.WEAPON).getItemId());
		assertEquals(10551, setup.getEquipment().get(EquipmentSlot.BODY).getItemId());
		assertEquals(1079, setup.getEquipment().get(EquipmentSlot.LEGS).getItemId());
		assertEquals(20232, setup.getEquipment().get(EquipmentSlot.AMMO).getItemId());

		// Null entries stay empty rather than shifting everything after them.
		assertNull(setup.getEquipment().get(EquipmentSlot.CAPE));
	}

	@Test
	public void inventoryKeepsOrderAndDuplicates()
	{
		Setup setup = importer.parse(BIRDHOUSE);
		assertNotNull(setup);

		assertEquals(14, setup.inventoryCount());
		assertEquals(8792, setup.getInventory().get(0).getItemId());
		assertEquals(8792, setup.getInventory().get(2).getItemId());
		assertEquals(6333, setup.getInventory().get(3).getItemId());
		assertEquals(563, setup.getInventory().get(13).getItemId());

		// Trailing nulls are trimmed, so the list stops after the last real item.
		assertEquals(14, setup.getInventory().size());
	}

	@Test
	public void countsEquipmentAndInventoryTogether()
	{
		Setup setup = importer.parse(BIRDHOUSE);
		assertNotNull(setup);

		// 10 equipped pieces plus 14 inventory items. The cape slot is empty in this record, and
		// indices 6, 8 and 11 are the cosmetic arms/hair/jaw slots that no real item occupies.
		assertEquals(10, setup.getEquipment().size());
		assertEquals(24, setup.size());
	}

	@Test
	public void malformedOrEmptyRecordsAreSkippedRatherThanCrashing()
	{
		assertNull(importer.parse("not json at all"));
		assertNull(importer.parse("{}"));
		assertNull(importer.parse("{\"name\":\"Empty\",\"inv\":[],\"eq\":[]}"));
	}

	@Test
	public void aSetupWithOnlyInventoryStillImports()
	{
		Setup setup = importer.parse(
			"{\"inv\":[{\"id\":385},null,{\"id\":385}],\"eq\":[],\"name\":\"Food\"}");

		assertNotNull(setup);
		assertEquals(2, setup.inventoryCount());
		assertEquals("Food", setup.getName());
	}
}

package com.gearforge;

import com.gearforge.data.ItemCategories;
import com.google.gson.Gson;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Guards the ammo pairing rules, including the two cases where the upstream category is misleading.
 */
public class ItemCategoriesTest
{
	private final ItemCategories categories = new ItemCategories(new Gson());

	@Test
	public void bowsTakeArrowsAndNotBolts()
	{
		assertTrue(categories.ammoFits(ItemID.MAGIC_SHORTBOW, ItemID.RUNE_ARROW));
		assertFalse(categories.ammoFits(ItemID.MAGIC_SHORTBOW, ItemID.XBOWS_CROSSBOW_BOLTS_RUNITE));
	}

	@Test
	public void crossbowsTakeBoltsAndNotArrows()
	{
		assertTrue(categories.ammoFits(ItemID.XBOWS_CROSSBOW_RUNITE, ItemID.XBOWS_CROSSBOW_BOLTS_RUNITE));
		assertFalse(categories.ammoFits(ItemID.XBOWS_CROSSBOW_RUNITE, ItemID.RUNE_ARROW));
	}

	@Test
	public void ballistasTakeJavelinsDespiteBeingCategorisedAsCrossbows()
	{
		// The upstream data calls a ballista a crossbow. A rule written off that field alone would
		// reject the only ammunition it can actually fire.
		assertEquals(ItemCategories.BALLISTA, categories.categoryOf(ItemID.HEAVY_BALLISTA));
		assertTrue(categories.ammoFits(ItemID.HEAVY_BALLISTA, ItemID.DRAGON_JAVELIN));
		assertFalse(categories.ammoFits(ItemID.HEAVY_BALLISTA, ItemID.XBOWS_CROSSBOW_BOLTS_RUNITE));
	}

	@Test
	public void weaponsThatNeedAmmoAreIdentified()
	{
		assertTrue(categories.requiresAmmo(ItemID.MAGIC_SHORTBOW));
		assertTrue(categories.requiresAmmo(ItemID.XBOWS_CROSSBOW_RUNITE));
		assertTrue(categories.requiresAmmo(ItemID.HEAVY_BALLISTA));

		// Melee weapons and thrown weapons draw nothing from the ammo slot.
		assertFalse(categories.requiresAmmo(ItemID.ABYSSAL_WHIP));
	}

	@Test
	public void unclassifiedWeaponsAcceptAnythingRatherThanBlockingValidSetups()
	{
		// A whip is unclassified; constraining its ammo slot would reject legitimate setups such as
		// wearing an assembler for its bonuses.
		assertTrue(categories.ammoFits(ItemID.ABYSSAL_WHIP, ItemID.RUNE_ARROW));
		assertTrue(categories.ammoFits(ItemID.ABYSSAL_WHIP, ItemID.XBOWS_CROSSBOW_BOLTS_RUNITE));
	}
}

package com.gearforge;

import com.gearforge.data.ItemRequirements;
import com.gearforge.data.PlayerLevels;
import com.google.gson.Gson;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Guards the generated requirements resource as well as the lookup logic — if the resource goes
 * missing or its shape changes, these fail rather than the plugin silently offering unusable gear.
 */
public class ItemRequirementsTest
{
	private final ItemRequirements requirements = new ItemRequirements(new Gson());

	private static PlayerLevels levels(int attack, int defence, int ranged)
	{
		return PlayerLevels.builder()
			.attack(attack).strength(attack).defence(defence).ranged(ranged).magic(1)
			.prayer(1).hitpoints(10).slayer(1)
			.build();
	}

	@Test
	public void theGeneratedResourceIsPresentAndPopulated()
	{
		// A representative spread rather than a single item, so a truncated resource is caught.
		assertTrue(requirements.isKnown(ItemID.ABYSSAL_WHIP));
		assertTrue(requirements.isKnown(ItemID.DRAGON_SCIMITAR));
	}

	@Test
	public void whipNeeds70Attack()
	{
		assertEquals(Integer.valueOf(70), requirements.requirementsFor(ItemID.ABYSSAL_WHIP).get("attack"));

		assertFalse(requirements.canEquip(ItemID.ABYSSAL_WHIP, levels(69, 99, 99)));
		assertTrue(requirements.canEquip(ItemID.ABYSSAL_WHIP, levels(70, 99, 99)));
	}

	@Test
	public void shortfallIsDescribedInGameTerms()
	{
		assertEquals("Needs 70 Attack", requirements.describeShortfall(ItemID.ABYSSAL_WHIP, levels(50, 99, 99)));
		assertNull(requirements.describeShortfall(ItemID.ABYSSAL_WHIP, levels(99, 99, 99)));
	}

	@Test
	public void unknownItemsAreTreatedAsEquippableRatherThanHidden()
	{
		// The source dataset is stale, so newer gear is absent. Hiding a player's best weapon because
		// of a data gap is worse than mentioning one they might not be able to wield.
		int unknown = 999999;

		assertFalse(requirements.isKnown(unknown));
		assertTrue(requirements.canEquip(unknown, levels(1, 1, 1)));
		assertTrue(requirements.requirementsFor(unknown).isEmpty());
	}

	/**
	 * The reported bug, and the reason the wiki is read at all: blood moon armour needs 75 Strength,
	 * osrsbox-db has never heard of it, and an account without the Strength was being told it was
	 * best in slot.
	 */
	@Test
	public void gearReleasedAfterTheOldDatasetIsStillEnforced()
	{
		PlayerLevels noStrength = PlayerLevels.builder()
			.attack(99).strength(70).defence(99).ranged(99).magic(99)
			.prayer(99).hitpoints(99).slayer(99)
			.build();

		for (int id : new int[]{ItemID.BLOOD_MOON_HELM, ItemID.BLOOD_MOON_CHESTPLATE,
			ItemID.BLOOD_MOON_TASSETS})
		{
			assertTrue("id " + id + " should have known requirements", requirements.isKnown(id));
			assertEquals(Integer.valueOf(75), requirements.requirementsFor(id).get("strength"));
			assertFalse("id " + id + " needs 75 Strength", requirements.canEquip(id, noStrength));
		}
	}

	@Test
	public void theRestOfTheModernBankIsCoveredToo()
	{
		assertEquals(Integer.valueOf(80), requirements.requirementsFor(ItemID.TORVA_HELM).get("defence"));
		assertEquals(Integer.valueOf(80), requirements.requirementsFor(ItemID.MASORI_BODY).get("ranged"));
		assertEquals(Integer.valueOf(85), requirements.requirementsFor(ItemID.TUMEKENS_SHADOW).get("magic"));
		assertEquals(Integer.valueOf(78), requirements.requirementsFor(ItemID.OATHPLATE_HELM).get("defence"));
		assertEquals(Integer.valueOf(75), requirements.requirementsFor(ItemID.VOIDWAKER).get("attack"));
		assertEquals(Integer.valueOf(82), requirements.requirementsFor(ItemID.OSMUMTENS_FANG).get("attack"));
	}

	/**
	 * Where the two sources disagree the wiki is the current one: osrsbox has the kodai wand at 75
	 * Magic and the bow of faerdhinen at 75 Ranged, and both are eighty.
	 */
	@Test
	public void aStaleRequirementDoesNotWinOverTheCurrentOne()
	{
		assertEquals(Integer.valueOf(80), requirements.requirementsFor(ItemID.KODAI_WAND).get("magic"));
		assertEquals(Integer.valueOf(80), requirements.requirementsFor(ItemID.BOW_OF_FAERDHINEN).get("ranged"));
	}

	/**
	 * An ornament kit does not lower a requirement. Recoloured and ornamented copies are left out of
	 * both sources, and falling back to the family is what keeps them from reading as unrestricted.
	 */
	@Test
	public void anOrnamentedCopyInheritsTheRequirementOfWhatItIs()
	{
		assertEquals(Integer.valueOf(60),
			requirements.requirementsFor(ItemID.DRAGON_CLAWS_ORNAMENT).get("attack"));
		assertEquals(Integer.valueOf(10),
			requirements.requirementsFor(ItemID.SLAYER_HELM_ARAXYTE).get("defence"));
	}

	/**
	 * Absent data and no requirement are not the same thing, and the panel was treating them alike —
	 * it warned that it could not check an amulet of glory, which anyone can wear. An item whose page
	 * says there is nothing to check is now recorded as such.
	 */
	@Test
	public void anItemWithNoRequirementsIsKnownToHaveNone()
	{
		assertTrue("An amulet of glory is a known quantity",
			requirements.isKnown(ItemID.AMULET_OF_GLORY));
		assertTrue(requirements.requirementsFor(ItemID.AMULET_OF_GLORY).isEmpty());
		assertNull(requirements.describeShortfall(ItemID.AMULET_OF_GLORY, levels(1, 1, 1)));
		assertTrue(requirements.canEquip(ItemID.AMULET_OF_GLORY, levels(1, 1, 1)));
	}

	@Test
	public void aLowLevelAccountIsBlockedFromHighTierGear()
	{
		PlayerLevels fresh = levels(1, 1, 1);

		assertFalse(requirements.canEquip(ItemID.ABYSSAL_WHIP, fresh));
		assertFalse(requirements.canEquip(ItemID.DRAGON_SCIMITAR, fresh));
	}
}

package com.gearforge;

import com.gearforge.data.Monster;
import com.gearforge.data.MonsterRepository;
import com.google.gson.Gson;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The target picker is a few thousand rows long, and the wiki data lists a row per NPC id, so the
 * same monster arrives many times over with nothing to tell the copies apart.
 */
public class MonsterRepositoryTest
{
	private final MonsterRepository repository = new MonsterRepository(new Gson());

	@Test
	public void noTwoEntriesShareADisplayName()
	{
		Set<String> seen = new HashSet<>();
		Set<String> duplicates = new HashSet<>();

		for (Monster monster : repository.all())
		{
			if (!seen.add(monster.displayName()))
			{
				duplicates.add(monster.displayName());
			}
		}

		assertEquals("Duplicate rows in the target picker: " + duplicates, 0, duplicates.size());
	}

	@Test
	public void formsAreOnlyShownWhenTheyDistinguishSomething()
	{
		for (Monster monster : repository.all())
		{
			if (monster.getVersion().isEmpty())
			{
				continue;
			}

			// A form survived, so there must be at least one sibling it is being told apart from.
			long siblings = repository.all().stream()
				.filter(other -> other.getName().equals(monster.getName()))
				.count();

			assertTrue(monster.displayName() + " keeps a form but has no sibling to differ from",
				siblings > 1);
		}
	}

	@Test
	public void theListIsStillUsefullyPopulated()
	{
		List<Monster> all = repository.all();

		assertFalse(all.isEmpty());
		assertFalse(repository.bosses().isEmpty());

		// Collapsing must not have eaten the things people actually search for.
		assertTrue(repository.search("Ammonite").stream()
			.anyMatch(monster -> monster.getName().equalsIgnoreCase("Ammonite Crab")));
		assertTrue(repository.search("Zulrah").size() > 1);
	}

	@Test
	public void entriesAreSortedSoScrollingIsPredictable()
	{
		List<Monster> all = repository.all();

		for (int i = 1; i < all.size(); i++)
		{
			assertTrue("Out of order at " + all.get(i).displayName(),
				all.get(i - 1).displayName().compareToIgnoreCase(all.get(i).displayName()) <= 0);
		}
	}

	/**
	 * The complaint that prompted this: twenty armoured zombies, differing only in which room they
	 * stand in. An ordinary monster gets one row, whatever the source data lists.
	 */
	@Test
	public void anOrdinaryMonsterGetsExactlyOneRow()
	{
		assertEquals(1, countNamed("Armoured zombie"));
		assertEquals(1, countNamed("Ankou"));
	}

	/**
	 * Bosses keep their forms, because a Zulrah colour really does defend differently and picking the
	 * wrong one gives you the wrong answer.
	 */
	@Test
	public void bossFormsSurvive()
	{
		assertTrue(countNamed("Zulrah") > 1);
	}

	@Test
	public void noOrdinaryMonsterNameAppearsTwice()
	{
		Set<String> seen = new HashSet<>();

		for (Monster monster : repository.all())
		{
			if (!monster.isBoss())
			{
				assertTrue("Two rows for " + monster.getName(), seen.add(monster.getName()));
			}
		}
	}

	private long countNamed(String name)
	{
		return repository.all().stream()
			.filter(monster -> monster.getName().equalsIgnoreCase(name))
			.count();
	}

	/**
	 * The Royal Titans are two NPCs called Branda and Eldric, so searching what the fight is called
	 * found nothing at all.
	 */
	@Test
	public void aFightCanBeFoundByItsOwnName()
	{
		assertTrue(repository.search("royal titans").size() >= 2);
		assertTrue(repository.search("dks").size() >= 3);
		assertTrue(repository.search("gauntlet").stream()
			.anyMatch(monster -> monster.getName().toLowerCase().contains("hunllef")));
	}

	/**
	 * Nobody looks up their best-in-slot for a level 13 zombie, and every one of those made the picker
	 * longer for everyone else. Bosses and slayer creatures stay at any level.
	 */
	@Test
	public void trashIsNotListedButSlayerCreaturesAre()
	{
		for (Monster monster : repository.all())
		{
			assertTrue(monster.getName() + " is level " + monster.getCombatLevel(),
				monster.isBoss() || monster.isSlayerMonster() || monster.getCombatLevel() >= 50);
		}

		// The two Jobo actually asked about.
		assertTrue(repository.search("undead druid").size() >= 1);
		assertTrue(repository.search("zulrah").size() >= 1);
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.data.EquipmentStats;
import com.gearforge.data.GearItem;
import com.gearforge.data.ItemCategories;
import com.gearforge.data.Storage;
import com.gearforge.dps.CombatContext;
import com.gearforge.dps.CombatStyle;
import com.gearforge.dps.DpsEngine;
import com.gearforge.dps.SetEffectRegistry;
import com.gearforge.dps.Target;
import com.gearforge.optimizer.DpsOptimizer;
import com.gearforge.optimizer.OptimizerBreadth;
import com.gearforge.optimizer.ScoredSetup;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Random;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * How much does the pre-filter cost in correctness?
 * <p>
 * The optimizer keeps only the best few items per slot by raw offensive stat before searching. That
 * is a guess at what might win, and a wrong guess is invisible: the item simply never enters the
 * search and the answer looks confident either way. This measures how often widening the filter
 * changes the recommendation, and what the extra breadth costs in time.
 */
public class OptimizerBreadthTest
{
	/** A bank with real depth in every slot, which is where a narrow filter can go wrong. */
	private static final int ITEMS_PER_SLOT = 40;

	/**
	 * The correctness contract: the shipped breadth must find what an exhaustive search finds. This is
	 * what was broken — at the old breadth of five it fell short on every bank below.
	 */
	@Test
	public void theShippedBreadthMatchesAnExhaustiveSearch()
	{
		for (int trial = 0; trial < 15; trial++)
		{
			List<GearItem> bank = randomBank(new Random(trial));

			double shipped = bestDps(bank, OptimizerBreadth.CANDIDATES_PER_SLOT);
			double exhaustive = bestDps(bank, ITEMS_PER_SLOT);

			assertEquals("Bank " + trial + ": the shipped breadth missed the best setup",
				exhaustive, shipped, 1e-6);
		}
	}

	/**
	 * The number that decides the shipped breadth: where does the answer stop improving, and what does
	 * each step cost? Printed rather than asserted, because it is a measurement.
	 */
	@Test
	public void reportWhereBreadthStopsMattering()
	{
		int[] breadths = {5, 10, 15, 20, 30, ITEMS_PER_SLOT};
		int trials = 15;

		// Breadth equal to the pool size searches everything, so it is the correct answer to measure
		// the cheaper ones against.
		for (int breadth : breadths)
		{
			int beaten = 0;
			double worst = 0;

			for (int trial = 0; trial < trials; trial++)
			{
				List<GearItem> bank = randomBank(new Random(trial));
				double got = bestDps(bank, breadth);
				double exhaustive = bestDps(bank, ITEMS_PER_SLOT);

				if (got < exhaustive - 1e-6)
				{
					beaten++;
					worst = Math.max(worst, (exhaustive - got) / exhaustive * 100);
				}
			}

			List<GearItem> bank = randomBank(new Random(1));
			for (int i = 0; i < 3; i++)
			{
				bestDps(bank, breadth);
			}
			long nanos = time(() -> bestDps(bank, breadth));

			System.out.printf("breadth %2d: short of exhaustive in %2d/%d banks, worst %.2f%% low, %.0fms%n",
				breadth, beaten, trials, worst, nanos / 1e6);
		}
	}

	/**
	 * The shipped breadth has to stay fast enough to run on every gear change. The panel debounces at
	 * 400ms and this runs off the client thread, so a budget well inside that is the requirement.
	 */
	@Test
	public void theShippedBreadthStaysWithinItsTimeBudget()
	{
		List<GearItem> bank = randomBank(new Random(7));

		// Warm up, so the measurement is not dominated by class loading and JIT.
		for (int i = 0; i < 5; i++)
		{
			bestDps(bank, OptimizerBreadth.CANDIDATES_PER_SLOT);
		}

		// Best of several rather than one sample. The question is whether the work can be done inside
		// the budget, and a single cold run on a busy machine answers a different question — this test
		// failed spuriously that way once already.
		long nanos = Long.MAX_VALUE;
		for (int i = 0; i < 5; i++)
		{
			nanos = Math.min(nanos, time(() -> bestDps(bank, OptimizerBreadth.CANDIDATES_PER_SLOT)));
		}

		double millis = nanos / 1e6;

		assertTrue("One optimise took " + millis + "ms, which is too slow to run on every gear change",
			millis < 250);
	}

	private static long time(Runnable work)
	{
		long start = System.nanoTime();
		work.run();
		return System.nanoTime() - start;
	}

	private static double bestDps(List<GearItem> bank, int candidatesPerSlot)
	{
		DpsOptimizer optimizer = OptimizerBreadth.withBreadth(
			new DpsEngine(), new SetEffectRegistry(), new ItemCategories(new Gson()), candidatesPerSlot);

		List<ScoredSetup> best = optimizer.best(bank, context(), false, 1);
		return best.isEmpty() ? 0 : best.get(0).getScore().getDps();
	}

	private static CombatContext context()
	{
		return CombatContext.builder()
			.attackLevel(99)
			.strengthLevel(99)
			.style(CombatStyle.SLASH)
			.equipment(EquipmentStats.builder().build())
			.target(Target.builder()
				.name("Benchmark")
				.defenceLevel(150)
				.defensiveBonuses(EquipmentStats.builder().dslash(100).dstab(100).dcrush(100).build())
				.build())
			.weaponSpeedTicks(4)
			.build();
	}

	/**
	 * Items with accuracy and strength traded off against each other, which is exactly the shape the
	 * pre-filter handles badly: something second best at both can beat something first at one.
	 */
	private static List<GearItem> randomBank(Random random)
	{
		List<GearItem> bank = new ArrayList<>();
		int id = 1;

		for (EquipmentSlot slot : EquipmentSlot.values())
		{
			for (int i = 0; i < ITEMS_PER_SLOT; i++)
			{
				int accuracy = random.nextInt(120);
				int strength = 110 - accuracy + random.nextInt(30);

				EquipmentStats.EquipmentStatsBuilder stats = EquipmentStats.builder()
					.aslash(accuracy)
					.astab(Math.max(0, accuracy - 10))
					.acrush(Math.max(0, accuracy - 20))
					.strength(Math.max(0, strength))
					.dslash(random.nextInt(200))
					.dstab(random.nextInt(200))
					.dcrush(random.nextInt(200))
					.slot(slot.getSlotIndex());

				if (slot == EquipmentSlot.WEAPON)
				{
					stats.speed(4 + random.nextInt(3));
				}

				bank.add(new GearItem(id++, slot + " " + i, 1, stats.build(), EnumSet.of(Storage.BANK)));
			}
		}

		return bank;
	}
}

package com.gearforge;

import com.gearforge.dps.SpecialAttack;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

/**
 * A bank holds a dagger(p++), never a plain dragon dagger. Checking ownership against the one
 * canonical id told those players they owned no special attack weapon at all — which is what the
 * empty "nothing you own is worth speccing with" line was actually reporting.
 */
public class OwnedSpecVariantTest
{
	@Test
	public void everyPoisonedDragonDaggerIsStillADragonDagger()
	{
		List<Integer> daggers = idsNamed("DRAGON_DAGGER");

		assertFalse("No dragon dagger ids found", daggers.isEmpty());

		for (int id : daggers)
		{
			assertEquals("id " + id + " should be recognised as the dragon dagger spec",
				SpecialAttack.DRAGON_DAGGER, SpecialAttack.forItem(id));
		}
	}

	@Test
	public void thePoisonedAbyssalDaggersAreRecognisedToo()
	{
		for (int id : idsNamed("ABYSSAL_DAGGER"))
		{
			assertEquals(SpecialAttack.ABYSSAL_DAGGER, SpecialAttack.forItem(id));
		}
	}

	private static List<Integer> idsNamed(String prefix)
	{
		List<Integer> ids = new ArrayList<>();

		for (Field field : ItemID.class.getFields())
		{
			if (!Modifier.isStatic(field.getModifiers()) || field.getType() != int.class
				|| !field.getName().startsWith(prefix))
			{
				continue;
			}

			try
			{
				ids.add(field.getInt(null));
			}
			catch (IllegalAccessException ignored)
			{
				// Not readable, so not something the plugin could see either.
			}
		}

		return ids;
	}
}

package com.gearforge;

import com.gearforge.data.PlayerLevels;
import com.gearforge.dps.Potion;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Boost values checked against the OSRS Wiki DPS calculator's own potion definitions.
 */
public class PotionTest
{
	private static final PlayerLevels MAXED = PlayerLevels.maxed();

	@Test
	public void superCombatBoostsMeleeOnly()
	{
		// floor(5 + 99 * 0.15) = 19
		assertEquals(19, Potion.SUPER_COMBAT.attackBoost(MAXED));
		assertEquals(19, Potion.SUPER_COMBAT.strengthBoost(MAXED));
		assertEquals(0, Potion.SUPER_COMBAT.rangedBoost(MAXED));
		assertEquals(0, Potion.SUPER_COMBAT.magicBoost(MAXED));
	}

	@Test
	public void rangingAndSuperRangingDiffer()
	{
		// floor(4 + 99 * 0.10) = 13, versus floor(5 + 99 * 0.15) = 19
		assertEquals(13, Potion.RANGING.rangedBoost(MAXED));
		assertEquals(19, Potion.SUPER_RANGING.rangedBoost(MAXED));
	}

	@Test
	public void overloadsBoostEverything()
	{
		// Overload floor(5 + 99 * 0.13) = 17; Overload (+) floor(6 + 99 * 0.16) = 21
		assertEquals(17, Potion.OVERLOAD.attackBoost(MAXED));
		assertEquals(17, Potion.OVERLOAD.rangedBoost(MAXED));
		assertEquals(17, Potion.OVERLOAD.magicBoost(MAXED));

		assertEquals(21, Potion.OVERLOAD_PLUS.attackBoost(MAXED));
		assertEquals(21, Potion.OVERLOAD_PLUS.magicBoost(MAXED));

		// floor(11 + 99 * 0.16) = 26
		assertEquals(26, Potion.SMELLING_SALTS.strengthBoost(MAXED));
	}

	@Test
	public void brewsTradeMeleeAwayForMagic()
	{
		// The drain is the point: a brew is not a free upgrade. floor(-2 - 99 * 0.10) = -12, and it
		// floors away from zero rather than truncating toward it.
		assertEquals(-12, Potion.FORGOTTEN_BREW.attackBoost(MAXED));
		assertEquals(-12, Potion.ANCIENT_BREW.strengthBoost(MAXED));

		// floor(3 + 99 * 0.08) = 10, floor(2 + 99 * 0.05) = 6
		assertEquals(10, Potion.FORGOTTEN_BREW.magicBoost(MAXED));
		assertEquals(6, Potion.ANCIENT_BREW.magicBoost(MAXED));
	}

	@Test
	public void heartsAndMagicPotionsDiffer()
	{
		// floor(4 + 9.9) = 13, floor(1 + 9.9) = 10, and a flat 4
		assertEquals(13, Potion.SATURATED_HEART.magicBoost(MAXED));
		assertEquals(10, Potion.IMBUED_HEART.magicBoost(MAXED));
		assertEquals(4, Potion.MAGIC.magicBoost(MAXED));
	}

	@Test
	public void moonlightScalesWithHerblore()
	{
		PlayerLevels lowHerblore = PlayerLevels.builder()
			.attack(99).strength(99).magic(99).ranged(99).herblore(10).build();
		PlayerLevels midHerblore = PlayerLevels.builder()
			.attack(99).strength(99).magic(99).ranged(99).herblore(50).build();

		// Below 45 Herblore the attack boost is the weaker tier; above it, the stronger one.
		assertEquals(12, Potion.MOONLIGHT.attackBoost(lowHerblore));
		assertEquals(19, Potion.MOONLIGHT.attackBoost(midHerblore));

		PlayerLevels noHerblore = PlayerLevels.builder()
			.attack(99).strength(99).magic(99).ranged(99).herblore(1).build();
		assertEquals(0, Potion.MOONLIGHT.attackBoost(noHerblore));
	}

	@Test
	public void noPotionBoostsNothing()
	{
		assertEquals(0, Potion.NONE.attackBoost(MAXED));
		assertEquals(0, Potion.NONE.strengthBoost(MAXED));
		assertEquals(0, Potion.NONE.rangedBoost(MAXED));
		assertEquals(0, Potion.NONE.magicBoost(MAXED));
	}

	@Test
	public void everyPotionIsNamedForDisplay()
	{
		for (Potion potion : Potion.values())
		{
			assertTrue(potion.name(), potion.toString().length() > 2);
		}
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentStats;
import com.gearforge.dps.CombatContext;
import com.gearforge.dps.CombatStyle;
import com.gearforge.dps.DpsEngine;
import com.gearforge.dps.PoweredStaff;
import com.gearforge.dps.Target;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * A powered staff carries its own attack and casts nothing. GearForge assumed Ice Barrage for every
 * magic setup, which judged a trident on a spell it cannot cast.
 */
public class PoweredStaffTest
{
	private final DpsEngine engine = new DpsEngine();

	@Test
	public void eachStaffScalesFromTheMagicLevel()
	{
		assertEquals(28, PoweredStaff.TRIDENT_OF_THE_SEAS.maxHit(99));
		assertEquals(31, PoweredStaff.TRIDENT_OF_THE_SWAMP.maxHit(99));
		assertEquals(33, PoweredStaff.SANGUINESTI_STAFF.maxHit(99));
		assertEquals(34, PoweredStaff.TUMEKENS_SHADOW.maxHit(99));
		assertEquals(24, PoweredStaff.WARPED_SCEPTRE.maxHit(99));
	}

	@Test
	public void aLowerMagicLevelHitsForLess()
	{
		assertTrue(PoweredStaff.SANGUINESTI_STAFF.maxHit(99) > PoweredStaff.SANGUINESTI_STAFF.maxHit(75));

		// Never below one, however low the level.
		assertEquals(1, PoweredStaff.TRIDENT_OF_THE_SEAS.maxHit(1));
	}

	@Test
	public void chargedAndUnchargedFormsBothResolve()
	{
		assertEquals(PoweredStaff.SANGUINESTI_STAFF, PoweredStaff.forItem(ItemID.SANGUINESTI_STAFF));
		assertEquals(PoweredStaff.SANGUINESTI_STAFF,
			PoweredStaff.forItem(ItemID.SANGUINESTI_STAFF_UNCHARGED));
		assertEquals(PoweredStaff.TRIDENT_OF_THE_SEAS, PoweredStaff.forItem(ItemID.TOTS_CHARGED));

		assertNull(PoweredStaff.forItem(ItemID.ABYSSAL_WHIP));
	}

	/**
	 * Tumeken's shadow triples every magic bonus worn, which is most of what it is for and would
	 * otherwise leave it looking barely better than a sanguinesti.
	 */
	@Test
	public void theShadowTriplesMagicDamageBonuses()
	{
		int withShadow = engine.maxHit(context(PoweredStaff.TUMEKENS_SHADOW, 20), 0);
		int withSang = engine.maxHit(context(PoweredStaff.SANGUINESTI_STAFF, 20), 0);

		// Same 20% bonus on the gear, but the shadow reads it as 60%.
		assertEquals(34 + 34 * 60 / 100, withShadow);
		assertEquals(33 + 33 * 20 / 100, withSang);
	}

	/**
	 * The whole point: the staff's own maximum replaces the assumed spell entirely.
	 */
	@Test
	public void theStaffsMaximumReplacesTheAssumedSpell()
	{
		int barrageAssumption = engine.maxHit(context(null, 0), 0);
		int trident = engine.maxHit(context(PoweredStaff.TRIDENT_OF_THE_SEAS, 0), 0);

		assertEquals(30, barrageAssumption);
		assertEquals(28, trident);
	}

	private static CombatContext context(PoweredStaff staff, int magicDamagePercent)
	{
		return CombatContext.builder()
			.magicLevel(99)
			.style(CombatStyle.MAGIC)
			.equipment(EquipmentStats.builder().magicDamage(magicDamagePercent).build())
			.target(Target.dummy())
			.baseSpellDamage(30)
			.poweredStaffType(staff)
			.poweredStaff(staff != null)
			.weaponSpeedTicks(4)
			.build();
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.data.EquipmentStats;
import com.gearforge.data.GearItem;
import com.gearforge.data.Storage;
import com.gearforge.dps.CombatContext;
import com.gearforge.dps.CombatStyle;
import com.gearforge.dps.DpsEngine;
import com.gearforge.dps.MonsterAttribute;
import com.gearforge.dps.PoweredStaff;
import com.gearforge.dps.SetEffectRegistry;
import com.gearforge.dps.SetEffects;
import com.gearforge.dps.Spell;
import com.gearforge.dps.Target;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.EnumSet;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The tail of the gear model: the staves that hit for a fixed amount, the salamanders that scale like
 * a strength bonus, and the three items that change how the accuracy roll is made rather than what
 * goes into it.
 */
public class RemainingEffectsTest
{
	private static final double TOLERANCE = 1e-9;

	private final SetEffectRegistry registry = new SetEffectRegistry();
	private final DpsEngine engine = new DpsEngine();

	@Test
	public void theCrystalStavesHitForAFixedAmount()
	{
		// Entirely independent of the Magic level, which is what makes them unusual.
		assertEquals(23, PoweredStaff.CRYSTAL_STAFF_BASIC.maxHit(99));
		assertEquals(23, PoweredStaff.CRYSTAL_STAFF_BASIC.maxHit(1));
		assertEquals(31, PoweredStaff.CRYSTAL_STAFF_ATTUNED.maxHit(75));
		assertEquals(39, PoweredStaff.CRYSTAL_STAFF_PERFECTED.maxHit(99));
	}

	@Test
	public void theCorruptedStavesMatchTheirCrystalCounterparts()
	{
		assertEquals(PoweredStaff.CRYSTAL_STAFF_BASIC, PoweredStaff.forItem(23852));
		assertEquals(PoweredStaff.CRYSTAL_STAFF_ATTUNED, PoweredStaff.forItem(23853));
		assertEquals(PoweredStaff.CRYSTAL_STAFF_PERFECTED, PoweredStaff.forItem(23854));
	}

	@Test
	public void salamandersScaleLikeAStrengthBonus()
	{
		// Tecu is the strongest breath, black next, then red, orange and the swamp lizard.
		assertTrue(PoweredStaff.TECU_SALAMANDER.maxHit(99) > PoweredStaff.BLACK_SALAMANDER.maxHit(99));
		assertTrue(PoweredStaff.BLACK_SALAMANDER.maxHit(99) > PoweredStaff.RED_SALAMANDER.maxHit(99));
		assertTrue(PoweredStaff.RED_SALAMANDER.maxHit(99) > PoweredStaff.ORANGE_SALAMANDER.maxHit(99));
		// The orange and the swamp lizard both land on 19 at 99 Magic; their bonuses are close enough
		// that the truncation swallows the difference.
		assertTrue(PoweredStaff.ORANGE_SALAMANDER.maxHit(99) >= PoweredStaff.SWAMP_LIZARD.maxHit(99));

		// The same formula the melee maximum uses, with the breath's bonus in place of gear.
		assertEquals((99 * (104 + 64) + 320) / 640, PoweredStaff.TECU_SALAMANDER.maxHit(99));
	}

	@Test
	public void theRemainingSceptresAreRecognised()
	{
		assertEquals(PoweredStaff.THAMMARONS_SCEPTRE, PoweredStaff.forItem(22555));
		assertEquals(PoweredStaff.ACCURSED_SCEPTRE, PoweredStaff.forItem(27665));
		assertEquals(PoweredStaff.EYE_OF_AYAK, PoweredStaff.forItem(31113));
		assertEquals(PoweredStaff.STARTER_STAFF, PoweredStaff.forItem(22335));
		assertNotNull(PoweredStaff.forItem(28796));
	}

	/**
	 * A brimstone ring lowers the target's magic defence a quarter of the time. That is not an accuracy
	 * multiplier — it is a different roll — so it had to reach the engine rather than the registry.
	 */
	@Test
	public void theBrimstoneRingRaisesMagicAccuracy()
	{
		double without = engine.score(magicContext(false, false)).getHitChance();
		double with = engine.score(magicContext(true, false)).getHitChance();

		assertTrue("The ring should land more often", with > without);
	}

	/**
	 * Osmumten's fang rerolls a miss. The result is not one minus the chance of missing twice, because
	 * both rolls share a defence roll.
	 */
	@Test
	public void aRerolledMissLandsMoreOftenButNotIndependently()
	{
		double single = engine.score(magicContext(false, false)).getHitChance();
		double rerolled = engine.score(magicContext(false, true)).getHitChance();

		assertTrue(rerolled > single);
		assertTrue("Two shared rolls beat one, but not as much as two independent ones",
			rerolled < 1 - (1 - single) * (1 - single) + TOLERANCE);
	}

	/**
	 * A tome raises a spell of its own element and nothing else. It used to be applied to whatever
	 * magic setup came past, because the spell was assumed rather than chosen.
	 */
	@Test
	public void aTomeOnlyHelpsItsOwnElement()
	{
		List<GearItem> tomeOfWater = worn(25574);
		Target target = plainTarget();

		SetEffects matched = registry.evaluate(
			tomeOfWater, CombatStyle.MAGIC, target, false, Spell.WATER_SURGE);
		SetEffects mismatched = registry.evaluate(
			tomeOfWater, CombatStyle.MAGIC, target, false, Spell.FIRE_SURGE);
		SetEffects noSpell = registry.evaluate(
			tomeOfWater, CombatStyle.MAGIC, target, false, Spell.ICE_BARRAGE);

		assertEquals(1.10, matched.getDamageMultiplier(), TOLERANCE);
		assertEquals(1.0, mismatched.getDamageMultiplier(), TOLERANCE);
		assertEquals("Ice Barrage carries no element for a tome to match",
			1.0, noSpell.getDamageMultiplier(), TOLERANCE);
	}

	private List<GearItem> worn(int... itemIds)
	{
		List<GearItem> worn = new ArrayList<>();
		for (int id : itemIds)
		{
			worn.add(new GearItem(id, "Item " + id, 1,
				EquipmentStats.builder().build(), EnumSet.of(Storage.BANK)));
		}

		return worn;
	}

	private static Target plainTarget()
	{
		return Target.builder()
			.name("Target")
			.defenceLevel(100)
			.magicLevel(100)
			.defensiveBonuses(EquipmentStats.builder().build())
			.build();
	}

	@Test
	public void theColossalBladeGrowsWithTheTarget()
	{
		SetEffects small = evaluateAgainstSize(CombatStyle.SLASH, 1, ItemID.GIANTS_FOUNDRY_COLOSSAL_BLADE);
		SetEffects large = evaluateAgainstSize(CombatStyle.SLASH, 5, ItemID.GIANTS_FOUNDRY_COLOSSAL_BLADE);

		assertEquals(2, small.getFlatMaxHit());
		assertEquals(10, large.getFlatMaxHit());
	}

	private SetEffects evaluate(CombatStyle style, int... itemIds)
	{
		return evaluateAgainstSize(style, 1, itemIds);
	}

	private SetEffects evaluateAgainstSize(CombatStyle style, int size, int... itemIds)
	{
		List<GearItem> worn = new ArrayList<>();
		for (int id : itemIds)
		{
			worn.add(new GearItem(id, "Item " + id, 1,
				EquipmentStats.builder().build(), EnumSet.of(Storage.BANK)));
		}

		Target target = Target.builder()
			.name("Target")
			.defenceLevel(100)
			.magicLevel(100)
			.size(size)
			.defensiveBonuses(EquipmentStats.builder().build())
			.attributes(EnumSet.noneOf(MonsterAttribute.class))
			.build();

		return registry.evaluate(worn, style, target, false);
	}

	private static CombatContext magicContext(boolean brimstone, boolean reroll)
	{
		return CombatContext.builder()
			.magicLevel(99)
			.style(CombatStyle.MAGIC)
			.equipment(EquipmentStats.builder().amagic(60).build())
			.target(Target.builder()
				.name("Target")
				.defenceLevel(150)
				.magicLevel(150)
				.defensiveBonuses(EquipmentStats.builder().dmagic(80).build())
				.build())
			.baseSpellDamage(30)
			.weaponSpeedTicks(5)
			.brimstoneRing(brimstone)
			.rerollsMisses(reroll)
			.build();
	}

	/**
	 * Crystal blessing raises a melee maximum by a fortieth per crystal piece — a different effect from
	 * the crystal armour's own bonus, which only helps a crystal bow.
	 */
	@Test
	public void crystalBlessingScalesWithThePiecesWorn()
