	public void inquisitorsCountsPerPieceAndOnlyOnCrush()
	{
		List<GearItem> full = Arrays.asList(
			piece(ItemID.INQUISITORS_HELM, EquipmentSlot.HEAD),
			piece(ItemID.INQUISITORS_BODY, EquipmentSlot.BODY),
			piece(ItemID.INQUISITORS_SKIRT, EquipmentSlot.LEGS));

		// helm 1 + hauberk 2 + skirt 2 = 5, applied as 205/200.
		SetEffects onCrush = registry.evaluate(full, CombatStyle.CRUSH, Target.dummy(), false);
		assertEquals(205.0 / 200.0, onCrush.getAccuracyMultiplier(), TOLERANCE);
		assertEquals(205.0 / 200.0, onCrush.getDamageMultiplier(), TOLERANCE);

		// Worth nothing on any other style, even wearing the whole set.
		assertEquals(1.0,
			registry.evaluate(full, CombatStyle.STAB, Target.dummy(), false).getDamageMultiplier(), TOLERANCE);
		assertEquals(1.0,
			registry.evaluate(full, CombatStyle.SLASH, Target.dummy(), false).getDamageMultiplier(), TOLERANCE);
	}

	@Test
	public void partialInquisitorsStillCounts()
	{
		// Not a full-set-only bonus — two pieces are still worth wearing.
		List<GearItem> partial = Arrays.asList(
			piece(ItemID.INQUISITORS_HELM, EquipmentSlot.HEAD),
			piece(ItemID.INQUISITORS_BODY, EquipmentSlot.BODY));

		assertEquals(203.0 / 200.0,
			registry.evaluate(partial, CombatStyle.CRUSH, Target.dummy(), false).getDamageMultiplier(),
			TOLERANCE);

		assertEquals(202.0 / 200.0,
			registry.evaluate(
				Collections.singletonList(piece(ItemID.INQUISITORS_SKIRT, EquipmentSlot.LEGS)),
				CombatStyle.CRUSH, Target.dummy(), false).getDamageMultiplier(),
			TOLERANCE);
	}

	@Test
	public void meleeWeaponPassivesDoNothingForSpellsOrArrows()
	{
		// Reported from the wild: magic best-in-slot returned Emberlight against Yama, because its
		// demonbane bonus was being applied to a spell cast while merely holding it.
		List<GearItem> emberlight = Collections.singletonList(
			piece(ItemID.EMBERLIGHT, EquipmentSlot.WEAPON));

		assertEquals(1.70,
			registry.evaluate(emberlight, CombatStyle.SLASH, DEMONIC, false).getDamageMultiplier(), TOLERANCE);
		assertEquals(1.0,
			registry.evaluate(emberlight, CombatStyle.MAGIC, DEMONIC, false).getDamageMultiplier(), TOLERANCE);
		assertEquals(1.0,
			registry.evaluate(emberlight, CombatStyle.RANGED, DEMONIC, false).getDamageMultiplier(), TOLERANCE);
	}

	@Test
	public void theTwistedBowOnlyScalesItsOwnShots()
	{
		List<GearItem> tbow = Collections.singletonList(piece(ItemID.TWISTED_BOW, EquipmentSlot.WEAPON));
		Target target = highMagic(false, 250);

		assertTrue(registry.evaluate(tbow, CombatStyle.RANGED, target, false).getDamageMultiplier() > 1.0);
		assertEquals(1.0,
			registry.evaluate(tbow, CombatStyle.MAGIC, target, false).getDamageMultiplier(), TOLERANCE);
		assertEquals(1.0,
			registry.evaluate(tbow, CombatStyle.CRUSH, target, false).getDamageMultiplier(), TOLERANCE);
	}

	@Test
	public void dragonbaneWeaponsOnlyCountOnTheirOwnStyle()
	{
		List<GearItem> lance = Collections.singletonList(
			piece(ItemID.DRAGONHUNTER_LANCE, EquipmentSlot.WEAPON));

		assertEquals(1.20,
			registry.evaluate(lance, CombatStyle.STAB, DRACONIC, false).getDamageMultiplier(), TOLERANCE);
		assertEquals(1.0,
			registry.evaluate(lance, CombatStyle.MAGIC, DRACONIC, false).getDamageMultiplier(), TOLERANCE);
	}

	private static Target highMagic(boolean xerician, int magic)
	{
		return Target.builder()
			.name("Test")
			.magicLevel(magic)
			.magicAttack(magic)
			.defensiveBonuses(EquipmentStats.builder().build())
			.attributes(xerician
				? EnumSet.of(MonsterAttribute.XERICIAN)
				: EnumSet.noneOf(MonsterAttribute.class))
			.build();
	}

	private static final Target KALPHITE = Target.builder()
		.name("Kalphite")
		.defenceLevel(100)
		.defensiveBonuses(EquipmentStats.builder().build())
		.attributes(EnumSet.of(MonsterAttribute.KALPHITE))
		.build();

	private static final Target GOLEM = Target.builder()
		.name("Golem")
		.defenceLevel(100)
		.defensiveBonuses(EquipmentStats.builder().build())
		.attributes(EnumSet.of(MonsterAttribute.GOLEM))
		.build();

	private static final Target DRACONIC = Target.builder()
		.name("Dragon")
		.defenceLevel(100)
		.defensiveBonuses(EquipmentStats.builder().build())
		.attributes(EnumSet.of(MonsterAttribute.DRAGON))
		.build();

	private static final Target DEMONIC = Target.builder()
		.name("Demon")
		.defenceLevel(100)
		.defensiveBonuses(EquipmentStats.builder().build())
		.attributes(EnumSet.of(MonsterAttribute.DEMON))
		.build();

	static List<GearItem> fullVoidMelee()
	{
		return Arrays.asList(
			piece(ItemID.GAME_PEST_MELEE_HELM, EquipmentSlot.HEAD),
			piece(ItemID.PEST_VOID_KNIGHT_TOP, EquipmentSlot.BODY),
			piece(ItemID.PEST_VOID_KNIGHT_ROBES, EquipmentSlot.LEGS),
			piece(ItemID.PEST_VOID_KNIGHT_GLOVES, EquipmentSlot.GLOVES));
	}

	static GearItem piece(int itemId, EquipmentSlot slot)
	{
		EquipmentStats stats = EquipmentStats.builder().slot(slot.getSlotIndex()).build();
		return new GearItem(itemId, "Item " + itemId, 1, stats, EnumSet.of(Storage.BANK));
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.setups.Setup;
import com.gearforge.setups.SetupCodec;
import com.gearforge.setups.SetupSource;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class SetupCodecTest
{
	private static Setup sample()
	{
		Setup setup = Setup.named("Vorkath", SetupSource.MANUAL);
		setup.put(EquipmentSlot.HEAD, 3751);
		setup.put(EquipmentSlot.WEAPON, 22978);
		setup.put(EquipmentSlot.AMMO, 892);
		setup.setInventoryFrom(new int[]{385, -1, 385, 2434});
		return setup;
	}

	@Test
	public void roundTripsEverythingThatMatters()
	{
		Setup decoded = SetupCodec.decode(SetupCodec.encode(sample()));

		assertNotNull(decoded);
		assertEquals("Vorkath", decoded.getName());
		assertEquals(3751, decoded.getEquipment().get(EquipmentSlot.HEAD).getItemId());
		assertEquals(22978, decoded.getEquipment().get(EquipmentSlot.WEAPON).getItemId());
		assertEquals(892, decoded.getEquipment().get(EquipmentSlot.AMMO).getItemId());
		assertEquals(4, decoded.getInventory().size());
		assertEquals(385, decoded.getInventory().get(0).getItemId());
		assertNull(decoded.getInventory().get(1));
		assertEquals(2434, decoded.getInventory().get(3).getItemId());
	}

	@Test
	public void aSharedSetupIsMarkedAsShared()
	{
		Setup decoded = SetupCodec.decode(SetupCodec.encode(sample()));
		assertNotNull(decoded);
		assertEquals(SetupSource.SHARED, decoded.getSource());
	}

	@Test
	public void namesWithDelimitersSurviveIntact()
	{
		// A name containing the separators would break a naive format.
		Setup setup = Setup.named("Zulrah | mage, range", SetupSource.MANUAL);
		setup.put(EquipmentSlot.WEAPON, 11235);

		Setup decoded = SetupCodec.decode(SetupCodec.encode(setup));
		assertNotNull(decoded);
		assertEquals("Zulrah | mage, range", decoded.getName());
	}

	@Test
	public void codesAreShortEnoughToPasteIntoChat()
	{
		assertTrue(SetupCodec.encode(sample()).length() < 200);
	}

	@Test
	public void rubbishInputIsRejectedRatherThanThrowing()
	{
		assertNull(SetupCodec.decode(null));
		assertNull(SetupCodec.decode(""));
		assertNull(SetupCodec.decode("hello"));
		assertNull(SetupCodec.decode("GF1|bad"));
		assertNull(SetupCodec.decode("GF9|dg9y|3:22978|"));
		assertNull(SetupCodec.decode("GF1|!!!!|3:22978|"));
		assertNull(SetupCodec.decode("GF1|dg9y|notanumber|"));
		assertNull(SetupCodec.decode("GF1|dg9y||"));
	}

	@Test
	public void anEmptyInventorySectionIsFine()
	{
		Setup setup = Setup.named("Gear only", SetupSource.MANUAL);
		setup.put(EquipmentSlot.WEAPON, 4151);

		Setup decoded = SetupCodec.decode(SetupCodec.encode(setup));
		assertNotNull(decoded);
		assertEquals(1, decoded.size());
		assertTrue(decoded.getInventory().isEmpty());
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.setups.Setup;
import com.gearforge.setups.SetupSource;
import com.google.gson.Gson;
import java.lang.reflect.Type;
import java.util.LinkedHashMap;
import java.util.Map;
import com.google.gson.reflect.TypeToken;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Saved setups have to survive a client restart.
 * <p>
 * They did not: Gson writes an enum map key with {@code String.valueOf}, which is the display name,
 * but reads it back through the enum adapter, which matches on the constant name. "Hands" and "Feet"
 * both resolved to null, Gson rejected the duplicate null key, and the store caught the exception and
 * started fresh — so every setup vanished on the next launch, imported ones included.
 */
public class SetupSerializationTest
{
	private final Gson gson = new Gson();

	@Test
	public void everySlotSurvivesARoundTrip()
	{
		Setup setup = Setup.named("Round trip", SetupSource.IMPORTED);

		int itemId = 100;
		for (EquipmentSlot slot : EquipmentSlot.values())
		{
			setup.put(slot, itemId++);
		}

		Setup restored = gson.fromJson(gson.toJson(setup), Setup.class);
		assertNotNull(restored);

		int expected = 100;
		for (EquipmentSlot slot : EquipmentSlot.values())
		{
			assertNotNull("Lost the " + slot + " slot on reload", restored.getEquipment().get(slot));
			assertEquals(expected++, restored.getEquipment().get(slot).getItemId());
		}
	}

	/**
	 * The pair that actually broke it. Their display names differ from their constant names, which is
	 * what made the mismatch produce two null keys rather than one silently wrong slot.
	 */
	@Test
	public void slotsWhoseDisplayNameDiffersFromTheirConstantNameStillLoad()
	{
		Type mapType = new TypeToken<Map<EquipmentSlot, Integer>>()
		{
		}.getType();

		Map<EquipmentSlot, Integer> legacy =
			gson.fromJson("{\"Hands\":1,\"Feet\":2,\"Neck\":3}", mapType);

		assertEquals(Integer.valueOf(1), legacy.get(EquipmentSlot.GLOVES));
		assertEquals(Integer.valueOf(2), legacy.get(EquipmentSlot.BOOTS));
		assertEquals(Integer.valueOf(3), legacy.get(EquipmentSlot.AMULET));
	}

	/**
	 * Setups written before the fix are on players' disks already, so both spellings have to load.
	 */
	@Test
	public void theConstantNameIsAcceptedTooSoNothingOnDiskIsLost()
	{
		Type mapType = new TypeToken<Map<EquipmentSlot, Integer>>()
		{
		}.getType();

		Map<EquipmentSlot, Integer> byConstantName =
			gson.fromJson("{\"GLOVES\":1,\"BOOTS\":2,\"AMULET\":3}", mapType);

		assertEquals(Integer.valueOf(1), byConstantName.get(EquipmentSlot.GLOVES));
		assertEquals(Integer.valueOf(2), byConstantName.get(EquipmentSlot.BOOTS));
		assertEquals(Integer.valueOf(3), byConstantName.get(EquipmentSlot.AMULET));
	}

	/**
	 * Guards the coupling the fix relies on: the annotation and the display name must stay equal, or
	 * writes and reads drift apart again.
	 */
	@Test
	public void everySlotWritesAKeyItCanReadBack()
	{
		Type mapType = new TypeToken<Map<EquipmentSlot, Integer>>()
		{
		}.getType();

		Map<EquipmentSlot, Integer> written = new LinkedHashMap<>();
		for (EquipmentSlot slot : EquipmentSlot.values())
		{
			written.put(slot, slot.getSlotIndex());
		}

		Map<EquipmentSlot, Integer> read = gson.fromJson(gson.toJson(written, mapType), mapType);
		assertEquals(written, read);
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.setups.ItemRequirement;
import com.gearforge.setups.Setup;
import com.gearforge.setups.SetupSource;
import com.gearforge.setups.SetupValidator;
import java.util.HashMap;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class SetupValidatorTest
{
	private static final IntUnaryOperator NO_FAMILIES = id -> id;

	/** Ids 101-103 are one variant family; everything else is its own. */
	private static final IntUnaryOperator FAMILIES = id -> id >= 101 && id <= 103 ? 100 : id;

	private static Map<Integer, Integer> owned(int... ids)
	{
		Map<Integer, Integer> owned = new HashMap<>();
		for (int id : ids)
		{
			owned.put(id, 1);
		}

		return owned;
	}

	@Test
	public void exactMatchIsHave()
	{
		assertEquals(
			SetupValidator.Status.HAVE,
			SetupValidator.check(ItemRequirement.of(5), owned(5), NO_FAMILIES));
	}

	@Test
	public void nothingOwnedIsMissing()
	{
		assertEquals(
			SetupValidator.Status.MISSING,
			SetupValidator.check(ItemRequirement.of(5), owned(6, 7), NO_FAMILIES));
	}

	@Test
	public void aDifferentVariantCountsAsVariantNotMissing()
	{
		// You asked for the undegraded piece and own a degraded one — that is worth saying, but it is
		// not the same as not having it.
		assertEquals(
			SetupValidator.Status.VARIANT,
			SetupValidator.check(ItemRequirement.of(101), owned(103), FAMILIES));
	}

	@Test
	public void exactMatchWinsOverVariantMatch()
	{
		assertEquals(
			SetupValidator.Status.HAVE,
			SetupValidator.check(ItemRequirement.of(101), owned(101, 103), FAMILIES));
	}

	@Test
	public void variantsAreIgnoredWhenTheRequirementIsNotFuzzy()
	{
		ItemRequirement strict = new ItemRequirement(101, 1, false);

		assertEquals(
			SetupValidator.Status.MISSING,
			SetupValidator.check(strict, owned(103), FAMILIES));
	}

	@Test
	public void quantityIsRespected()
	{
		Map<Integer, Integer> two = new HashMap<>();
		two.put(5, 2);

		assertEquals(
			SetupValidator.Status.HAVE,
			SetupValidator.check(new ItemRequirement(5, 2, true), two, NO_FAMILIES));
		assertEquals(
			SetupValidator.Status.MISSING,
			SetupValidator.check(new ItemRequirement(5, 3, true), two, NO_FAMILIES));
	}

	@Test
	public void validatesAWholeSetupAndCountsWhatIsSatisfied()
	{
		Setup setup = Setup.named("Test", SetupSource.MANUAL);
		setup.put(EquipmentSlot.HEAD, 1);
		setup.put(EquipmentSlot.BODY, 2);
		setup.put(EquipmentSlot.WEAPON, 101);

		Map<EquipmentSlot, SetupValidator.Status> statuses =
			SetupValidator.validate(setup, owned(1, 103), FAMILIES);

		assertEquals(SetupValidator.Status.HAVE, statuses.get(EquipmentSlot.HEAD));
		assertEquals(SetupValidator.Status.MISSING, statuses.get(EquipmentSlot.BODY));
		assertEquals(SetupValidator.Status.VARIANT, statuses.get(EquipmentSlot.WEAPON));

		// A variant counts as satisfied — you can go and get it.
		assertEquals(2, SetupValidator.satisfiedCount(statuses));
	}

	@Test
	public void inventoryDuplicatesNeedTheFullQuantity()
	{
		// Four sharks asked for, one owned: every one of those slots is missing, not just three.
		Setup setup = Setup.named("Food", SetupSource.MANUAL);
		setup.setInventoryFrom(new int[]{10, 10, 10, 10});

		Map<Integer, Integer> onlyOne = new HashMap<>();
		onlyOne.put(10, 1);

		Map<Integer, SetupValidator.Status> statuses =
			SetupValidator.validateInventory(setup, onlyOne, NO_FAMILIES);

		assertEquals(4, statuses.size());
		assertEquals(0, SetupValidator.countSatisfied(statuses.values()));

		Map<Integer, Integer> allFour = new HashMap<>();
		allFour.put(10, 4);
		assertEquals(4, SetupValidator.countSatisfied(
			SetupValidator.validateInventory(setup, allFour, NO_FAMILIES).values()));
	}

	@Test
	public void inventoryKeepsSlotPositionsIncludingGaps()
	{
		Setup setup = Setup.named("Gapped", SetupSource.MANUAL);
		setup.setInventoryFrom(new int[]{5, -1, 7, -1});

		// Trailing empties are dropped, but the gap in the middle is real and preserved.
		assertEquals(3, setup.getInventory().size());
		assertEquals(null, setup.getInventory().get(1));
		assertEquals(2, setup.inventoryCount());

		Map<Integer, SetupValidator.Status> statuses =
			SetupValidator.validateInventory(setup, owned(5, 7), NO_FAMILIES);

		assertEquals(2, statuses.size());
		assertEquals(SetupValidator.Status.HAVE, statuses.get(0));
		assertEquals(SetupValidator.Status.HAVE, statuses.get(2));
	}

	@Test
	public void setupSizeCountsEquipmentAndInventoryTogether()
	{
		Setup setup = Setup.named("Both", SetupSource.MANUAL);
		setup.put(EquipmentSlot.WEAPON, 1);
		setup.setInventoryFrom(new int[]{2, 3, -1});

		assertEquals(3, setup.size());
	}

	@Test
	public void anEmptySetupValidatesToNothingRatherThanFailing()
	{
		Setup empty = Setup.named("Empty", SetupSource.MANUAL);
		assertEquals(0, SetupValidator.validate(empty, owned(1, 2), FAMILIES).size());
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.data.Monster;
import com.gearforge.data.MonsterRepository;
import com.gearforge.data.SlayerGear;
import com.google.gson.Gson;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Some slayer monsters cannot be fought without a specific item. A best-in-slot answer that puts a
 * helm of neitiznot where a nose peg belongs is not suboptimal, it is unusable — and the optimizer had
 * no idea these existed.
 */
public class SlayerGearTest
{
	private final MonsterRepository monsters = new MonsterRepository(new Gson());

	@Test
	public void aSpectreDemandsANosePegOrASlayerHelmet()
	{
		SlayerGear.Requirement requirement = SlayerGear.forMonster(named("Aberrant spectre"));

		assertNotNull(requirement);
		assertTrue(requirement.isWorn());
		assertEquals(EquipmentSlot.HEAD, requirement.getSlot());
		assertTrue("A bare nose peg must be accepted", requirement.getAccepted().contains(4168));
		assertTrue("So must a slayer helmet", requirement.getAccepted().contains(11864));
	}

	/**
	 * A slayer helmet does not stop a basilisk's gaze — only the shields do, which is why this one
	 * cannot share the head-slot handling.
	 */
	@Test
	public void aBasiliskDemandsAShieldRatherThanAHelmet()
	{
		SlayerGear.Requirement requirement = SlayerGear.forMonster(named("Basilisk Knight"));

		assertNotNull(requirement);
		assertEquals(EquipmentSlot.SHIELD, requirement.getSlot());
		assertTrue("V's shield", requirement.getAccepted().contains(24266));
		assertTrue("Mirror shield", requirement.getAccepted().contains(4156));
		assertFalse("A slayer helmet is no help here", requirement.getAccepted().contains(11864));
	}

	/**
	 * A carried item takes no slot, so the reasoning is the only place it can be said.
	 */
	@Test
	public void aCarriedItemIsSaidRatherThanWorn()
	{
		SlayerGear.Requirement gargoyle = SlayerGear.forMonster(named("Gargoyle"));

		assertNotNull(gargoyle);
		assertFalse(gargoyle.isWorn());
		assertNull(gargoyle.getSlot());
		assertTrue(gargoyle.getNote().toLowerCase().contains("rock hammer"));

		SlayerGear.Requirement lizard = SlayerGear.forMonster(named("Desert Lizard"));
		assertNotNull(lizard);
		assertTrue(lizard.getNote().toLowerCase().contains("ice cooler"));
	}

	@Test
	public void everyMonsterWithARequirementIsInTheData()
	{
		for (String name : new String[]{
			"Aberrant spectre", "Deviant spectre", "Banshee", "Twisted Banshee", "Dust devil",
			"Basilisk", "Basilisk Knight", "Cave horror", "Killerwatt", "Fever spider",
			"Gargoyle", "Rockslug", "Desert Lizard", "Kurask", "Turoth"})
		{
			assertNotNull(name + " is missing from the monster data", named(name));
			assertNotNull(name + " has no requirement", SlayerGear.forMonster(named(name)));
		}
	}

	@Test
	public void anOrdinaryMonsterDemandsNothing()
	{
		assertNull(SlayerGear.forMonster(named("Zulrah")));

		Monster crab = new Monster();
		crab.setName("Ammonite Crab");
		assertNull(SlayerGear.forMonster(crab));
		assertNull(SlayerGear.forMonster(null));
	}

	private Monster named(String name)
	{
		return monsters.all().stream()
			.filter(monster -> monster.getName().equalsIgnoreCase(name))
			.findFirst()
			.orElse(null);
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.data.EquipmentStats;
import com.gearforge.data.GearItem;
import com.gearforge.data.GearStat;
import com.gearforge.data.SlotRanker;
import com.gearforge.data.Storage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.function.IntUnaryOperator;
import java.util.stream.Collectors;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class SlotRankerTest
{
	private static final IntUnaryOperator NO_GROUPING = id -> id;

	@Test
	public void ranksBestFirst()
	{
		List<GearItem> owned = Arrays.asList(
			amulet(1, "Amulet of glory", 10),
			amulet(2, "Amulet of fury", 15),
			amulet(3, "Amulet of strength", 10));

		List<GearItem> ranked = SlotRanker.rank(
			owned, EquipmentSlot.AMULET, GearStat.SLASH_ATTACK, false, true, NO_GROUPING);

		assertEquals(Arrays.asList("Amulet of fury", "Amulet of glory", "Amulet of strength"), names(ranked));
	}

	@Test
	public void excludesItemsFromOtherSlots()
	{
		List<GearItem> owned = Arrays.asList(
			amulet(1, "Amulet of fury", 15),
			item(2, "Rune platebody", EquipmentSlot.BODY, 0, 0));

		List<GearItem> ranked = SlotRanker.rank(
			owned, EquipmentSlot.AMULET, GearStat.SLASH_ATTACK, false, true, NO_GROUPING);

		assertEquals(Collections.singletonList("Amulet of fury"), names(ranked));
	}

	@Test
	public void hidesNonPositiveBonusesWhenAsked()
	{
		List<GearItem> owned = Arrays.asList(
			amulet(1, "Amulet of fury", 15),
			amulet(2, "Amulet of nothing", 0),
			amulet(3, "Cursed amulet", -5));

		List<GearItem> hidden = SlotRanker.rank(
			owned, EquipmentSlot.AMULET, GearStat.SLASH_ATTACK, false, true, NO_GROUPING);
		assertEquals(Collections.singletonList("Amulet of fury"), names(hidden));

		List<GearItem> shown = SlotRanker.rank(
			owned, EquipmentSlot.AMULET, GearStat.SLASH_ATTACK, false, false, NO_GROUPING);
		assertEquals(3, shown.size());
		assertEquals("Cursed amulet", shown.get(2).getName());
	}

	@Test
	public void groupingKeepsTheBestMemberOfEachFamily()
	{
		// Every degradation state maps to family 100; the undegraded one is strongest.
		List<GearItem> owned = Arrays.asList(
			item(101, "Ahrim's robetop", EquipmentSlot.BODY, 0, 30),
			item(102, "Ahrim's robetop 75", EquipmentSlot.BODY, 0, 25),
			item(103, "Ahrim's robetop 25", EquipmentSlot.BODY, 0, 10),
			item(201, "Mystic robe top", EquipmentSlot.BODY, 0, 20));

		IntUnaryOperator families = id -> id >= 101 && id <= 103 ? 100 : id;

		List<GearItem> ranked = SlotRanker.rank(
			owned, EquipmentSlot.BODY, GearStat.MAGIC_ATTACK, true, true, families);

		assertEquals(Arrays.asList("Ahrim's robetop", "Mystic robe top"), names(ranked));
	}

	@Test
	public void groupingNeverHidesAStrongerVariant()
	{
		// The stronger member is listed second — grouping must still surface it, not the first seen.
		List<GearItem> owned = Arrays.asList(
			item(101, "Ring of suffering", EquipmentSlot.RING, 0, 0, 20),
			item(102, "Ring of suffering (i)", EquipmentSlot.RING, 0, 0, 40));

		List<GearItem> ranked = SlotRanker.rank(
			owned, EquipmentSlot.RING, GearStat.MAGIC_DEFENCE, true, true, id -> 100);

		assertEquals(1, ranked.size());
		assertEquals("Ring of suffering (i)", ranked.get(0).getName());
	}

	@Test
	public void rankingIsStableForTiedItems()
	{
		List<GearItem> owned = new ArrayList<>(Arrays.asList(
			amulet(3, "Zebra amulet", 10),
			amulet(1, "Apple amulet", 10),
			amulet(2, "Mango amulet", 10)));

		List<String> first = names(SlotRanker.rank(
			owned, EquipmentSlot.AMULET, GearStat.SLASH_ATTACK, false, true, NO_GROUPING));

		Collections.reverse(owned);
		List<String> second = names(SlotRanker.rank(
			owned, EquipmentSlot.AMULET, GearStat.SLASH_ATTACK, false, true, NO_GROUPING));

		assertEquals(first, second);
		assertEquals(Arrays.asList("Apple amulet", "Mango amulet", "Zebra amulet"), first);
	}

	@Test
	public void emptyBankRanksToEmptyListRatherThanFailing()
	{
		List<GearItem> ranked = SlotRanker.rank(
			Collections.emptyList(), EquipmentSlot.WEAPON, GearStat.STAB_ATTACK, true, true, NO_GROUPING);

		assertTrue(ranked.isEmpty());
	}

	@Test
	public void magicDamageFormatsAsAPercentage()
	{
		assertEquals("+5%", GearStat.MAGIC_DAMAGE.format(5.0));
		assertEquals("+0.2%", GearStat.MAGIC_DAMAGE.format(0.2));
		assertEquals("+15", GearStat.STAB_ATTACK.format(15));
		assertEquals("-5", GearStat.STAB_ATTACK.format(-5));
	}

	@Test
	public void arrowsRankEmptyOnRangedAttackAndSuggestRangedStrength()
	{
		// Real OSRS data: arrows carry ranged strength and no ranged attack at all, so asking for
		// ranged attack in the ammo slot correctly finds nothing. The suggestion is what rescues it.
		List<GearItem> owned = Arrays.asList(
			arrow(892, "Rune arrow", 49),
			arrow(11212, "Dragon arrow", 60),
			arrow(882, "Bronze arrow", 7));

		List<GearItem> ranked = SlotRanker.rank(
			owned, EquipmentSlot.AMMO, GearStat.RANGED_ATTACK, true, true, NO_GROUPING);
		assertTrue(ranked.isEmpty());

		List<GearStat> suggestions = SlotRanker.suggestStats(
			SlotRanker.positiveCounts(owned, EquipmentSlot.AMMO), GearStat.RANGED_ATTACK, 2);
		assertEquals(Collections.singletonList(GearStat.RANGED_STRENGTH), suggestions);

		// And the stat they should have picked does rank them.
		List<GearItem> byStrength = SlotRanker.rank(
			owned, EquipmentSlot.AMMO, GearStat.RANGED_STRENGTH, true, true, NO_GROUPING);
		assertEquals(Arrays.asList("Dragon arrow", "Rune arrow", "Bronze arrow"), names(byStrength));
	}

	@Test
	public void positiveCountsIgnoresOtherSlots()
	{
		List<GearItem> owned = Arrays.asList(
			arrow(892, "Rune arrow", 49),
			amulet(1, "Amulet of fury", 15));

		assertEquals(
			Integer.valueOf(1),
			SlotRanker.positiveCounts(owned, EquipmentSlot.AMMO).get(GearStat.RANGED_STRENGTH));
		assertEquals(
			null,
			SlotRanker.positiveCounts(owned, EquipmentSlot.AMMO).get(GearStat.SLASH_ATTACK));
	}

	@Test
	public void suggestionsAreEmptyWhenTheSlotHasNothingAtAll()
	{
		List<GearStat> suggestions = SlotRanker.suggestStats(
			SlotRanker.positiveCounts(Collections.emptyList(), EquipmentSlot.AMMO),
			GearStat.RANGED_ATTACK,
			2);

		assertTrue(suggestions.isEmpty());
	}

	private static GearItem arrow(int id, String name, int rangedStrength)
	{
		EquipmentStats stats = EquipmentStats.builder()
			.rangedStrength(rangedStrength)
			.slot(EquipmentSlot.AMMO.getSlotIndex())
			.build();

		return new GearItem(id, name, 1000, stats, EnumSet.of(Storage.BANK));
	}

	private static List<String> names(List<GearItem> items)
	{
		return items.stream().map(GearItem::getName).collect(Collectors.toList());
	}

	private static GearItem amulet(int id, String name, int slashAttack)
	{
		return item(id, name, EquipmentSlot.AMULET, slashAttack, 0);
	}

	private static GearItem item(int id, String name, EquipmentSlot slot, int slashAttack, int magicAttack)
	{
		return item(id, name, slot, slashAttack, magicAttack, 0);
	}

	private static GearItem item(int id, String name, EquipmentSlot slot, int slashAttack, int magicAttack, int magicDefence)
	{
		EquipmentStats stats = EquipmentStats.builder()
			.aslash(slashAttack)
			.amagic(magicAttack)
			.dmagic(magicDefence)
			.slot(slot.getSlotIndex())
			.build();

		return new GearItem(id, name, 1, stats, EnumSet.of(Storage.BANK));
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.data.EquipmentStats;
import com.gearforge.data.GearItem;
import com.gearforge.data.ItemCategories;
import com.gearforge.data.Storage;
import com.google.gson.Gson;
import com.gearforge.dps.CombatContext;
import com.gearforge.dps.CombatStyle;
import com.gearforge.dps.DpsEngine;
import com.gearforge.dps.SpecialAttack;
import com.gearforge.dps.Target;
import com.gearforge.optimizer.SpecFinder;
import com.gearforge.optimizer.SpecSuggestion;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * A spec recommendation is only useful if it changes with the target and with the gear. These pin
 * the two behaviours the whole feature exists for.
 */
public class SpecFinderTest
{
	private final SpecFinder finder = new SpecFinder(new DpsEngine(), new ItemCategories(new Gson()));

	private static final GearItem CLAWS = weapon(ItemID.DRAGON_CLAWS, "Dragon claws", 57, 56, 4);
	private static final GearItem VOIDWAKER = weapon(ItemID.VOIDWAKER, "Voidwaker", 80, 80, 4);
	private static final GearItem WARHAMMER = weapon(ItemID.DRAGON_WARHAMMER, "Dragon warhammer", 95, 80, 6);
	/**
	 * The setup's own weapon, and the control for "has no special attack". Deliberately not the whip:
	 * that gained one, which is what broke this test the first time.
	 */
	private static final GearItem PLAIN = weapon(ItemID.RUNE_SCIMITAR, "Rune scimitar", 45, 44, 4);

	@Test
	public void aGuaranteedSpecWinsWhereAccuracyIsHardToCome()
	{
		// A target you can barely hit is exactly where never missing is worth most.
		List<SpecSuggestion> suggestions = find(armoured(), CLAWS, VOIDWAKER);

		assertFalse(suggestions.isEmpty());
		assertEquals(SpecialAttack.VOIDWAKER, suggestions.get(0).getSpecial());
	}

	@Test
	public void burstDamageWinsWhereEverythingLandsAnyway()
	{
		// Against no defence at all the claws' four hits beat a capped guaranteed roll.
		List<SpecSuggestion> suggestions = find(Target.dummy(), CLAWS, VOIDWAKER);

		assertFalse(suggestions.isEmpty());
		assertEquals(SpecialAttack.DRAGON_CLAWS, suggestions.get(0).getSpecial());
	}

	/**
	 * The point of scoring against the worn setup: a stronger body slot raises your max hit, which the
	 * voidwaker's damage is a straight fraction of.
	 */
	@Test
	public void strongerGearMakesTheSpecHitHarder()
	{
		double weak = valueOf(find(Target.dummy(), 0, VOIDWAKER), SpecialAttack.VOIDWAKER);
		double strong = valueOf(find(Target.dummy(), 40, VOIDWAKER), SpecialAttack.VOIDWAKER);

		assertTrue("Strength bonus should raise what the voidwaker hits for", strong > weak);
	}

	/**
	 * A warhammer is nearly worthless on something that dies in two hits and genuinely good on a boss,
	 * because all it does is shorten what remains.
	 */
	@Test
	public void aDefenceReductionIsWorthMoreOnALongerFight()
	{
		double onShortFight = valueOf(find(armoured(), 50, WARHAMMER), SpecialAttack.DRAGON_WARHAMMER);
		double onLongFight = valueOf(find(armoured(), 50, 2000, WARHAMMER), SpecialAttack.DRAGON_WARHAMMER);

		assertTrue("A longer kill should make the reduction worth more", onLongFight > onShortFight);
	}

	@Test
	public void aWeaponWithNoSpecialIsNotSuggested()
	{
		assertTrue(find(Target.dummy(), PLAIN).isEmpty());
	}

	/**
	 * A spec that is not worth using is still reported, just at no value. Dropping it made owning the
	 * weapon look identical to not owning it.
	 */
	@Test
	public void anUnhelpfulSpecIsStillListed()
	{
		GearItem scimitar = weapon(ItemID.DRAGON_SCIMITAR, "Dragon scimitar", 67, 66, 4);

		List<SpecSuggestion> suggestions = find(Target.dummy(), scimitar);

		assertEquals(1, suggestions.size());
		assertEquals(SpecialAttack.DRAGON_SCIMITAR, suggestions.get(0).getSpecial());
	}

	private List<SpecSuggestion> find(Target target, GearItem... specWeapons)
	{
		return find(target, 0, specWeapons);
	}

	private List<SpecSuggestion> find(Target target, int bodyStrength, GearItem... specWeapons)
	{
		return find(target, bodyStrength, 300, specWeapons);
	}

	private List<SpecSuggestion> find(
		Target target, int bodyStrength, int hitpoints, GearItem... specWeapons)
	{
		return find(target, bodyStrength, hitpoints, 99, specWeapons);
	}

	private List<SpecSuggestion> find(
		Target target, int bodyStrength, int hitpoints, int magicLevel, GearItem... specWeapons)
	{
		Map<EquipmentSlot, GearItem> setup = new EnumMap<>(EquipmentSlot.class);
		setup.put(EquipmentSlot.WEAPON, PLAIN);
		setup.put(EquipmentSlot.BODY, body(bodyStrength));

		List<EquipmentStats> pieces = new ArrayList<>();
		for (GearItem item : setup.values())
		{
			pieces.add(item.getStats());
		}

		CombatContext context = CombatContext.builder()
			.attackLevel(99)
			.strengthLevel(99)
			.rangedLevel(99)
			.magicLevel(magicLevel)
			.style(CombatStyle.SLASH)
			.equipment(EquipmentStats.sum(pieces))
			.target(target)
			.targetHitpoints(hitpoints)
			.weaponSpeedTicks(4)
			.build();

		List<GearItem> owned = new ArrayList<>(Arrays.asList(specWeapons));
		owned.add(PLAIN);

		return finder.find(setup, owned, context);
	}

	private static double valueOf(List<SpecSuggestion> suggestions, SpecialAttack special)
	{
		for (SpecSuggestion suggestion : suggestions)
		{
			if (suggestion.getSpecial() == special)
			{
				return suggestion.getDamageAdded();
			}
		}

		return 0;
	}

	/** Something with real defence, where landing a hit is the hard part. */
	private static Target armoured()
	{
		return Target.builder()
			.name("Armoured")
			.defenceLevel(300)
			.defensiveBonuses(EquipmentStats.builder().dslash(200).dstab(200).dcrush(200).build())
			.build();
	}

	private static GearItem body(int strength)
	{
		EquipmentStats stats = EquipmentStats.builder()
			.strength(strength)
			.slot(EquipmentSlot.BODY.getSlotIndex())
			.build();

		return new GearItem(9999, "Body", 1, stats, EnumSet.of(Storage.BANK));
	}

	private static GearItem weapon(int id, String name, int slash, int strength, int speed)
	{
		EquipmentStats stats = EquipmentStats.builder()
			.aslash(slash)
			.astab(slash - 10)
			.acrush(slash - 20)
			.strength(strength)
			.slot(EquipmentSlot.WEAPON.getSlotIndex())
			.speed(speed)
			.build();

		return new GearItem(id, name, 1, stats, EnumSet.of(Storage.BANK));
	}

	/**
	 * A halberd's second swing only reaches something bigger than one tile, so the same spec is worth
	 * more on a large boss than on a person-sized one.
	 */
	@Test
	public void theHalberdSweepIsWorthMoreOnALargeTarget()
	{
		GearItem halberd = weapon(ItemID.DRAGON_HALBERD, "Dragon halberd", 70, 70, 7);

		double small = valueOf(find(sized(1), 0, halberd), SpecialAttack.DRAGON_HALBERD);
		double large = valueOf(find(sized(3), 0, halberd), SpecialAttack.DRAGON_HALBERD);

		assertTrue("The second hit should only land on a large target", large > small);
	}

	/**
	 * An instant special costs no attack turn, so it is a hit gained rather than a hit swapped — it
	 * must never score as worthless just because it has no damage boost.
	 */
	@Test
	public void anInstantSpecialCountsAsAWholeExtraHit()
	{
		GearItem maul = weapon(ItemID.GRANITE_MAUL, "Granite maul", 81, 79, 7);

		double added = valueOf(find(Target.dummy(), 0, maul), SpecialAttack.GRANITE_MAUL);

		assertTrue("A free hit is worth roughly a hit, not nothing", added > 1);
	}

	private static Target sized(int size)
	{
		return Target.builder()
			.name("Sized")
			.defenceLevel(100)
			.size(size)
			.defensiveBonuses(EquipmentStats.builder().dslash(50).dstab(50).dcrush(50).build())
			.build();
	}

	/**
	 * A charged weapon arrives under a different id per charge tier, and every one of them specs the
	 * same. Matching only exact ids would quietly ignore the weapon you actually own.
	 */
	@Test
	public void aChargeVariantIsRecognisedAsTheSameSpecWeapon()
	{
		assertEquals(SpecialAttack.CRYSTAL_HALBERD,
			SpecialAttack.forItem(ItemID.CRYSTAL_HALBERD));
		assertEquals(SpecialAttack.CRYSTAL_HALBERD,
			SpecialAttack.forItem(ItemID.CRYSTAL_HALBERD_INACTIVE));
	}

	@Test
	public void anOrdinaryItemHasNoSpecialAttack()
	{
		assertNull(SpecialAttack.forItem(ItemID.RUNE_SCIMITAR));
		assertNull(SpecialAttack.forItem(ItemID.SHARK));
	}

	/**
	 * A bow must roll ranged and a staff must roll magic. Scored as a sword, a dark bow would read its
	 * strength bonus instead of its ranged strength and roll against the wrong defence — producing a
	 * number that looks perfectly reasonable and is nonsense.
	 */
	@Test
	public void aBowIsScoredAsRangedAndAStaffAsMagic()
	{
		GearItem darkBow = rangedWeapon(ItemID.DARKBOW, "Dark bow", 95, 9);
		GearItem staff = magicWeapon(ItemID.NIGHTMARE_STAFF_VOLATILE, "Volatile nightmare staff");

		// Both must produce a suggestion at all: a mis-styled weapon scores zero and vanishes.
		assertFalse(find(Target.dummy(), 0, darkBow).isEmpty());
		assertFalse(find(Target.dummy(), 0, staff).isEmpty());
	}

	/**
	 * The Magic specials take their ceiling from the Magic level, not from the spell, so they must not
	 * depend on spell damage at all.
	 */
	@Test
	public void aMagicSpecialScalesWithMagicLevelRatherThanTheSpell()
	{
		GearItem volatileStaff = magicWeapon(ItemID.NIGHTMARE_STAFF_VOLATILE, "Volatile nightmare staff");

		double atNinetyNine = valueOf(
			find(Target.dummy(), 0, 300, 99, volatileStaff), SpecialAttack.VOLATILE_NIGHTMARE_STAFF);
		double atFifty = valueOf(
			find(Target.dummy(), 0, 300, 50, volatileStaff), SpecialAttack.VOLATILE_NIGHTMARE_STAFF);

		assertTrue("A higher Magic level should raise the ceiling", atNinetyNine > atFifty);
	}

	private static GearItem rangedWeapon(int id, String name, int rangedAttack, int speed)
	{
		EquipmentStats stats = EquipmentStats.builder()
			.arange(rangedAttack)
			.rangedStrength(60)
			.slot(EquipmentSlot.WEAPON.getSlotIndex())
			.speed(speed)
			.build();

		return new GearItem(id, name, 1, stats, EnumSet.of(Storage.BANK));
	}

	private static GearItem magicWeapon(int id, String name)
	{
		EquipmentStats stats = EquipmentStats.builder()
			.amagic(25)
			.slot(EquipmentSlot.WEAPON.getSlotIndex())
			.speed(4)
			.build();

		return new GearItem(id, name, 1, stats, EnumSet.of(Storage.BANK));
	}
}

package com.gearforge;

import com.gearforge.dps.SpecialAttack;
import java.awt.Canvas;
import java.awt.FontMetrics;
import net.runelite.client.ui.FontManager;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * The damage figure sits in a column of fixed width, so the width has to be checked rather than
 * assumed — a figure clipped to its first character reads as a broken number, which is exactly how
 * it was reported.
 */
public class SpecRowWidthTest
{
	private static final int VALUE_WIDTH = 44;
	private static final int TEXT_WIDTH = 92;

	private final FontMetrics bold = new Canvas().getFontMetrics(FontManager.getRunescapeBoldFont());
	private final FontMetrics small = new Canvas().getFontMetrics(FontManager.getRunescapeSmallFont());

	@Test
	public void everyDamageFigureFitsItsColumn()
	{
		for (double added : new double[]{0, 0.4, 1.4, 9.9, 13.6, 99.9, 100, 486.2})
		{
			String shown = added < 0.05 ? "\u2014"
				: added >= 100 ? String.format("+%.0f", added) : String.format("+%.1f", added);

			assertTrue(shown + " needs " + bold.stringWidth(shown) + "px of " + VALUE_WIDTH,
				bold.stringWidth(shown) <= VALUE_WIDTH);
		}
	}

	@Test
	public void everySpecDescriptionFitsTheTextColumn()
	{
		for (SpecialAttack special : SpecialAttack.values())
		{
			// Wrapping is fine; a single word wider than the column is not, since it cannot break.
			for (String word : special.describe().split(" "))
			{
				assertTrue(special.getDisplayName() + ": '" + word + "' is "
						+ small.stringWidth(word) + "px of " + TEXT_WIDTH,
					small.stringWidth(word) <= TEXT_WIDTH);
			}

			assertTrue(special.getDisplayName() + " name is " + bold.stringWidth(special.getDisplayName()),
				bold.stringWidth(special.getDisplayName()) > 0);
		}

		assertTrue(small.stringWidth("average hit 486.2") <= TEXT_WIDTH);
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentStats;
import com.gearforge.data.Monster;
import com.gearforge.data.MonsterRepository;
import com.gearforge.dps.Spell;
import com.gearforge.dps.Target;
import com.google.gson.Gson;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Magic assumed Ice Barrage for everything. It is the strongest spell in the game and the right guess
 * against something with no elemental weakness — but over a thousand monsters have one, and a
 * matching spell gains that weakness as a share of both accuracy and damage.
 */
public class SpellTest
{
	@Test
	public void theStrongestSpellWinsWhereThereIsNoWeakness()
	{
		Spell best = Spell.bestFor(plain(), 99, true);

		assertEquals(Spell.ICE_BARRAGE, best);
	}

	/**
	 * The case that makes this worth doing: a Fire Surge hits for six less than an Ice Barrage on
	 * paper, and beats it outright against something fire-weak.
	 */
	@Test
	public void anElementalSpellWinsAgainstAMatchingWeakness()
	{
		Spell best = Spell.bestFor(weakTo(Spell.Element.FIRE, 50), 99, true);

		assertEquals(Spell.FIRE_SURGE, best);
		assertEquals(36, Spell.FIRE_SURGE.maxHitAgainst(weakTo(Spell.Element.FIRE, 50)));
		assertEquals(30, Spell.ICE_BARRAGE.maxHitAgainst(weakTo(Spell.Element.FIRE, 50)));
	}

	@Test
	public void theWrongElementGainsNothing()
	{
		Target fireWeak = weakTo(Spell.Element.FIRE, 50);

		assertEquals(22, Spell.WATER_SURGE.maxHitAgainst(fireWeak));
		assertEquals(Spell.WATER_SURGE.getMaxHit(), Spell.WATER_SURGE.maxHitAgainst(fireWeak));
	}

	@Test
	public void aLowerLevelCasterGetsTheBestTheyCanCast()
	{
		Spell atFifty = Spell.bestFor(plain(), 50, true);
		Spell atNinetyNine = Spell.bestFor(plain(), 99, true);

		assertNotNull(atFifty);
		assertTrue("A level 50 spell cannot need more than 50 Magic", atFifty.getMagicLevel() <= 50);
		assertTrue(atNinetyNine.getMaxHit() > atFifty.getMaxHit());
	}

	@Test
	public void withoutAncientsTheBestStandardSpellIsChosen()
	{
		Spell standard = Spell.bestFor(plain(), 99, false);

		assertEquals(Spell.FIRE_SURGE, standard);
	}

	/**
	 * The weakness has to survive the generator, or none of this fires.
	 */
	@Test
	public void theMonsterDataCarriesElementalWeaknesses()
	{
		long withWeakness = new MonsterRepository(new Gson()).all().stream()
			.map(Monster::toTarget)
			.filter(target -> target.getWeaknessElement() != null)
			.count();

		assertTrue("Elemental weaknesses are missing from the monster data", withWeakness > 400);
	}

	@Test
	public void aWeakMonsterResolvesItsElement()
	{
		Monster spectre = new MonsterRepository(new Gson()).all().stream()
			.filter(monster -> monster.getName().equalsIgnoreCase("Aberrant spectre"))
			.findFirst()
			.orElseThrow(() -> new AssertionError("Aberrant spectre missing"));

		assertEquals(Spell.Element.AIR, spectre.toTarget().getWeaknessElement());
		assertEquals(50, spectre.toTarget().getWeaknessSeverity());
		assertEquals(Spell.WIND_SURGE, Spell.bestFor(spectre.toTarget(), 99, true));
	}

	private static Target plain()
	{
		return Target.builder()
			.name("Plain")
			.defenceLevel(100)
			.defensiveBonuses(EquipmentStats.builder().build())
			.build();
	}

	private static Target weakTo(Spell.Element element, int severity)
	{
		return Target.builder()
			.name("Weak")
			.defenceLevel(100)
			.defensiveBonuses(EquipmentStats.builder().build())
			.weaknessElement(element)
			.weaknessSeverity(severity)
			.build();
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentSlot;
import com.gearforge.data.EquipmentStats;
import com.gearforge.data.GearItem;
import com.gearforge.data.ItemCategories;
import com.gearforge.data.Storage;
import com.google.gson.Gson;
import com.gearforge.dps.CombatContext;
import com.gearforge.dps.CombatStyle;
import com.gearforge.dps.DpsEngine;
import com.gearforge.dps.SetEffectRegistry;
import com.gearforge.dps.Target;
import com.gearforge.optimizer.Constraints;
import com.gearforge.optimizer.UpgradeFinder;
import com.gearforge.optimizer.UpgradeSuggestion;
import com.gearforge.setups.Setup;
import com.gearforge.setups.SetupSource;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class UpgradeFinderTest
{
	private final UpgradeFinder finder =
		new UpgradeFinder(new DpsEngine(), new SetEffectRegistry(), new ItemCategories(new Gson()));

	private static CombatContext context()
	{
		return CombatContext.builder()
			.attackLevel(99)
			.strengthLevel(99)
			.style(CombatStyle.SLASH)
			.equipment(EquipmentStats.builder().build())
			.target(Target.dummy())
			.weaponSpeedTicks(4)
			.build();
	}

	@Test
	public void suggestsABetterItemThePlayerAlreadyOwns()
	{
		GearItem whip = weapon(1, "Abyssal whip", 82, 82, false);
		GearItem weakHelm = armour(2, "Iron full helm", EquipmentSlot.HEAD, 0);
		GearItem strongHelm = armour(3, "Slayer helmet", EquipmentSlot.HEAD, 30);

		Setup setup = Setup.named("Test", SetupSource.MANUAL);
		setup.put(EquipmentSlot.WEAPON, whip.getItemId());
		setup.put(EquipmentSlot.HEAD, weakHelm.getItemId());

		List<UpgradeSuggestion> suggestions =
			finder.find(setup, Arrays.asList(whip, weakHelm, strongHelm), context());

		assertEquals(1, suggestions.size());
		assertEquals(EquipmentSlot.HEAD, suggestions.get(0).getSlot());
		assertEquals("Slayer helmet", suggestions.get(0).getReplacement().getName());
		assertTrue(suggestions.get(0).getGain() > 0);
	}

	@Test
	public void staysQuietWhenTheSetupIsAlreadyBest()
	{
		GearItem whip = weapon(1, "Abyssal whip", 82, 82, false);
		GearItem strongHelm = armour(3, "Slayer helmet", EquipmentSlot.HEAD, 30);
		GearItem weakHelm = armour(2, "Iron full helm", EquipmentSlot.HEAD, 0);

		Setup setup = Setup.named("Test", SetupSource.MANUAL);
		setup.put(EquipmentSlot.WEAPON, whip.getItemId());
		setup.put(EquipmentSlot.HEAD, strongHelm.getItemId());

		assertTrue(finder.find(setup, Arrays.asList(whip, weakHelm, strongHelm), context()).isEmpty());
	}

	@Test
	public void accuracyUpgradesAreVisibleNotJustDamageOnes()
	{
		// The helm here adds only accuracy. Judged against a zero-defence dummy this would score as
		// worthless, because accuracy is already ~100% — the benchmark target exists to catch it.
		GearItem whip = weapon(1, "Abyssal whip", 82, 82, false);
		GearItem plainHelm = armour(2, "Iron full helm", EquipmentSlot.HEAD, 0);
		GearItem accurateHelm = armour(3, "Accurate helm", EquipmentSlot.HEAD, 40);

		Setup setup = Setup.named("Test", SetupSource.MANUAL);
		setup.put(EquipmentSlot.WEAPON, whip.getItemId());
		setup.put(EquipmentSlot.HEAD, plainHelm.getItemId());

		List<UpgradeSuggestion> suggestions =
			finder.find(setup, Arrays.asList(whip, plainHelm, accurateHelm), context());

		assertEquals(1, suggestions.size());
		assertEquals("Accurate helm", suggestions.get(0).getReplacement().getName());
	}

	@Test
	public void ignoresGainsTooSmallToBeWorthSaying()
	{
		GearItem whip = weapon(1, "Abyssal whip", 82, 82, false);
		GearItem helm = armour(2, "Helm", EquipmentSlot.HEAD, 0);
		// A single point of accuracy is far below the threshold.
		GearItem barelyBetter = armour(3, "Barely better helm", EquipmentSlot.HEAD, 1);

		Setup setup = Setup.named("Test", SetupSource.MANUAL);
		setup.put(EquipmentSlot.WEAPON, whip.getItemId());
		setup.put(EquipmentSlot.HEAD, helm.getItemId());

		assertTrue(finder.find(setup, Arrays.asList(whip, helm, barelyBetter), context()).isEmpty());
	}

	@Test
	public void dismissedItemsAreNeverSuggestedAgain()
	{
		GearItem whip = weapon(1, "Abyssal whip", 82, 82, false);
		GearItem weakHelm = armour(2, "Iron full helm", EquipmentSlot.HEAD, 0);
		GearItem strongHelm = armour(3, "Slayer helmet", EquipmentSlot.HEAD, 30);

		Setup setup = Setup.named("Test", SetupSource.MANUAL);
		setup.put(EquipmentSlot.WEAPON, whip.getItemId());
		setup.put(EquipmentSlot.HEAD, weakHelm.getItemId());
		setup.getDismissedUpgrades().add(strongHelm.getItemId());

		assertTrue(finder.find(setup, Arrays.asList(whip, weakHelm, strongHelm), context()).isEmpty());
	}

	@Test
	public void suggestingATwoHanderAccountsForLosingTheShield()
	{
		// The two-hander is better on paper, but only wins once the shield it displaces is costed.
		GearItem oneHander = weapon(1, "One-hander", 82, 82, false);
		GearItem twoHander = weapon(2, "Two-hander", 84, 84, true);
		GearItem shield = armour(3, "Big shield", EquipmentSlot.SHIELD, 60);

		Setup setup = Setup.named("Test", SetupSource.MANUAL);
		setup.put(EquipmentSlot.WEAPON, oneHander.getItemId());
		setup.put(EquipmentSlot.SHIELD, shield.getItemId());

		List<UpgradeSuggestion> suggestions =
			finder.find(setup, Arrays.asList(oneHander, twoHander, shield), context());

		// Whatever it decides, it must never propose an illegal pairing.
		for (UpgradeSuggestion suggestion : suggestions)
		{
			assertTrue(suggestion.getSlot() != EquipmentSlot.SHIELD
				|| !Constraints.isTwoHanded(oneHander));
		}
	}

	@Test
	public void aSetupWithNoWeaponProducesNothingRatherThanFailing()
	{
		Setup setup = Setup.named("Test", SetupSource.MANUAL);
		setup.put(EquipmentSlot.HEAD, 2);

		assertTrue(finder.find(setup,
			Collections.singletonList(armour(2, "Helm", EquipmentSlot.HEAD, 0)), context()).isEmpty());
	}

	@Test
	public void suggestionsReadInPlainLanguage()
	{
		GearItem whip = weapon(1, "Abyssal whip", 82, 82, false);
		GearItem weakHelm = armour(2, "Iron full helm", EquipmentSlot.HEAD, 0);
		GearItem strongHelm = armour(3, "Slayer helmet", EquipmentSlot.HEAD, 30);

		Setup setup = Setup.named("Test", SetupSource.MANUAL);
		setup.put(EquipmentSlot.WEAPON, whip.getItemId());
		setup.put(EquipmentSlot.HEAD, weakHelm.getItemId());

		String described = finder.find(setup, Arrays.asList(whip, weakHelm, strongHelm), context())
			.get(0).describe();

		assertTrue(described.startsWith("Better head: Slayer helmet, +"));
		assertTrue(described.endsWith("% DPS"));
	}

	private static GearItem weapon(int id, String name, int slash, int strength, boolean twoHanded)
	{
		EquipmentStats stats = EquipmentStats.builder()
			.aslash(slash).strength(strength)
			.slot(EquipmentSlot.WEAPON.getSlotIndex())
			.twoHanded(twoHanded).speed(4).build();

		return new GearItem(id, name, 1, stats, EnumSet.of(Storage.BANK));
	}

	private static GearItem armour(int id, String name, EquipmentSlot slot, int slash)
	{
		EquipmentStats stats = EquipmentStats.builder()
			.aslash(slash).slot(slot.getSlotIndex()).build();

		return new GearItem(id, name, 1, stats, EnumSet.of(Storage.BANK));
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentStats;
import com.gearforge.dps.AttackStyle;
import com.gearforge.dps.CombatContext;
import com.gearforge.dps.CombatStyle;
import com.gearforge.dps.DpsEngine;
import com.gearforge.dps.Target;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Cross-validation against the OSRS Wiki's own DPS calculator.
 * <p>
 * Every expected value here is lifted from that project's test suite
 * ({@code src/tests/calc/BasicRolls.test.ts} in weirdgloop/osrs-dps-calc), and the item stats are
 * from its equipment dataset. This is the independent check the rest of the DPS suite lacks: those
 * tests confirm the implementation matches the formulas I transcribed, whereas these confirm the
 * formulas themselves produce the same numbers as the reference calculator.
 * <p>
 * The reference scenarios use the accurate attack style, which is why every case adds +3.
 */
public class WikiCalculatorReferenceTest
{
	private final DpsEngine engine = new DpsEngine();

	/** slash +82, strength +82, speed 4. */
	private static final EquipmentStats ABYSSAL_WHIP = EquipmentStats.builder()
		.aslash(82).strength(82).speed(4).slot(3).build();

	/** ranged +128, ranged strength +106, speed 5. */
	private static final EquipmentStats BOW_OF_FAERDHINEN = EquipmentStats.builder()
		.arange(128).rangedStrength(106).speed(5).slot(3).build();

	/** magic +15, speed 4. */
	private static final EquipmentStats TRIDENT_OF_THE_SEAS = EquipmentStats.builder()
		.amagic(15).speed(4).slot(3).build();

	// ------------------------------------------------------------------ melee

	@Test
	public void whipAttackRollMatchesTheWikiCalculator()
	{
		assertEquals(1752, attackRoll(melee(1, 1)));
		assertEquals(16060, attackRoll(melee(99, 1)));
	}

	@Test
	public void whipMaxHitMatchesTheWikiCalculator()
	{
		assertEquals(2, maxHit(melee(1, 1)));
		assertEquals(24, maxHit(melee(1, 99)));
	}

	// ------------------------------------------------------------------ ranged

	@Test
	public void bowOfFaerdhinenAttackRollMatchesTheWikiCalculator()
	{
		assertEquals(2304, attackRoll(ranged(1)));
		assertEquals(21120, attackRoll(ranged(99)));
	}

	@Test
	public void bowOfFaerdhinenMaxHitMatchesTheWikiCalculator()
	{
		assertEquals(3, maxHit(ranged(1)));
		assertEquals(29, maxHit(ranged(99)));
	}

	// ------------------------------------------------------------------ magic

	@Test
	public void tridentAttackRollMatchesTheWikiCalculator()
	{
		// Powered staves get the accurate style bonus; a spellbook cast would not, and these numbers
		// only line up with it applied.
		assertEquals(948, attackRoll(magic(1)));
		assertEquals(8690, attackRoll(magic(99)));
	}

	// ------------------------------------------------------------------ helpers

	private int attackRoll(CombatContext context)
	{
		return engine.attackRoll(
			engine.effectiveAttackLevel(context),
			context.getStyle().attackBonusOf(context.getEquipment()),
			context.getAccuracyMultiplier());
	}

	private int maxHit(CombatContext context)
	{
		return engine.maxHit(context, engine.effectiveStrengthLevel(context));
	}

	private static CombatContext melee(int attackLevel, int strengthLevel)
	{
		return CombatContext.builder()
			.attackLevel(attackLevel)
			.strengthLevel(strengthLevel)
			.style(CombatStyle.SLASH)
			.attackStyle(AttackStyle.ACCURATE)
			.equipment(ABYSSAL_WHIP)
			.weaponSpeedTicks(4)
			.target(Target.dummy())
			.build();
	}

	private static CombatContext ranged(int rangedLevel)
	{
		return CombatContext.builder()
			.rangedLevel(rangedLevel)
			.style(CombatStyle.RANGED)
			.attackStyle(AttackStyle.ACCURATE)
			.equipment(BOW_OF_FAERDHINEN)
			.weaponSpeedTicks(5)
			.target(Target.dummy())
			.build();
	}

	private static CombatContext magic(int magicLevel)
	{
		return CombatContext.builder()
			.magicLevel(magicLevel)
			.style(CombatStyle.MAGIC)
			.attackStyle(AttackStyle.ACCURATE)
			.poweredStaff(true)
			.equipment(TRIDENT_OF_THE_SEAS)
			.weaponSpeedTicks(4)
			.target(Target.dummy())
			.build();
	}
}

package com.gearforge;

import com.gearforge.data.EquipmentStats;
import com.gearforge.dps.CombatContext;
import com.gearforge.dps.CombatPrayer;
import com.gearforge.dps.CombatStyle;
import com.gearforge.dps.DpsEngine;
import com.gearforge.dps.Potion;
import com.gearforge.data.ItemCategories;
import com.gearforge.data.Monster;
import com.gearforge.data.MonsterRepository;
import com.gearforge.data.PlayerLevels;
import com.gearforge.data.Reachability;
import com.google.gson.Gson;
import net.runelite.api.gameval.ItemID;
import com.gearforge.dps.SetupScore;
import com.gearforge.dps.Target;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * A reported max hit of 52 with a blade of saeldor at Zulrah. Reproduced here from the numbers the
 * panel says it assumed, so the figure can be checked against what the weapon can actually do rather
 * than argued about.
 */
public class ZulrahDiagnosticTest
{
	@Test
	public void reportTheMeleeMaximum()
	{
		PlayerLevels maxed = PlayerLevels.builder()
			.attack(99).strength(99).defence(99).ranged(99).magic(99)
			.prayer(99).hitpoints(99).slayer(99).herblore(99)
			.build();

		// Roughly the setup the panel showed: saeldor, torva helm, blood moon body and legs, torture,
		// infernal cape, barrows gloves, dragon boots, berserker ring.
		int strengthBonus = 89 + 4 + 10 + 8 + 12 + 4 + 8 + 6 + 4;

		CombatContext context = CombatContext.builder()
			.attackLevel(99)
			.strengthLevel(99)
			.strengthBoost(Potion.SUPER_COMBAT.strengthBoost(maxed))
			.attackBoost(Potion.SUPER_COMBAT.attackBoost(maxed))
			.prayer(CombatPrayer.PIETY)
			.style(CombatStyle.SLASH)
			.equipment(EquipmentStats.builder().aslash(150).strength(strengthBonus).build())
			.target(Target.builder()
				.name("Zulrah")
				.defenceLevel(300)
				.defensiveBonuses(EquipmentStats.builder().dslash(0).build())
				.build())
			.weaponSpeedTicks(4)
			.build();

		SetupScore score = new DpsEngine().score(context);

		System.out.printf(
			"Saeldor at Zulrah: strength bonus %d, effective strength %d, max hit %d, accuracy %.1f%%%n",
			strengthBonus, score.getEffectiveStrengthLevel(), score.getMaxHit(), score.accuracyPercent());

		// A blade of saeldor with a super combat and piety tops out around 50. Anything far above that
		// means something is being counted twice.
		assertTrue("Max hit " + score.getMaxHit() + " is higher than the weapon can produce",
			score.getMaxHit() <= 52);
	}

	/**
	 * The reported bug: a blade of saeldor recommended for Zulrah on the Bosses tab. It cannot reach.
	 * The BiS tab had the filter; this tab was a separate path that never received it.
	 */
	@Test
	public void aSaeldorCannotBeOfferedForZulrah()
	{
		Monster zulrah = new MonsterRepository(new Gson()).all().stream()
			.filter(monster -> monster.getName().equalsIgnoreCase("Zulrah"))
			.findFirst()
			.orElseThrow(() -> new AssertionError("Zulrah missing"));

		ItemCategories categories = new ItemCategories(new Gson());

		assertTrue("Zulrah needs reach", Reachability.requiresReach(zulrah));
		assertFalse("A blade of saeldor is not a polearm",
			categories.hasReach(ItemID.BLADE_OF_SAELDOR));
		assertFalse("So it cannot be offered",
			Reachability.meleeCanReach(zulrah, categories.hasReach(ItemID.BLADE_OF_SAELDOR)));

		// A dragon warhammer cannot reach it either, which is why it must not be suggested as a spec.
		assertFalse(Reachability.meleeCanReach(zulrah, categories.hasReach(ItemID.DRAGON_WARHAMMER)));

		// A halberd can, and that is the answer people actually use.
		assertTrue(Reachability.meleeCanReach(zulrah, categories.hasReach(ItemID.DRAGON_HALBERD)));
	}
}

package com.gearforge.ui;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.PluginPanel;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * The panel is 225 pixels wide and nothing may exceed it.
 * <p>
 * This kept going wrong for one reason: a BoxLayout gives each child the container's width, but never
 * less than that child's own <em>minimum</em>, and a minimum is computed from the text inside. One
 * long monster name or item name therefore lays its row out wider than the panel, and since the
 * scroll pane has no horizontal bar, whatever is on the right simply cannot be reached. Padding never
 * fixed it, which is why it kept coming back.
 * <p>
 * Rather than checking a screenshot again, the widths are asserted here.
 */
public class PanelWidthTest
{
	/** Nothing a monster or item is called is longer than this. */
	private static final String LONG_NAME =
		"Dagannoth Rex (Deep Wilderness, superior, on task, imbued)";

	@Test
	public void theWidthBudgetAddsUp()
	{
		assertTrue("The content width has to fit the panel RuneLite gives us",
			Cards.CONTENT_WIDTH <= PluginPanel.PANEL_WIDTH);

		// A row is an icon, some text and a value, and the three of them plus the padding are the width.
		int row = 2 * Cards.ROW_PADDING + Cards.ROW_ICON_WIDTH + 2 * Cards.ROW_GAP
			+ Cards.IN_ROW_TEXT_WIDTH + Cards.ROW_VALUE_WIDTH;

		assertTrue("A row of " + row + " does not fit " + Cards.CONTENT_WIDTH,
			row <= Cards.CONTENT_WIDTH);

		// Wrapped text sits inside a card, which has padding of its own on both sides.
		assertTrue("Wrapped text must fit inside a card",
			Cards.TEXT_WIDTH + 2 * Cards.CARD_PADDING <= Cards.CONTENT_WIDTH);
	}

	@Test
	public void noBuildingBlockDemandsMoreWidthThanThePanelHas()
	{
		assertFits("muted", Cards.muted(LONG_NAME + " " + LONG_NAME));
		assertFits("body in row", Cards.bodyInRow(LONG_NAME));
		assertFits("muted in row", Cards.mutedInRow(LONG_NAME));
		assertFits("warning", Cards.warning(LONG_NAME + " " + LONG_NAME));
		assertFits("button", Cards.button("A button with a very long label indeed"));
		assertFits("section label", Cards.sectionLabel(LONG_NAME));
		assertFits("body", Cards.body(LONG_NAME));
		assertFits("title", Cards.title(LONG_NAME));
		assertFits("headline", Cards.headline(LONG_NAME));
		assertFits("segmented", Cards.segmented(
			new String[]{"A long first option", "A long second option"}, 0, index -> { }));
	}

	/**
	 * The dropdown sizes itself to its longest entry, and the monster list has a thousand of them.
	 */
	@Test
	public void aDropdownOfLongNamesStillFits()
	{
		assertFits("combo box", Cards.comboBox(new String[]{"Short", LONG_NAME, LONG_NAME + LONG_NAME}));
	}

	/**
	 * The layout itself, not just the declared sizes: laid out at the panel's width, the value on the
	 * right of a row has to still be on screen.
	 */
	@Test
	public void aRowWithALongNameKeepsItsValueOnScreen()
	{
		JPanel row = new JPanel(new BorderLayout(Cards.ROW_GAP, 0));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(Cards.ROW_ICON_WIDTH, 32));
		row.add(icon, BorderLayout.WEST);

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.add(new JLabel(LONG_NAME));
		text.add(Cards.mutedInRow(LONG_NAME));
		Cards.fitToPanel(text);
		row.add(text, BorderLayout.CENTER);

		JLabel value = new JLabel("+13.6");
		value.setPreferredSize(new Dimension(Cards.ROW_VALUE_WIDTH, 16));
		row.add(value, BorderLayout.EAST);

		Cards.fitRow(row);
		assertFits("row", row);

		row.setSize(Cards.CONTENT_WIDTH, row.getPreferredSize().height);
		row.doLayout();

		for (Component child : row.getComponents())
		{
			assertTrue("A child ran to " + (child.getX() + child.getWidth())
					+ ", past the panel's " + Cards.CONTENT_WIDTH,
				child.getX() + child.getWidth() <= Cards.CONTENT_WIDTH);
		}

		assertTrue("The value must keep its full width",
			value.getWidth() >= Cards.ROW_VALUE_WIDTH);
	}

	private static void assertFits(String what, javax.swing.JComponent component)
	{
		assertTrue(what + " has a minimum width of " + component.getMinimumSize().width
				+ ", more than the panel's " + Cards.CONTENT_WIDTH,
			component.getMinimumSize().width <= Cards.CONTENT_WIDTH);
	}
}

